// ═══════════════════════════════════════════════════════════════════════════
// ── Firebase Anonymous Auth (REST API) ──────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════
// Quand FIREBASE_API_KEY est vide → auth désactivée, fetch direct (compat actuelle)
// Quand FIREBASE_API_KEY est défini → chaque requête Firebase passe ?auth=<idToken>
// Permet d'activer rules Firebase {".read":"auth!=null",".write":"auth!=null"}
// v2.9.14 — DÉCISION ARCHITECTURALE : Firebase RTDB désactivé
// Raisons (analyse objective coût/bénéfice) :
//   1. ERR_CONNECTION_RESET récurrent depuis Cameroun (Firebase Europe)
//   2. Coût de scaling élevé (>$1000/mois à 1M users)
//   3. LWS api/db.php déjà en place, stable, gratuit, sous contrôle VÉRITAS
//   4. Latence LWS (France) < latence Firebase (Belgique) pour CM
//   5. Pas de quota externe (Firebase free tier = 100 connexions max)
//   6. Multi-device sync : polling LWS toutes les 30s suffit pour l'usage scolaire
// Conséquence : LWS devient le seul backend. Firebase Auth désactivé aussi
// (l'auth anonyme générait un userId qu'on peut désormais générer côté client).
// Pour réactiver Firebase un jour : remettre la clé API ici.
const FIREBASE_API_KEY = ''; // Désactivé — backend unique = LWS api/db.php
const FIREBASE_API_KEY_BACKUP = ''; // v1.2.2 : clé retirée du source (sensible). Conservez-la hors-ligne (gestionnaire de mots de passe) pour une éventuelle réactivation.

// Cache persistant : 1 utilisateur anonyme par navigateur (pas un à chaque ouverture)
window._fbAuth = (function(){
  try{
    var raw = localStorage.getItem('_vrtFbAuth');
    if(raw){
      var saved = JSON.parse(raw);
      if(saved && saved.refreshToken){
        return {
          idToken: saved.idToken || null,
          refreshToken: saved.refreshToken,
          expiresAt: saved.expiresAt || 0,
          localId: saved.localId || null,
          pending: null
        };
      }
    }
  }catch(e){}
  return { idToken: null, refreshToken: null, expiresAt: 0, localId: null, pending: null };
})();

function _fbAuthPersist(){
  try{
    localStorage.setItem('_vrtFbAuth', JSON.stringify({
      idToken: window._fbAuth.idToken,
      refreshToken: window._fbAuth.refreshToken,
      expiresAt: window._fbAuth.expiresAt,
      localId: window._fbAuth.localId
    }));
  }catch(e){}
}

async function _ensureFbAuth(){
  if(!FIREBASE_API_KEY) return null; // Auth désactivée
  // 1) Token encore valide (refresh 1 min avant expiration) → retour direct
  if(window._fbAuth.idToken && Date.now() < window._fbAuth.expiresAt - 60000){
    return window._fbAuth.idToken;
  }
  // 2) Requête déjà en cours → mutualiser
  if(window._fbAuth.pending) return window._fbAuth.pending;
  // 3) Si on a un refreshToken → renouveler (pas créer un nouvel utilisateur !)
  if(window._fbAuth.refreshToken){
    window._fbAuth.pending = (async function(){
      try{
        var body = 'grant_type=refresh_token&refresh_token=' + encodeURIComponent(window._fbAuth.refreshToken);
        var res = await fetch('https://securetoken.googleapis.com/v1/token?key=' + FIREBASE_API_KEY, {
          method: 'POST',
          headers: {'Content-Type': 'application/x-www-form-urlencoded'},
          body: body
        });
        if(!res.ok){
          console.warn('[Firebase Auth] refresh HTTP ' + res.status + ' — signUp inline');
          // FIX race : signUp INLINE au lieu de récursion via _ensureFbAuth
          // (sinon fenêtre où pending=null avant nouvelle Promise → 2 signUps possibles)
          window._fbAuth.refreshToken = null;
          window._fbAuth.idToken = null;
          _fbAuthPersist();
          var su = await fetch('https://identitytoolkit.googleapis.com/v1/accounts:signUp?key=' + FIREBASE_API_KEY, {
            method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({returnSecureToken:true})
          });
          if(!su.ok){console.warn('[Firebase Auth] signUp fallback HTTP '+su.status); return null;}
          var sd = await su.json();
          window._fbAuth.idToken = sd.idToken;
          window._fbAuth.refreshToken = sd.refreshToken;
          window._fbAuth.localId = sd.localId;
          window._fbAuth.expiresAt = Date.now() + (parseInt(sd.expiresIn || '3600') * 1000);
          _fbAuthPersist();
          return sd.idToken;
        }
        var data = await res.json();
        window._fbAuth.idToken = data.id_token || data.access_token;
        window._fbAuth.refreshToken = data.refresh_token || window._fbAuth.refreshToken;
        window._fbAuth.expiresAt = Date.now() + (parseInt(data.expires_in || '3600') * 1000);
        _fbAuthPersist();
        return window._fbAuth.idToken;
      } catch(e){
        console.warn('[Firebase Auth] erreur refresh:', e);
        return null;
      } finally {
        window._fbAuth.pending = null;
      }
    })();
    return window._fbAuth.pending;
  }
  // 4) Aucun token : signUp anonyme (UNE SEULE FOIS par navigateur)
  window._fbAuth.pending = (async function(){
    try{
      var res = await fetch('https://identitytoolkit.googleapis.com/v1/accounts:signUp?key=' + FIREBASE_API_KEY, {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({returnSecureToken: true})
      });
      if(!res.ok){
        console.warn('[Firebase Auth] signUp HTTP ' + res.status);
        return null;
      }
      var data = await res.json();
      window._fbAuth.idToken = data.idToken;
      window._fbAuth.refreshToken = data.refreshToken;
      window._fbAuth.localId = data.localId;
      window._fbAuth.expiresAt = Date.now() + (parseInt(data.expiresIn || '3600') * 1000);
      _fbAuthPersist();
      console.info('[Firebase Auth] Identité anonyme créée (' + data.localId + ')');
      return data.idToken;
    } catch(e){
      console.warn('[Firebase Auth] échec signUp:', e);
      return null;
    } finally {
      window._fbAuth.pending = null;
    }
  })();
  return window._fbAuth.pending;
}

// v2.9.14 : CIRCUIT BREAKER générique pour le backend (LWS depuis maintenant)
// Si le backend échoue 3 fois en moins de 10 secondes, on suspend les appels
// pendant 5 minutes. Évite le spam d'erreurs réseau et garde l'UX fluide.
window._fbBreaker = {
  failures: [],
  suspendedUntil: 0,
  isOpen: function() {
    return Date.now() < this.suspendedUntil;
  },
  recordFailure: function() {
    var now = Date.now();
    this.failures.push(now);
    this.failures = this.failures.filter(function(t){ return now - t < 10000; });
    if (this.failures.length >= 3) {
      this.suspendedUntil = now + 5 * 60 * 1000;
      this.failures = [];
      console.warn('[Backend] CIRCUIT OUVERT — sync suspendu 5 min (mode hors-ligne actif)');
      if (typeof toast === 'function') {
        toast('🔌 Mode hors-ligne (sync suspendu)', 'warn');
      }
    }
  },
  recordSuccess: function() {
    if (this.failures.length > 0) this.failures = [];
    if (this.suspendedUntil > 0) {
      this.suspendedUntil = 0;
      console.log('[Backend] CIRCUIT FERMÉ — connexion rétablie ✓');
      if (typeof toast === 'function') {
        toast('🌐 Connexion rétablie', 'ok');
      }
    }
  }
};

// v2.9.14 : _fbFetch — wrapper pour les appels au backend LWS (PHP)
// Firebase RTDB désactivé. Auth Firebase aussi (FIREBASE_API_KEY vide).
// Le code conservé compatibilité : on garde le nom _fbFetch pour ne pas
// avoir à modifier les 12+ appels existants. La fonction route vers LWS.
async function _fbFetch(url, options){
  // v2.9.17 : Court-circuit db.php pour les non-admins.
  // db.php exige requireAuth() côté serveur (données sensibles). Inutile que
  // le visiteur tente l'appel → 401 garanti. On retourne une réponse vide
  // silencieuse (200 {}) pour ne pas polluer la console.
  if (typeof url === 'string' && url.indexOf('/api/db.php') >= 0) {
    var _isAdm = false;
    try {
      var _r = sessionStorage.getItem('VERITAS_SES');
      if (_r) { var _x = JSON.parse(_r); _isAdm = _x && (_x.type==='admin'||_x.type==='superadmin'||_x.type==='enseignant'); }
    } catch(e){}
    if (!_isAdm) {
      return new Response('{}', { status: 200, headers: { 'Content-Type': 'application/json' } });
    }
    // Admin : s'assurer que le header Authorization est présent
    options = options || {};
    options.headers = options.headers || {};
    if (!options.headers['Authorization'] && DB && DB.cloudConfig && DB.cloudConfig.secret) {
      options.headers['Authorization'] = 'Bearer ' + DB.cloudConfig.secret;
    }
  }

  // Court-circuit : circuit breaker ouvert → réponse 503 silencieuse
  if (window._fbBreaker && window._fbBreaker.isOpen()) {
    return new Response('{"_offline":true,"_reason":"circuit_open"}', {
      status: 503,
      statusText: 'Backend suspendu (circuit breaker)',
      headers: { 'Content-Type': 'application/json' }
    });
  }

  try {
    // Timeout 8 sec via AbortController
    var ctrl = new AbortController();
    var timeoutId = setTimeout(function(){ ctrl.abort(); }, 8000);
    var opts = Object.assign({}, options || {}, { signal: ctrl.signal });

    // Pas d'auth Firebase à ajouter (LWS gère son auth via headers Bearer
    // depuis api/config_sync.php). Le code appelant passe les bons headers.
    var resp = await fetch(url, opts);
    clearTimeout(timeoutId);

    if (resp.ok) {
      if (window._fbBreaker) window._fbBreaker.recordSuccess();
    } else if (resp.status >= 500) {
      if (window._fbBreaker) window._fbBreaker.recordFailure();
    }
    return resp;
  } catch (e) {
    if (window._fbBreaker) window._fbBreaker.recordFailure();
    return new Response('{"_offline":true,"_reason":"' + (e.name || 'fetch_error') + '"}', {
      status: 503,
      statusText: 'Backend fetch error',
      headers: { 'Content-Type': 'application/json' }
    });
  }
}

// Pré-warming : déclencher l'auth dès le chargement de la page (avant le premier save)
// Évite la race condition au démarrage où save() est appelé avant que l'auth ne soit prête
if(FIREBASE_API_KEY && typeof window !== 'undefined'){
  setTimeout(function(){ _ensureFbAuth().catch(function(){}); }, 0);
}

let _syncTimeout = null;

window.onerror=function(msg,src,line,col,err){
  var box=document.getElementById('_errBox');
  if(!box){box=document.createElement('div');box.id='_errBox';
    box.style.cssText='position:fixed;bottom:0;left:0;right:0;background:#7f1d1d;color:#fef2f2;font-size:12px;font-family:monospace;padding:8px 12px;z-index:99999;max-height:120px;overflow-y:auto;';
    document.body.appendChild(box);}
  box.innerHTML+='<div>⚠️ '+msg+' (ligne '+line+')</div>';
  return false;
};
