// ════════════════════════════════════════════════════════════════════════
// ♿ v1.2.2 — Accessibilité clavier des éléments cliquables
// La plupart des contrôles sont des <div onclick="..."> : non focusables et non
// activables au clavier (inutilisables au lecteur d'écran / sans souris). Sans
// toucher aux 1200+ handlers, ce shim rend ces éléments focusables (tabindex +
// role="button") et activables via Entrée/Espace, y compris après chaque re-rendu.
// NB : le LIBELLÉ pour lecteur d'écran (aria-label) reste une passe à part.
// ════════════════════════════════════════════════════════════════════════
// ════════════════════════════════════════════════════════════════════════
// PREMIUM — Fallback pictogramme : les pictos « 3D » sont des IMAGES servies par
// un CDN emoji externe (em-content.zobj.net). Sur connexion lente/coupée (fréquent
// au Cameroun) l'image échoue → picto cassé. Ce listener capture l'erreur de
// chargement et remplace l'image par l'emoji natif (data-ef si fourni, sinon un
// repli neutre) → JAMAIS de picto cassé, sans toucher chaque site de rendu.
// ════════════════════════════════════════════════════════════════════════
document.addEventListener('error', function(e){
  try{
    var el=e.target;
    if(!el||el.tagName!=='IMG'||el.__ef) return;
    var em=(el.getAttribute&&el.getAttribute('data-ef'))||'';
    var src=(el.getAttribute&&el.getAttribute('src'))||'';
    // Ne traiter QUE les pictogrammes emoji (pas les vraies photos/logos).
    if(!em && src.indexOf('zobj.net')<0 && src.indexOf('em-content')<0) return;
    el.__ef=1;
    var s=document.createElement('span');
    s.textContent=em||'📦';
    s.setAttribute('aria-hidden','true');
    s.style.cssText='display:inline-flex;align-items:center;justify-content:center;font-size:1.7em;line-height:1;width:100%;height:100%';
    if(el.parentNode) el.parentNode.replaceChild(s,el);
  }catch(_e){}
}, true);

// ════════════════════════════════════════════════════════════════════════
// ÉPURE v1.3 — petits effets de DÉROULEMENT (scroll reveal). Progressive
// enhancement : si IntersectionObserver indisponible OU reduced-motion, on NE
// pose PAS html.js-reveal → rien n'est masqué (tout reste visible). Couvre le
// contenu visiteur rendu dynamiquement (MutationObserver).
// ════════════════════════════════════════════════════════════════════════
(function(){
  try{
    if(!('IntersectionObserver' in window)) return;
    if(window.matchMedia && window.matchMedia('(prefers-reduced-motion:reduce)').matches) return;
    document.documentElement.classList.add('js-reveal');
    var SEL='.vsec .card,.vsec .vcard,.vsec .sc,.vsec .vplan,.vsec .vprod-card,.vsec .vbook-card,.vsec .acc-pill,.v-hero-gradient';
    var io=new IntersectionObserver(function(entries){
      for(var i=0;i<entries.length;i++){ if(entries[i].isIntersecting){ entries[i].target.classList.add('ep-in'); io.unobserve(entries[i].target); } }
    },{ rootMargin:'0px 0px -6% 0px', threshold:0.04 });
    function obs(el){
      if(!el||el.nodeType!==1||el.__epr) return; el.__epr=1;
      // Déjà (presque) dans le viewport au moment du scan → révéler TOUT DE SUITE
      // (jamais de carte visible coincée masquée). Le scroll-reveal ne s'applique
      // qu'au contenu réellement SOUS le pli.
      try{ var r=el.getBoundingClientRect(); if(r.bottom>0 && r.top < (window.innerHeight||800)*0.98){ el.classList.add('ep-in'); return; } }catch(e){}
      io.observe(el);
    }
    function scan(root){ try{ var l=(root||document).querySelectorAll(SEL); for(var i=0;i<l.length;i++) obs(l[i]); }catch(e){} }
    function start(){
      scan(document);
      try{
        var mo=new MutationObserver(function(muts){
          for(var i=0;i<muts.length;i++){ var add=muts[i].addedNodes; for(var j=0;j<add.length;j++){ var n=add[j];
            if(n&&n.nodeType===1){ if(n.matches&&n.matches(SEL)) obs(n); scan(n); } } }
        });
        mo.observe(document.body,{childList:true,subtree:true});
      }catch(e){}
    }
    if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',start); else start();
  }catch(e){}
})();

(function(){
  var NATIVE=/^(A|BUTTON|INPUT|SELECT|TEXTAREA|LABEL|SUMMARY|OPTION)$/;
  function isNative(el){
    if(NATIVE.test(el.tagName))return true;
    if(el.tagName==='A'&&el.hasAttribute('href'))return true;
    return false;
  }
  function enhance(el){
    try{
      if(!el||el.nodeType!==1||el.__a11y)return;
      if(isNative(el))return;
      if(el.getAttribute('aria-hidden')==='true')return;   // éléments invisibles/décoratifs (ex. point d'accès admin secret) : ne pas les rendre focusables ni nommés
      if(!el.hasAttribute('tabindex'))el.setAttribute('tabindex','0');
      if(!el.hasAttribute('role'))el.setAttribute('role','button');
      el.__a11y=true;
    }catch(e){}
  }
  function sweep(root){
    try{
      var list=(root||document).querySelectorAll('[onclick]');
      for(var i=0;i<list.length;i++)enhance(list[i]);
    }catch(e){}
  }
  // Activation clavier déléguée (un seul listener, couvre tout le contenu dynamique)
  document.addEventListener('keydown',function(e){
    if(e.key!=='Enter'&&e.key!==' '&&e.key!=='Spacebar')return;
    var t=e.target;
    if(!t||t.nodeType!==1||isNative(t))return;
    if(!t.hasAttribute('onclick'))return;
    e.preventDefault();      // évite le scroll sur Espace
    t.click();
  },true);
  function start(){
    sweep(document);
    try{
      var mo=new MutationObserver(function(muts){
        for(var i=0;i<muts.length;i++){
          var added=muts[i].addedNodes;
          for(var j=0;j<added.length;j++){
            var n=added[j];
            if(!n||n.nodeType!==1)continue;
            if(n.hasAttribute&&n.hasAttribute('onclick'))enhance(n);
            if(n.querySelectorAll)sweep(n);
          }
        }
      });
      mo.observe(document.body,{childList:true,subtree:true});
    }catch(e){}
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);
  else start();
})();

// ── Polling arrière-plan : vérifie toutes les 90s si le cloud est plus récent ─
// Fonctionne même sans login admin (utilise le cache vrt10_cc si disponible)
// ── Score de richesse d'une DB (pour comparaison de contenu) ─────────────────
// Compare les données réelles, pas seulement le timestamp
function _dbScore(d){
  if(!d)return 0;
  return ((d.students||[]).length*10)
        +((d.books||[]).length*8)
        +((d.teachers||[]).length*6)
        +((d.grades||[]).length*2)
        +((d.payments||[]).length*2)
        +((d.elearning&&d.elearning.contenus||[]).length*5)
        +((d.galleryImages||[]).length*3)
        +((d.packs||[]).length*4)
        +(d.lastModified?1:0);
}

function _startBgPoll(){
  if(_bgPollTimer)return; // déjà actif
  // FIX: polling Firebase (plus de dépendance LWS sync.php)
  _bgPollTimer=setInterval(function(){
    if(!navigator.onLine)return;
    // S1 (v1.2.13) : sonder d'abord ?meta=1 (~50 o) ; ne télécharger la base
    // entière (centaines de Ko) que si le serveur a réellement changé. Évite un
    // téléchargement complet toutes les 15 s sur chaque appareil admin.
    var _metaUrl=LWS_API.db+(LWS_API.db.indexOf('?')>=0?'&':'?')+'meta=1&t='+Date.now();
    _fbFetch(_metaUrl,{}).then(function(r){return r.ok?r.json():null;}).then(function(_meta){
      var _remoteTS=(_meta&&parseInt(_meta.lastModified,10))||0;
      var _remoteSize=(_meta&&parseInt(_meta.size,10))||0;
      var _localTS=DB.lastModified||0;
      var _srvEmpty=(_remoteSize>0&&_remoteSize<1000);
      var _needFull=(_meta===null)||(_remoteTS>_localTS+3000)||(_srvEmpty&&iA()&&DB.school&&(DB.students||[]).length);
      if(!_needFull){
        // Rien de neuf côté serveur. Si NOUS sommes plus récents → push sans télécharger.
        if(iA()&&!_autoSyncDirty&&!_srvEmpty&&_localTS>_remoteTS+3000) save();
        return;
      }
      var url=LWS_API.db+'?t='+Date.now();
      _fbFetch(url,{})
      .then(function(r){return r.ok?r.json():null;})
      .then(function(serverDB){
      if(!serverDB)return;
      // Si la DB serveur est corrompue/vide (pas de school), un admin peut la restaurer
      if(!serverDB.school){
        if(iA()&&DB.school&&DB.students){
          // Push de restauration : la DB locale est complète, le serveur est vide/corrompu
          _triggerAutoSync&&_triggerAutoSync();
        }
        return;
      }
      var serverTS=serverDB.lastModified||0;
      var localTS=DB.lastModified||0;
      // Score basé UNIQUEMENT sur les données non-supprimables (élèves, livres, cours…)
      // La galerie et les notes sont EXCLUES du score pour éviter les faux "pull" après suppression
      function _scoreStable(d){
        if(!d)return 0;
        return ((d.students||[]).length*10)
              +((d.books||[]).length*8)
              +((d.teachers||[]).length*6)
              +((d.elearning&&d.elearning.contenus||[]).length*5)
              +((d.packs||[]).length*4)
              +(d.lastModified?1:0);
      }
      var serverScore=_scoreStable(serverDB);
      var localScore=_scoreStable(DB);

      // ── Décision de pull : UNIQUEMENT si le cloud est plus récent en timestamp ──
      // Ne plus se baser sur le score de galerie (faux-positif après suppression locale)
      var shouldPull=(serverTS>localTS+3000)          // cloud plus récent (timestamp fiable)
                   ||(serverScore>localScore+8);       // cloud a clairement plus d'élèves/livres/cours

      // ── Décision de push : local plus récent EN TIMESTAMP (ignore score après suppression) ──
      var shouldPush=iA()&&!_autoSyncDirty
                   &&(localTS>serverTS+3000);          // timestamp seul suffit — local est plus récent

      if(shouldPull){
        var prevCfg=DB.cloudConfig||cfg2;
        // ── Fusion intelligente des ressources ──────────────────────────
        // Les données admin (élèves, notes, paiements) : le cloud prime
        // Les ressources (livres, galerie, e-learning) : UNION des deux
        function _mergeById(localArr,serverArr){
          var merged=JSON.parse(JSON.stringify(serverArr||[]));
          var serverIds={};merged.forEach(function(x){serverIds[x.id||x.mat||x.mat2]=true;});
          (localArr||[]).forEach(function(x){
            var k=x.id||x.mat||x.mat2;
            if(k&&!serverIds[k])merged.push(x); // ajouter les items locaux absents du cloud
          });
          return merged;
        }
        // ── Fusion des images : préserver les images non-vides locales ────
        // Si le cloud a une image vide (upload échoué/strippé) mais local en a une, garder locale
        function _mergeBooks(localArr,serverArr){
          var merged=_mergeById(localArr,serverArr);
          // Construire un index des livres locaux
          var localMap={};(localArr||[]).forEach(function(b){if(b.id)localMap[b.id]=b;});
          merged.forEach(function(b){
            var loc=localMap[b.id];
            if(!loc)return;
            // coverImg : préférer une URL/data non-vide si le cloud a vide
            if((!b.coverImg||b.coverImg==='')&&loc.coverImg)b.coverImg=loc.coverImg;
            // previewPdfUrl / previewPdfKey
            if((!b.previewPdfUrl||b.previewPdfUrl==='')&&loc.previewPdfUrl)b.previewPdfUrl=loc.previewPdfUrl;
            if((!b.previewPdfKey||b.previewPdfKey==='')&&loc.previewPdfKey)b.previewPdfKey=loc.previewPdfKey;
            // previewImages : union des deux tableaux (server prime pour les URLs, local pour data:)
            if(loc.previewImages&&loc.previewImages.length>0){
              var srvImgs=b.previewImages||[];
              var extra=loc.previewImages.filter(function(img){return img&&!srvImgs.includes(img);});
              b.previewImages=(srvImgs.concat(extra)).filter(function(img){return img&&img.length>0;});
            }
          });
          return merged;
        }
        function _mergeGallery(localArr,serverArr){
          var merged=_mergeById(localArr,serverArr);
          var localMap={};(localArr||[]).forEach(function(g){if(g.id)localMap[g.id]=g;});
          merged.forEach(function(g){
            var loc=localMap[g.id];
            if(!loc)return;
            // src : préférer non-vide si cloud a vide
            if((!g.src||g.src==='')&&loc.src)g.src=loc.src;
          });
          return merged;
        }
        // Sauvegarder les ressources locales avant écrasement
        var localBooks=DB.books||[];
        var localGallery=DB.galleryImages||[];
        var localElearn=(DB.elearning&&DB.elearning.contenus)||[];
        var localPacks=DB.packs||[];
        var localCitations=DB.citations||[];
        // FIX : préserver les suppressions locales (jeux, labos, cartes, produits)
        var _localDel={
          dj:(DB.deletedJeux||[]).slice(), pj:(DB.purgedJeux||[]).slice(),
          dd:(DB.deletedDefaults||[]).slice(), hl:(DB.hiddenLabos||[]).slice(),
          pl:(DB.purgedLabos||[]).slice(), dc:(DB.deletedCartes||[]).slice(),
          dp:(DB.deletedProducts||[]).slice()
        };
        // BUG-03 FIX : ne remplacer DB que si l'utilisateur est admin
        if(!iA()){return;}
        // Remplacer par la version cloud (données admin)
        DB=serverDB;
        // Re-injecter les suppressions locales (union avec cloud)
        function _uIds(a,b){var s={};(a||[]).forEach(function(x){s[x]=1;});(b||[]).forEach(function(x){s[x]=1;});return Object.keys(s);}
        DB.deletedJeux=_uIds(_localDel.dj,DB.deletedJeux);
        DB.purgedJeux=_uIds(_localDel.pj,DB.purgedJeux);
        DB.deletedDefaults=_uIds(_localDel.dd,DB.deletedDefaults);
        DB.hiddenLabos=_uIds(_localDel.hl,DB.hiddenLabos);
        DB.purgedLabos=_uIds(_localDel.pl,DB.purgedLabos);
        DB.deletedCartes=_uIds(_localDel.dc,DB.deletedCartes);
        DB.deletedProducts=_uIds(_localDel.dp,DB.deletedProducts);
        // BUG-03/BUG-09 FIX : re-run migration pour garantir tous les champs v1.2
        _migrateDB();
        // Fusionner les ressources
        DB.books=_mergeBooks(localBooks,DB.books);
        DB.galleryImages=_mergeGallery(localGallery,DB.galleryImages);
        if(!DB.elearning)DB.elearning={contenus:[],plans:[],abonnements:[],commandes:[],soumissions:[]};
        DB.elearning.contenus=_mergeById(localElearn,DB.elearning.contenus);
        DB.packs=_mergeById(localPacks,DB.packs);
        DB.citations=_mergeById(localCitations,DB.citations);
        // Restaurer la config cloud locale
        if(!DB.cloudConfig||!DB.cloudConfig.url)DB.cloudConfig=prevCfg;
        DB.cloudConfig.lastSync=new Date().toLocaleString('fr-FR')+' ↓';
        save();
        _saveCloudConfigCache();
        _setSyncDot&&_setSyncDot('ok',DB.cloudConfig.lastSync);
        // Si admin connecté : re-pousser la fusion vers Firebase (pour que l'autre appareil en bénéficie)
        // save() est debounced 800ms et pousse vers Firebase via PUT
        if(iA()){setTimeout(function(){save();},5000);}
        toast('🔄 Données synchronisées et fusionnées','info');
        if(typeof re==='function')setTimeout(re,600);
      } else if(shouldPush){
        // Push local plus récent vers Firebase via save() (toujours PUT, jamais sync.php)
        save();
      }
      })
      .catch(function(){});
    }).catch(function(){});
  },15000); // ── v1.2 sync v2 : 15s ; allégé en v1.2.13 (meta-first, S1) ──
}

// ═══════════════════════════════════════════════════════════════════════════
// VERITAS_SYNC_V2 — Module de synchronisation définitive (v1.2)
// ═══════════════════════════════════════════════════════════════════════════
// Couches ajoutées par-dessus le polling existant :
//   1. Sync au focus (Page Visibility API) → instantané quand on revient sur l'onglet
//   2. Auto-retry des uploads binaires en tâche de fond (60s)
//   3. Toast "🔄 Mis à jour" quand un autre appareil push
//   4. Modal diagnostic mSyncDiag() accessible depuis Paramètres
//   5. Polling adaptatif : 5s sur dashboard actif, 15s en arrière-plan
// ═══════════════════════════════════════════════════════════════════════════
(function initSyncV2(){
  if(window.__veritasSyncV2Loaded)return;
  window.__veritasSyncV2Loaded=true;

  // ── 1. Sync au focus de l'onglet (Page Visibility API) ──────────────────────
  document.addEventListener('visibilitychange',function(){
    if(document.visibilityState==='visible' && navigator.onLine){
      // Force un poll immédiat dès que l'utilisateur revient sur l'onglet
      setTimeout(function(){
        if(typeof _bgPollTimer!=='undefined' && _bgPollTimer){
          // Déclencher manuellement la logique du poll
          var url=(typeof LWS_API!=='undefined' && LWS_API.db)?(LWS_API.db+'?t='+Date.now()):null;
          if(!url || typeof _fbFetch!=='function')return;
          _fbFetch(url,{}).then(function(r){return r.ok?r.json():null;}).then(function(serverDB){
            if(!serverDB || !serverDB.lastModified)return;
            if(serverDB.lastModified > (DB.lastModified||0)+3000){
              if(typeof toast==='function') toast('🔄 Mise à jour depuis un autre appareil...','info');
              if(typeof _triggerAutoSync==='function') setTimeout(function(){location.reload();},1500);
            }
          }).catch(function(){});
        }
      },400);
    }
  });

  // ── 2. Auto-retry uploads binaires toutes les 60s ───────────────────────────
  var _retryUploadTimer=null;
  function _startRetryUpload(){
    if(_retryUploadTimer) return;
    _retryUploadTimer=setInterval(function(){
      if(!navigator.onLine)return;
      if(typeof iA!=='function' || !iA())return;
      if(typeof _hasLocalBinaries!=='function')return;
      if(_hasLocalBinaries()){
        if(typeof _cloudAutoUploadBinaries==='function'){
          console.log('[SyncV2] Retry upload binaires locaux...');
          _cloudAutoUploadBinaries(function(){
            if(typeof _triggerAutoSync==='function') _triggerAutoSync();
          });
        }
      }
    },60000);
  }
  setTimeout(_startRetryUpload, 12000); // démarrer 12s après chargement

  // ── 3. Notifier les pulls (un autre appareil a poussé) ──────────────────────
  // Hook sur l'événement de pull en interceptant _setSyncDot('ok') après pull
  if(typeof window.__syncV2_pullCount==='undefined') window.__syncV2_pullCount=0;
  var _origRe=window.re;
  window._syncV2_notifyPull=function(){
    window.__syncV2_pullCount++;
    if(typeof toast==='function') toast('🔄 Données synchronisées (cloud)','success');
  };

  // ── 4. Helper pour mSyncDiag — Modal Diagnostic ─────────────────────────────
  window.mSyncDiag=function(){
    if(typeof M!=='function') return;
    var body='<div class="ib ibt mb14"><span>🔍</span><span>Test des 4 canaux de synchronisation. Patientez...</span></div>'+
      '<div id="syncDiagResults" style="display:grid;gap:8px"></div>';
    M('🔍 Diagnostic Synchronisation','Test complet en cours...',body,
      '<button class="btn bo" onclick="cm()">Fermer</button>',true);

    // Tester chaque canal
    var results=document.getElementById('syncDiagResults');
    function logResult(label,status,detail){
      if(!results) return;
      var iconMap={ok:'✅',warn:'⚠️',err:'❌',pending:'⏳'};
      var colorMap={ok:'#3A8F73',warn:'#F59E0B',err:'#AE5353',pending:'#64748B'};
      var div=document.createElement('div');
      div.style.cssText='display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:10px;background:#F8FAFC;font-size:13px';
      div.innerHTML='<span style="font-size:20px">'+iconMap[status]+'</span>'+
        '<div style="flex:1"><div style="font-weight:700;color:#142554">'+label+'</div>'+
        '<div style="font-size:11px;color:#64748B;margin-top:2px">'+(detail||'')+'</div></div>';
      results.appendChild(div);
    }

    // Test 1 : Firebase READ
    logResult('Test 1/5 : Firebase READ (lecture DB)','pending','En cours...');
    fetch(LWS_API.db+'?t='+Date.now()).then(function(r){
      results.lastChild.remove();
      if(r.ok){
        return r.json().then(function(j){
          var size=JSON.stringify(j||{}).length;
          logResult('Firebase READ ✓','ok','Lecture OK ('+Math.round(size/1024)+' KB · '+(j&&j.students?j.students.length:0)+' élèves)');
        });
      }
      logResult('Firebase READ','err','HTTP '+r.status);
    }).catch(function(e){
      results.lastChild.remove();
      logResult('Firebase READ','err','Erreur réseau : '+e.message);
    });

    // Test 2 : Firebase WRITE
    setTimeout(function(){
      logResult('Test 2/5 : Firebase WRITE (écriture test)','pending','Push d\'un objet test...');
      var testKey='_syncTest_'+Date.now();
      var testUrl=LWS_API.db.replace('/db.json','/'+testKey+'.json');
      _fbFetch(testUrl,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({ok:true,t:Date.now()})}).then(function(r){
        results.lastChild.remove();
        if(r.ok){
          logResult('Firebase WRITE ✓','ok','Écriture OK · Auth fonctionne');
          // Nettoyer le test
          _fbFetch(testUrl,{method:'DELETE'}).catch(function(){});
        } else {
          logResult('Firebase WRITE','err','HTTP '+r.status+(r.status===401?' (auth Firebase échouée)':''));
        }
      }).catch(function(e){
        results.lastChild.remove();
        logResult('Firebase WRITE','err','Erreur : '+e.message);
      });
    },1500);

    // Test 3 : LWS db.php (backup secondaire)
    setTimeout(function(){
      logResult('Test 3/5 : LWS db.php (backup)','pending','Connexion LWS...');
      var cfg=DB.cloudConfig||{};
      if(!cfg.url||!cfg.secret){
        results.lastChild.remove();
        logResult('LWS db.php','warn','Non configuré (Paramètres → Cloud)');
        return;
      }
      fetch(cfg.url.replace(/\/+$/,'')+'/db.php?t='+Date.now(),{
        headers:{'Authorization':'Bearer '+cfg.secret}
      }).then(function(r){
        results.lastChild.remove();
        if(r.ok){logResult('LWS db.php ✓','ok','Backup secondaire opérationnel');}
        else if(r.status===401){logResult('LWS db.php','warn','Token API invalide (vérifiez Cloud → secret)');}
        else {logResult('LWS db.php','err','HTTP '+r.status);}
      }).catch(function(e){
        results.lastChild.remove();
        logResult('LWS db.php','err','Erreur réseau : '+e.message);
      });
    },3000);

    // Test 4 : LWS upload.php (upload fichiers)
    setTimeout(function(){
      logResult('Test 4/5 : LWS upload.php','pending','Test endpoint upload...');
      var cfg=DB.cloudConfig||{};
      if(!cfg.url||!cfg.secret){
        results.lastChild.remove();
        logResult('LWS upload.php','warn','Non configuré');
        return;
      }
      // POST OPTIONS (sans envoyer de fichier)
      fetch(cfg.url.replace(/\/+$/,'')+'/upload.php',{
        method:'OPTIONS',
        headers:{'Authorization':'Bearer '+cfg.secret}
      }).then(function(r){
        results.lastChild.remove();
        if(r.ok || r.status===204 || r.status===405){logResult('LWS upload.php ✓','ok','Endpoint joignable');}
        else {logResult('LWS upload.php','err','HTTP '+r.status);}
      }).catch(function(e){
        results.lastChild.remove();
        logResult('LWS upload.php','err','Erreur : '+e.message);
      });
    },4500);

    // Test 5 : État local
    setTimeout(function(){
      var hasLocal=(typeof _hasLocalBinaries==='function' && _hasLocalBinaries())?'OUI':'NON';
      var lastSync=DB.cloudConfig&&DB.cloudConfig.lastSync||'Jamais';
      var pollOK=(typeof _bgPollTimer!=='undefined' && _bgPollTimer)?'Actif (15s)':'INACTIF';
      var dirty=(typeof _autoSyncDirty!=='undefined' && _autoSyncDirty)?'OUI':'NON';
      var size=Math.round(JSON.stringify(DB).length/1024);
      var nStu=(DB.students||[]).length;
      var nBooks=(DB.books||[]).length;
      logResult('Test 5/5 : État local','ok',
        'Polling: '+pollOK+' | Binaires en attente: '+hasLocal+' | Modif en attente: '+dirty+'<br>'+
        'Taille DB: '+size+' KB | '+nStu+' élèves · '+nBooks+' livres | Dernière sync: '+lastSync);
    },6000);

    // Conclusion
    setTimeout(function(){
      var div=document.createElement('div');
      div.style.cssText='margin-top:14px;padding:14px 18px;background:linear-gradient(135deg,#F0FDF4,#DCFCE7);border-radius:12px;border:1px solid #86EFAC;font-size:13px;color:#065F46;line-height:1.6';
      div.innerHTML='<strong>🛠️ Si un test échoue :</strong><br>'+
        '• <strong>Firebase WRITE 401</strong> → règles Firebase trop strictes (modifier dans console Firebase)<br>'+
        '• <strong>LWS 401</strong> → token incohérent entre <code>DB.cloudConfig.secret</code> et <code>config_sync.php</code><br>'+
        '• <strong>LWS HTTP 500</strong> → vérifier <code>api/data/</code> avec permissions 755<br>'+
        '• <strong>Polling inactif</strong> → recharger la page (Ctrl+Shift+R)';
      results.appendChild(div);
    },7000);
  };

  console.log('[SyncV2] Module initialisé : polling 15s + focus sync + retry uploads + diagnostic');

  // ── 6. Indicateur online/offline flottant (UX) ──────────────────────────────
  function _ensureOnlineIndicator(){
    var ind=document.getElementById('vgzOnlineIndicator');
    if(!ind){
      ind=document.createElement('div');
      ind.id='vgzOnlineIndicator';
      ind.className='vgz-online-indicator '+(navigator.onLine?'online':'offline');
      ind.innerHTML='<span class="dot"></span><span class="lbl">'+(navigator.onLine?'En ligne':'Hors ligne')+'</span>';
      ind.style.opacity='0';
      ind.style.transform='translateY(-10px)';
      document.body.appendChild(ind);
      // Afficher seulement 3s à l'apparition, puis cacher (sauf si offline)
      setTimeout(function(){
        ind.style.transition='opacity .4s,transform .4s';
        ind.style.opacity='1';
        ind.style.transform='translateY(0)';
      },300);
      if(navigator.onLine){
        setTimeout(function(){ind.style.opacity='0';ind.style.transform='translateY(-10px)';},3500);
      }
    }
    return ind;
  }
  function _updateOnlineIndicator(){
    var ind=_ensureOnlineIndicator();
    var online=navigator.onLine;
    ind.className='vgz-online-indicator '+(online?'online':'offline');
    ind.querySelector('.lbl').textContent=online?'En ligne':'Hors ligne';
    ind.style.opacity='1';
    ind.style.transform='translateY(0)';
    if(online){
      setTimeout(function(){ind.style.opacity='0';ind.style.transform='translateY(-10px)';},2500);
    }
  }
  window.addEventListener('online',_updateOnlineIndicator);
  window.addEventListener('offline',_updateOnlineIndicator);
  setTimeout(_ensureOnlineIndicator,2000);
})();

function _triggerAutoSync(){
  if(!iA())return; // admins seulement
  var cfg=DB.cloudConfig;
  if(!cfg||!cfg.url||!cfg.secret)return; // pas configuré
  _autoSyncDirty=true;
  _setSyncDot('pending');
  if(_autoSyncTimer)clearTimeout(_autoSyncTimer);
  _autoSyncTimer=setTimeout(function(){
    _autoSyncTimer=null;
    if(_autoSyncDirty)_cloudAutoSync();
  },2000); // 2 secondes — assez court pour battre le bg poll (30s)
}

function _cloudAutoSync(){
  if(!iA())return;
  var cfg=DB.cloudConfig;
  if(!cfg||!cfg.url||!cfg.secret)return;
  _autoSyncDirty=false;
  _setSyncDot('syncing');

  // ── Étape 1 : uploader TOUS les binaires locaux d'abord ──────────────────
  if(_hasLocalBinaries()){
    _cloudAutoUploadBinaries(function(uploaded){
      // Quelle que soit l'issue (succès ou échec partiel) : pousser la DB
      // avec les URLs serveur qui ont pu être obtenus. Les binaires restés
      // locaux seront retentés au prochain save(). (pas de boucle infinie)
      _cloudAutoSyncPush();
    });
    return;
  }
  _cloudAutoSyncPush();
}

// ── Push DB vers cloud (sans binaires, avec retry) ────────────────────────────
function _cloudAutoSyncPush(attempt){
  attempt=attempt||1;
  var cfg=DB.cloudConfig;
  if(!cfg||!cfg.url||!cfg.secret){_setSyncDot('err');return;}

  var data=JSON.parse(JSON.stringify(DB));
  // Stripping binaires
  if(data.introVideo&&data.introVideo.src&&data.introVideo.src.startsWith('data:'))data.introVideo.src='';
  var _AL=273000; // seuil uniforme 200 Ko
  if(data.school&&data.school.logo&&data.school.logo.startsWith('data:')&&data.school.logo.length>_AL)data.school.logo='';
  if(data.elearning&&data.elearning.contenus)data.elearning.contenus.forEach(function(c){if(c.fichierData&&c.fichierData.length>_AL)c.fichierData='';});
  if(data.elearning&&data.elearning.soumissions)data.elearning.soumissions.forEach(function(s){if(s.fichierData&&!s.fichierUrl&&s.fichierData.length>_AL)s.fichierData='';});
  if(data.devoirs)data.devoirs.forEach(function(d){if(d.fichierData&&!d.fichierUrl&&d.fichierData.length>_AL)d.fichierData='';});
  if(data.partenaires)data.partenaires.forEach(function(p){if(p.logo&&p.logo.startsWith('data:')&&p.logo.length>_AL)p.logo='';});
  if(data.books)data.books.forEach(function(b){
    // Couvertures : seuil 200 KB (273 000 chars) pour ne pas effacer les JPEG légères
    if(b.coverImg&&b.coverImg.startsWith('data:')&&b.coverImg.length>273000)b.coverImg='';
    if(b.fichierKey){if(b.fichierData)b.fichierData='';b.fichierKey='';}
    // Strip previewImages data URLs (si upload a échoué) pour éviter payload surdimensionné
    if(b.previewImages){
      b.previewImages=b.previewImages.map(function(img){
        return (img&&img.startsWith('data:')&&img.length>273000)?'':img;
      }).filter(function(img){return img&&img.length>0;});
    }
  });
  if(data.galleryImages)data.galleryImages.forEach(function(img){
    if(img.src&&img.src.startsWith('data:')&&img.src.length>_AL)img.src=img.serverSrc||'';
  });

  // Strip plain passwords avant push Firebase (garder pwdHash bcrypt one-way)
  function _stripPlainPwdFb(o){
    if(!o)return;
    if(o.pwd && !(typeof o.pwd==='string' && o.pwd.startsWith('$'))) delete o.pwd;
  }
  if(data.superAdmin)_stripPlainPwdFb(data.superAdmin);
  (data.admins||[]).forEach(_stripPlainPwdFb);
  (data.visitorAccounts||[]).forEach(_stripPlainPwdFb);
  if(data.tpwd)data.tpwd={};

  // Timeout 15s pour éviter les blocages
  var ctrl=typeof AbortController!=='undefined'?new AbortController():null;
  var tmt=ctrl?setTimeout(function(){ctrl.abort();},15000):null;

  // FIX: PUT Firebase au lieu de POST sync.php (LWS) — sync multi-appareils fiable
  _fbFetch(LWS_API.db,{
    method:'PUT',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify(data),
    signal:ctrl?ctrl.signal:undefined
  })
  .then(function(r){
    if(tmt)clearTimeout(tmt);
    if(!r.ok)throw new Error('HTTP '+r.status+(r.status===413?' (données trop volumineuses)':r.status===401?' (clé API invalide)':''));
    // Firebase retourne l'objet PUT en succès — pas besoin de parser
    return {saved_at:new Date().toLocaleString('fr-FR')};
  })
  .then(function(res){
    if(res.error)throw new Error(res.error);
    var dateSync=res.saved_at||new Date().toLocaleString('fr-FR');
    DB.cloudConfig.lastSync=dateSync;
    window._fbLastSyncedMs=DB.lastModified||Date.now();
    _saveCloudConfigCache(); // mettre à jour le cache pour le téléphone
    _syncRetryCount=0;
    try{localStorage.setItem('vrt10',JSON.stringify(DB));}catch(e){}
    _setSyncDot('ok',dateSync);
  })
  .catch(function(e){
    if(tmt)clearTimeout(tmt);
    var msg=e.message||'Erreur inconnue';
    var isNetwork=msg.indexOf('fetch')<0?false:true;
    console.warn('[VÉRITAS auto-sync] Tentative '+attempt+' échouée :', msg);

    if(attempt<3){
      // Retry avec backoff exponentiel : 8s, 16s
      var delay=attempt*8000;
      _syncRetryCount=attempt;
      _setSyncDot('pending','Retry '+attempt+'/3 dans '+(delay/1000)+'s…');
      if(_syncRetryTimer)clearTimeout(_syncRetryTimer);
      _syncRetryTimer=setTimeout(function(){_cloudAutoSyncPush(attempt+1);},delay);
    } else {
      // Toutes les tentatives épuisées → marquer dirty pour reessai au prochain save
      _syncRetryCount=0;
      _autoSyncDirty=true;
      _setSyncDot('err','Sync échouée ('+msg+')');
      // Écouter le retour de connexion
      _addOnlineListener();
    }
  });
}

// ── Retry automatique quand la connexion revient ──────────────────────────────
function _addOnlineListener(){
  if(_onlineListenerAdded)return;
  _onlineListenerAdded=true;
  window.addEventListener('online',function(){
    if(_autoSyncDirty&&iA()){
      _setSyncDot('pending','Connexion rétablie — sync…');
      setTimeout(function(){_autoSyncDirty=true;_cloudAutoSync();},2000);
    }
  });
}

function _setSyncDot(state,label){
  var dot=document.getElementById('vSyncDot');
  if(!dot)return;
  var cfg={
    pending: {bg:'#FFC93C',title:'Modifications non synchronisées',ico:'⏳'},
    syncing: {bg:'#87A9D3',title:'Synchronisation en cours…',ico:'🔄'},
    ok:      {bg:'#5CAB8E',title:'Synchronisé'+(label?' — '+label:''),ico:'✓'},
    err:     {bg:'#D58E8E',title:'Échec de la synchronisation'+(label?' — '+label:''),ico:'⚠'}
  }[state]||{bg:'#9CA3AF',title:'',ico:'?'};
  dot.style.background=cfg.bg;
  dot.title=cfg.title;
  dot.textContent=cfg.ico;
  dot.style.display=iA()?'inline-flex':'none';
  // Stocker l'état pour le menu
  window._lastSyncState=state;
  window._lastSyncLabel=label||'';
}
// ── Menu de synchronisation (clic sur la pastille) ─────────────────
function mSyncMenu(){
  if(!iA())return;
  var cfg=DB.cloudConfig||{};
  var st=window._lastSyncState||'?';
  var stLbl={pending:'⏳ Non synchronisé',syncing:'🔄 En cours…',ok:'✅ Synchronisé',err:'⚠️ Échec'}[st]||'État inconnu';
  var lastSync=cfg.lastSync||'jamais';
  M("🔄 Synchronisation Cloud","Gérez la synchronisation manuellement",
    "<div style='background:var(--bg);border-radius:12px;padding:14px;margin-bottom:14px'>"
    +"<div style='font-size:11px;color:var(--ink4);margin-bottom:4px'>État actuel</div>"
    +"<div style='font-family:Montserrat,sans-serif;font-size:14px;font-weight:700;color:var(--bl)'>"+stLbl+"</div>"
    +(window._lastSyncLabel?"<div style='font-size:11px;color:#AE5353;margin-top:4px'>"+_esc(window._lastSyncLabel)+"</div>":"")
    +"<div style='font-size:11px;color:var(--ink4);margin-top:8px'>Dernière sync : "+_esc(lastSync)+"</div>"
    +"<div style='font-size:11px;color:var(--ink4)'>Cloud : "+(cfg.url?_esc(cfg.url):"<span style='color:#AE5353'>non configuré</span>")+"</div>"
    +"</div>"
    +"<div class='ib ibt mb12'><span>💡</span><span>Astuce : la sync automatique se déclenche 8s après chaque modification. Utilisez ces boutons en cas de problème.</span></div>"
    +"<div style='display:grid;grid-template-columns:1fr 1fr;gap:8px'>"
    +"<button class='btn bi sm' onclick='cm();_autoSyncDirty=true;_cloudAutoSync();toast(\"⬆️ Synchronisation lancée…\")'><svg class='vico bico' aria-hidden='true'><use href='#lc-upload'/></svg>Pousser maintenant</button>"
    +"<button class='btn sm' style='background:#6D28D9;color:#fff' onclick='cm();cloudForcePull&&cloudForcePull()'><svg class='vico bico' aria-hidden='true'><use href='#lc-download'/></svg>Récupérer du cloud</button>"
    +"<button class='btn sm' style='background:#065F46;color:#fff' onclick='cm();cloudSyncBinaries&&cloudSyncBinaries()'><svg class='vico bico' aria-hidden='true'><use href='#lc-refresh'/></svg>Sync fichiers locaux</button>"
    +"<button class='btn sm' style='background:#1E3A8A;color:#fff' onclick='cm();mCloudFilesList&&mCloudFilesList()'><svg class='vico bico' aria-hidden='true'><use href='#lc-package'/></svg>Fichiers en ligne</button>"
    +"<button class='btn sm' style='background:#B45309;color:#fff' onclick='mStorageDiag()'><svg class='vico bico' aria-hidden='true'><use href='#lc-chart'/></svg>Diagnostiquer stockage</button>"
    +"<button class='btn sm' style='background:#7F1D1D;color:#fff' onclick='_purgeLocalBinaries()'><svg class='vico bico' aria-hidden='true'><use href='#lc-trash'/></svg>Libérer espace local</button>"
    +"</div>",
    "<button class='btn bo' onclick='cm()'>Fermer</button>");
}

// ── Diagnostic de l'espace localStorage ────────────────────────────────────
function mStorageDiag(){
  var total=0;
  var rows=[];
  try{
    var raw=localStorage.getItem('vrt10');
    if(raw){
      var d=JSON.parse(raw);
      var cat=function(label,val){
        var ko=_strKo(JSON.stringify(val));
        if(ko>0)rows.push({label:label,ko:ko});
        total+=ko;
      };
      cat('Intro vidéo',d.introVideo);
      cat('Logo école',d.school&&d.school.logo);
      cat('Galerie photos',(d.galleryImages||[]).map(function(g){return g.src||'';}));
      cat('Partenaires logos',(d.partenaires||[]).map(function(p){return p.logo||'';}));
      cat('Livres (couv+data)',(d.books||[]).map(function(b){return (b.coverImg||'')+(b.fichierData||'');}));
      cat('E-learning fichiers',(d.elearning&&d.elearning.contenus||[]).map(function(c){return c.fichierData||'';}));
      cat('Élèves',d.students);
      cat('Notes',d.grades);
      cat('Paiements',d.payments);
      cat('Autres',d);
    }
  }catch(e){rows=[{label:'Erreur lecture',ko:0}];}
  rows.sort(function(a,b){return b.ko-a.ko;});
  var bar=function(ko){var pct=Math.min(100,Math.round(ko/51.2));return '<div style="height:6px;background:#E5E7EB;border-radius:3px;margin-top:2px"><div style="height:6px;background:'+(pct>60?'#AE5353':pct>30?'#D97706':'#059669')+';border-radius:3px;width:'+pct+'%"></div></div>';};
  var html='<div style="font-size:11px;color:var(--ink4);margin-bottom:10px">Quota localStorage ≈ 5 Mo (5 120 Ko) · Utilisé : <b>'+fmtN(total)+' Ko</b></div>';
  html+='<div style="max-height:260px;overflow-y:auto">';
  rows.forEach(function(r){html+='<div style="margin-bottom:6px"><div style="display:flex;justify-content:space-between"><span style="font-size:12px">'+_esc(r.label)+'</span><b style="font-size:12px">'+fmtN(r.ko)+' Ko</b></div>'+bar(r.ko)+'</div>';});
  html+='</div>';
  if(total>4000)html+='<div class="ib ibt" style="margin-top:10px;background:#FEF2F2;border-color:#AE5353"><span>⚠️</span><span>Stockage presque plein. Cliquez "Libérer espace local" pour supprimer les images binaires du cache local (elles restent sur le serveur).</span></div>';
  cm();
  M('📊 Diagnostic Stockage','Utilisation du cache local navigateur',html,'<button class="btn bi" onclick="cm()">OK</button>');
}

// ── Purge d'urgence : supprime toutes les data-URLs du localStorage ─────────
function _purgeLocalBinaries(silent){
  if(!silent&&!confirm('Supprimer toutes les images/vidéos du cache local ?\nElles restent sur le serveur et seront rechargées au prochain lancement.'))return;
  try{
    // BUG-02 FIX : muter DB en mémoire en place, sans remplacer depuis localStorage
    // (localStorage = snapshot sans données non-sauvegardées — toujours muter le live DB)
    var _clear=function(s){return(_isHeavyData(s)?'':s);};
    if(DB.school)DB.school.logo=_clear(DB.school.logo);
    if(DB.introVideo)DB.introVideo.src=_clear(DB.introVideo.src);
    (DB.galleryImages||[]).forEach(function(g){g.src=_clear(g.src);});
    (DB.partenaires||[]).forEach(function(p){p.logo=_clear(p.logo);});
    (DB.books||[]).forEach(function(b){
      b.coverImg=_clear(b.coverImg);
      b.fichierData=_clear(b.fichierData);
      if(b.previewImages)b.previewImages=b.previewImages.map(_clear);
    });
    (DB.elearning&&DB.elearning.contenus||[]).forEach(function(c){c.fichierData=_clear(c.fichierData);});
    (DB.students||[]).forEach(function(s){s.photo=_clear(s.photo);});
    (DB.teachers||[]).forEach(function(t){t.photo=_clear(t.photo);});
    save(); // persiste DB muté (toutes données non-binaires préservées)
    if(!silent){toast('✓ Espace libéré — images supprimées localement','ok');cm();}
  }catch(e){toast('Erreur: '+e.message,'err');}
}
function gid(){return Math.random().toString(36).slice(2,10);}
function today(){return new Date().toLocaleDateString('fr-FR');}
function starsHtml(n){var h='';for(var i=1;i<=5;i++)h+=i<=Math.round(n)?'<span class="star">'+ICO('lc-star','i vt-star on')+'</span>':'<span class="star-off">'+ICO('lc-star','i vt-star')+'</span>';return h;}
function getBookRating(bid){var rvs=(DB.bookReviews||[]).filter(function(r){return r.bid===bid;});if(!rvs.length)return{avg:0,count:0};var avg=rvs.reduce(function(s,r){return s+r.stars;},0)/rvs.length;return{avg:avg,count:rvs.length};}

function fmt(n){return new Intl.NumberFormat('fr-FR').format(n)+' FCFA';}
function fmtN(n){return new Intl.NumberFormat('fr-FR').format(n);}

// Numéro camerounais présentable. La fiche contact publique affichait
// « 671469236 » (espace parasite en tête, pas d'indicatif) : illisible et
// non composable depuis l'étranger, sur la page même où l'on demande au
// parent d'appeler. Rendu : +237 6 71 46 92 36. Toute valeur non reconnue
// est renvoyée telle quelle (simplement détourée) — jamais de perte.
function _fmtTel(t){
  if(!t) return '';
  var brut = String(t).trim();
  var d = brut.replace(/[^0-9]/g, '');
  if(d.length === 9 && d.charAt(0) === '6') d = '237' + d;          // national → international
  if(d.length === 12 && d.indexOf('237') === 0){
    var n = d.slice(3);
    return '+237 ' + n.charAt(0) + ' ' + n.slice(1,3) + ' ' + n.slice(3,5) + ' ' + n.slice(5,7) + ' ' + n.slice(7,9);
  }
  return brut;
}
window._fmtTel = _fmtTel;
function S(id){return DB.students.find(s=>s.id===id||s.mat===id);}
// Moyenne d'une matière, ROBUSTE au type : coerce n1/n2 en nombres (évite la
// concaténation de chaînes "12"+"8"="128"/2=64 si les notes arrivent en texte —
// ex. lecture future depuis MySQL où PDO renvoie les DECIMAL en string). Si une
// seule note est présente, on l'utilise ; si aucune, 0 (au lieu de NaN). Pour des
// nombres propres (saisie normale), le résultat est STRICTEMENT identique à avant.
function _subMoy(g){ if(!g)return 0; var a=+g.n1, b=+g.n2; if(isNaN(a)&&isNaN(b))return 0; if(isNaN(a))return b; if(isNaN(b))return a; return (a+b)/2; }
function SN(nom){return DB.students.find(s=>s.pre+' '+s.nom===nom);}
function T(id){return DB.teachers.find(t=>t.id===id);}
function tp(id,btn){const i=$(id);i.type=i.type==='password'?'text':'password';btn.textContent=i.type==='password'?'👁':'🙈';}
function getLogo(){return DB.school?.logo||LOGO_B64;}
function getWatermark(){return WATERMARK_B64||getLogo();}

function _watermarkHtml(){
  var wm=getWatermark();if(!wm)return '';
  return '<div style="position:absolute;top:0;left:0;right:0;bottom:0;pointer-events:none;z-index:0;overflow:hidden;display:flex;flex-wrap:wrap;align-items:center;justify-content:center;align-content:center;opacity:0.07">'
    +'<img src="'+wm+'" style="width:480px;height:480px;object-fit:contain">'
    +'</div>';
}
function wu(tel,msg){let p=(tel||'').replace(/[\s\-\(\)]/g,'');if(p&&!p.startsWith('+'))p='+237'+p;return'https://wa.me/'+(p?p.replace('+',''):'')+'?text='+encodeURIComponent(msg);}
function wb(html){return`<div class="wabg"><div class="wab">${html}</div><div style="font-size:13px;color:var(--ink4);text-align:right;margin-top:6px">📱 Aperçu WhatsApp</div></div>`;}
function na(){return`<div class="empty"><div class="empty-ico">🔒</div><div class="semi mb8">Accès restreint</div><div class="s mut">Vous n\'avez pas accès à cette section</div></div>`;}
function iA(){return SES?.type==='admin'||SES?.type==='superadmin';}
function isSA(){return SES?.type==='superadmin';}
function isEleve(){return SES?.type==='eleve';}
function isEnseignant(){return SES?.type==='enseignant';}

// ─── PORTAIL VISITEUR ────────────────────────────
/* ÉCRAN INTERMÉDIAIRE SUPPRIMÉ (v1.15.8). Le parcours faisait : fiche →
   formulaire (nom / téléphone / code promo) → modal de paiement. Or l'étape ①
   du modal, « Vos coordonnées », demande EXACTEMENT la même chose : payNom,
   payTel, payEmail et promoInput + appliquerPromo(). Le visiteur saisissait
   donc deux fois, et chaque écran supplémentaire avant l'encaissement est un
   endroit où il abandonne.
   Le produit numérique n'a pas d'adresse de livraison : rien ne justifiait cet
   écran. On enregistre la commande et on ouvre le paiement directement.
   ⚠️ Le parcours MANUEL PAPIER garde son formulaire — lui collecte une adresse
   de livraison, que le modal de paiement ne demande pas. */
function visitorOrderProduct(title,price){
  var ses=(typeof SES!=='undefined'&&SES)?SES:null;
  var nom=ses?((ses.pre||'')+' '+(ses.nom||'')).trim():'';
  var tel=ses?(ses.tel||''):'';
  if(!DB.visitorOrders)DB.visitorOrders=[];
  // Le prix stocké est le prix CATALOGUE : la remise éventuelle est appliquée
  // dans le modal (appliquerPromo) et c'est DB.payAttempts qui porte le montant
  // réellement encaissé — la source de vérité pour la comptabilité.
  var cmd={id:gid(),bookTitle:title,nom:nom,tel:tel,date:today(),statut:'En attente',prix:price,promo:''};
  DB.visitorOrders.push(cmd);
  save();
  if(typeof openPaymentModal!=='function'||!(price>0)){toast('✓ Commande enregistrée');return;}
  openPaymentModal({
    montant:price, label:'🛒 '+title, refPrefix:'SHOP',
    intent:'product', targetId:cmd.id,
    customerAccountId:ses?(ses.accountId||ses.id):null,
    customerNom:nom, customerTel:tel
  });
}
/* confirmProductOrder RETIRÉE (v1.15.9) — code mort. Elle servait l'écran
   intermédiaire supprimé au commit précédent ; plus aucun appelant depuis que
   visitorOrderProduct ouvre le paiement directement. Elle lisait vpNom/vpTel/
   vpPromo, des champs qui n'existent plus dans le DOM. */

function visitorOrderBook(bid){
  var autoPromo=(typeof SES!=='undefined'&&SES&&SES.type==='eleve')?'ELEVE10':'';

  const b=DB.books.find(x=>x.id===bid);if(!b)return;
  if(b.stock<=0){toast('Ce manuel est en rupture de stock','warn');return;}
  // Un visiteur connecté ne doit pas retaper ce que le compte sait déjà : seule
  // l'adresse de livraison reste réellement à saisir.
  var _ses=(typeof SES!=='undefined'&&SES)?SES:null;
  var _voPre={ nom:_ses?((_ses.pre||'')+' '+(_ses.nom||'')).trim():'',
               tel:_ses?(_ses.tel||''):'', email:_ses?(_ses.email||''):'' };
  const overlay=document.createElement('div');
  if(overlay)overlay.className='mov';
  overlay.innerHTML=`<div class="modal"><div class="mhd"><div><div class="mtt">${ICO('lc-cart')}Commander : ${_esc(b.titre)}</div><div class="mst">${_esc(b.cls)} · ${_esc(b.auteur)} · ${fmt(b.prix)}</div></div><button class="mc" onclick="this.closest('.mov').remove()">✕</button></div>
  <div class="mb">
    <!-- Le prix était en or (#FFC93C) sur le fond clair de la modale : 1,45:1,
         illisible. L'or est une couleur d'accent ou de fond, jamais d'encre sur
         clair. On réutilise .book-price-box / .book-price (encre bleu nuit) déjà
         définies pour la boutique, plutôt que d'écrire une seconde correction.
         Le picto passe de 48px bruts à un cadre calibré : à 48px, un emoji
         déborde de sa ligne et se lit comme une image cassée. -->
    <div class="book-price-box" style="text-align:center;margin-bottom:16px">
      <div class="bk-picto" role="img" aria-label="${_esc(b.titre)}">${b.ico}</div>
      <div class="book-price" style="margin-top:8px">${fmt(b.prix)}</div>
    </div>
    <div class="ib ibt mb14"><span>📦</span><span>Manuel <strong>papier</strong> : il nous faut une adresse de livraison. Le paiement s'ouvre juste après.</span></div>
    <div class="fg2">
      <div class="fg"><span class="fl">Nom complet *</span><input class="fi" id="voNom" value="${_esc(_voPre.nom)}" placeholder="Nom et prénom"></div>
      <div class="fg"><span class="fl">Téléphone WhatsApp *</span><input class="fi" id="voTel" type="tel" value="${_esc(_voPre.tel)}" placeholder="+237 6 XX XX XX XX"></div>
      <div class="fg"><span class="fl">Classe de l&#39;élève</span><select class="fi" id="voCls">${CLS.map(c=>'<option'+(c===b.cls?' selected':'')+'>'+c+'</option>').join('')}</select></div>
      <div class="fg"><span class="fl">Email (optionnel)</span><input class="fi" id="voEmail" type="email" value="${_esc(_voPre.email)}" placeholder="email@exemple.com"></div>
    </div>
    <div class="fg"><span class="fl">📍 Adresse de livraison *</span><input class="fi" id="voAdresse" placeholder="Quartier + ville (ex : Akwa, Douala)"></div>
    <div class="fg"><span class="fl">Code promo</span><input class="fi" id="voPromo" value="${autoPromo}" placeholder="ELEVE10" style="text-transform:uppercase"></div>
    ${autoPromo?'<div style="font-size:13px;color:var(--gr);margin:-8px 0 8px">✅ Code ELEVE10 appliqué (-10%)</div>':''}
    <div class="fg"><span class="fl">Message (optionnel)</span><textarea class="fi" id="voMsg" rows="2" placeholder="Précisions, quantité..."></textarea></div>
  </div>
  <div class="mf"><button class="btn bo" onclick="this.closest('.mov').remove()">Annuler</button><button class="btn bi" onclick="confirmVisitorOrder('${b.id}')"><svg class="vico bico" aria-hidden="true"><use href="#lc-check"/></svg>Confirmer la commande</button></div></div>`;
  document.body.appendChild(overlay);
}

function confirmVisitorOrder(bid){
  const b=DB.books.find(x=>x.id===bid);if(!b)return;
  const nom=(document.getElementById('voNom')?.value||'').trim();
  const tel=(document.getElementById('voTel')?.value||'').trim();
  const adresse=(document.getElementById('voAdresse')?.value||'').trim();
  if(!nom||!tel){toast('Nom et téléphone requis','warn');return;}
  if(!adresse){toast('Adresse de livraison requise','warn');return;}
  if(!DB.visitorOrders)DB.visitorOrders=[];
  const promoCode=(document.getElementById('voPromo')?.value||'').trim().toUpperCase();
  let finalPrix=b.prix;let promoUsed='';
  if(promoCode){const promo=(DB.promoCodes||[]).find(p=>p.code===promoCode&&p.actif);
    if(promo){if(promo.type==='percent')finalPrix=Math.round(b.prix*(100-promo.reduction)/100);else finalPrix=Math.max(0,b.prix-promo.reduction);promoUsed=promoCode;promo.usage=(promo.usage||0)+1;}}
  DB.visitorOrders.push({id:gid(),bid,bookTitle:b.titre,nom,tel,adresse,
    email:document.getElementById('voEmail')?.value||'',
    cls:document.getElementById('voCls')?.value||'',
    msg:document.getElementById('voMsg')?.value||'',
    promo:promoUsed,prixOriginal:b.prix,
    date:today(),statut:'En attente',prix:finalPrix});
  // ── PROGRAMME PARTENARIAT v1 : tracking commission si code parrainage utilisé ──
  if(promoCode && typeof applyPartnerCode==='function'){
    try {
      applyPartnerCode(promoCode, {
        refType:'book', refId:bid, refLabel:b.titre,
        saleAmount: finalPrix, qty:1
      });
    } catch(e){ /* fail silent — la vente reste enregistrée même si commission KO */ }
  }
  save();
  const mov=document.querySelector('.mov');if(mov)mov.remove();
  // v1.0 : ouvrir le modal de paiement unifié
  setTimeout(function(){
    if(typeof openPaymentModal === 'function' && finalPrix > 0){
      // ── v1.2 : metadata pour activation automatique ──
      openPaymentModal({
        montant: finalPrix,
        label: '📚 '+b.titre,
        refPrefix: 'BOOK',
        intent: 'book',
        targetId: bid,
        customerNom: nom,
        customerTel: tel,
        customerAdresse: adresse,
        customerEmail: document.getElementById('voEmail')?.value||''
      });
    } else {
      toast('✓ Commande enregistrée ! Nous vous contacterons au '+tel);
    }
  }, 100);
}

function addBookContent(bid){
  const b=DB.books.find(x=>x.id===bid);if(!b)return;
  let previewHtml='<span class="xs2 mut">Aucune image</span>';
  if(b.previewImages&&b.previewImages.length){
    previewHtml=b.previewImages.map(function(img,i){
      return '<div style="position:relative;width:80px;height:100px;border:1px solid var(--bg3);border-radius:4px;overflow:hidden"><img src="'+img+'" style="width:100%;height:100%;object-fit:cover"><div style="position:absolute;top:2px;right:2px;background:var(--re);color:#fff;border:none;border-radius:50%;width:16px;height:16px;font-size:13px;cursor:pointer;display:flex;align-items:center;justify-content:center" onclick="removeBookPreview('+String.fromCharCode(39)+bid+String.fromCharCode(39)+','+i+')">×</div></div>';
    }).join('');
  }
  let coverHtml=b.coverImg?'<img src="'+_esc(b.coverImg)+'" style="width:60px;height:80px;object-fit:cover;border-radius:4px;border:1px solid var(--bg3)" onerror="this.outerHTML=\'<span class=\\\'xs2 mut\\\'>Image indisponible</span>\'">':'<span class="xs2 mut">Aucune couverture</span>';
  var _pdfStat=(b.previewPdfUrl||b.previewPdfKey)
    ?'<span class="bg bgg">✅ '+_esc(b.previewPdfName||'apercu.pdf')+'</span> '
      +(b.previewPdfUrl?'<span class="xs2" style="color:var(--gr)">☁️ Disponible sur tous les appareils</span> ':'<span class="xs2 mut">📱 Local uniquement</span> ')
      +'<button class="btn bo xs" onclick="removeBookPdfPreview(\''+bid+'\')" style="font-size:10px;padding:2px 8px"><svg class="vico bico" aria-hidden="true"><use href="#lc-trash"/></svg>Supprimer</button>'
    :'<span class="xs2 mut">Aucun aperçu PDF chargé</span>';
  M('📖 Gérer le contenu — '+b.titre,'Extraits et chapitres consultables par les visiteurs',
  '<div class="ib ibt mb14"><span>📝</span><span>Ajoutez des extraits que les visiteurs pourront lire avant d\'acheter.</span></div>'+
  '<div class="fg mb12"><span class="fl">📄 Aperçu PDF / Word (avant achat)</span>'+
  '<div class="fl2 fic g8 mt6" id="bkPdfStatus">'+_pdfStat+'</div>'+
  '<div class="ib" style="background:var(--blb);border:1px solid var(--bld);color:var(--bl);border-radius:var(--r);padding:7px 11px;font-size:12px;margin:5px 0">💡 Chargez 2-3 pages PDF/Word — les visiteurs les liront avant d\'acheter.</div>'+
  '<input type="file" class="fi mt4" id="bkPdfFile" accept=".pdf,.doc,.docx" style="font-size:12px"></div>'+
  '<div class="fg mb12"><span class="fl">Extrait principal (texte)</span><textarea class="fi" id="bkExtrait" rows="6" placeholder="Collez ici un extrait du livre (10-20 pages)...">'+(b.extrait||'')+'</textarea></div>'+
  '<div class="fg mb12"><span class="fl">Chapitres (un par ligne)</span><textarea class="fi" id="bkChaps" rows="4" placeholder="Chapitre 1 — Algèbre">'+(b.chaps||[]).join('\n')+'</textarea></div>'+
  '<div class="fg mb12"><span class="fl">📸 Images / Captures de pages</span>'+
  '<div class="fl2 g8 fw mt8" id="bkPreviews">'+previewHtml+'</div>'+
  '<button class="btn bo sm mt8" onclick="uploadBookPreview('+String.fromCharCode(39)+bid+String.fromCharCode(39)+')">＋ Ajouter des captures</button></div>'+
  '<div class="fg"><span class="fl">📸 Image de couverture</span>'+
  '<div class="fl2 fic g8 mt8">'+coverHtml+'<button class="btn bo sm" onclick="uploadBookCover('+String.fromCharCode(39)+bid+String.fromCharCode(39)+')"><svg class="vico bico" aria-hidden="true"><use href="#lc-camera"/></svg>Changer couverture</button></div></div>',
  '<button class="btn bo" onclick="cm()">Annuler</button><button class="btn bi" onclick="saveBookContent('+String.fromCharCode(39)+bid+String.fromCharCode(39)+')"><svg class="vico bico" aria-hidden="true"><use href="#lc-check"/></svg>Enregistrer</button>',true);
}

function saveBookContent(bid){
  var b=DB.books.find(function(x){return x.id===bid;});if(!b)return;
  b.extrait=document.getElementById('bkExtrait')?.value||'';
  var chapsText=document.getElementById('bkChaps')?.value||'';
  b.chaps=chapsText.split('\n').map(function(x){return x.trim();}).filter(function(x){return x;});
  var pdfInput=document.getElementById('bkPdfFile');
  var pdfFile=pdfInput&&pdfInput.files&&pdfInput.files[0];
  if(pdfFile){
    var cloudCfg=_effectiveCloudConfig();
    if(cloudCfg&&cloudCfg.url&&cloudCfg.secret){
      // ── Upload direct vers le cloud pour accessibilité multi-appareils ──
      toast('⬆️ Upload PDF en cours…','info');
      var fd=new FormData();
      fd.append('file',pdfFile,pdfFile.name);
      fd.append('type','book');
      fd.append('ref_id',bid);
      var ctrl=typeof AbortController!=='undefined'?new AbortController():null;
      var tmt=ctrl?setTimeout(function(){ctrl.abort();},120000):null;
      var baseUrl=cloudCfg.url.replace(/\/+$/,'');
      // FIX WAF LWS 2026 : Authorization header au lieu de _secret= dans URL/FormData
      fetch(baseUrl+'/upload_file.php',{
        method:'POST',
        headers:{'Authorization':'Bearer '+cloudCfg.secret},
        body:fd,
        signal:ctrl?ctrl.signal:undefined
      }).then(function(r){
        if(tmt)clearTimeout(tmt);
        return r.json();
      }).then(function(j){
        if(j&&j.url){
          b.previewPdfUrl=j.url;
          b.previewPdfName=pdfFile.name;
          b.previewPdfKey=''; // plus besoin du stockage local
          save();cm();re();toast('✓ PDF disponible sur tous les appareils ☁️');
        } else {
          throw new Error(j&&j.error?j.error:'Réponse invalide');
        }
      }).catch(function(e){
        if(tmt)clearTimeout(tmt);
        // Fallback : stocker en IDB local
        toast('⚠️ Upload cloud échoué, enregistrement local…','warn');
        var pdfReader=new FileReader();
        pdfReader.onload=function(ev){
          var pdfKey='bkprev_'+bid;
          idbSave(pdfKey,ev.target.result,pdfFile.name,pdfFile.type||'application/pdf',function(){
            b.previewPdfKey=pdfKey;b.previewPdfName=pdfFile.name;
            save();cm();re();toast('✓ PDF enregistré localement (cloud indisponible)','warn');
          });
        };
        pdfReader.onerror=function(){save();cm();re();toast('✓ Contenu enregistré (erreur lecture PDF)','warn');};
        pdfReader.readAsDataURL(pdfFile);
      });
    } else {
      // ── Pas de cloud configuré : stockage IDB local ──
      var pdfReader=new FileReader();
      pdfReader.onload=function(ev){
        var pdfKey='bkprev_'+bid;
        idbSave(pdfKey,ev.target.result,pdfFile.name,pdfFile.type||'application/pdf',function(){
          b.previewPdfKey=pdfKey;b.previewPdfName=pdfFile.name;
          save();cm();re();toast('✓ Contenu + aperçu PDF enregistrés');
        });
      };
      pdfReader.onerror=function(){save();cm();re();toast('✓ Contenu enregistré (erreur lecture PDF)','warn');};
      pdfReader.readAsDataURL(pdfFile);
    }
  } else {
    save();cm();re();toast('✓ Contenu du livre mis à jour');
  }
}

function removeBookPdfPreview(bid){
  var b=DB.books.find(function(x){return x.id===bid;});if(!b)return;
  if(b.previewPdfKey){
    var _idbReq=indexedDB.open('veritasDB',1);
    _idbReq.onsuccess=function(e){
      try{e.target.result.transaction('files','readwrite').objectStore('files').delete(b.previewPdfKey);}catch(ex){}
    };
  }
  b.previewPdfKey='';b.previewPdfName='';b.previewPdfUrl='';
  save();addBookContent(bid);toast('✓ Aperçu PDF supprimé');
}
function removeBookPreview(bid,idx){
  const b=DB.books.find(x=>x.id===bid);if(!b||!b.previewImages)return;
  b.previewImages.splice(idx,1);save();toast('Image supprimée');
  addBookContent(bid);
}

function viewBookDetail(bid){
  var b=DB.books.find(function(x){return x.id===bid;});if(!b)return;
  var cv=document.getElementById('vContent');if(!cv)return;
  var cc=b.coverColor||'#1a3a8a';
  var rt=getBookRating(bid);
  var rvs=(DB.bookReviews||[]).filter(function(r){return r.bid===bid;});
  var author=(DB.authors||[]).find(function(a){return(a.books||[]).indexOf(bid)>-1;});
  var h='<div class="vsec">';
  h+='<button class="btn bo sm mb16" onclick="vShowSec(\'boutique\',document.querySelector(\'.vnav-btn[onclick*=&quot;boutique&quot;]\'))">← Retour à la boutique</button>';
  // v1.16 — la fiche passe en deux colonnes : le contenu à gauche, le panneau
  // d'achat COLLANT à droite. Il reste visible pendant toute la lecture, au
  // lieu d'obliger à remonter pour retrouver le prix et le bouton.
  h+='<div class="bkpage">';
  h+=(typeof _bookBuyPanel==='function'?_bookBuyPanel(b,rt,rvs):'');
  h+='<div class="bkpage-main">';
  h+='<div class="book-viewer"><div class="book-hero">';
  // Cover
  h+='<div style="display:flex;flex-direction:column;gap:10px;align-items:center">';
  h+='<div class="book-cover-lg" style="background:linear-gradient(160deg,'+cc+','+cc+'dd);color:#fff;flex-direction:column;padding:20px;text-align:center">';
  // Fallback emoji+titre toujours rendu en arrière-plan, masqué si l'img charge
  h+='<div class="bk-fallback" style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:20px;text-align:center"><div class="bk-cover-pic">'+(b.ico?PIC(b.ico):ICO('i-book'))+'</div><div style="font-family:Libre Baskerville,serif;font-size:14px;font-weight:700;line-height:1.3;color:#fff">'+_esc(b.titre)+'</div></div>';
  if(b.coverImg)h+='<img src="'+_esc(b.coverImg)+'" style="width:100%;height:100%;object-fit:cover;position:absolute;inset:0;z-index:1" onerror="this.style.display=\'none\'" onload="var p=this.parentNode.querySelector(\'.bk-fallback\');if(p)p.style.display=\'none\'">';
  h+='</div>';
  h+='<button class="btn bo sm" onclick="downloadBookCover(\''+bid+'\')" style="width:100%"><svg class="vico bico" aria-hidden="true"><use href="#lc-download"/></svg>Couverture</button></div>';
  // Info
  h+='<div class="book-info"><h2>'+_esc(b.titre)+'</h2>';
  h+='<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:6px"><span class="bg bgb">'+_esc(b.cls)+'</span><span class="bg bgd">'+_esc(String(b.pages))+' pages</span><span class="bg '+(b.stock>0?'bgg':'bgr')+'">'+(b.stock>0?b.stock+' en stock':'Rupture')+'</span></div>';
  h+='<div style="font-size:13px;color:var(--ink3)">'+ICO('i-feather')+'<strong>'+_esc(b.auteur)+'</strong> · '+ICO('i-book-open')+' '+(b.chaps?.length||0)+' chapitres</div>';
  if(author)h+='<div class="author-badge mt4">'+ICO('i-check')+'Auteur vérifié — '+author.nom+'</div>';
  // Stars
  if(rt.count>0)h+='<div style="display:flex;align-items:center;gap:8px;margin:8px 0"><span style="font-size:18px">'+starsHtml(rt.avg)+'</span><span class="mono bold" style="color:var(--gold)">'+rt.avg.toFixed(1)+'</span><span class="xs2 mut">('+rt.count+' avis)</span></div>';
  h+='<p style="font-size:13px;color:var(--ink2);line-height:1.8;margin:8px 0">'+(b.desc||'')+'</p>';
  // Price
  h+='<div class="book-price-box">';
  if(b.ancienPrix)h+='<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px"><span style="font-size:14px;color:var(--ink4);text-decoration:line-through;text-decoration-color:#AE5353">'+fmt(b.ancienPrix)+'</span><span style="font-size:13px;font-weight:700;color:#fff;background:#AE5353;padding:2px 10px;border-radius:8px;box-shadow:0 2px 6px rgba(220,38,38,.25)">'+ICO("lc-flame")+'-'+Math.round((1-b.prix/b.ancienPrix)*100)+'%</span></div>';
  h+='<div class="book-price">'+fmt(b.prix)+'</div>';
  h+='<div style="margin-top:8px;padding:8px;background:var(--grb);border:1px solid var(--grd);border-radius:var(--r);font-size:13px;color:var(--gr)">'+ICO('i-badge')+'Code <span class="mono bold" style="background:var(--gp);padding:1px 6px;border-radius:3px;color:var(--gold)">ELEVE10</span> = -10%</div>';
  h+='<div style="margin-top:8px"><div class="fl2 g6" style="align-items:stretch"><input class="fi" id="promoInput_'+bid+'" placeholder="Code promo" style="font-size:13px;padding:8px;text-transform:uppercase;flex:1"><button class="btn bgr2 sm" onclick="applyPromo(\''+bid+'\')">Appliquer</button></div><div id="promoResult_'+bid+'"></div></div>';
  h+='</div>';
  if(b.stock>0)h+='<button class="book-order-btn mt12" onclick="visitorOrderBook(\''+bid+'\')">'+ICO("lc-cart")+'Payer (papier) — '+fmt(b.prix)+'</button>';
  // v1.7 : LECTURE NUMÉRIQUE SÉCURISÉE — aperçu gratuit + achat débloque tout.
  // Visible quand le livre a été préparé (b.secureId/securePages) ou marqué digital.
  if(b.secureId||b.securePages||b.digital){
    var _fp=b.freePages||10, _pd=b.prixDigital||b.priceDigital||b.prix;
    h+='<button class="btn bi mt8" style="width:100%;background:linear-gradient(135deg,#142554,#1E3A7A)" onclick="openSecureBook(\''+bid+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-bookopen"/></svg>Lire en ligne · '+_fp+' pages gratuites</button>';
    h+='<div style="font-size:11px;color:var(--ink4);text-align:center;margin-top:6px">'+ICO('i-lock')+'Version numérique '+fmtN(_pd)+' FCFA — consultation protégée, sans téléchargement ni partage</div>';
  }
  h+='</div></div>';
  // Tabs
  h+='<div style="padding:16px 24px 24px"><div class="book-tabs">';
  h+='<div class="book-tab active" onclick="showBookTab(this,\'chap_'+bid+'\')">'+ICO('i-clipboard-check')+'Chapitres</div>';
  h+='<div class="book-tab" onclick="showBookTab(this,\'prev_'+bid+'\')">'+ICO('i-eye')+'Extrait</div>';
  h+='<div class="book-tab" onclick="showBookTab(this,\'revs_'+bid+'\')">'+ICO('i-star')+'Avis ('+rvs.length+')</div>';
  h+='</div>';
  // Chapters tab
  h+='<div id="chap_'+bid+'">';
  (b.chaps||[]).forEach(function(ch,i){h+='<div class="book-chapter"><div class="ch-num">'+(i+1)+'</div><div><strong>'+ch+'</strong></div></div>';});
  if(!(b.chaps||[]).length)h+='<div class="empty xs2">Aucun chapitre</div>';
  h+='</div>';
  // Excerpt tab — supporte PDF (URL cloud ou IDB) + texte + images
  var _pdfAttr=b.previewPdfKey?' data-pdfkey="'+b.previewPdfKey+'"':'';
  var _pdfUrlAttr=b.previewPdfUrl?' data-pdfurl="'+b.previewPdfUrl+'"':'';
  h+='<div id="prev_'+bid+'"'+_pdfAttr+_pdfUrlAttr+' style="display:none">';
  if(b.previewPdfUrl){
    var _isMobUA=/Mobi|Android|iPhone|iPad/i.test(navigator.userAgent||'');
    h+='<div style="background:var(--blb);border:1px solid var(--bld);border-radius:var(--r);padding:8px 12px;font-size:12px;color:var(--bl);margin-bottom:8px">📄 <strong>Aperçu PDF disponible</strong> ☁️</div>';
    if(_isMobUA){
      // Mobile : iframe PDF ne fonctionne pas → FIX : window.open au lieu de <a target=_blank>
      // qui sur Android navigue le SPA (même origine PDF = vue inline qui remplace l'app)
      var _gv='https://docs.google.com/viewer?embedded=true&url='+encodeURIComponent(b.previewPdfUrl);
      window['_bookPdfUrl_'+bid]=b.previewPdfUrl;
      window['_bookGvUrl_'+bid]=_gv;
      h+='<div style="border:2px dashed var(--bld);border-radius:var(--r);padding:24px;text-align:center;background:var(--blb)">'
        +'<div style="font-size:48px;margin-bottom:10px">📄</div>'
        +'<div style="font-family:Libre Baskerville,serif;font-size:14px;font-weight:700;color:var(--bl);margin-bottom:14px">'+_esc(b.previewPdfName||'Aperçu')+'</div>'
        +'<button class="btn bi" style="border:none;cursor:pointer;font-size:13px;padding:10px 18px;margin:4px" onclick="var w=window.open(window[\'_bookPdfUrl_'+bid+'\'],\'_blank\');if(!w)alert(\'Autorisez les pop-ups pour ouvrir le PDF\');"><svg class="vico bico" aria-hidden="true"><use href="#lc-bookopen"/></svg>Ouvrir le PDF</button>'
        +'<button class="btn bo" style="border:none;cursor:pointer;font-size:13px;padding:10px 18px;margin:4px" onclick="var w=window.open(window[\'_bookGvUrl_'+bid+'\'],\'_blank\');if(!w)alert(\'Autorisez les pop-ups\');"><svg class="vico bico" aria-hidden="true"><use href="#lc-search"/></svg>Voir aperçu</button>'
        +'</div>';
    } else {
      // Desktop : viewer PDF robuste (fetch+blob → PDF.js fallback)
      var _pvId='pdfPv_'+bid;
      h+='<div id="'+_pvId+'"><div class="ib ibt"><span>⏳</span><span>Chargement de l\'aperçu PDF…</span></div></div>';
      window['_bookPdfUrl_'+bid]=b.previewPdfUrl;
      setTimeout(function(){ if(typeof _pdfViewerIframe==='function') _pdfViewerIframe(window['_bookPdfUrl_'+bid],_pvId,{height:'58vh'}); },120);
    }
  }else if(b.previewPdfKey){
    h+='<div style="background:var(--blb);border:1px solid var(--bld);border-radius:var(--r);padding:8px 12px;font-size:12px;color:var(--bl);margin-bottom:8px">📄 <strong>Aperçu PDF disponible</strong></div>';
    h+='<div id="pdfCont_'+bid+'"><div class="ib ibt"><span>⏳</span><span>Chargement de l\'aperçu…</span></div></div>';
  }else if(b.extrait){
    h+='<div style="background:var(--bg);border:var(--br);border-radius:var(--r2);padding:20px;font-family:Libre Baskerville,serif;font-size:13px;line-height:2;color:var(--ink2);white-space:pre-line;max-height:400px;overflow-y:auto;position:relative">';
    h+='<div style="position:absolute;top:8px;right:8px;background:var(--gp);color:var(--gold);padding:2px 10px;border-radius:12px;font-size:13px;font-weight:700;font-family:Outfit,sans-serif">EXTRAIT GRATUIT</div>';
    h+=b.extrait;
    h+='<div style="margin-top:20px;padding-top:16px;border-top:2px dashed var(--bg3);text-align:center;font-family:Outfit,sans-serif;font-size:13px;color:var(--ink4)"><div style="font-size:24px;margin-bottom:4px">📚</div><strong>Fin de l&#39;extrait</strong><br>Commandez le manuel complet</div></div>';
  }else h+='<div class="empty"><div class="empty-ico">📄</div>Aperçu non disponible</div>';
  h+='</div>';
  // Reviews tab
  h+='<div id="revs_'+bid+'" style="display:none">';
  if(rt.count>0){
    h+='<div class="avg-box"><div class="avg-num">'+rt.avg.toFixed(1)+'</div><div><div class="avg-stars">'+starsHtml(rt.avg)+'</div><div class="avg-cnt">'+rt.count+' avis vérifiés</div></div></div>';
  }
  if(rvs.length){
    rvs.forEach(function(r){
      h+='<div class="review-card"><div class="review-hd"><div class="review-av">'+r.nom[0]+'</div><div><div class="review-nm">'+r.nom+'</div><div class="review-rl">'+r.role+'</div></div></div>';
      h+='<div>'+starsHtml(r.stars)+'</div>';
      h+='<div class="review-txt">&laquo; '+r.text+' &raquo;</div>';
      h+='<div class="fl2 fic fsb"><span class="review-dt">'+r.date+'</span>'+(r.verified?'<span class="review-vf">'+ICO('i-check')+'Achat vérifié</span>':'')+'</div></div>';
    });
  }else h+='<div class="empty"><div class="empty-ico">⭐</div>Aucun avis pour le moment</div>';
  // Add review form
  h+='<div style="margin-top:14px;padding:14px;border:1px solid var(--bg3);border-radius:var(--r2);background:var(--bg)">';
  h+='<div class="semi s mb8">✍️ Laisser un avis</div>';
  h+='<div class="fl2 g6 mb8">'; for(var s=1;s<=5;s++)h+='<span class="vt-star-pick" onclick="setReviewStars('+s+')" id="rs_'+s+'">'+ICO('lc-star','i vt-star')+'</span>'; h+='<span class="xs2 mut" id="rsLabel">Sélectionnez</span></div>';
  h+='<input class="fi mb8" id="rvNom" placeholder="Votre nom"><input class="fi mb8" id="rvRole" placeholder="Rôle (Parent, Élève...)">';
  h+='<textarea class="fi mb8" id="rvText" rows="2" placeholder="Votre avis sur ce manuel..."></textarea>';
  h+='<button class="btn bi sm" onclick="submitReview(\''+bid+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-upload"/></svg>Publier l&#39;avis</button></div>';
  h+='</div></div></div>';
  // « Comment recevoir mon exemplaire ? » — le parcours d'achat expliqué,
  // juste après l'argumentaire, là où l'acheteur se demande « et ensuite ? »
  h+=(typeof _bookCommentRecevoir==='function'?_bookCommentRecevoir(b):'');
  h+='</div>';   // .bkpage-main
  h+='</div>';   // .bkpage
  h+='</div>';   // .vsec
  if(cv)cv.innerHTML=h;
  window._rvStars=0;
}
// ── Modale "Extrait gratuit" — visible directement depuis la boutique ──
function _showExtrait(bid){
  var b=DB.books.find(function(x){return x.id===bid;});if(!b)return;
  function _showPdfExtrait(pdfSrc,pdfName){
    var _isMob=/Mobi|Android|iPhone|iPad/i.test(navigator.userAgent||'');
    var _isHttpUrl=pdfSrc&&pdfSrc.indexOf('http')===0;
    var h='<div style="background:var(--blb);border:1px solid var(--bld);border-radius:var(--r);padding:8px 12px;font-size:12px;color:var(--bl);margin-bottom:10px">'
          +'📢 <strong>Extrait gratuit</strong> — Lisez les premières pages avant d\'acheter.</div>';
    if(_isMob&&_isHttpUrl){
      // Sur mobile, iframe + PDF ne fonctionne pas → FIX : window.open au lieu de <a target=_blank>
      // Android navigue le SPA quand le PDF est sur même origine (vue inline)
      var _gv='https://docs.google.com/viewer?embedded=true&url='+encodeURIComponent(pdfSrc);
      window._extraitPdfUrl=pdfSrc;
      window._extraitGvUrl=_gv;
      window._extraitPdfName=pdfName||'apercu.pdf';
      h+='<div style="border:2px dashed var(--bld);border-radius:var(--r);padding:28px;text-align:center;background:var(--blb)">'
        +'<div style="font-size:56px;margin-bottom:12px">📄</div>'
        +'<div style="font-family:Libre Baskerville,serif;font-size:15px;font-weight:700;color:var(--bl);margin-bottom:16px">'+_esc(pdfName||'Aperçu PDF')+'</div>'
        +'<button class="btn bi" style="border:none;cursor:pointer;font-size:14px;padding:12px 22px;margin:5px" onclick="var w=window.open(window._extraitPdfUrl,\'_blank\');if(!w)alert(\'Autorisez les pop-ups pour ouvrir le PDF\');"><svg class="vico bico" aria-hidden="true"><use href="#lc-bookopen"/></svg>Ouvrir le PDF</button><br>'
        +'<button class="btn bo" style="border:none;cursor:pointer;font-size:13px;padding:10px 18px;margin:5px" onclick="var w=window.open(window._extraitGvUrl,\'_blank\');if(!w)alert(\'Autorisez les pop-ups\');"><svg class="vico bico" aria-hidden="true"><use href="#lc-search"/></svg>Voir aperçu intégré</button>'
        +'</div>';
    } else if(_isMob&&!_isHttpUrl&&pdfSrc&&pdfSrc.indexOf('data:')===0){
      // Mobile + data: URL → convertir en Blob URL pour ouverture/téléchargement natif
      var _blobUrl='';
      try{
        var _arr=pdfSrc.split(','),_mime=(_arr[0].match(/:(.*?);/)||['','application/pdf'])[1];
        var _bstr=atob(_arr[1]),_n=_bstr.length,_u8=new Uint8Array(_n);
        while(_n--)_u8[_n]=_bstr.charCodeAt(_n);
        _blobUrl=URL.createObjectURL(new Blob([_u8],{type:_mime}));
        // FIX mémoire mobile : révoquer le Blob URL après 60s (pour PDF déjà ouvert ou abandonné)
        setTimeout(function(_u){try{URL.revokeObjectURL(_u);}catch(eR){}},60000,_blobUrl);
      }catch(_be){_blobUrl='';}
      if(_blobUrl){
        var _fname=_esc(pdfName||'apercu.pdf');
        h+='<div style="border:2px dashed var(--bld);border-radius:var(--r);padding:28px;text-align:center;background:var(--blb)">'
          +'<div style="font-size:56px;margin-bottom:12px">📄</div>'
          +'<div style="font-family:Libre Baskerville,serif;font-size:15px;font-weight:700;color:var(--bl);margin-bottom:16px">'+_fname+'</div>'
          +'<button class="btn bi" style="font-size:14px;padding:12px 22px;margin:5px;cursor:pointer" onclick="window.open(\''+_blobUrl+'\',\'_blank\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-bookopen"/></svg>Ouvrir le PDF</button><br>'
          +'<a href="'+_blobUrl+'" download="'+_fname+'" class="btn bo" style="display:inline-block;text-decoration:none;font-size:13px;padding:10px 18px;margin:5px"><svg class="vico bico" aria-hidden="true"><use href="#lc-download"/></svg>Télécharger</a>'
          +'</div>';
      } else {
        // Fallback data URL mobile sans blob → Google Docs viewer impossible → iframe data:
        h+='<iframe src="'+pdfSrc+'" style="width:100%;height:62vh;border:1px solid var(--bg3);border-radius:8px;display:block" title="Aperçu PDF" allowfullscreen>'
          +'<p style="text-align:center;padding:20px">PDF non affiché. <a href="'+pdfSrc+'" target="_blank">Ouvrir →</a></p></iframe>';
      }
    } else if(_isHttpUrl){
      // Desktop + URL HTTP → viewer robuste (fetch+blob → PDF.js fallback)
      var _epvId='extraitPv_'+bid;
      h+='<div id="'+_epvId+'"><div class="ib ibt"><span>⏳</span><span>Chargement de l\'aperçu PDF…</span></div></div>';
      window._extraitPdfUrl=pdfSrc;
      setTimeout(function(){ if(typeof _pdfViewerIframe==='function') _pdfViewerIframe(window._extraitPdfUrl,_epvId,{height:'62vh'}); },120);
    } else {
      // Desktop + data: URL locale → iframe direct (pas de CORS)
      h+='<iframe src="'+pdfSrc+'" style="width:100%;height:62vh;border:1px solid var(--bg3);border-radius:8px;display:block" title="Aperçu PDF" allowfullscreen>'
        +'<p style="text-align:center;padding:20px">PDF non affiché. <a href="'+pdfSrc+'" target="_blank">Ouvrir →</a></p></iframe>'
        +'<div style="margin-top:6px;text-align:center"><a href="'+pdfSrc+'" target="_blank" style="font-size:12px;color:var(--bl)">↗ Ouvrir dans le navigateur</a></div>';
    }
    M('📄 Aperçu — '+b.titre,'Extrait gratuit avant achat',h,
      '<button class="btn bo" onclick="cm()">Fermer</button>'
      +'<button class="btn bg2 sm" onclick="cm();viewBookDetail(\''+bid+'\')" style="font-size:12px"><svg class="vico bico" aria-hidden="true"><use href="#lc-clipboard"/></svg>Détails</button>'
      +(b.stock>0?'<button class="btn bi" onclick="cm();visitorOrderBook(\''+bid+'\')" ><svg class="vico bico" aria-hidden="true"><use href="#lc-cart"/></svg>Payer — '+fmt(b.prix)+'</button>':''),true);
  }
  // 1. URL serveur (cross-device) — priorité maximale
  if(b.previewPdfUrl){_showPdfExtrait(b.previewPdfUrl,b.previewPdfName||'apercu.pdf');return;}
  // 2. Clé IndexedDB (même appareil seulement)
  if(b.previewPdfKey){
    idbGetFile(b.previewPdfKey,function(rec){
      if(!rec){
        if(b.extrait||(b.previewImages||[]).length>0){_showExtrait_text(bid);return;}
        toast('Aperçu PDF introuvable — uploadez via Sauvegarde cloud pour accès multi-appareils','warn');return;
      }
      _showPdfExtrait(rec.data,rec.name||b.previewPdfName);
    });
    return;
  }
  _showExtrait_text(bid);
}
function _showExtrait_text(bid){
  var b=DB.books.find(function(x){return x.id===bid;});if(!b)return;
  var hasExt=b.extrait||((b.previewImages||[]).length>0);
  if(!hasExt){toast('Aucun aperçu disponible pour ce manuel','warn');return;}
  var cc=b.coverColor||'#1a3a8a';
  var rt=getBookRating(bid);

  // En-tête du livre
  var h='<div style="display:flex;gap:14px;align-items:flex-start;margin-bottom:16px;padding-bottom:14px;border-bottom:1px solid var(--bg3)">';
  h+='<div style="width:64px;height:90px;border-radius:8px;background:linear-gradient(160deg,'+cc+','+cc+'cc);display:flex;align-items:center;justify-content:center;font-size:28px;flex-shrink:0;overflow:hidden;position:relative;box-shadow:0 4px 12px rgba(0,0,0,.2);color:#fff">';
  h+='<span style="position:relative;z-index:0">'+b.ico+'</span>';
  if(b.coverImg)h+='<img src="'+_esc(b.coverImg)+'" style="width:100%;height:100%;object-fit:cover;position:absolute;inset:0;z-index:1" onerror="this.style.display=\'none\'">';
  h+='</div>';
  h+='<div style="flex:1;min-width:0">';
  h+='<div style="font-family:Libre Baskerville,serif;font-size:15px;font-weight:700;color:var(--bl);margin-bottom:3px;line-height:1.3">'+_esc(b.titre)+'</div>';
  h+='<div style="font-size:12px;color:var(--ink4);margin-bottom:6px">'+_esc(b.cls)+' · '+_esc(b.auteur)+' · '+b.pages+' pages</div>';
  if(rt.count>0)h+='<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px"><span style="font-size:13px">'+starsHtml(rt.avg)+'</span><span class="mono" style="font-size:12px;color:var(--gold);font-weight:700">'+rt.avg.toFixed(1)+'</span><span style="font-size:11px;color:var(--ink4)">('+rt.count+')</span></div>';
  if(b.ancienPrix)h+='<span style="font-size:12px;color:var(--re);text-decoration:line-through;margin-right:6px">'+fmt(b.ancienPrix)+'</span>';
  h+='<span style="font-family:Fira Code,monospace;font-size:17px;font-weight:700;color:var(--gold)">'+fmt(b.prix)+'</span>';
  h+='</div></div>';

  // Badge "EXTRAIT GRATUIT"
  h+='<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">';
  h+='<div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:1px;color:var(--gr)">📖 Extrait gratuit</div>';
  h+='<span style="background:var(--grb);color:var(--gr);font-size:10px;font-weight:700;padding:3px 10px;border-radius:20px;border:1px solid var(--grd)">Aperçu avant achat</span>';
  h+='</div>';

  // Texte de l'extrait
  if(b.extrait){
    h+='<div style="background:var(--bg);border:var(--br);border-radius:var(--r2);padding:16px 18px;font-family:Libre Baskerville,serif;font-size:13px;line-height:2;color:var(--ink2);white-space:pre-line;max-height:42vh;overflow-y:auto;position:relative;scrollbar-width:thin">';
    h+=_esc(b.extrait);
    h+='<div style="margin-top:16px;padding-top:12px;border-top:2px dashed var(--bg3);text-align:center;font-size:12px;color:var(--ink4);font-family:Plus Jakarta Sans,sans-serif">📚 <strong>Fin de l\'extrait</strong> — Le manuel complet contient '+b.pages+' pages</div>';
    h+='</div>';
  }

  // Images de prévisualisation
  if((b.previewImages||[]).length>0){
    h+='<div style="margin-top:12px"><div style="font-size:11px;font-weight:700;color:var(--bl);text-transform:uppercase;letter-spacing:.8px;margin-bottom:8px">📸 Aperçu des pages</div>';
    h+='<div style="display:flex;gap:8px;overflow-x:auto;padding:4px 0;scrollbar-width:thin">';
    (b.previewImages||[]).forEach(function(img){
      h+='<img src="'+img+'" style="height:140px;border-radius:6px;border:1px solid var(--bg3);flex-shrink:0;cursor:zoom-in;box-shadow:0 2px 8px rgba(0,0,0,.08)" onclick="window.open(\''+img+'\',\'_blank\')">';
    });
    h+='</div></div>';
  }

  // CTA
  M('📖 Aperçu gratuit', b.titre, h,
    '<button class="btn bo" onclick="cm()">Fermer</button>'+
    '<button class="btn bg2 sm" onclick="cm();viewBookDetail(\''+bid+'\')" style="font-size:12px"><svg class="vico bico" aria-hidden="true"><use href="#lc-clipboard"/></svg>Détails & Avis</button>'+
    (b.stock>0?'<button class="btn bi" onclick="cm();visitorOrderBook(\''+bid+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-cart"/></svg>Payer — '+fmt(b.prix)+'</button>':'<span style="font-size:12px;color:var(--re);font-weight:700;padding:8px">Rupture de stock</span>'),
    true // large modal
  );
}

function setReviewStars(n){
  window._rvStars=n;
  for(var i=1;i<=5;i++){var el=document.getElementById('rs_'+i);if(el)el.style.color=i<=n?'#FFC93C':'#ddd';}
  var lbl=document.getElementById('rsLabel');
  if(lbl)lbl.textContent=['','Mauvais','Moyen','Bien','Très bien','Excellent'][n];
}
function submitReview(bid){
  var nom=(document.getElementById('rvNom')?.value||'').trim();
  var role=(document.getElementById('rvRole')?.value||'').trim();
  var text=(document.getElementById('rvText')?.value||'').trim();
  var stars=window._rvStars||0;
  if(!nom||!text||!stars){toast('Remplissez tous les champs et notez avec les étoiles','warn');return;}
  if(!DB.bookReviews)DB.bookReviews=[];
  DB.bookReviews.push({id:gid(),bid:bid,nom:nom,role:role||'Lecteur',stars:stars,text:text,date:today(),verified:false});
  save();viewBookDetail(bid);toast('✓ Merci pour votre avis !');
}

function showBookTab(btn,tabId){
  var tabs=btn.parentElement;
  tabs.querySelectorAll('.book-tab').forEach(function(t){t.classList.remove('active');});
  btn.classList.add('active');
  var viewer=tabs.parentElement;
  viewer.querySelectorAll('[id^="chap_"],[id^="prev_"],[id^="revs_"],[id^="chapters_"],[id^="preview_"]').forEach(function(d){d.style.display='none';});
  var target=document.getElementById(tabId);
  if(target){
    target.style.display='block';
    // Charger l'aperçu PDF depuis IDB si disponible et pas encore chargé
    var pdfKey=target.getAttribute('data-pdfkey');
    var bid=tabId.replace('prev_','');
    var cont=document.getElementById('pdfCont_'+bid);
    if(pdfKey&&cont&&!target._pdfLoaded){
      target._pdfLoaded=true;
      idbGetFile(pdfKey,function(rec){
        if(!cont)return;
        if(!rec){
          cont.innerHTML='<div class="ib" style="background:#FEE2E2;color:#AE5353;padding:10px;border-radius:8px;font-size:12px">'
            +'❌ Aperçu PDF introuvable (peut être chargé sur un autre appareil).</div>';
          return;
        }
        // Convertir data: URL en Blob URL (les iframes bloquent les data: URLs dans Chrome moderne)
        var _pdfSrc=rec.data;
        if(_pdfSrc&&_pdfSrc.startsWith('data:')){
          try{
            var _pa=_pdfSrc.split(','),_pm=(_pa[0].match(/:(.*?);/)||['','application/pdf'])[1];
            var _pb=atob(_pa[1]),_pn=_pb.length,_pu=new Uint8Array(_pn);
            while(_pn--)_pu[_pn]=_pb.charCodeAt(_pn);
            _pdfSrc=URL.createObjectURL(new Blob([_pu],{type:_pm}));
          }catch(_pe){_pdfSrc=rec.data;}
        }
        var _isMobIDB=/Mobi|Android|iPhone|iPad/i.test(navigator.userAgent||'');
        if(_isMobIDB){
          var _fn2=rec.name||'apercu.pdf';
          // FIX mobile : window.open au lieu de <a target=_blank> (Android navigue le SPA)
          window._idbPdfSrc=_pdfSrc;
          window._idbPdfName=_fn2;
          cont.innerHTML='<div style="border:2px dashed var(--bld);border-radius:var(--r);padding:24px;text-align:center;background:var(--blb)">'
            +'<div style="font-size:48px;margin-bottom:10px">📄</div>'
            +'<div style="font-family:Libre Baskerville,serif;font-size:14px;font-weight:700;color:var(--bl);margin-bottom:14px">'+_esc(_fn2)+'</div>'
            +'<button class="btn bi" style="border:none;cursor:pointer;font-size:13px;padding:10px 18px;margin:4px" onclick="var w=window.open(window._idbPdfSrc,\'_blank\');if(!w)alert(\'Autorisez les pop-ups pour ouvrir le PDF\');"><svg class="vico bico" aria-hidden="true"><use href="#lc-bookopen"/></svg>Ouvrir le PDF</button>'
            +'<a href="'+_pdfSrc+'" download="'+_esc(_fn2)+'" class="btn bo" style="display:inline-block;text-decoration:none;font-size:13px;padding:10px 18px;margin:4px"><svg class="vico bico" aria-hidden="true"><use href="#lc-download"/></svg>Télécharger</a>'
            +'</div>';
        } else {
          cont.innerHTML='<iframe src="'+_pdfSrc+'" style="width:100%;height:58vh;border:1px solid var(--bg3);border-radius:8px;display:block" title="Aperçu PDF"></iframe>'
            +'<div style="margin-top:6px;text-align:center"><a href="'+_pdfSrc+'" target="_blank" style="font-size:12px;color:var(--bl)">↗ Ouvrir dans le navigateur</a></div>';
        }
      });
    }
  }
}

function applyPromo(bid){
  const b=DB.books.find(x=>x.id===bid);if(!b)return;
  const code=(document.getElementById('promoInput_'+bid)?.value||'').trim().toUpperCase();
  const result=document.getElementById('promoResult_'+bid);
  if(!code){if(result)result.innerHTML='';return;}
  const promo=(DB.promoCodes||[]).find(p=>p.code===code&&p.actif);
  if(!promo){if(result)result.innerHTML='<div style="font-size:13px;color:var(--re);margin-top:4px">❌ Code promo invalide</div>';return;}
  let newPrice=b.prix;let savings=0;
  if(promo.type==='percent'){savings=Math.round(b.prix*promo.reduction/100);newPrice=b.prix-savings;}
  else{savings=promo.reduction;newPrice=Math.max(0,b.prix-promo.reduction);}
  if(result)result.innerHTML='<div style="font-size:13px;color:var(--gr);margin-top:4px;padding:6px;background:var(--grb);border-radius:var(--r)">✅ <strong>'+promo.desc+'</strong> — Vous économisez <strong>'+fmt(savings)+'</strong><br><span class="mono bold" style="font-size:14px;color:var(--gold)">Nouveau prix: '+fmt(newPrice)+'</span></div>';
}

// ═══════════════════════════════════════════════════════════════════
// HELPER PDF VIEWER ROBUSTE (v1.2)
// Stratégie en cascade pour contourner X-Frame-Options / CORS / blocage tiers :
//   1. fetch() le PDF → Blob URL → iframe (le PDF devient "local" pour le navigateur)
//   2. si fetch échoue (CORS) → Mozilla PDF.js viewer (https://mozilla.github.io/pdf.js)
//   3. si PDF.js échoue → iframe direct
//   4. fallback final → boutons "Ouvrir" + "Télécharger"
// ═══════════════════════════════════════════════════════════════════
function _pdfViewerIframe(pdfUrl, containerId, opts){
  opts = opts || {};
  var ifrId = 'pdfIfr_'+Math.random().toString(36).substr(2,7);
  var fallbackId = 'pdfFb_'+Math.random().toString(36).substr(2,7);
  var ctn = document.getElementById(containerId);
  if(!ctn) return;
  // Squelette : iframe vide + zone fallback cachée
  ctn.innerHTML =
    '<iframe id="'+ifrId+'" style="width:100%;height:'+(opts.height||'62vh')+';border:1px solid var(--bg3);border-radius:8px;display:block;background:#525659" allowfullscreen></iframe>'
    +'<div id="'+fallbackId+'" style="display:none;text-align:center;padding:24px;background:var(--blb);border-radius:8px;margin-top:6px">'
      +'<div style="font-size:48px;margin-bottom:10px">📄</div>'
      +'<div style="font-size:13px;color:var(--ink3);margin-bottom:14px">L\'aperçu n\'a pas pu être chargé directement.<br>Choisissez une option :</div>'
      +'<a href="'+pdfUrl+'" target="_blank" rel="noopener" class="btn bi" style="display:inline-block;text-decoration:none;margin:4px"><svg class="vico bico" aria-hidden="true"><use href="#lc-bookopen"/></svg>Ouvrir dans un onglet</a>'
      +'<a href="'+pdfUrl+'" download class="btn bo" style="display:inline-block;text-decoration:none;margin:4px"><svg class="vico bico" aria-hidden="true"><use href="#lc-download"/></svg>Télécharger</a>'
    +'</div>'
    +'<div style="margin-top:6px;text-align:center;display:flex;gap:12px;justify-content:center;flex-wrap:wrap;font-size:11px">'
      +'<a href="'+pdfUrl+'" target="_blank" rel="noopener" style="color:var(--bl);text-decoration:none">↗ Ouvrir le PDF directement</a>'
      +'<a href="https://mozilla.github.io/pdf.js/web/viewer.html?file='+encodeURIComponent(pdfUrl)+'" target="_blank" rel="noopener" style="color:var(--gr);text-decoration:none">🔍 Viewer alternatif (PDF.js)</a>'
    +'</div>';
  var ifr = document.getElementById(ifrId);
  var fb = document.getElementById(fallbackId);

  // Étape 1 : fetch → Blob URL (contourne X-Frame-Options du serveur source)
  var revoked=false;
  function _revokeLater(url){ setTimeout(function(){ if(!revoked){revoked=true;try{URL.revokeObjectURL(url);}catch(e){}} }, 5*60*1000); }

  // Timeout : si rien ne se charge en 6s, on bascule sur PDF.js
  var loadTimeout = setTimeout(function(){
    if(!ifr.src || ifr.src===window.location.href){
      // Plan B : Mozilla PDF.js
      ifr.src = 'https://mozilla.github.io/pdf.js/web/viewer.html?file=' + encodeURIComponent(pdfUrl);
    }
  }, 6000);

  fetch(pdfUrl, {mode:'cors', credentials:'omit'})
    .then(function(r){
      if(!r.ok) throw new Error('HTTP '+r.status);
      return r.blob();
    })
    .then(function(blob){
      clearTimeout(loadTimeout);
      var blobUrl = URL.createObjectURL(blob);
      _revokeLater(blobUrl);
      ifr.src = blobUrl;
    })
    .catch(function(err){
      console.warn('[pdfViewer] fetch échoué, Plan B (PDF.js):',err.message);
      clearTimeout(loadTimeout);
      // Plan B : Mozilla PDF.js (gère bien les PDF cross-origin)
      ifr.src = 'https://mozilla.github.io/pdf.js/web/viewer.html?file=' + encodeURIComponent(pdfUrl);
      // Si PDF.js lui-même échoue (rare), basculer sur les boutons après 8s
      setTimeout(function(){
        try {
          var doc = ifr.contentDocument || ifr.contentWindow?.document;
          if(!doc) { ifr.style.display='none'; fb.style.display='block'; }
        } catch(e){
          // CORS sur l'iframe = c'est probablement OK (PDF.js fonctionne en cross-origin)
        }
      }, 8000);
    });
}

function downloadBookCover(bid){
  const b=DB.books.find(x=>x.id===bid);if(!b)return;
  const safeName='Couverture_'+(b.titre||'manuel').replace(/[^a-zA-ZÀ-ÿ0-9]/g,'_');

  // ── PRIORITÉ 1 : vraie image de couverture uploadée par l'admin ──
  // (b.coverImg est défini par uploadBookCover → URL serveur OU data URL)
  if(b.coverImg){
    const img=new Image();
    img.crossOrigin='anonymous'; // pour autoriser le canvas si CORS le permet
    img.onload=function(){
      try {
        const canvas=document.createElement('canvas');
        // Respecter le ratio original de l'image
        canvas.width=img.naturalWidth||img.width||600;
        canvas.height=img.naturalHeight||img.height||800;
        const ctx=canvas.getContext('2d');
        ctx.drawImage(img,0,0,canvas.width,canvas.height);
        // Filigrane discret
        if(typeof applyWatermark==='function') applyWatermark(canvas,ctx);
        const link=document.createElement('a');
        link.download=safeName+'.png';
        link.href=canvas.toDataURL('image/png');
        link.click();
        toast('✓ Couverture téléchargée (image originale)');
      } catch(e){
        // CORS tainted canvas → fallback : téléchargement direct du fichier source
        console.warn('[downloadBookCover] canvas CORS, fallback direct',e);
        const link=document.createElement('a');
        link.href=b.coverImg;
        link.download=safeName+'.'+((b.coverImg.match(/\.(png|jpg|jpeg|webp|gif)/i)||[,'png'])[1].toLowerCase());
        if(b.coverImg.indexOf('http')===0) link.target='_blank';
        link.click();
        toast('✓ Couverture ouverte dans un nouvel onglet');
      }
    };
    img.onerror=function(){
      // Image inaccessible (404 ou CORS dur) → on retombe sur le placeholder canvas
      console.warn('[downloadBookCover] image non chargeable, fallback placeholder');
      _downloadBookCoverPlaceholder(b,safeName);
    };
    img.src=b.coverImg;
    return;
  }

  // ── PRIORITÉ 2 : aucune image uploadée → générer un placeholder esthétique ──
  _downloadBookCoverPlaceholder(b,safeName);
}

function _downloadBookCoverPlaceholder(b,safeName){
  const cc=b.coverColor||'#1a3a8a';
  const canvas=document.createElement('canvas');
  canvas.width=600;canvas.height=800;
  const ctx=canvas.getContext('2d');
  const grd=ctx.createLinearGradient(0,0,600,800);
  grd.addColorStop(0,cc);grd.addColorStop(1,cc+'cc');
  ctx.fillStyle=grd;ctx.fillRect(0,0,600,800);
  ctx.fillStyle='rgba(255,255,255,0.08)';
  for(let i=0;i<20;i++){ctx.beginPath();ctx.arc(Math.random()*600,Math.random()*800,Math.random()*80+20,0,Math.PI*2);ctx.fill();}
  ctx.fillStyle='rgba(255,255,255,0.15)';ctx.fillRect(40,40,520,720);
  ctx.fillStyle='#fff';ctx.font='bold 80px serif';ctx.textAlign='center';
  ctx.fillText(b.ico||'📚',300,200);
  ctx.font='bold 32px "Libre Baskerville",serif';
  const words=(b.titre||'').split(' ');let line='';let y=300;
  for(const w of words){const test=line+w+' ';if(ctx.measureText(test).width>460&&line){ctx.fillText(line.trim(),300,y);y+=44;line=w+' ';}else{line=test;}}
  ctx.fillText(line.trim(),300,y);
  ctx.font='italic 18px "Libre Baskerville",serif';ctx.fillStyle='rgba(255,255,255,0.7)';
  ctx.fillText(b.auteur||'',300,y+60);
  ctx.font='bold 16px sans-serif';ctx.fillStyle='rgba(255,255,255,0.5)';
  ctx.fillText((b.cls||'')+' — '+(b.pages||0)+' pages',300,720);
  ctx.fillStyle='rgba(232,200,112,0.9)';ctx.fillRect(200,740,200,4);
  ctx.font='12px sans-serif';ctx.fillStyle='rgba(255,255,255,0.4)';
  ctx.fillText(DB.school?.nom||'Centre VÉRITAS',300,770);
  if(typeof applyWatermark==='function') applyWatermark(canvas,ctx);
  const link=document.createElement('a');
  link.download=safeName+'.png';
  link.href=canvas.toDataURL('image/png');
  link.click();
  toast('ℹ️ Couverture générique téléchargée (aucune image personnalisée)');
}

// ─── CAROUSEL "À LA UNE" ────────────────────────
var _slideIdx=0,_slideTimer=null;
function _slideNav(dir){var slides=document.querySelectorAll('#vSlides .vslide');if(!slides.length)return;_slideIdx=(_slideIdx+dir+slides.length)%slides.length;_slideGo();}
function _slideTo(i){_slideIdx=i;_slideGo();}
function _slideGo(){
  var track=$('vSlides');if(!track)return;
  track.style.transform='translateX(-'+(_slideIdx*100)+'%)';
  var dots=document.querySelectorAll('#vSlideDots > div');
  dots.forEach(function(d,i){d.style.width=i===_slideIdx?'24px':'8px';d.style.background=i===_slideIdx?'#FFC93C':'rgba(255,255,255,.4)';});
  _slideAutoStart();
}
function _slideAutoStart(){clearInterval(_slideTimer);_slideTimer=setInterval(function(){_slideNav(1);},5000);}

// ═══════════════════════════════════════════════════════════════════════════
// PLANCHER DE LISIBILITÉ MOBILE (v1.12)
// ═══════════════════════════════════════════════════════════════════════════
// Sur un écran de téléphone, l'accueil comptait ~146 textes sous 11 px, dont
// 16 à 8 px (« Taux de réussite », « Mentions ») : illisibles pour l'élève ET
// pour le parent qui décide de l'abonnement. Ces tailles sont posées en style
// INLINE dans des dizaines de gabarits — une règle CSS ne peut pas les
// atteindre proprement. On applique donc un plancher au rendu, uniquement sur
// petit écran, et uniquement dans la zone visiteur.
var _PLANCHER_MOBILE = 10.5;

function _mobileTypeFloor(){
  try{
    var racine = document.getElementById('vContent');
    if(!racine) return;
    var estMobile = window.matchMedia && matchMedia('(max-width:480px)').matches;

    if(!estMobile){
      // Retour en paysage / tablette / bureau : on RETIRE le plancher, sinon
      // la micro-typographie d'origine resterait figée à 10,5 px après une
      // simple rotation du téléphone.
      var poses = racine.querySelectorAll('[data-tfloor="1"]');
      for(var j=0;j<poses.length;j++){
        poses[j].style.fontSize = '';
        delete poses[j].dataset.tfloor;
      }
      return;
    }

    var noeuds = racine.querySelectorAll('*');
    for(var i=0;i<noeuds.length;i++){
      var el = noeuds[i];
      if(el.children.length) continue;                 // feuilles seulement
      if(el.dataset && el.dataset.tfloor === '1') continue;   // déjà traité
      var fs = parseFloat(getComputedStyle(el).fontSize);
      if(fs && fs < _PLANCHER_MOBILE){
        el.style.fontSize = _PLANCHER_MOBILE + 'px';
        if(el.dataset) el.dataset.tfloor = '1';
      }
    }
  }catch(e){}
}
window._mobileTypeFloor = _mobileTypeFloor;

// Le contenu visiteur est re-rendu par de nombreux chemins (vShowSec sort par
// une dizaine de `return` différents) : on observe la zone plutôt que de
// greffer un appel sur chacun, sinon un futur chemin oublierait le plancher.
function _installTypeFloorObserver(){
  try{
    if(window._tfloorObs) return;
    var cible = document.getElementById('vContent');
    if(!cible || !window.MutationObserver) return;
    var minuteur = null;
    var replanifier = function(){
      clearTimeout(minuteur);
      minuteur = setTimeout(_mobileTypeFloor, 120);
    };
    // L'observateur est posé quelle que soit la taille : _mobileTypeFloor
    // décide seul s'il applique ou retire le plancher. Sinon, un visiteur
    // arrivé en paysage puis passé en portrait n'en bénéficierait jamais.
    window._tfloorObs = new MutationObserver(replanifier);
    window._tfloorObs.observe(cible, {childList:true, subtree:true});
    window.addEventListener('resize', replanifier, {passive:true});
    if(window.matchMedia){
      var mq = matchMedia('(max-width:480px)');
      if(mq.addEventListener) mq.addEventListener('change', replanifier);
    }
    _mobileTypeFloor();
  }catch(e){}
}
window._installTypeFloorObserver = _installTypeFloorObserver;

// ═══════════════════════════════════════════════════════════════════════════
// TOUR INTERACTIF — Onboarding au 1er visiteur (v1.2 OPTIMISATION)
// ═══════════════════════════════════════════════════════════════════════════
function maybeShowOnboarding(){
  // Ne montrer qu'aux visiteurs anonymes (pas aux comptes inscrits) et 1x seulement
  if(SES) return;
  if(localStorage.getItem('_vrtOnboardingSeen')==='1') return;
  if(window._onboardingActive) return;

  // v1.12 — DÉCLENCHEMENT SUR ENGAGEMENT, plus sur l'arrivée.
  // Avant : un calque plein écran s'ouvrait 1,5 s après le chargement. Un
  // visiteur venu de Google pour « corrigé BEPC » se voyait interrompu avant
  // d'avoir lu une ligne — le meilleur moyen de le faire repartir. On attend
  // désormais un vrai signal d'intérêt : il a fait défiler la page, ou il est
  // resté. Le tour garde tout son sens, il arrive juste au bon moment.
  if(location.hash && location.hash.length > 1) return;   // arrivé sur une ancre précise (QR, page SEO) → il sait ce qu'il cherche

  var lance = false, minuteur = null;
  var nettoyer = function(){
    if(minuteur) clearTimeout(minuteur);
    window.removeEventListener('scroll', auDefilement);
  };
  var lancer = function(){
    if(lance) return;
    lance = true;
    nettoyer();
    // Re-vérifier : l'état a pu changer pendant l'attente (connexion, tour relancé…).
    if(SES || window._onboardingActive) return;
    if(localStorage.getItem('_vrtOnboardingSeen')==='1') return;
    window._onboardingActive = true;
    _showOnboardingStep(0);
  };
  var auDefilement = function(){
    var y = window.scrollY || document.documentElement.scrollTop || 0;
    if(y > Math.max(280, (window.innerHeight||600) * 0.45)) lancer();
  };
  window.addEventListener('scroll', auDefilement, {passive:true});
  minuteur = setTimeout(lancer, 25000);   // sinon : après 25 s de présence réelle
}

window.startOnboarding=function(){
  // Permet de relancer manuellement (depuis menu Aide par ex.)
  localStorage.removeItem('_vrtOnboardingSeen');
  window._onboardingActive=true;
  _showOnboardingStep(0);
};

