/* Le nombre d'étapes était écrit en dur dans le texte d'accueil : « en 8 étapes »
   pour 9 étapes réellement affichées — le compteur de la modale annonçait donc
   « Étape 1 / 9 » deux lignes plus bas. On le dérive du tableau : ajouter ou
   retirer une étape ne peut plus faire mentir la phrase. */
try{
  _ONBOARDING_STEPS[0].text = _ONBOARDING_STEPS[0].text
    .replace(/en \d+ étapes/, 'en ' + _ONBOARDING_STEPS.length + ' étapes');
}catch(e){}

function _showOnboardingStep(idx){
  if(idx>=_ONBOARDING_STEPS.length){_endOnboarding();return;}
  var step=_ONBOARDING_STEPS[idx];
  var totalSteps=_ONBOARDING_STEPS.length;
  var progress=Math.round(((idx+1)/totalSteps)*100);

  // Nettoyage : retirer ancien overlay + listener clavier précédent
  var existing=document.getElementById('_obOverlay');
  if(existing)existing.remove();
  if(window._obKeyHandler){
    document.removeEventListener('keydown', window._obKeyHandler, true);
    window._obKeyHandler = null;
  }

  // v2.4 FIX : pointer-events explicite + role dialog + a11y
  var ov=document.createElement('div');
  ov.id='_obOverlay';
  ov.setAttribute('role','dialog');
  ov.setAttribute('aria-modal','true');
  ov.setAttribute('aria-labelledby','_obTitle');
  ov.setAttribute('aria-describedby','_obText');
  ov.style.cssText='position:fixed;inset:0;background:rgba(13,27,62,.78);z-index:2147483646;display:flex;align-items:center;justify-content:center;padding:20px;animation:obFade .3s ease-out;font-family:Montserrat,sans-serif;pointer-events:auto !important;cursor:auto';

  ov.innerHTML=
    '<style>@keyframes obFade{from{opacity:0}to{opacity:1}}@keyframes obPop{from{transform:scale(.85);opacity:0}to{transform:scale(1);opacity:1}}#_obOverlay *{pointer-events:auto !important}#_obOverlay button{cursor:pointer !important}</style>'+
    '<div id="_obCard" style="background:#fff;border-radius:24px;max-width:480px;width:100%;padding:32px 28px 24px;box-shadow:0 30px 80px rgba(0,0,0,.4);text-align:center;animation:obPop .4s cubic-bezier(.34,1.56,.64,1);position:relative;pointer-events:auto !important">'+
      // Skip top right — bouton avec zone hit large
      '<button type="button" id="_obSkipBtn" onclick="window._endOnboarding(true);return false;" style="position:absolute;top:8px;right:8px;background:#F1F5F9;border:1px solid #E2E8F0;color:#475569;font-size:12px;cursor:pointer;padding:8px 14px;border-radius:20px;font-weight:700;min-width:64px;min-height:36px;line-height:1;transition:all .2s" aria-label="Passer le tour de bienvenue">Passer ✕</button>'+
      // Big emoji
      '<div style="font-size:64px;margin-bottom:12px;line-height:1" aria-hidden="true">'+step.emoji+'</div>'+
      // Title
      '<h2 id="_obTitle" style="font-family:Plus Jakarta Sans,Libre Baskerville,Georgia,serif;font-size:24px;font-weight:700;color:#142554;margin:0 0 14px;line-height:1.2">'+step.title+'</h2>'+
      // Text
      '<p id="_obText" style="font-size:14px;color:#475569;line-height:1.65;margin:0 0 24px">'+step.text+'</p>'+
      // Progress
      '<div style="background:#E2E8F0;height:6px;border-radius:3px;overflow:hidden;margin:0 0 18px"><div style="height:100%;width:'+progress+'%;background:linear-gradient(90deg,#FFC93C,#F59E0B);transition:width .4s"></div></div>'+
      '<div style="font-size:11px;color:#5A6B85;margin-bottom:14px">Étape'+(idx+1)+' / '+totalSteps+'</div>'+
      // Boutons : Retour (si idx>0) + CTA
      '<div style="display:flex;gap:10px">'+
        (idx>0 ? '<button type="button" id="_obBackBtn" onclick="window._showOnboardingStep('+(idx-1)+');return false;" style="background:#F1F5F9;color:#142554;border:1px solid #E2E8F0;border-radius:14px;padding:14px 20px;font-family:Plus Jakarta Sans,Montserrat,sans-serif;font-weight:700;font-size:14px;cursor:pointer;min-width:80px;letter-spacing:.5px" aria-label="Étape précédente">←</button>' : '')+
        '<button type="button" id="_obCtaBtn" onclick="window._onboardingNext('+idx+');return false;" style="background:linear-gradient(135deg,#142554,#1E3A8A);color:#fff;border:none;border-radius:14px;padding:14px 28px;font-family:Plus Jakarta Sans,Montserrat,sans-serif;font-weight:800;font-size:14px;cursor:pointer;box-shadow:0 6px 20px rgba(20,37,84,.3);flex:1;letter-spacing:.5px;min-height:50px" autofocus>'+step.cta+'</button>'+
      '</div>'+
      // Indication clavier discrète
      '<div style="font-size:10px;color:#5A6B85;margin-top:12px;letter-spacing:.3px">⌨️ Entrée pour continuer · Échap pour passer · ← → pour naviguer</div>'+
    '</div>';
  document.body.appendChild(ov);

  // v2.4 FIX : Listener clavier pour navigation
  window._obKeyHandler = function(e){
    if(!document.getElementById('_obOverlay')) return;
    if(e.key === 'Enter' || e.key === ' '){
      e.preventDefault(); e.stopPropagation();
      window._onboardingNext(idx);
    } else if(e.key === 'Escape'){
      e.preventDefault(); e.stopPropagation();
      window._endOnboarding(true);
    } else if(e.key === 'ArrowRight'){
      e.preventDefault();
      window._onboardingNext(idx);
    } else if(e.key === 'ArrowLeft' && idx>0){
      e.preventDefault();
      window._showOnboardingStep(idx-1);
    }
  };
  document.addEventListener('keydown', window._obKeyHandler, true);

  // v2.4 FIX : Click sur l'overlay (en dehors du card) = pass au lieu de bloquer
  ov.addEventListener('click', function(e){
    if(e.target === ov){
      // Clic sur le backdrop = passer
      window._endOnboarding(true);
    }
  });

  // v2.4 FIX : Auto-focus sur le CTA (pour navigation clavier immédiate)
  setTimeout(function(){
    var cta = document.getElementById('_obCtaBtn');
    if(cta){
      try { cta.focus(); } catch(e){}
    }
  }, 100);

  // v2.4 FIX : Safety timeout — si l'utilisateur reste bloqué 30s, fermer
  if(window._obSafetyTimeout) clearTimeout(window._obSafetyTimeout);
  window._obSafetyTimeout = setTimeout(function(){
    if(document.getElementById('_obOverlay')){
      console.warn('[VERITAS] Onboarding bloqué 30s — auto-fermeture sécurité');
      window._endOnboarding(true);
    }
  }, 30000);
}

// v2.4 FIX : exposer en global pour usage depuis HTML inline onclick
window._showOnboardingStep = _showOnboardingStep;

window._onboardingNext=function(idx){
  var step=_ONBOARDING_STEPS[idx];
  if(step&&step.action&&typeof window[step.action]==='function'){
    _endOnboarding();
    setTimeout(function(){window[step.action]();},300);
    return;
  }
  _showOnboardingStep(idx+1);
};

window._endOnboarding=function(skipped){
  var ov=document.getElementById('_obOverlay');
  if(ov){ov.style.opacity='0';setTimeout(function(){if(ov.parentNode)ov.remove();},300);}
  // v2.4 FIX : nettoyer listeners clavier + safety timeout
  if(window._obKeyHandler){
    document.removeEventListener('keydown', window._obKeyHandler, true);
    window._obKeyHandler = null;
  }
  if(window._obSafetyTimeout){ clearTimeout(window._obSafetyTimeout); window._obSafetyTimeout = null; }
  localStorage.setItem('_vrtOnboardingSeen','1');
  window._onboardingActive=false;
  if(!skipped&&typeof toast==='function')toast('🎉 Bonne découverte de VÉRITAS !','success');
};


function initVisitor(){
  const img=$("vLogo");if(img)img.src=getLogo();
  const nm=$("vName");if(nm)nm.textContent=DB.school?.nom||"VÉRITAS Academy";
  const sl=$("vSlogan");if(sl)sl.textContent=DB.school?.slogan||"Centre d'Excellence Scolaire";
  const ct=$("vCity");if(ct)ct.textContent=DB.school?.ville||"Douala, Cameroun";
  const se=$("vStatEtu");if(se)se.textContent=DB.students.length;
  const se2=$("vStatEns");if(se2)se2.textContent=DB.teachers.length;
  // Mettre à jour le label de la barre de connexion avec le vrai nom de l'école
  // Écrire dans #vBrandName et NON dans le span parent : celui-ci porte le
  // pictogramme, qu'un textContent effacerait à chaque rendu.
  var lbLabel=document.getElementById('vBrandName');
  if(lbLabel)lbLabel.textContent=(DB.school&&DB.school.nom)||'VÉRITAS Academy';
  /* ═══ IL N'Y A PLUS D'ACCUEIL ICI ═══════════════════════════════════════
     Cette ligne rendait l'accueil de l'application par défaut. C'était la
     seconde page d'accueil du site, et c'est elle qu'on supprime.

     Première tentative : rediriger depuis vShowSec avec une fenêtre de trois
     secondes. Mauvaise idée — l'accueil se re-rend à des moments imprévisibles
     (retour de public_data.php), et passé la fenêtre la redirection partait
     pour de bon : un visiteur tranquille sur /app.html?ref=… se retrouvait
     éjecté vers la vitrine au bout de trois secondes. Une minuterie ne règle
     pas une course, elle la déplace.

     Règle déterministe à la place, sans minuterie de course :
       · PAS d'ancre → il n'y a rien à voir ici, on part sur la vitrine en
         conservant la requête (parrainage, retour de paiement) ;
       · UNE ancre → c'est le routeur qui place la section. On ne rend rien en
         attendant : afficher l'accueil « en attendant » revient précisément à
         le garder.
     Le filet de sécurité plus bas rattrape le cas d'une ancre que personne ne
     sait traiter — il ne se déclenche que si RIEN n'a été rendu. */
  (function _plusDAccueilIci(){
    var connecte = (typeof SES !== 'undefined' && SES);
    var h = (location.hash || '').replace(/^#/, '').split('?')[0].trim();
    if(!h && !connecte){ location.replace('/' + (location.search || '')); return; }

    // Filet : si aucune section ne s'est rendue, on ne laisse pas un écran vide.
    setTimeout(function(){
      try{
        if(typeof SES !== 'undefined' && SES) return;
        var c = document.getElementById('vContent');
        if(c && c.innerHTML.trim() === '') location.replace('/' + (location.search || ''));
      }catch(e){}
    }, 1600);
  })();
  initTicker();
  // ── Plancher de lisibilité mobile (voir _mobileTypeFloor) ──
  try { if(typeof _installTypeFloorObserver === 'function') _installTypeFloorObserver(); } catch(e){}
  // ── v1.2 OPTIMISATION : Tour interactif au premier visiteur ──
  setTimeout(function(){
    try { if(typeof maybeShowOnboarding === 'function') maybeShowOnboarding(); } catch(e){}
  }, 1500);
  if(SES&&(SES.type==="visiteur"||SES.type==="visiteur_inscrit"))setTimeout(_updateVisitorHeader,50);
  // Sync dot : visible si admin déjà connecté (ex: admin navigue vers la page visiteur)
  if(iA()){var sd=document.getElementById('vSyncDot');if(sd){sd.style.display='inline-flex';_setSyncDot((DB.cloudConfig&&DB.cloudConfig.lastSync)?'ok':'pending',DB.cloudConfig&&DB.cloudConfig.lastSync||'');}}
  // Polling arrière-plan pour tous les appareils : reçoit les mises à jour du cloud
  // Utilise _effectiveCloudConfig() → fonctionne même sans login admin (via cache vrt10_cc)
  if(!_bgPollTimer) _startBgPoll();
  setTimeout(_slideAutoStart,1000);
  // Charger les actualités dans le hero panel
  setTimeout(function(){_heroActuLoad('education');},800);
  // Activer le son vidéo au premier toucher/clic sur la page
  _vheroAutoUnmuteOnInteraction();
  // Charger les données publiques depuis le serveur (partenaires, calendrier, etc.)
  // v1.14 — reporté à l'inactivité du navigateur. Ces données (partenaires,
  // calendrier) ne conditionnent pas le premier affichage, et l'appel partait
  // jusqu'ici en pleine phase de rendu. Le repli setTimeout couvre Safari, qui
  // n'implémente pas requestIdleCallback.
  if(typeof requestIdleCallback==='function'){
    requestIdleCallback(function(){ try{ _fetchPublicData(); }catch(e){} }, {timeout:3000});
  } else {
    setTimeout(function(){ try{ _fetchPublicData(); }catch(e){} }, 1200);
  }
  // Ré-attacher les gestes d'accès admin sur le logo (au cas où il a été recréé)
  setTimeout(function(){
    if(window._lpAttachLogos)_lpAttachLogos();
    if(window._tapAttachLogos)_tapAttachLogos();
  },200);
}

function _fetchPublicData(){
  // ⚡ perf — Idempotence anti-refetch : l'init est rejoué à chaque navigation, et
  // le succès ci-dessous RE-REND la section (vShowSec) → cascade. Sans garde,
  // public_data.php était appelé ~4× au chargement. On saute l'appel si un succès
  // date de < 5 min ou si un fetch est déjà en cours. (Le retry sur ÉCHEC reste actif.)
  if(_fetchPublicData._inflight) return;
  if(_fetchPublicData._lastOk && (Date.now()-_fetchPublicData._lastOk)<300000) return;
  _fetchPublicData._inflight=true;
  // Stratégie d'URL : 1) URL relative au fichier HTML (fonctionne si l'app et l'API sont sur le même serveur)
  //                   2) URL cloud configurée par l'admin
  var relUrl='';
  try{
    var base2=window.location.href.replace(/\/[^\/]*$/,'/').replace(/\?.*$/,'');
    if(base2.startsWith('http'))relUrl=base2+'api/public_data.php';
  }catch(e){}
  var cfgUrl=(DB.cloudConfig&&DB.cloudConfig.url||'https://veritas-school.com/api').replace(/\/+$/,'')+'/public_data.php';
  // Utiliser l'URL relative si disponible et différente de l'URL configurée, sinon l'URL configurée
  var url=(relUrl&&relUrl!==cfgUrl)?relUrl:cfgUrl;

  function _doFetch(fetchUrl,fallbackUrl){
    return fetch(fetchUrl,{method:'GET',headers:{'Accept':'application/json'},signal:(typeof AbortSignal!=='undefined'&&AbortSignal.timeout?AbortSignal.timeout(8000):undefined)})
    .then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.json();})
    .catch(function(e){
      // Si l'URL relative a échoué, essayer l'URL cloud configurée
      if(fallbackUrl&&fetchUrl!==fallbackUrl){
        return fetch(fallbackUrl,{method:'GET',headers:{'Accept':'application/json'},signal:(typeof AbortSignal!=='undefined'&&AbortSignal.timeout?AbortSignal.timeout(6000):undefined)})
        .then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.json();});
      }
      throw e;
    });
  }

  _doFetch(url,(url!==cfgUrl)?cfgUrl:null)
  .then(function(data){
    _fetchPublicData._inflight=false; _fetchPublicData._lastOk=Date.now();
    _fetchPublicData._essais=0;   // succès : le compteur de reprises repart à zéro
    var isAdmin=iA();
    var changed=false;

    // ── Partenaires ─────────────────────────────────────────────────────────
    if(data.partenaires&&data.partenaires.length>0){
      // Non-admins : toujours prendre les données du serveur
      // Admins     : ne pas écraser (ils gèrent depuis le dashboard local)
      if(!isAdmin||(DB.partenaires||[]).length===0){
        DB.partenaires=data.partenaires;changed=true;
      }
    }

    // ── Calendrier ──────────────────────────────────────────────────────────
    if(data.calendrier&&data.calendrier.length>0){
      if(!isAdmin||(DB.calendrier||[]).length===0){
        DB.calendrier=data.calendrier;changed=true;
      }
    }

    // ── Ticker (messages défilants) ─────────────────────────────────────────
    if(data.tickerItems&&data.tickerItems.length>0){
      if(!isAdmin||(DB.tickerItems||[]).length===0){
        DB.tickerItems=data.tickerItems;changed=true;
      }
      // Toujours ré-initialiser le ticker pour les visiteurs (DOM peut être vide)
      if(!isAdmin){initTicker();}
    }

    // ── Infos école ─────────────────────────────────────────────────────────
    if(data.school){
      if(!isAdmin||!DB.school||!DB.school.nom||DB.school.nom==='VÉRITAS Academy'){
        DB.school=Object.assign(DB.school||{},data.school);
        var nm2=$('vName');if(nm2)nm2.textContent=DB.school.nom||'VÉRITAS Academy';
        var sl2=$('vSlogan');if(sl2)sl2.textContent=DB.school.slogan||"Centre d'Excellence Scolaire";
        var ct2=$('vCity');if(ct2)ct2.textContent=DB.school.ville||'Douala, Cameroun';
        changed=true;
      }
    }

    // ── publicInfo (présentation, description, contact…) ────────────────────
    if(data.publicInfo){
      if(!isAdmin||!DB.publicInfo||!DB.publicInfo.description){
        DB.publicInfo=Object.assign(DB.publicInfo||{},data.publicInfo);changed=true;
      }
    }

    // ── Plans e-learning ────────────────────────────────────────────────────
    if(data.elearning_plans&&data.elearning_plans.length>0){
      if(!isAdmin||(!(DB.elearning&&DB.elearning.plans)||DB.elearning.plans.length===0)){
        if(!DB.elearning)DB.elearning={plans:[],categories:[],contenus:[],abonnements:[],commandes:[]};
        DB.elearning.plans=data.elearning_plans;changed=true;
      }
    }

    /* ── Catalogue e-learning public (v1.19.1) ─────────────────────────────
       Le visiteur non inscrit voyait les prix d'abonnement sans jamais voir ce
       qu'ils ouvrent : public_data.php n'exposait que les plans, donc la page
       affichait une étagère vide et le mur d'essais ne gardait rien.
       Les fiches arrivent maintenant en liste blanche (aucun contenu, aucun
       identifiant de compte) — de quoi dessiner les cartes et leurs cadenas.
       On n'écrase JAMAIS la base d'un admin : la sienne fait foi. */
    if(!isAdmin){
      if(data.elearning_categories&&data.elearning_categories.length>0){
        if(!DB.elearning)DB.elearning={plans:[],categories:[],contenus:[],abonnements:[],commandes:[]};
        DB.elearning.categories=data.elearning_categories;changed=true;
      }
      if(data.elearning_contenus&&data.elearning_contenus.length>0){
        if(!DB.elearning)DB.elearning={plans:[],categories:[],contenus:[],abonnements:[],commandes:[]};
        DB.elearning.contenus=data.elearning_contenus;changed=true;
      }
      // Politique d'essais : c'est le panneau admin qui commande la vitrine,
      // sinon le visiteur tomberait sur les valeurs par défaut du code et la
      // ressource offerte ne serait pas celle que Jacques a choisie.
      if(data.paywall&&typeof data.paywall==='object'){ DB.paywall=data.paywall;changed=true; }
    }

    // ── Ré-initialiser les éléments visuels dynamiques pour les visiteurs ───
    if(!isAdmin&&changed){
      // Ticker : re-lancer toujours (les nouveaux items du serveur doivent s'afficher)
      if(typeof initTicker==='function')initTicker();
      // v1.2.6 : bouton "🤝 Partenaires" dupliqué dans le nav retiré — fusionné
      // dans "Nos partenaires" (Communauté ▾ → pgInstitutionalShowcase).
      // Label école dans la barre de connexion
      var lbl=document.getElementById('vBrandName');
      if(lbl&&DB.school&&DB.school.nom)lbl.textContent=DB.school.nom;
      // Re-rendre la section courante si ses données ont été mises à jour
      var curSec=window._vCurrentSec||'presentation';
      if(curSec==='partenaires'||curSec==='presentation'||curSec==='elearning'||curSec==='contact'||curSec==='boutique'){
        try{vShowSec(curSec,document.querySelector('.vnav-btn.on'));}catch(e){}
      }
    }

    // NB: on ne call pas save() ici — ces données viennent du serveur et ne
    // doivent pas remplacer le localStorage admin (qui fait foi côté gestion)
  })
  .catch(function(e){
    _fetchPublicData._inflight=false;
    // Silencieux — hors ligne, serveur non configuré, ou premier lancement.
    //
    // v1.14 — CORRECTIF : le drapeau « déjà réessayé » était remis à zéro PAR
    // la reprise elle-même, juste avant de rappeler la fonction. L'intention
    // écrite était « une seule fois » ; le comportement réel était une boucle
    // sans fin, toutes les 8 s, tant que l'appel échouait. Mesuré ici sur un
    // serveur sans PHP : 82 requêtes en six minutes. Sur un forfait mobile
    // camerounais, un onglet oublié consommait pour rien.
    //
    // Trois tentatives espacées, puis on renonce jusqu'au prochain
    // chargement : ces données (partenaires, calendrier) ne valent pas de
    // harceler un serveur qui ne répond pas.
    var _essais = _fetchPublicData._essais || 0;
    var _delais = [8000, 20000, 45000];
    if(_essais < _delais.length){
      _fetchPublicData._essais = _essais + 1;
      setTimeout(function(){ try{ _fetchPublicData(); }catch(e){} }, _delais[_essais]);
    }
  });
}
function _vheroAutoUnmuteOnInteraction(){
  // Attendre que la vidéo soit dans le DOM, puis brancher le son sur un tap direct
  var tries=0;
  var interval=setInterval(function(){
    var v=document.getElementById('vheroVideo');
    if(v){
      clearInterval(interval);
      // Touch direct sur la vidéo → unmute (satisfait la politique navigateur mobile)
      v.addEventListener('touchstart',function onTouch(){
        v.removeEventListener('touchstart',onTouch);
        _vheroUnmute();
      },{passive:true,once:true});
      v.addEventListener('click',function onClick(){
        v.removeEventListener('click',onClick);
        _vheroUnmute();
      },{once:true});
    }
    if(++tries>40)clearInterval(interval);
  },200);
}
function _vheroUnmute(){
  var v=document.getElementById('vheroVideo');
  var btn=document.getElementById('vheroSoundBtn');
  if(v&&v.muted){
    v.muted=false;
    v.play().catch(function(){});
    if(btn){btn.classList.remove('muted');btn.classList.add('playing');btn.innerHTML='🔊 <span>Son activé</span>';}
  }
}
