function submitOrientation(){
  const nom=(document.getElementById('orNom')?.value||'').trim();
  const tel=(document.getElementById('orTel')?.value||'').trim();
  const type=document.getElementById('orType')?.value||'';
  if(!nom||!tel||!type){toast('Nom, téléphone et type de service requis','warn');return;}
  if(!DB.orientationDemandes)DB.orientationDemandes=[];
  DB.orientationDemandes.push({
    id:gid(),
    nom,tel,
    niveau:document.getElementById('orNiveau')?.value||'—',
    type,
    msg:document.getElementById('orMsg')?.value||'',
    dispo:document.getElementById('orDispo')?.value||'',
    date:today(),
    statut:'En attente'
  });
  save();
  toast('✓ Demande envoyée ! Nous vous contacterons au '+tel);
  ['orNom','orTel','orNiveau','orType','orMsg','orDispo'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
}
function hideAll(){[$("LS"),$("APP"),$("VISITOR")].forEach(el=>{if(el)el.style.display="none";});
  // v1.13 : le FAB WhatsApp et le flux d'activité sont attachés à <body>, donc
  // ils ne disparaissent pas avec le portail visiteur — il faut les masquer ici,
  // sinon ils flottent au-dessus du tableau de bord admin.
  try{ if(typeof _vtHideSupportFab==='function') _vtHideSupportFab(); }catch(e){}}
function goToVisitor(){
  hideAll();
  $("VISITOR").style.display="flex";
  initVisitor();
}
function showLogin(role){
  hideAll();
  $("LS").style.display="flex";
  var tabMap={admin:"ltbA",superadmin:"ltbSA"};
  var tid=tabMap[role];
  if(tid){var t=$(tid);if(t){t.style.display="";t.style.animation="fadeIn .3s ease";}}
  swLR(role);
}

/* Porte d'entrée du bouton « Connexion » de la barre (v1.18).
   Distincte de _portailAller() : celle-ci montre d'abord le contenu gratuit du
   rôle, ce qui est juste quand on clique « Je suis élève » depuis l'accueil,
   mais absurde quand on clique un bouton marqué « Connexion ». Ici, on ouvre
   le formulaire.
   Onglet par défaut : « Élève », le public le plus nombreux. Les onglets
   Élève / Enseignant restent visibles au-dessus — c'est par eux qu'un
   enseignant bascule sur son propre formulaire. */
function _ouvrirConnexion(){
  try{
    var actuel = (typeof _portailRoleActuel==='function') ? _portailRoleActuel() : '';
    // Déjà connecté : « Connexion » doit ramener à SON espace, pas redemander
    // un mot de passe déjà donné.
    if(actuel){ _portailAller(actuel); return; }
    showLogin('eleve');
  }catch(e){
    try{ showLogin('eleve'); }catch(_){}
  }
}
window._ouvrirConnexion = _ouvrirConnexion;


