    plansCheckboxes+='<label style="display:flex;align-items:center;gap:6px;cursor:pointer;padding:6px 10px;background:var(--bg2);border-radius:8px;font-size:12px"><input type="checkbox" id="ecPlan_'+pid+'" checked> '+planLabels[pid]+'</label>';
