function mEditElearningContent(itemId){
  var el=DB.elearning||{categories:[],contenus:[]};
  var item=(el.contenus||[]).find(function(c){return c.id===itemId;});
  if(!item)return;
  var planOptions=['plan1','plan2','plan3','plan4'];
  var planLabels={plan1:'📗 Pack EXAMEN',plan2:'📘 Pack INTERMÉDIAIRE',plan3:'📙 Pack ENSEIGNANT',plan4:'🏆 Pack FAMILLE / ÉCOLE'};
  var plansCheckboxes='<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:6px">';
  planOptions.forEach(function(pid){
    var checked=(item.plans||[]).indexOf(pid)>-1;
    plansCheckboxes+='<label style="display:flex;align-items:center;gap:6px;cursor:pointer;padding:6px 10px;background:var(--bg2);border-radius:8px;font-size:12px"><input type="checkbox" id="ecPlan_'+pid+'"'+(checked?' checked':'')+'>'+planLabels[pid]+'</label>';
  });
  plansCheckboxes+='</div>';
  M('✏️ Modifier: '+item.titre,'Modifier les informations du contenu',
  '<div class="fg2">'+
  '<div class="fg"><span class="fl">Titre *</span><input class="fi" id="ecTitre" value="'+item.titre+'"></div>'+
  '<div class="fg"><span class="fl">Catégorie</span><select class="fi" id="ecCat">'+el.categories.map(function(c){return '<option value="'+c.id+'"'+(c.id===item.cat?' selected':'')+'>'+c.ico+' '+c.nom+'</option>';}).join('')+'</select></div>'+
  '<div class="fg"><span class="fl">Classe</span><select class="fi" id="ecCls">'+CLS.map(function(cl){return '<option'+(cl===item.classe?' selected':'')+'>'+cl+'</option>';}).join('')+'</select></div>'+
  '<div class="fg"><span class="fl">Matière</span><select class="fi" id="ecMat">'+SUBS.concat(['Toutes']).map(function(s){return '<option'+(s===item.matiere?' selected':'')+'>'+s+'</option>';}).join('')+'</select></div>'+
  '<div class="fg"><span class="fl">Séquence</span><select class="fi" id="ecSeq">'+['Séquence 1','Séquence 2','Séquence 3','Séquence 4','Séquence 5','Séquence 6','Toutes séquences','Examens'].map(function(s){return '<option'+(s===item.seq?' selected':'')+'>'+s+'</option>';}).join('')+'</select></div>'+
  '<div class="fg"><span class="fl">Prix (FCFA)</span><input class="fi" id="ecPrix" type="number" value="'+(item.prix||0)+'"></div>'+
  '<div class="fg full"><span class="fl">Description</span><textarea class="fi" id="ecDesc" rows="2">'+( item.desc||'')+'</textarea></div>'+
  '<div class="fg full"><span class="fl">Aperçu du contenu (texte)</span><textarea class="fi" id="ecApercu" rows="3">'+(item.apercu||'')+'</textarea></div>'+
  '<div class="fg full"><span class="fl">📄 Aperçu PDF/Word (gratuit avant abonnement)</span>'+
  '<div class="fl2 fic g8 mt6" id="elPdfStat_'+itemId+'">'+(item.previewPdfKey?'<span class="bg bgg">'+_esc(item.previewPdfName||'apercu.pdf')+'</span> <button class="btn bo xs" onclick="_removeElPreview(\''+itemId+'\')" style="font-size:10px;padding:2px 8px">Suppr.</button>':'<span class="xs2 mut">Aucun apercu PDF</span>')+'</div>'+
  '<input type="file" class="fi mt6" id="elPdfFile_'+itemId+'" accept=".pdf,.doc,.docx" style="font-size:12px"></div>'+
  '<div class="fg full"><span class="fl">📦 Packs qui donnent accès</span>'+plansCheckboxes+'</div>'+
  '<div class="fg"><label style="display:flex;align-items:center;gap:8px;cursor:pointer;padding:8px;background:var(--grb);border-radius:8px"><input type="checkbox" id="ecGratuit"'+(item.gratuit?' checked':'')+'>  <span style="color:var(--gr)">Contenu gratuit</span></label></div>'+
  '</div>',
  '<button class="btn bo" onclick="cm()">Annuler</button><button class="btn bi" onclick="saveEditElearningContent(\''+itemId+'\')">Enregistrer</button>',true);
}

function saveEditElearningContent(itemId){
  var el=DB.elearning||{contenus:[]};
  var item=(el.contenus||[]).find(function(c){return c.id===itemId;});
  if(!item)return;
  item.titre=document.getElementById('ecTitre')?.value||item.titre;
  item.cat=document.getElementById('ecCat')?.value||item.cat;
  item.classe=document.getElementById('ecCls')?.value||item.classe;
  item.matiere=document.getElementById('ecMat')?.value||item.matiere;
  item.seq=document.getElementById('ecSeq')?.value||item.seq;
  item.prix=parseInt(document.getElementById('ecPrix')?.value)||0;
  item.desc=document.getElementById('ecDesc')?.value||'';
  item.apercu=document.getElementById('ecApercu')?.value||'';
  item.gratuit=document.getElementById('ecGratuit')?.checked||false;
  item.plans=['plan1','plan2','plan3','plan4'].filter(function(pid){return document.getElementById('ecPlan_'+pid)?.checked;});
  // Aperçu PDF optionnel
  var _elPdfIn=document.getElementById('elPdfFile_'+itemId);
  var _elPdfFile=_elPdfIn&&_elPdfIn.files&&_elPdfIn.files[0];
  if(_elPdfFile){
    var _elReader=new FileReader();
    _elReader.onload=function(ev){
      var pdfKey='elprev_'+itemId;
      idbSave(pdfKey,ev.target.result,_elPdfFile.name,_elPdfFile.type||'application/pdf',function(){
        item.previewPdfKey=pdfKey;item.previewPdfName=_elPdfFile.name;
        save();cm();re();toast('✓ Contenu + aperçu PDF enregistrés');
      });
    };
    _elReader.readAsDataURL(_elPdfFile);
  } else {
    save();cm();re();toast('✓ Contenu mis à jour');
  }
}

function _removeElPreview(itemId){
  var item=(DB.elearning&&DB.elearning.contenus||[]).find(function(c){return c.id===itemId;});if(!item)return;
  if(item.previewPdfKey){
    var _r=indexedDB.open('veritasDB',1);
    _r.onsuccess=function(e){try{e.target.result.transaction('files','readwrite').objectStore('files').delete(item.previewPdfKey);}catch(ex){}};
  }
  item.previewPdfKey='';item.previewPdfName='';
  save();mEditElearningContent(itemId);toast('✓ Aperçu PDF supprimé');
}


function saveElearningContent(){
  var titre=(document.getElementById('ecTitre')?.value||'').trim();
  var prix=parseInt(document.getElementById('ecPrix')?.value)||0;
  if(!titre){toast('Titre requis','warn');return;}
  toast('Enregistrement en cours...');
  if(!DB.elearning.contenus) DB.elearning.contenus=[];
  var isGratuit=document.getElementById('ecGratuit')?.checked||false;
  var selectedPlans=['plan1','plan2','plan3','plan4'].filter(function(pid){return document.getElementById('ecPlan_'+pid)?.checked;});
  var apercu=document.getElementById('ecApercu')?.value||'';
  var fileInput=document.getElementById('ecFile');
  function doSaveEl(fd,fn){
    var ftype=document.getElementById('ecType')?.value||'fichier';
    var extUrl=(document.getElementById('ecExternalUrl')?.value||'').trim();
    DB.elearning.contenus.push({
      id:gid(),cat:document.getElementById('ecCat')?.value||'cat1',
      titre:titre,classe:document.getElementById('ecCls')?.value||'3ème',
      matiere:document.getElementById('ecMat')?.value||'',
      seq:document.getElementById('ecSeq')?.value||'',
      prix:prix,gratuit:isGratuit,plans:selectedPlans,
      apercu:apercu,fichier:fn,fichierData:fd,
      fileType:ftype,
      externalUrl:(ftype==='html'&&extUrl)?extUrl:'',
      desc:document.getElementById('ecDesc')?.value||''
    });
    save();cm();re();toast('✓ Contenu ajouté au catalogue');
  }
  if(document.getElementById('ecType')?.value==='html'){
    var extUrl2=(document.getElementById('ecExternalUrl')?.value||'').trim();
    if(extUrl2){ doSaveEl('',''); return; }
    // HTML file uploaded
    if(fileInput&&fileInput.files&&fileInput.files[0]){
      var reader=new FileReader();reader.onload=function(e){doSaveEl(e.target.result,fileInput.files[0].name);};
      reader.readAsDataURL(fileInput.files[0]);
    } else { toast('Entrez une URL ou choisissez un fichier HTML','warn'); }
    return;
  }
  if(fileInput&&fileInput.files&&fileInput.files[0]){
    var reader=new FileReader();reader.onload=function(e){doSaveEl(e.target.result,fileInput.files[0].name);};
    reader.readAsDataURL(fileInput.files[0]);
  } else { doSaveEl('',''); }
}

function _delContenueVisiteur(id){
  var c=(DB.elearning.contenus||[]).find(function(x){return x.id===id;});
  if(!c) return;
  if(!confirm('Supprimer "'+_esc(c.titre)+'" du catalogue ?')) return;
  DB.elearning.contenus=(DB.elearning.contenus||[]).filter(function(x){return x.id!==id;});
  var _defIds=(defaultDB().elearning.contenus||[]).map(function(x){return x.id;});
  if(_defIds.indexOf(id)>=0){
    if(!DB.deletedDefaults) DB.deletedDefaults=[];
    if(DB.deletedDefaults.indexOf(id)<0) DB.deletedDefaults.push(id);
  }
  save();
  toast('&#10003; Contenu supprimé','ok');
  window._elCat='';
  vShowSec('elearning',document.querySelector('.vnav-btn.on'));
}
function deleteElearningContent(id){
  if(!confirm('Supprimer ce contenu ?\nNote : les ressources par défaut peuvent être restaurées depuis Paramètres.'))return;
  DB.elearning.contenus=(DB.elearning.contenus||[]).filter(function(c){return c.id!==id;});
  // Mémoriser la suppression des contenus par défaut pour éviter leur réapparition
  var _defIds=(defaultDB().elearning.contenus||[]).map(function(c){return c.id;});
  if(_defIds.indexOf(id)>=0){
    if(!DB.deletedDefaults)DB.deletedDefaults=[];
    if(DB.deletedDefaults.indexOf(id)<0)DB.deletedDefaults.push(id);
  }
  save();re();toast('✓ Contenu supprimé');
}

function restoreAllDefaultContents(){
  if(!iA())return;
  if(!confirm('Restaurer tous les contenus e-learning par défaut supprimés ?'))return;
  DB.deletedDefaults=[];
  var _defC2=defaultDB().elearning.contenus||[];
  var _curC2=DB.elearning.contenus||[];
  _defC2.forEach(function(dc){
    if((dc.resPedago||dc.externalUrl||dc.htmlContent)&&!_curC2.find(function(c){return c.id===dc.id;})){
      _curC2.push(dc);
    }
  });
  DB.elearning.contenus=_curC2;
  save();re();toast('✓ Ressources par défaut restaurées');
}

