function mGererAccesContenu(itemId){
  if(!iA())return;
  var el=DB.elearning||{contenus:[]};
  var item=(el.contenus||[]).find(function(c){return c.id===itemId;});
  if(!item)return;
  var accs=DB.visitorAccounts||[];
  if(!accs.length){M('👥 Gestion des accès','Aucun compte visiteur enregistré.','<p style="color:var(--ink3);font-size:13px">Aucun compte visiteur inscrit pour le moment.</p>','<button class="btn bo" onclick="cm()">Fermer</button>');return;}
  if(!item.unlockedFor)item.unlockedFor=[];
  if(!item.blockedFor)item.blockedFor=[];
  var rows='';
  accs.forEach(function(acc){
    var isUnlocked=item.unlockedFor.indexOf(acc.id)>=0;
    var isBlocked=item.blockedFor.indexOf(acc.id)>=0;
    var _ap=acc.plans||[],_ed=DB&&DB.elearning&&DB.elearning.plans||[];var _ep=_ap.reduce(function(ef,pid){if(ef.indexOf(pid)<0)ef.push(pid);var pd=_ed.find(function(p){return p.id===pid;});if(pd&&pd.planTags)pd.planTags.forEach(function(t){if(ef.indexOf(t)<0)ef.push(t);});return ef;},[]);
    var hasPlan=_ep.length&&item.plans&&item.plans.some(function(p){return _ep.indexOf(p)>=0;});
    var status=isBlocked?'<span style="background:#FEE2E2;color:#AE5353;font-size:10px;font-weight:700;padding:2px 8px;border-radius:6px">🔒 Bloqué</span>':isUnlocked?'<span style="background:#D1FAE5;color:#059669;font-size:10px;font-weight:700;padding:2px 8px;border-radius:6px">🔓 Débloqué</span>':hasPlan?'<span style="background:#E0EAFF;color:#3C8DFF;font-size:10px;font-weight:700;padding:2px 8px;border-radius:6px">✅ Via plan</span>':'<span style="background:#F3F4F6;color:#6B7280;font-size:10px;font-weight:700;padding:2px 8px;border-radius:6px">— Aucun accès</span>';
    rows+='<tr>'
      +'<td class="semi s">'+_esc(acc.pre)+' '+_esc(acc.nom)+'</td>'
      +'<td class="xs2 mut">'+_esc(acc.email||acc.tel||'')+'</td>'
      +'<td>'+status+'</td>'
      +'<td><div class="fl2 g4">'
      +(isBlocked
        ?'<button class="btn bgg xs" onclick="toggleAccesContenu(\''+itemId+'\',\''+acc.id+'\',\'unblock\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-lock"/></svg>Rétablir</button>'
        :isUnlocked
          ?'<button class="btn br2 xs" onclick="toggleAccesContenu(\''+itemId+'\',\''+acc.id+'\',\'block\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-lock"/></svg>Bloquer</button>'
            +'<button class="btn bo xs" onclick="toggleAccesContenu(\''+itemId+'\',\''+acc.id+'\',\'remove_unlock\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-x"/></svg>Retirer</button>'
          :'<button class="btn bgg xs" onclick="toggleAccesContenu(\''+itemId+'\',\''+acc.id+'\',\'unlock\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-lock"/></svg>Débloquer</button>'
            +'<button class="btn br2 xs" onclick="toggleAccesContenu(\''+itemId+'\',\''+acc.id+'\',\'block\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-lock"/></svg>Bloquer</button>'
      )
      +'</div></td>'
      +'</tr>';
  });
  M('👥 Accès : '+item.titre,'Gérer l\'accès individuel par utilisateur',
    '<div class="ib ibt mb14"><span>ℹ️</span><span><b>Débloquer</b> = accès sans abonnement. <b>Bloquer</b> = refus même avec un plan actif.</span></div>'
    +'<div class="tw"><table><thead><tr><th>Visiteur</th><th>Contact</th><th>Statut</th><th>Actions</th></tr></thead><tbody>'+rows+'</tbody></table></div>',
    '<button class="btn bo" onclick="cm()">Fermer</button>',true);
}

function toggleAccesContenu(itemId,accId,action){
  var el=DB.elearning||{contenus:[]};
  var item=(el.contenus||[]).find(function(c){return c.id===itemId;});
  if(!item)return;
  if(!item.unlockedFor)item.unlockedFor=[];
  if(!item.blockedFor)item.blockedFor=[];
  if(action==='unlock'){
    if(item.unlockedFor.indexOf(accId)<0)item.unlockedFor.push(accId);
    item.blockedFor=item.blockedFor.filter(function(id){return id!==accId;});
    toast('✅ Accès accordé');
  } else if(action==='block'){
    if(item.blockedFor.indexOf(accId)<0)item.blockedFor.push(accId);
    item.unlockedFor=item.unlockedFor.filter(function(id){return id!==accId;});
    toast('🔒 Accès bloqué');
  } else if(action==='remove_unlock'){
    item.unlockedFor=item.unlockedFor.filter(function(id){return id!==accId;});
    toast('Accès individuel retiré');
  } else if(action==='unblock'){
    item.blockedFor=item.blockedFor.filter(function(id){return id!==accId;});
    toast('🔓 Blocage levé');
  }
  save();
  // Re-ouvrir la modale avec les données à jour
  mGererAccesContenu(itemId);
}

