function validerAbonnement(planId){
  var nom=(document.getElementById('elNom')?.value||'').trim();
  var tel=(document.getElementById('elTel')?.value||'').trim();
  if(!nom||!tel){toast('Nom et WhatsApp requis','warn');return;}
  if(!DB.elearning) DB.elearning={plans:[],categories:[],contenus:[],abonnements:[],commandes:[]};
  if(!DB.elearning.abonnements) DB.elearning.abonnements=[];
  var plan=(DB.elearning.plans||[]).find(function(p){return p.id===planId;});
  var newAbo={
    id:gid(),plan:planId,nom:nom,tel:tel,
    classe:document.getElementById('elClasse')?.value||SES?.cls||'',
    email:document.getElementById('elEmail')?.value||SES?.email||'',
    date:today(),statut:'En attente',
    // Lien vers le compte visiteur si connecté — nécessaire pour activation automatique
    accountId: SES && (SES.type==='visiteur'||SES.type==='visiteur_inscrit') ? (SES.id||SES.accountId||'') : '',
    payRef: '' // sera renseigné lors du paiement
  };
  DB.elearning.abonnements.push(newAbo);
  // ── PROGRAMME PARTENARIAT v1 : tracking commission si code parrainage utilisé ──
  var elPromoCode = (document.getElementById('elPromo')?.value||'').trim().toUpperCase();
  if(elPromoCode && typeof applyPartnerCode==='function'){
    try {
      applyPartnerCode(elPromoCode, {
        refType:'elearning', refId:planId,
        refLabel: plan ? plan.nom : ('Abonnement '+planId),
        saleAmount: plan ? (plan.prix||0) : 0, qty:1
      });
      newAbo.partnerCode = elPromoCode; // trace dans l'abonnement
    } catch(e){ /* fail silent */ }
  }
  // Notification admin
  autoNotify(
    '🔔 Nouvelle souscription E-Learning',
    nom+' a souscrit au pack "'+(plan?plan.nom:planId)+'" ('+newAbo.classe+'). Tél: '+tel+'. En attente de validation.',
    'admin'
  );
  save();cm();
  var montant = plan ? (plan.prix||0) : 0;
  var aboId = newAbo.id; // capture avant le timeout
  setTimeout(function(){
    if(typeof openPaymentModal === 'function' && montant > 0){
      // Générer la ref en avance pour la stocker dans l'abonnement
      var payRef = 'ELRN'+new Date().toISOString().slice(2,10).replace(/-/g,'')+'-'+(Math.random().toString(36).slice(2,6)).toUpperCase();
      // Rétro-lier : stocker la payRef dans l'abonnement pour que mPayAttempts puisse la retrouver
      var aboToLink = (DB.elearning&&DB.elearning.abonnements||[]).find(function(a){return a.id===aboId;});
      if(aboToLink){aboToLink.payRef=payRef;save();}
      openPaymentModal({
        montant: montant,
        label: '🎓 '+(plan ? plan.nom : 'Abonnement E-Learning'),
        refPrefix: 'ELRN',
        ref: payRef,
        // ── v1.2 : metadata pour activation automatique ──
        intent: 'subscription',
        targetId: planId,
        customerAccountId: (SES&&(SES.type==='visiteur'||SES.type==='visiteur_inscrit')?SES.id:null),
        customerNom: nom,
        customerTel: tel
      });
    } else {
      toast('✓ Demande d\'abonnement envoyée ! L\'administration sera contactée.');
      var msg='🔔 *Nouvel abonnement E-Learning VÉRITAS !*\n\n📋 Plan: '+(plan?plan.nom:planId)+'\n👤 Nom: '+nom+'\n📱 Tél: '+tel+'\n📚 Classe: '+newAbo.classe+'\n📅 Date: '+today();
      window.open('https://wa.me/237697637739?text='+encodeURIComponent(msg),'_blank');
    }
  }, 100);
}

function commanderContenu(itemId){
  var el=DB.elearning||{contenus:[]};
  var item=el.contenus.find(function(c){return c.id===itemId;});
  if(!item) return;
  var cat=(el.categories||[]).find(function(c){return c.id===item.cat;})||{nom:'Autre'};
  /* Écran intermédiaire court-circuité (v1.15.8) : il ne demandait que nom et
     WhatsApp, soit exactement l'étape ① du modal de paiement. Un contenu
     e-learning n'a pas d'adresse de livraison — il ne restait donc aucune
     raison de faire saisir deux fois avant d'encaisser. */
  if(typeof openPaymentModal==='function' && (item.prix||0)>0){
    var ses=(typeof SES!=='undefined'&&SES)?SES:null;
    var nom=ses?((ses.pre||'')+' '+(ses.nom||'')).trim():'';
    var tel=ses?(ses.tel||''):'';
    if(!el.commandes) el.commandes=[];
    el.commandes.push({id:gid(),contenu:itemId,nom:nom,tel:tel,date:today(),
                       statut:'En attente',prix:item.prix});
    save();
    openPaymentModal({
      montant:item.prix, label:'📄 '+item.titre, refPrefix:'ELRN',
      intent:'contenu', targetId:itemId,
      customerAccountId:ses?(ses.accountId||ses.id):null,
      customerNom:nom, customerTel:tel
    });
    return;
  }
  M('🛒 Commander: '+item.titre,cat.nom,
  '<div style="text-align:center;margin-bottom:12px">'+
  '<div style="font-family:Montserrat,sans-serif;font-size:16px;font-weight:700;color:#142554">'+item.titre+'</div>'+
  '<div style="font-size:12px;color:var(--ink3)">'+item.classe+' · '+item.matiere+' · '+item.seq+'</div>'+
  '<div style="font-family:Georgia,serif;font-size:13px;color:var(--ink3);margin-top:6px;font-style:italic">'+item.desc+'</div>'+
  '<div style="font-family:Georgia,serif;font-size:22px;font-weight:700;color:#FFC93C;margin:10px 0">'+fmt(item.prix)+'</div>'+
  '</div>'+
  '<div class="fg2">'+
  '<div class="fg"><span class="fl">Votre nom *</span><input class="fi" id="cmdNom" placeholder="Nom complet"></div>'+
  '<div class="fg"><span class="fl">WhatsApp *</span><input class="fi" id="cmdTel" placeholder="697 637 739"></div>'+
  '</div>'+
  '<div class="ib ibt mb13"><span>💳</span><span>Après validation, vous serez redirigé(e) vers notre formulaire de paiement sécurisé.</span></div>',
  '<button class="btn bo" onclick="cm()">Annuler</button><button class="btn bi" onclick="validerCommandeContenu(\''+itemId+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-check"/></svg>Payer maintenant</button>',true);
}

function validerCommandeContenu(itemId){
  var nom=(document.getElementById('cmdNom')?.value||'').trim();
  var tel=(document.getElementById('cmdTel')?.value||'').trim();
  if(!nom||!tel){toast('Nom et WhatsApp requis','warn');return;}
  if(!DB.elearning.commandes) DB.elearning.commandes=[];
  var item=(DB.elearning.contenus||[]).find(function(c){return c.id===itemId;});
  DB.elearning.commandes.push({id:gid(),contenu:itemId,nom:nom,tel:tel,date:today(),statut:'En attente',prix:item?item.prix:0});
  save();cm();
  // v1.0 : ouvrir le modal de paiement unifié
  var montant = item ? (item.prix||0) : 0;
  setTimeout(function(){
    if(typeof openPaymentModal === 'function' && montant > 0){
      // `intent:'product'` sur un CONTENU e-learning : le droit de `product` est
      // null, l'élève payait son épreuve et rien ne s'ouvrait — ni ici, ni sur
      // le serveur. Même défaut que commanderContenu (corrigé au commit
      // précédent) ; ce chemin de repli l'avait gardé. Sans customerAccountId,
      // l'octroi n'a par ailleurs aucun compte où inscrire le droit.
      openPaymentModal({
        montant: montant,
        label: '📄 '+(item ? item.titre : 'Contenu E-Learning'),
        refPrefix: 'ELRN',
        intent: 'contenu',
        targetId: itemId,
        customerAccountId: (typeof SES!=='undefined'&&SES)?(SES.accountId||SES.id):null,
        customerNom: nom,
        customerTel: tel
      });
    } else {
      toast('✓ Commande envoyée ! Livraison par WhatsApp sous 24h.');
    }
  }, 100);
}

