function pgDataReset(){
  if(!iA())return na();
  var logs=(DB.loginLog||[]).length;
  var notifs=(DB.notifications||[]).length;
  var orders=(DB.visitorOrders||[]).length;
  var elCmds=(DB.elearning?.commandes||[]).length;
  var elSoum=(DB.elearning?.soumissions||[]).length;
  var total=logs+notifs+orders+elCmds+elSoum;

  var h='<div class="fl2 fic fsb mb16 fw g8"><div class="bold" style="font-size:18px">🗑 Nettoyage & Réinitialisation</div>';
  h+='<button class="btn bi" onclick="autoCleanOldData()"><svg class="vico bico" aria-hidden="true"><use href="#lc-zap"/></svg>Nettoyage automatique</button></div>';

  h+='<div class="ib ibr mb14"><span>⚠️</span><span><strong>Espace utilisé:</strong> ~'+Math.round(JSON.stringify(DB).length/1024)+' Ko — <strong>'+total+'</strong> entrées nettoyables. Imprimez avant de supprimer.</span></div>';

  h+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px">';

  var items=[
    ['loginLog','📋 Journal de connexions',logs,'Journal'],
    ['notifications','🔔 Notifications',notifs,'Notifications'],
    ['visitorOrders','🛒 Commandes boutique',orders,'Commandes'],
  ];
  items.forEach(function(it){
    h+='<div class="card"><div class="ct">'+it[1]+'</div>';
    h+='<div style="font-size:14px;margin-bottom:10px"><strong style="font-size:20px;color:var(--bl2)">'+it[2]+'</strong> entrées</div>';
    h+='<div class="fl2 g8"><button class="btn bo sm" onclick="printResetData(\''+it[0]+'\',\''+it[3]+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-printer"/></svg>Imprimer</button>';
    h+='<button class="btn br2 sm" onclick="resetData(\''+it[0]+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-trash"/></svg>Vider</button></div></div>';
  });

  // E-learning items
  [['commandes','📚 Commandes e-learning',elCmds],['soumissions','📤 Soumissions',elSoum]].forEach(function(it){
    h+='<div class="card"><div class="ct">'+it[1]+'</div>';
    h+='<div style="font-size:14px;margin-bottom:10px"><strong style="font-size:20px;color:var(--bl2)">'+it[2]+'</strong> entrées</div>';
    h+='<div class="fl2 g8"><button class="btn bo sm" onclick="printResetData(\'elearning.'+it[0]+'\',\''+it[1]+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-printer"/></svg>Imprimer</button>';
    h+='<button class="btn br2 sm" onclick="resetElData(\''+it[0]+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-trash"/></svg>Vider</button></div></div>';
  });

  h+='</div>';
  return h;
}

function autoCleanOldData(){
  if(!confirm('Nettoyer automatiquement les journaux de connexion (>30j), les notifications lues et les anciennes commandes livrées ?'))return;
  var today=new Date();
  var count=0;
  // Clean old login logs (keep last 50)
  if(DB.loginLog&&DB.loginLog.length>50){count+=DB.loginLog.length-50;DB.loginLog=DB.loginLog.slice(-50);}
  // Clean read notifications
  var oldNotifs=(DB.notifications||[]).length;
  DB.notifications=(DB.notifications||[]).filter(function(n){return !(n.read&&n.read.length>0);});
  count+=oldNotifs-(DB.notifications||[]).length;
  save();re();toast('✓ '+count+' éléments nettoyés');
}
function resetData(key){
  if(!confirm('Supprimer toutes les données de: '+key+' ?'))return;
  DB[key]=[];save();re();toast('✓ Données réinitialisées');
}

function resetElData(key){
  if(!confirm('Supprimer les données e-learning: '+key+' ?'))return;
  if(DB.elearning) DB.elearning[key]=[];
  save();re();toast('✓ Données réinitialisées');
}

function printResetData(key,title){
  var data=key.includes('.')?DB.elearning?.[key.split('.')[1]]||[]:DB[key]||[];
  if(data.length===0){toast('Aucune donnée à imprimer','warn');return;}
  var html=docHeader('Export: '+title);
  html+='<div style="padding:12px;font-size:10px"><table style="width:100%;border-collapse:collapse;font-size:9px">';
  html+='<thead><tr style="background:#142554;color:#fff">';
  var keys=Object.keys(data[0]||{}).filter(function(k){return k!=='fichierData'&&k.length<20;});
  keys.forEach(function(k){html+='<th style="padding:4px;text-align:left">'+k+'</th>';});
  html+='</tr></thead><tbody>';
  data.forEach(function(row){
    html+='<tr style="border-bottom:1px solid #ddd">';
    keys.forEach(function(k){
      var v=row[k];if(typeof v==='object')v=JSON.stringify(v);
      html+='<td style="padding:3px">'+((v||'')+'').substring(0,30)+'</td>';
    });
    html+='</tr>';
  });
  html+='</tbody></table></div>';
  printDoc(html,'Export '+title);
}

function exportAllData(){
  const dataStr=JSON.stringify(DB,null,2);
  const blob=new Blob([dataStr],{type:'application/json'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download='VERITAS_backup_'+today().replace(/\//g,'-')+'.json';
  a.click();URL.revokeObjectURL(url);
  toast('✓ Sauvegarde exportée');
}

function importAllData(){
  if(!isSA()&&!iA()){toast('Acc\u00e8s refus\u00e9','err');return;}
  if(!confirm('ATTENTION: Cette action remplacera TOUTES les donn\u00e9es actuelles.\nContinuer ?'))return;
  if(!confirm('CONFIRMATION: \u00cates-vous absolument s\u00fbr ? Cette op\u00e9ration est irr\u00e9versible.'))return;
  var input=document.createElement('input');
  input.type='file';input.accept='.json';
  input.onchange=function(e){
    var file=e.target.files[0];if(!file)return;
    if(file.size>10*1024*1024){toast('Fichier trop volumineux (max 10 Mo)','err');return;}
    var reader=new FileReader();
    reader.onload=function(evt){
      try{
        var imported=JSON.parse(evt.target.result);
        // Validation de structure
        if(!imported.school||!imported.students||!Array.isArray(imported.students)){
          toast('Fichier invalide : structure incorrecte','warn');return;
        }
        // Validation des types critiques
        var requiredArrays=['students','teachers','grades','payments'];
        for(var i=0;i<requiredArrays.length;i++){
          if(imported[requiredArrays[i]]&&!Array.isArray(imported[requiredArrays[i]])){
            toast('Donn\u00e9es corrompues : '+requiredArrays[i]+' invalide','err');return;
          }
        }
        // Nettoyer les champs dangereux potentiels (pas de scripts dans les noms)
        if(imported.students){imported.students.forEach(function(s){
          if(s.nom)s.nom=sanitizeInput(s.nom);
          if(s.pre)s.pre=sanitizeInput(s.pre);
        });}
        // Hasher les mots de passe import\u00e9s en clair
        Object.assign(DB,imported);save();
        setTimeout(function(){_migratePasswords();},200);
        toast('\u2713 Donn\u00e9es import\u00e9es avec succ\u00e8s');
        setTimeout(function(){location.reload();},1500);
      }catch(err){toast('Erreur: '+err.message,'err');}
    };
    reader.readAsText(file);
  };
  input.click();
}

