function getTeacherTotalHours(tid){
  return(DB.teacherHours||[]).filter(h=>h.tid===tid).reduce((s,h)=>s+h.heures,0);
}

function getTeacherPay(tid){
  return getTeacherTotalHours(tid)*(DB.tauxHoraire||2000);
}

function mAddTeacherHours(tid){
  const t=T(tid);if(!t)return;
  M('Enregistrer des heures',''+t.pre+' '+t.nom+' — '+t.mat2,
    '<div class="fg2">'+
    '<div class="fg"><span class="fl">Date</span><input class="fi" id="thDate" type="date" value="'+new Date().toISOString().split('T')[0]+'"></div>'+
    '<div class="fg"><span class="fl">Classe</span><select class="fi" id="thCls">'+CLS.map(c=>'<option>'+c+'</option>').join('')+'</select></div>'+
    '<div class="fg"><span class="fl">Nombre d\'heures *</span><input class="fi" id="thHeures" type="number" min="1" max="12" value="2"></div>'+
    '<div class="fg"><span class="fl">Description</span><input class="fi" id="thDesc" placeholder="Cours, TP, examen..."></div>'+
    '</div>'+
    '<div class="ib ibi mt8 mb0"><span>💰</span><span>Taux horaire: <strong>'+fmt(DB.tauxHoraire||2000)+' /h</strong></span></div>',
    '<button class="btn bo" onclick="cm()">Annuler</button><button class="btn bi" onclick="saveTeacherHours(\''+tid+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-check"/></svg>Enregistrer</button>');
}

function saveTeacherHours(tid){
  const t=T(tid);if(!t)return;
  const heures=parseInt(document.getElementById('thHeures')?.value);
  const date=document.getElementById('thDate')?.value;
  if(!heures||heures<1){toast('Heures invalides','warn');return;}
  const dateStr=date?new Date(date).toLocaleDateString('fr-FR'):today();
  if(!DB.teacherHours)DB.teacherHours=[];
  DB.teacherHours.push({id:gid(),tid,date:dateStr,heures,cls:document.getElementById('thCls')?.value||'',
    matiere:t.mat2,desc:document.getElementById('thDesc')?.value||''});
  save();cm();re();toast('✓ '+heures+'h enregistrées — '+fmt(heures*(DB.tauxHoraire||2000)));
}

// ─── LOGIN MULTI-RÔLES ────────────────────────────
function swLR(t){
  lr=t;
  window._loginAttempts=0;
  ["V","E","T","A","SA"].forEach(x=>$("ltb"+x)?.classList.remove("on"));
  const map={visiteur:"V",eleve:"E",enseignant:"T",admin:"A",superadmin:"SA"};
  if($("ltb"+map[t]))$("ltb"+map[t]).classList.add("on");
  const lfa=$("lFormArea"),lb=$("lBtn"),ls=$("lSubtitle");
  if(t==="visiteur"){
    if(lfa)lfa.innerHTML=`<div id="lVisitorMsg" style="padding:14px;background:var(--blb);border-radius:var(--r);border:1px solid var(--bld);text-align:center;font-size:13px;color:var(--bl)"><div style="font-size:24px;margin-bottom:8px">🌐</div><div class="semi">Portail Public</div><div style="font-size:13px;color:var(--ink4);margin-top:4px">Accédez aux informations du centre sans connexion</div></div>`;
    lb.textContent="Accéder au portail →";lb.onclick=()=>goToVisitor();
    if(ls)ls.textContent="Portail Public";
  } else {
    const labels={eleve:"Espace Élève",enseignant:"Espace Enseignant",admin:"Administration",superadmin:"Super Administration"};
    const placeholders={eleve:"Matricule",enseignant:"Identifiant",admin:"Identifiant",superadmin:"Identifiant"};
    if(ls)ls.textContent=labels[t]||"Connexion";
    if(lfa)lfa.innerHTML=`<div class="lf"><label>Identifiant</label><input id="lu" placeholder="${placeholders[t]||'Identifiant'}" autocomplete="username"></div><div class="lf"><label>Mot de passe</label><div class="pw"><input id="lp" type="password" placeholder="••••••••" autocomplete="current-password" onkeydown="if(event.key==='Enter')doLogin()"><button class="pwe" onclick="tp('lp',this)">👁</button></div></div>`;
    lb.textContent="Connexion →";lb.onclick=doLogin;
  }
  /* Texte d'aide propre au rôle, écrit HORS de lFormArea pour survivre aux
     bascules d'onglet. Il répond à la question que l'écran laissait sans
     réponse : « je n'ai pas d'identifiant, je fais quoi ? » — un enseignant
     ne devine pas que son compte est délivré par le centre. */
  var aide=$("lAide");
  if(aide){
    var A={
      eleve:"Votre identifiant est votre <b>matricule</b>, remis par le centre à l'inscription. Perdu ? Écrivez-nous sur WhatsApp, il vous est renvoyé.",
      enseignant:"Les comptes enseignants sont <b>ouverts par le centre</b>, ils ne se créent pas en ligne. Pas encore le vôtre ? Passez par « Enseignant » ci-dessous.",
      admin:"Accès réservé à l'administration du centre.",
      superadmin:"Accès réservé à la direction.",
      visiteur:""
    };
    aide.innerHTML=A[t]||"";
    aide.style.display=A[t]?"block":"none";
  }
  $("lerr").style.display="none";
}

// ═══════════════════════════════════════════════
// AUTHENTIFICATION DIRECTE — Sans OTP
// ═══════════════════════════════════════════════
// ═══ [SECTION] Mission 2.B/C — Rate limiting + comparaison à temps constant ═══
// [SEC v1.2] Comparaison de mots de passe à temps constant (résistance timing attack)
function _safeCmp(a,b){
  if(typeof a!=='string'||typeof b!=='string')return false;
  if(a.length!==b.length)return false;
  var diff=0;
  for(var i=0;i<a.length;i++)diff|=a.charCodeAt(i)^b.charCodeAt(i);
  return diff===0;
}

// [SEC v1.2] Rate limiting login (couche supplémentaire au-dessus de _checkLoginLock)
var _loginAttempts={count:0,locked:false,timer:null};
function _checkLoginRateLimit(){
  // v1.2.x : ne bloque QUE si déjà verrouillé. Le compteur d'échecs monte désormais
  // dans _recordLoginFail (sur ÉCHEC réel), plus à chaque tentative : un mot de passe
  // CORRECT (même au 5e essai) ou le mode visiteur ne doivent JAMAIS être bloqués.
  return !_loginAttempts.locked;
}

var _otpPending={code:null,user:null,data:null,expires:0,attempts:0};
var _otpTimer=null;

function generateOTP(){
  return String(Math.floor(100000+Math.random()*900000));
}

function sendOTP(adminData, onSent){
  // Connexion directe sans OTP — système monofichier sans serveur
  if(!DB.loginLog)DB.loginLog=[];
  DB.loginLog.push({user:adminData.user,role:adminData.type||'admin',date:today()});
  save();
  toast('✅ Bienvenue '+adminData.nom);
  go2SES({...adminData});
  if(onSent) onSent();
}

