// ═══════════════════════════════════════════════════════════════════════════
// S3 (v1.2.x) — Sync PAR UTILISATEUR (élève/parent) côté client.
// Récupère la tranche de données de l'élève authentifié depuis student_data.php
// pour qu'il voie SES notes/paiements sur N'IMPORTE QUEL appareil. Lecture seule
// ici (l'écriture viendra brancher action=submit). Repli silencieux si hors-ligne.
// ═══════════════════════════════════════════════════════════════════════════
function _studentSyncUrl(){
  try{ return (LWS_API.db||'').replace(/db\.php(\?.*)?$/,'student_data.php'); }catch(e){ return ''; }
}
async function _studentSyncFetch(login,password){
  var url=_studentSyncUrl(); if(!url||!navigator.onLine) return null;
  try{
    var ctrl=(typeof AbortController!=='undefined')?new AbortController():null;
    var tmt=ctrl?setTimeout(function(){ctrl.abort();},10000):null;
    var r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({action:'fetch',login:login,password:password}),signal:ctrl?ctrl.signal:undefined});
    if(tmt)clearTimeout(tmt);
    if(!r.ok) return null;
    var j=await r.json();
    // S3 v1.2.x (Étape 3) : mémoriser le token par compte émis par le serveur
    // → permet à content.php d'authentifier sans renvoyer le mot de passe.
    if(j&&j.token){try{window._vrtContentToken=j.token;sessionStorage.setItem('_vrtCT',j.token);}catch(e){}}
    // S3 v1.2.x (Étape 2) : injecter les contenus PROTÉGÉS autorisés (métadonnées)
    // pour que l'abonné les VOIE sur n'importe quel appareil (lecture via content.php).
    if(j&&j.ok&&j.contenusAutorises){try{_studentApplyContenus(j.contenusAutorises);}catch(e){}}
    return (j&&j.ok)?j:null;
  }catch(e){ return null; }
}
// S3 v1.2.x (Étape 2) — fusionne les contenus PROTÉGÉS autorisés (métadonnées serveur)
// sans JAMAIS écraser un contenu local complet. N'ajoute QUE ceux qui ont un
// fichierProtege (lisibles via content.php par leur id) → aucune entrée injouable.
function _studentApplyContenus(list){
  if(!list||!list.length) return;
  if(!DB.elearning) DB.elearning={};
  if(!DB.elearning.contenus) DB.elearning.contenus=[];
  var byId={}; DB.elearning.contenus.forEach(function(c){ if(c&&c.id) byId[c.id]=true; });
  var added=0;
  list.forEach(function(c){
    if(!c||!c.id||byId[c.id]) return;     // ne jamais remplacer un contenu local existant
    if(!c.fichierProtege) return;          // seul le contenu protégé est lisible via la porte
    DB.elearning.contenus.push(c); byId[c.id]=true; added++;
  });
  if(added){ try{ if(typeof save==='function') save(); }catch(e){} }
}
function _contentToken(){
  try{ return window._vrtContentToken || sessionStorage.getItem('_vrtCT') || ''; }catch(e){ return ''; }
}
// Étape 2 — diffusion par la porte serveur UNIQUEMENT pour le contenu PROTÉGÉ
// (item.fichierProtege). Modèle piloté par la donnée : pas de flag global (qui
// n'atteindrait pas les visiteurs, lesquels ne synchronisent pas db.php). content.php
// n'a besoin que de l'id + du token. Le contenu non protégé (data:/idbKey/fichierUrl
// public) conserve exactement son comportement actuel.
function _serverGateUrl(item){
  if(!item||!item.id||!item.fichierProtege) return null;
  var tok=_contentToken(); if(!tok) return null;            // pas authentifié serveur → repli
  var base; try{ base=(LWS_API.db||'').replace(/db\.php(\?.*)?$/,'content.php'); }catch(e){ base=''; }
  if(!base) return null;
  return {
    url: base+'?id='+encodeURIComponent(item.id)+'&token='+encodeURIComponent(tok),
    name: item.fichier||(item.titre||'document'),
    type: item.fileType||''
  };
}
// Fusionne la tranche serveur dans la base locale par UPSERT (id) — n'efface JAMAIS
// les enregistrements d'autres élèves (sûr sur un appareil admin/partagé). Persiste
// en local ; save() ne pousse pas vers le serveur pour un non-admin.
function _studentApplySlice(slice){
  if(!slice||!slice.student||!slice.student.id) return;
  var sid=slice.student.id;
  DB.students=DB.students||[];
  var si=DB.students.findIndex(function(s){return s.id===sid;});
  if(si>=0) DB.students[si]=slice.student; else DB.students.push(slice.student);
  function _upsert(arrName,list){
    DB[arrName]=DB[arrName]||[];
    var byId={}; DB[arrName].forEach(function(x,idx){ if(x&&x.id!=null) byId[x.id]=idx; });
    (list||[]).forEach(function(x){
      if(!x) return;
      if(x.id!=null && byId[x.id]!=null){ DB[arrName][byId[x.id]]=x; }
      else { DB[arrName].push(x); if(x.id!=null) byId[x.id]=DB[arrName].length-1; }
    });
  }
  _upsert('grades',slice.grades);
  _upsert('payments',slice.payments);
  _upsert('absences',slice.absences);
  _upsert('submissions',slice.submissions);
  _upsert('devoirs',slice.devoirs);
  try{ if(typeof save==='function') save(); }catch(e){}
}
// Rafraîchissement en arrière-plan (appareil déjà connu) — non bloquant.
function _studentSyncBg(login,password){
  try{
    _studentSyncFetch(login,password).then(function(slice){
      if(slice){ _studentApplySlice(slice); try{ if(typeof re==='function') re(); }catch(e){} }
    });
  }catch(e){}
}

async function doLogin(){
  // [SEC v1.2] Rate limiting global (bloque après 5 tentatives toutes cibles)
  if(!_checkLoginRateLimit())return;
  var u=($("lu")?.value||"").trim(),p=$("lp")?.value||"";
  $("lerr").style.display="none";
  if(lr==="visiteur"){goToVisitor();return;}
  if(!u||!p){$("lerr").style.display="block";$("lerr").textContent="Veuillez remplir tous les champs.";return;}
  // Anti brute-force par compte
  var lock=_checkLoginLock(u);
  if(lock.locked){$("lerr").style.display="block";$("lerr").innerHTML='<div>Compte temporairement verrouill\u00e9</div><div style="font-size:11px;margin-top:4px;color:#6b7280">R\u00e9essayez dans '+lock.remaining+' secondes</div>';return;}
  if(lr==="eleve"){
    var sa2=null;
    if(DB.studentAccounts){for(var i=0;i<DB.studentAccounts.length;i++){
      var a2=DB.studentAccounts[i];
      if(a2.user.toLowerCase()===u.toLowerCase()){var ok=await verifyPassword(p,a2.pwd,a2.user,a2);if(ok){sa2=a2;break;}}
    }}
    if(sa2){var s=S(sa2.eid);if(s){window._vrtPrevLogin=sa2.lastLoginISO||sa2.lastLogin||null;sa2.lastLogin=today();sa2.lastLoginISO=new Date().toISOString();save();_recordLoginSuccess(u);_loginAttempts.count=0;go2SES({...s,type:'eleve',sid:s.id,accountId:sa2.id,plans:sa2.plans||[]});_studentSyncBg(u,p);return;}}
    // Visiteurs inscrits en ligne
    var va2=null;
    if(DB.visitorAccounts){for(var j=0;j<DB.visitorAccounts.length;j++){
      var v2=DB.visitorAccounts[j];
      if(v2.user.toLowerCase()===u.toLowerCase()&&v2.statut!=='suspendu'){var ok2=await verifyPassword(p,v2.pwd,v2.user,v2);if(ok2){va2=v2;break;}}
    }}
    if(va2){window._vrtPrevLogin=va2.lastLoginISO||va2.lastLogin||null;va2.lastLogin=today();va2.lastLoginISO=new Date().toISOString();save();_recordLoginSuccess(u);_loginAttempts.count=0;_createSession({id:va2.id,nom:va2.nom,pre:va2.pre,mat:va2.user,cls:va2.cls,tel:va2.tel,type:'visiteur_inscrit',accountId:va2.id,plans:va2.plans||[]});
      // v1.4.9 : compte au profil anglophone → interface intégralement en anglais au login
      try{ if(va2.profil&&va2.profil.sys==='en'&&typeof setLang==='function') setLang('en', true); }catch(e){}
      hideAll();$('VISITOR').style.display='flex';initVisitor();setTimeout(_updateVisitorHeader,120);setTimeout(function(){try{if(typeof _welcomeBack==='function')_welcomeBack();}catch(e){}},1200);_studentSyncBg(u,p);return;}
    // S3 (v1.2.x) : appareil neuf — aucun compte en local → tenter le serveur (lecture).
    var _slice=await _studentSyncFetch(u,p);
    if(_slice&&_slice.student&&_slice.student.id){
      _studentApplySlice(_slice);
      _recordLoginSuccess(u);_loginAttempts.count=0;
      go2SES({..._slice.student,type:'eleve',sid:_slice.student.id,accountId:(_slice.account&&_slice.account.user)||u,plans:(_slice.account&&_slice.account.plans)||[]});
      toast('☁️ Données chargées depuis le serveur','ok');
      return;
    } else if(_slice&&_slice.account){
      var _ac=_slice.account;
      _recordLoginSuccess(u);_loginAttempts.count=0;
      _createSession({id:_ac.user,nom:_ac.nom||'',pre:_ac.pre||'',mat:_ac.user,cls:_ac.cls||'',type:'visiteur_inscrit',accountId:_ac.user,plans:_ac.plans||[]});
      hideAll();$('VISITOR').style.display='flex';initVisitor();setTimeout(_updateVisitorHeader,120);
      return;
    }
  } else if(lr==="enseignant"){
    var t=DB.teachers.find(function(t2){return t2.user===u;});
    if(t&&DB.tpwd[u]){
      // Wrapper pour permettre l'upgrade DB.tpwd[u] via recordRef.pwd
      var _tpwdRef={get pwd(){return DB.tpwd[u];},set pwd(v){DB.tpwd[u]=v;}};
      var okT=await verifyPassword(p,DB.tpwd[u],u,_tpwdRef);
      if(okT){DB.loginLog.push({user:u,role:'enseignant',date:today()});save();_recordLoginSuccess(u);_loginAttempts.count=0;go2SES({...t,type:'enseignant',tid:t.id});return;}
    }
  } else if(lr==="admin"){
    var foundAdmin=null;
    if(DB.admins){for(var k=0;k<DB.admins.length;k++){
      var ad=DB.admins[k];
      if(ad.user===u){var okA=await verifyPassword(p,ad.pwd,ad.user,ad);if(okA){foundAdmin=ad;break;}}
    }}
    if(foundAdmin){_recordLoginSuccess(u);_loginAttempts.count=0;sendOTP({...foundAdmin,type:'admin'});return;}
  } else if(lr==="superadmin"){
    var sa=DB.superAdmin;
    if(sa&&u===sa.user){var okS=await verifyPassword(p,sa.pwd,sa.user,sa);
      if(okS){_recordLoginSuccess(u);_loginAttempts.count=0;sendOTP({...sa,type:'superadmin',pre:'',role2:'superadmin'});return;}
    }
  }
  _recordLoginFail(u);
  $("lerr").style.display="block";
  if($("lp"))$("lp").value="";
  var lockAfter=_checkLoginLock(u);
  if(lockAfter.locked){
    $("lerr").innerHTML='<div>Identifiants incorrects</div><div style="font-size:11px;margin-top:4px;color:#AE5353">Compte verrouill\u00e9 pour '+lockAfter.remaining+'s apr\u00e8s trop de tentatives</div>';
    return;
  }

  /* \u2550\u2550\u2550 \u00ab Identifiants incorrects \u00bb peut \u00eatre un MENSONGE, et il l'\u00e9tait \u2550\u2550\u2550
     Les comptes administrateurs ne vivent QUE dans le navigateur : DB.admins
     et DB.superAdmin viennent de localStorage, aliment\u00e9 par defaultDB() au
     premier chargement. Sur un appareil neuf \u2014 ou apr\u00e8s un vidage de cache,
     une navigation priv\u00e9e, un changement de t\u00e9l\u00e9phone \u2014 la liste locale est
     celle du jeu de D\u00c9MONSTRATION (\u00ab directeur \u00bb, \u00ab secretaire \u00bb). Le vrai
     compte de l'administrateur, lui, est dans la base SERVEUR.

     R\u00e9sultat : le mot de passe est bon, le compte existe, et l'application
     r\u00e9pond \u00ab Identifiants incorrects \u00bb. C'est le signalement \u00ab les comptes
     admins ne s'ouvrent pas \u00bb.

     Et la sortie de secours \u00e9tait inatteignable : cloudRestoreDB() exige
     isSA(), donc il fallait d\u00e9j\u00e0 \u00eatre connect\u00e9 pour r\u00e9cup\u00e9rer de quoi se
     connecter. On ouvre donc la porte ICI, avant toute session \u2014 la cl\u00e9 de
     synchronisation joue ce r\u00f4le, c'est d\u00e9j\u00e0 un secret de niveau
     administrateur.

     \u26a0\ufe0f On ne restaure QUE les listes de comptes, jamais la base enti\u00e8re :
     \u00e9craser un appareil qui porte du travail non synchronis\u00e9 pour r\u00e9gler un
     probl\u00e8me de connexion serait un rem\u00e8de pire que le mal. */
  var estAdmin = (lr === 'admin' || lr === 'superadmin');
  var connuIci = false;
  try{
    if(lr === 'superadmin') connuIci = !!(DB.superAdmin && DB.superAdmin.user === u);
    else connuIci = (DB.admins || []).some(function(a){ return a && a.user === u; });
  }catch(e){}

  if(estAdmin && !connuIci){
    $("lerr").innerHTML =
      '<div>Ce compte n\'existe pas <b>sur cet appareil</b>.</div>'
      + '<div style="font-size:11.5px;margin-top:5px;line-height:1.5;color:#AE5353">'
      + 'Les comptes d\'administration sont stock\u00e9s dans le navigateur. Sur un appareil neuf, '
      + 'ou apr\u00e8s un vidage de cache, il faut d\'abord les r\u00e9cup\u00e9rer depuis le serveur.</div>'
      + '<button class="btn bi" style="margin-top:9px;width:100%" onclick="_restaurerComptesAdmin()">'
      + 'R\u00e9cup\u00e9rer mes comptes depuis le serveur</button>';
    return;
  }

  $("lerr").innerHTML='<div>Identifiants incorrects</div>';
}

/* \u2550\u2550\u2550 \u00ab /app.html#connexion \u00bb doit MONTRER le formulaire, et le GARDER \u2550\u2550\u2550
   Signal\u00e9 par Jacques, capture \u00e0 l'appui : l'adresse #connexion affichait les
   panneaux d'abonnement de l'ancienne interface, pas le formulaire.

   Ce n'est pas un mauvais aiguillage \u2014 c'est une COURSE. Le routeur d'ancres
   se d\u00e9clenche 60 ms apr\u00e8s le chargement et appelle bien l'ouverture du
   formulaire ; mais l'amor\u00e7age de l'espace visiteur, lui, rend l'accueil
   ENSUITE (et le re-rend plusieurs fois : c'est un comportement connu de cette
   page). Le dernier qui \u00e9crit gagne, et ce n'est pas nous.

   On ne se contente donc pas d'ouvrir : on RE-V\u00c9RIFIE pendant une seconde et
   demie, et on repose le formulaire s'il a \u00e9t\u00e9 recouvert. On s'arr\u00eate net d\u00e8s
   qu'une session existe \u2014 un utilisateur d\u00e9j\u00e0 connect\u00e9 n'a rien \u00e0 faire l\u00e0 \u2014
   et on ne touche \u00e0 rien si l'\u00e9cran de connexion est d\u00e9j\u00e0 \u00e0 l'affiche. */
window._ouvrirConnexionAncre = function(){
  var essais = 0;
  var poser = function(){
    try{
      if(typeof SES !== 'undefined' && SES) return;        // connect\u00e9 : ne pas insister
      var ls = document.getElementById('LS');
      if(ls && getComputedStyle(ls).display === 'none'){
        if(typeof showLogin === 'function') showLogin('eleve');
      }
    }catch(e){}
    if(++essais < 7) setTimeout(poser, 220);               // ~1,5 s de vigilance
  };
  poser();
};

/* R\u00e9cup\u00e8re les LISTES DE COMPTES depuis la base serveur, avant toute session.
   Demande la cl\u00e9 de synchronisation : c'est elle qui fait autorit\u00e9 ici, et
   elle n'ouvre aucune session \u2014 elle ne fait que rapatrier de quoi en ouvrir
   une. Le mot de passe reste exig\u00e9 juste apr\u00e8s. */
window._restaurerComptesAdmin = function(){
  var cc = null;
  try{ cc = (DB.cloudConfig && DB.cloudConfig.secret) || (_loadCloudConfigCache() || {}).secret || ''; }catch(e){ cc = ''; }
  if(typeof M !== 'function') return;
  M('R\u00e9cup\u00e9rer les comptes d\'administration',
    'La cl\u00e9 de synchronisation est demand\u00e9e une seule fois sur cet appareil',
    '<div class="fg"><span class="fl">Cl\u00e9 de synchronisation</span>'
    + '<input class="fi" id="_racSec" type="password" autocomplete="off" value="' + _esc(cc) + '" placeholder="fournie par l\'administrateur"></div>'
    + '<p style="font-size:12.5px;color:var(--ink3);margin:9px 0 0;line-height:1.55">'
    + 'Seules les <b>listes de comptes</b> sont rapatri\u00e9es \u2014 \u00e9l\u00e8ves, notes et paiements de cet appareil '
    + 'ne sont pas touch\u00e9s. Votre mot de passe vous sera toujours demand\u00e9 ensuite.</p>'
    + '<div id="_racMsg" style="margin-top:10px;font-size:13px"></div>',
    '<button class="btn bo" onclick="cm()">Annuler</button>'
    + '<button class="btn bi" onclick="_restaurerComptesAdminGo()">R\u00e9cup\u00e9rer</button>');
};

window._restaurerComptesAdminGo = function(){
  var sec = (_ge('_racSec') && _ge('_racSec').value || '').trim();
  if(!sec){ _si('_racMsg','<span style="color:#AE5353">Cl\u00e9 requise.</span>'); return; }
  _si('_racMsg','<span style="color:var(--ink3)">Connexion au serveur\u2026</span>');
  if(!DB.cloudConfig) DB.cloudConfig = { url:_VRT_API, secret:'', lastSync:'Jamais' };
  var base = (DB.cloudConfig.url || _VRT_API || 'https://veritas-school.com/api').replace(/\/$/,'');
  fetch(base + '/db.php?t=' + Date.now(), { headers:{ 'Authorization':'Bearer ' + sec } })
    .then(function(r){
      if(r.status === 401 || r.status === 403) throw new Error('Cl\u00e9 refus\u00e9e par le serveur.');
      if(!r.ok) throw new Error('Serveur injoignable (HTTP ' + r.status + ').');
      return r.json();
    })
    .then(function(d){
      if(!d || d.error) throw new Error((d && d.error) || 'R\u00e9ponse vide.');
      var nb = 0;
      if(Array.isArray(d.admins) && d.admins.length){ DB.admins = d.admins; nb += d.admins.length; }
      if(d.superAdmin && d.superAdmin.user){ DB.superAdmin = d.superAdmin; nb += 1; }
      if(!nb) throw new Error('Le serveur ne contient aucun compte d\'administration.');
      // La cl\u00e9 a fait ses preuves : on la garde pour la synchronisation \u00e0 venir.
      DB.cloudConfig.secret = sec;
      try{ _saveCloudConfigCache && _saveCloudConfigCache(); }catch(e){}
      save();
      _si('_racMsg','<span style="color:#0B7A2A">' + nb + ' compte(s) r\u00e9cup\u00e9r\u00e9(s). Saisissez maintenant votre mot de passe.</span>');
      setTimeout(function(){ try{ cm(); }catch(e){} var lp = _ge('lp'); if(lp) lp.focus(); }, 1400);
    })
    .catch(function(e){
      _si('_racMsg','<span style="color:#AE5353">' + _esc(e.message) + '</span>');
    });
};

function go2SES(acc){
  try{
    // v1.19.20 : go2SES est la porte d'entree de l'application (admin,
    // enseignant, eleve) et elle n'ecrivait RIEN dans sessionStorage.
    // Consequences : (1) un rechargement deconnectait, (2) save() et _fbFetch
    // lisent sessionStorage pour autoriser la synchro — elle etait donc
    // silencieusement desactivee, le voyant au vert et rien d'envoye.
    _createSession(acc);
    hideAll();
    $("APP").style.display="flex";
    buildNav();topUI();goTo("dashboard");
    // 👋 Apprenant de retour après une longue absence (élève ; visiteur inscrit géré au login)
    setTimeout(function(){try{ if(typeof _welcomeBack==='function') _welcomeBack(); }catch(e){}}, 1200);
    // Afficher l'indicateur de sync cloud pour les admins
    setTimeout(function(){
      if(iA()){
        var dot=document.getElementById('vSyncDot');
        if(dot){
          dot.style.display='inline-flex';
          var lastSync=DB.cloudConfig&&DB.cloudConfig.lastSync;
          _setSyncDot(lastSync?'ok':'pending',lastSync||'');
        }
        // 🔐 v1.2.2 : alerte mot de passe par défaut (admin connecté)
        setTimeout(function(){try{_warnDefaultPasswords();}catch(e){}},2000);
        // 📣 Relances : scan des inscrits inactifs (1×/jour, client-side) + rappel à l'admin
        setTimeout(function(){try{
          if(typeof _scanInactifs!=='function')return;
          var _tI=new Date().toISOString().slice(0,10);
          var _al=localStorage.getItem('_vrtRelanceToast')===_tI;
          var _n=(_scanInactifs()||[]).length;
          if(_n>0&&!_al){ localStorage.setItem('_vrtRelanceToast',_tI);
            toast('📣 '+_n+' inscrit'+(_n>1?'s':'')+' inactif'+(_n>1?'s':'')+' à relancer (E-Learning → Relances)','info'); }
        }catch(e){}}, 2400);
        // Sync intelligente au login : compare lastModified local vs serveur
        // Si serveur plus récent → pull (restaure) ; sinon → push
        var cfg=DB.cloudConfig;
        if(cfg&&cfg.url&&cfg.secret){
          setTimeout(function(){
            if(!iA())return;
            var localTS=DB.lastModified||0;
            // FIX: GET Firebase au lieu de sync.php
            _fbFetch(LWS_API.db+'?t='+Date.now())
            .then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.json();})
            .then(function(serverDB){
              if(!serverDB||!serverDB.school||!serverDB.students){if(!_autoSyncDirty)_cloudAutoSync();return;}
              var serverTS=serverDB.lastModified||0;
              var localScore2=_dbScore(DB),serverScore2=_dbScore(serverDB);
              if(serverTS>localTS||(serverScore2>localScore2+5)){
                // BUG-03 FIX : le polling background ne remplace DB que pour les admins
                if(!iA())return;
                // Serveur plus récent OU plus riche → fusionner
                var cloudCfg=DB.cloudConfig;
                function _mL(la,sa){var m=JSON.parse(JSON.stringify(sa||[]));var si={};m.forEach(function(x){si[x.id||x.mat]=true;});(la||[]).forEach(function(x){var k=x.id||x.mat;if(k&&!si[k])m.push(x);});return m;}
                var lb2=DB.books||[],lg2=DB.galleryImages||[],le2=(DB.elearning&&DB.elearning.contenus)||[];
                DB=serverDB;
                // BUG-09/BUG-03 FIX : re-migration systématique
                _migrateDB();
                DB.books=_mL(lb2,DB.books);
                DB.galleryImages=_mL(lg2,DB.galleryImages);
                if(!DB.elearning)DB.elearning={contenus:[],plans:[],abonnements:[],commandes:[],soumissions:[]};
                DB.elearning.contenus=_mL(le2,DB.elearning.contenus);
                DB.cloudConfig=cloudCfg;
                DB.cloudConfig.lastSync=new Date().toLocaleString('fr-FR')+' (auto-sync ↓)';
                save();
                _setSyncDot('ok',DB.cloudConfig.lastSync);
                toast('🔄 Données synchronisées depuis le cloud','info');
                setTimeout(function(){re();},800);
                // Re-pousser la fusion si admin
                setTimeout(function(){if(iA()){_autoSyncDirty=true;_cloudAutoSync();}},6000);
              } else {
                // Local à jour ou plus récent → pousser vers serveur
                if(!_autoSyncDirty)_cloudAutoSync();
              }
            })
            .catch(function(){
              if(!_autoSyncDirty)_cloudAutoSync();
            });
          },3000);
          // Démarrer le polling arrière-plan (sync automatique toutes les 90s)
          setTimeout(_startBgPoll, 8000);
        } else {
          // 🔐 v1.2.2 : admin connecté mais aucune clé Cloud sur cet appareil → la demander une fois.
          setTimeout(function(){try{_ensureCloudSecret();}catch(e){}},600);
        }
      }
    },300);
  }catch(err){
    // Afficher l'erreur si le chargement du tableau de bord échoue
    $("APP").style.display="none";
    $("LS").style.display="flex";
    $("lerr").style.display="block";
    $("lerr").innerHTML="❌ Erreur chargement: "+err.message+"<br><small style='font-size:10px'>Essayez de <button onclick=\"localStorage.removeItem(\'vrt10\');location.reload()\" style=\"background:#AE5353;color:#fff;border:none;padding:2px 8px;border-radius:4px;cursor:pointer\">réinitialiser</button></small>";
    console.error("go2SES error:",err);
  }
}
