    marketplace_teacher:pgMarketplaceEnseignant,parrainage_teacher:pgParrainageEns,
    ambassa:pgAmbassa,
    // ── PROGRAMME PARTENARIAT v1 ──
    partenariat:pgPartnerships,
    'partenariat-enseignant':function(){return pgPartnerProgram('enseignant');},
