function printVisitorReceipt(oid){
  var o=(DB.visitorOrders||[]).find(function(x){return x.id===oid;});
  if(!o)return;
  printDoc('<div style="max-width:500px;margin:0 auto;font-family:Outfit,sans-serif">'+docHeader("Reçu — Commande en ligne")+
  '<div style="padding:16px 26px">'+
  [["Client",o.nom],["Téléphone",o.tel||"—"],["Manuel/Produit",o.bookTitle],["Date",o.date],["Référence",o.id]].map(function(x){return '<div style="display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #e8e4dc"><span style="color:#6b5e52;font-size:12px">'+x[0]+'</span><span style="font-weight:700;font-size:12px">'+x[1]+'</span></div>';}).join("")+
  (o.promo?'<div style="display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #e8e4dc"><span style="color:#6b5e52;font-size:12px">Code promo</span><span style="font-weight:700;font-size:13px;color:#1a6e40">'+o.promo+'</span></div>':"")+
  '<div style="background:#142554;color:#fff;padding:12px 16px;display:flex;justify-content:space-between;align-items:center;margin-top:12px;border-radius:7px"><span style="font-size:13px;font-weight:700">TOTAL PAYÉ</span><span style="font-family:Fira Code;font-size:20px;font-weight:700;color:#FFC93C">'+fmt(o.prix)+'</span></div>'+
  '</div></div>',"Reçu commande — "+o.nom);
}

// ═══════════════════════════════════════════════
// STATISTIQUES & PERFORMANCES COMPARATIVES
// ═══════════════════════════════════════════════
function pgHonneur(){
  if(!iA())return na();
  var tri=window._hTri||TRS[0];
  var h='<div class="fl2 fic fsb mb16 fw g8">';
  h+='<div class="tabs">'+TRS.map(function(t){return '<button class="tab'+(t===tri?' on':'')+'" onclick="window._hTri=\''+t+'\';re()">'+t+'</button>';}).join('')+'</div>';
  h+='<button class="btn bi sm" onclick="printHonneur()"><svg class="vico bico" aria-hidden="true"><use href="#lc-printer"/></svg>Imprimer</button></div>';
  // Compute all students with averages
  var allData=[];
  CLS.forEach(function(cls){
    DB.students.filter(function(s){return s.cls===cls;}).forEach(function(s){
      var gr=DB.grades.filter(function(g){return g.eid===s.id&&g.tri===tri;});
      var tc=gr.reduce(function(a,g){return a+(+g.coef||1);},0)||1;
      if(!gr.length)return;
      var moy=gr.reduce(function(a,g){return a+(_subMoy(g))*g.coef;},0)/tc;
      var mention=moy>=16?'Félicitations':moy>=14?'Tableau d\'honneur':moy>=12?'Encouragements':'';
      var sanctions=[];
      var abs=(DB.absences||[]).filter(function(a){return a.eid===s.id;});
      var absNJ=abs.filter(function(a){return!a.justifie;}).reduce(function(sum,a){return sum+(a.heures||0);},0);
      if(absNJ>10)sanctions.push('Abs. non justifiées: '+absNJ+'h');
      // Sub-average subjects
      var subMoy=gr.filter(function(g){return _subMoy(g)<10;}).map(function(g){return g.sub+' ('+((_subMoy(g)).toFixed(1))+')';});
      allData.push({s:s,cls:cls,moy:moy,mention:mention,sanctions:sanctions,subMoy:subMoy,gr:gr});
    });
  });
  allData.sort(function(a,b){return b.moy-a.moy;});
  // KPIs
  var felicitations=allData.filter(function(d){return d.mention==='Félicitations';}).length;
  var honneur=allData.filter(function(d){return d.mention==='Tableau d\'honneur';}).length;
  var encouragements=allData.filter(function(d){return d.mention==='Encouragements';}).length;
  var subAvg=allData.filter(function(d){return d.moy<10;}).length;
  h+='<div class="sg">';
  h+='<div class="sc scg"><div class="sci">🏆</div><div class="scl">Félicitations</div><div class="scv vg">'+felicitations+'</div></div>';
  h+='<div class="sc scb"><div class="sci">⭐</div><div class="scl">Tableau d\'honneur</div><div class="scv vb">'+honneur+'</div></div>';
  h+='<div class="sc scgr"><div class="sci">📌</div><div class="scl">Encouragements</div><div class="scv vgr">'+encouragements+'</div></div>';
  h+='<div class="sc scr"><div class="sci">⚠️</div><div class="scl">Sous la moyenne</div><div class="scv vr">'+subAvg+'</div></div>';
  h+='</div>';
  // Félicitations table
  if(felicitations>0){
    h+='<div class="card"><div class="ct" style="color:var(--gold)">🏆 Félicitations du Conseil de Classe (≥16/20)</div>';
    h+='<div class="tw"><table><thead><tr><th>#</th><th>Élève</th><th>Classe</th><th>Moyenne</th><th>Matières sous la moyenne</th><th></th></tr></thead><tbody>';
    var rank=0;
    allData.filter(function(d){return d.mention==='Félicitations';}).forEach(function(d){
      rank++;
      h+='<tr><td class="semi">'+rank+'</td><td class="semi">'+d.s.pre+' '+d.s.nom+'</td><td><span class="bg bgd">'+d.cls+'</span></td>';
      h+='<td class="mono bold" style="color:var(--gr)">'+d.moy.toFixed(2)+'/20</td>';
      h+='<td class="xs2">'+(d.subMoy.length?'<span style="color:var(--re)">'+d.subMoy.join(', ')+'</span>':'<span style="color:var(--gr)">Aucune</span>')+'</td>';
      h+='<td><button class="btn bgr2 xs" onclick="printStudentHonneur(\''+d.s.id+'\',\''+tri+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-printer"/></svg>️</button></td></tr>';
    });
    h+='</tbody></table></div></div>';
  }
  // Tableau d\'honneur table
  if(honneur>0){
    h+='<div class="card mt16"><div class="ct" style="color:var(--bl)">⭐ Tableau d\'Honneur (14-15.99/20)</div>';
    h+='<div class="tw"><table><thead><tr><th>#</th><th>Élève</th><th>Classe</th><th>Moyenne</th><th>Matières sous la moyenne</th><th></th></tr></thead><tbody>';
    rank=0;
    allData.filter(function(d){return d.mention==='Tableau d\'honneur';}).forEach(function(d){
      rank++;
      h+='<tr><td class="semi">'+rank+'</td><td class="semi">'+d.s.pre+' '+d.s.nom+'</td><td><span class="bg bgd">'+d.cls+'</span></td>';
      h+='<td class="mono bold" style="color:var(--bl)">'+d.moy.toFixed(2)+'/20</td>';
      h+='<td class="xs2">'+(d.subMoy.length?'<span style="color:var(--re)">'+d.subMoy.join(', ')+'</span>':'<span style="color:var(--gr)">Aucune</span>')+'</td>';
      h+='<td><button class="btn bgr2 xs" onclick="printStudentHonneur(\''+d.s.id+'\',\''+tri+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-printer"/></svg>️</button></td></tr>';
    });
    h+='</tbody></table></div></div>';
  }
  // Encouragements
  if(encouragements>0){
    h+='<div class="card mt16"><div class="ct"><span class="ct-ico"><svg class="vico" aria-hidden="true"><use href="#lc-mappin"/></svg></span>Encouragements (12-13.99/20)</div>';
    h+='<div class="tw"><table><thead><tr><th>#</th><th>Élève</th><th>Classe</th><th>Moyenne</th><th>Matières sous la moyenne</th><th></th></tr></thead><tbody>';
    rank=0;
    allData.filter(function(d){return d.mention==='Encouragements';}).forEach(function(d){
      rank++;
      h+='<tr><td class="semi">'+rank+'</td><td class="semi">'+d.s.pre+' '+d.s.nom+'</td><td><span class="bg bgd">'+d.cls+'</span></td>';
      h+='<td class="mono bold">'+d.moy.toFixed(2)+'/20</td>';
      h+='<td class="xs2">'+(d.subMoy.length?'<span style="color:var(--re)">'+d.subMoy.join(', ')+'</span>':'<span style="color:var(--gr)">Aucune</span>')+'</td>';
      h+='<td><button class="btn bgr2 xs" onclick="printStudentHonneur(\''+d.s.id+'\',\''+tri+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-printer"/></svg>️</button></td></tr>';
    });
    h+='</tbody></table></div></div>';
  }
  // Sous la moyenne with sanctions
  if(subAvg>0){
    h+='<div class="card mt16"><div class="ct" style="color:var(--re)">⚠️ Élèves sous la moyenne (<10/20) — Sanctions possibles</div>';
    h+='<div class="tw"><table><thead><tr><th>#</th><th>Élève</th><th>Classe</th><th>Moyenne</th><th style="color:var(--re)">Matières en difficulté</th><th>Sanctions</th><th></th></tr></thead><tbody>';
    rank=0;
    allData.filter(function(d){return d.moy<10;}).forEach(function(d){
      rank++;
      h+='<tr style="background:rgba(184,40,40,.03)"><td class="semi">'+rank+'</td><td class="semi">'+d.s.pre+' '+d.s.nom+'</td><td><span class="bg bgr">'+d.cls+'</span></td>';
      h+='<td class="mono bold" style="color:var(--re)">'+d.moy.toFixed(2)+'/20</td>';
      h+='<td class="xs2" style="color:var(--re)">'+d.subMoy.join(', ')+'</td>';
      h+='<td class="xs2">'+(d.sanctions.length?d.sanctions.join('; '):'—')+'</td><td></td></tr>';
    });
    h+='</tbody></table></div></div>';
  }
  return h;
}
function printHonneur(){
  var tri=window._hTri||TRS[0];
  var allData=[];
  CLS.forEach(function(cls){
    DB.students.filter(function(s){return s.cls===cls;}).forEach(function(s){
      var gr=DB.grades.filter(function(g){return g.eid===s.id&&g.tri===tri;});
      var tc=gr.reduce(function(a,g){return a+(+g.coef||1);},0)||1;
      if(!gr.length)return;
      var moy=gr.reduce(function(a,g){return a+(_subMoy(g))*g.coef;},0)/tc;
      if(moy>=12)allData.push({nom:s.pre+' '+s.nom,cls:cls,moy:moy,mention:moy>=16?'Félicitations':moy>=14?'Tableau d\'honneur':'Encouragements'});
    });
  });
  allData.sort(function(a,b){return b.moy-a.moy;});
  var html=docHeader('Tableau d\'Honneur — '+tri);
  html+='<div style="padding:16px"><table style="width:100%;border-collapse:collapse;font-size:12px">';
  html+='<thead><tr style="background:#142554;color:#fff"><th style="padding:8px">#</th><th style="padding:8px;text-align:left">Élève</th><th style="padding:8px">Classe</th><th style="padding:8px">Moyenne</th><th style="padding:8px">Mention</th></tr></thead><tbody>';
  allData.forEach(function(d,i){
    var col=d.mention==='Félicitations'?'#c49a3c':d.mention==='Tableau d\'honneur'?'#1a3a8a':'#1a6e40';
    html+='<tr style="border-bottom:1px solid #eee"><td style="padding:6px;text-align:center">'+(i+1)+'</td><td style="padding:6px;font-weight:700">'+d.nom+'</td><td style="padding:6px;text-align:center">'+d.cls+'</td><td style="padding:6px;text-align:center;font-family:Fira Code;font-weight:700;color:'+col+'">'+d.moy.toFixed(2)+'/20</td><td style="padding:6px;text-align:center;color:'+col+';font-weight:700">'+d.mention+'</td></tr>';
  });
  html+='</tbody></table></div>';
  printDoc(html,'Tableau d\'Honneur '+tri,'landscape');
}
function printStudentHonneur(sid,tri){
  var s=S(sid);if(!s)return;
  var gr=DB.grades.filter(function(g){return g.eid===sid&&g.tri===(tri||window._hTri||TRS[0]);});
  var tc=gr.reduce(function(a,g){return a+(+g.coef||1);},0)||1;
  if(!gr.length)return toast('Pas de notes','warn');
  var moy=gr.reduce(function(a,g){return a+(_subMoy(g))*g.coef;},0)/tc;
  if(moy<12)return toast('Moyenne insuffisante pour un tableau d\'honneur','warn');
  var mention=moy>=16?'FÉLICITATIONS':moy>=14?'TABLEAU D\'HONNEUR':'ENCOURAGEMENTS';
  var mentionColor=moy>=16?'#c49a3c':moy>=14?'#1a3a8a':'#1a6e40';
  var sc=DB.school;var logo=getLogo();var tri2=tri||window._hTri||TRS[0];
  var allMoy=DB.students.filter(function(st){return st.cls===s.cls;}).map(function(st){
    var gG=DB.grades.filter(function(g){return g.eid===st.id&&g.tri===tri2;});
    var tC=gG.reduce(function(a,g){return a+(+g.coef||1);},0)||1;
    return gG.length?gG.reduce(function(a,g){return a+(_subMoy(g))*g.coef;},0)/tC:null;
  }).filter(function(m){return m!==null;}).sort(function(a,b){return b-a;});
  var rang=allMoy.findIndex(function(m){return Math.abs(m-moy)<0.001;})+1;
  // v1.2.5 : rendu unifié sur le modèle certificat VÉRITAS (logo, calligraphie, sceau, QR).
  if(typeof _certVeritasHTML==='function'){
    var _mn=moy>=16?'Félicitations':moy>=14?'Tableau d\'Honneur':'Encouragements';
    var _tc=moy>=16?'#C9A227':moy>=14?'#25407e':'#1a6e40';
    var _rf=(typeof gid==='function'?gid().substring(0,8).toUpperCase():'VRT');
    return printDoc(_certVeritasHTML({
      titleHTML:'<i>Tableau</i> d\'Honneur', plainTitle:'Tableau d Honneur',
      kicker:'Excellence académique · '+tri2+' · '+((sc&&sc.annee)||'2025-2026'),
      cta:'Le Centre VÉRITAS inscrit avec fierté',
      name:s.pre+' '+s.nom, badgeIcon:'trophy', badgeLabel:_mn, tierColor:_tc, certRef:_rf,
      descHTML:'élève de <b>'+_esc(s.cls)+'</b> (matricule '+_esc(s.mat)+'), pour ses résultats et son sérieux, avec une moyenne de <b>'+moy.toFixed(2)+' / 20</b> — '+rang+'<sup>e</sup> sur '+allMoy.length+'.',
      qrData:((sc&&sc.nom)||'VERITAS')+' | Tableau Honneur | '+s.pre+' '+s.nom+' | '+s.cls+' '+s.mat+' | Moy '+moy.toFixed(2)+'/20 Rang '+rang+'/'+allMoy.length+' | '+tri2+' | Ref '+_rf
    }),'Certificat '+_mn+' — '+s.pre+' '+s.nom,'landscape');
  }
  var html='<div style="max-width:900px;margin:0 auto;font-family:Outfit,sans-serif;background:#fff;padding:8px;border-radius:7px;overflow:hidden;box-shadow:inset 0 0 0 2px '+mentionColor+',inset 0 0 0 6px #142554,inset 0 0 0 8px '+mentionColor+';-webkit-print-color-adjust:exact;print-color-adjust:exact">';
  html+='<div style="background:linear-gradient(135deg,#142554,#1a3a8a);padding:16px 24px;text-align:center">';
  html+='<div style="display:flex;justify-content:space-between;font-size:13px;color:rgba(255,255,255,.5);margin-bottom:8px"><span>RÉPUBLIQUE DU CAMEROUN</span><span>REPUBLIC OF CAMEROON</span></div>';
  html+='<img src="'+logo+'" style="width:50px;height:50px;border-radius:50%;background:#fff;padding:2px;object-fit:contain;margin-bottom:6px">';
  html+='<div style="font-family:Libre Baskerville,serif;font-size:20px;color:#FFC93C;letter-spacing:2px">'+(sc?.nom||'VÉRITAS')+'</div>';
  html+='<div style="font-size:13px;color:rgba(255,255,255,.4);margin-top:4px">'+(sc?.ville||'Yaoundé')+'</div></div>';
  // Certificate body
  html+='<div style="padding:30px;text-align:center">';
  html+='<div style="font-size:13px;color:#888;text-transform:uppercase;letter-spacing:3px;margin-bottom:12px">Année scolaire '+(sc?.annee||'2024-2025')+' — '+tri2+'</div>';
  html+='<div style="font-size:28px;font-family:Libre Baskerville,serif;font-weight:700;color:'+mentionColor+';margin:16px 0;letter-spacing:2px">'+mention+'</div>';
  html+='<div style="width:60px;height:2px;background:'+mentionColor+';margin:12px auto"></div>';
  html+='<div style="font-size:13px;color:#666;margin:16px 0">Le Conseil de Classe décerne la mention</div>';
  html+='<div style="font-size:13px;color:'+mentionColor+';font-weight:700;margin-bottom:16px">« '+mention+' »</div>';
  html+='<div style="font-size:14px;color:#333;margin:8px 0">à l\'élève</div>';
  // Student photo + name
  html+='<div style="margin:16px auto;display:flex;flex-direction:column;align-items:center">';
  if(s.photo)html+='<img src="'+s.photo+'" style="width:60px;height:60px;border-radius:50%;object-fit:cover;border:2px solid '+mentionColor+';margin-bottom:8px">';
  html+='<div style="font-family:Libre Baskerville,serif;font-size:17px;font-weight:700;color:#142554">'+s.pre+' '+s.nom+'</div>';
  html+='<div style="font-size:13px;color:#888;margin-top:4px">Classe de '+s.cls+' — Matricule: '+s.mat+'</div>';
  html+='</div>';
  // Stats
  html+='<div style="display:flex;justify-content:center;gap:24px;margin:20px 0">';
  html+='<div style="text-align:center"><div style="font-size:13px;color:#aaa;text-transform:uppercase;letter-spacing:1px">Moyenne</div><div style="font-family:Fira Code;font-size:24px;font-weight:700;color:'+mentionColor+'">'+moy.toFixed(2)+'/20</div></div>';
  html+='<div style="text-align:center"><div style="font-size:13px;color:#aaa;text-transform:uppercase;letter-spacing:1px">Rang</div><div style="font-family:Fira Code;font-size:24px;font-weight:700;color:#142554">'+rang+'<span style="font-size:13px;color:#888"> / '+allMoy.length+'</span></div></div>';
  html+='</div>';
  html+='<div style="width:60px;height:2px;background:'+mentionColor+';margin:16px auto"></div>';
  // Signatures
  html+='<div style="display:flex;justify-content:space-between;margin-top:30px;padding:0 20px">';
  html+='<div style="text-align:center"><div style="font-size:13px;color:#aaa;text-transform:uppercase;letter-spacing:.5px">Prof. Principal</div><div style="margin-top:30px;border-top:1px solid #ddd;padding-top:4px;font-size:13px;color:#bbb">Signature</div></div>';
  html+='<div style="text-align:center"><div style="font-size:13px;color:#aaa;text-transform:uppercase;letter-spacing:.5px">Le Directeur</div><div style="margin-top:30px;border-top:1px solid #ddd;padding-top:4px;font-size:13px;color:#bbb">'+(sc?.directeur||'')+'</div></div>';
  html+='</div></div>';
  // QR Code authentification
  var certRef=gid().substring(0,8).toUpperCase();
  var certQRData=(sc?.nom||'VERITAS')+'\nCertificat '+mention+'\n'+s.pre+' '+s.nom+'\n'+s.cls+' - '+s.mat+'\nMoy:'+moy.toFixed(2)+'/20 Rang:'+rang+'/'+allMoy.length+'\n'+today()+'\nREF:'+certRef;
  html+='<div style="display:flex;align-items:center;justify-content:flex-end;gap:8px;padding:8px 16px;border-top:1.5px solid '+mentionColor+'">';
  html+='<div style="text-align:right;line-height:1.3"><div style="font-size:7px;color:'+mentionColor+';font-weight:800;letter-spacing:1.5px;text-transform:uppercase">Document Authentifié</div>';
  html+='<div style="font-size:6px;color:#888;margin-top:1px">'+today()+' · Réf: <strong style="color:#142554;font-family:monospace">'+certRef+'</strong></div>';
  html+='<div style="font-size:5px;color:#aaa;margin-top:1px">Scannez le QR code pour vérifier</div></div>';
  html+='<div style="flex-shrink:0;border:1.5px solid '+mentionColor+';border-radius:4px;padding:2px;background:#fff;line-height:0">'+_qrSvg.toSVG(certQRData,1)+'</div>';
  html+='</div>';
  html+='<div style="background:#f5f3ef;border-top:1px solid #ddd;padding:6px;text-align:center;font-size:13px;color:#bbb">'+(sc?.nom||'VÉRITAS')+' · '+new Date().toLocaleDateString('fr-FR')+'</div>';
  html+='</div>';
  printDoc(html,'Certificat '+mention+' — '+s.pre+' '+s.nom,'landscape');
}


// (exportClassStats v1 supprimée)


// ═══════════════════════════════════════════════
// INSCRIPTIONS ÉLÈVES (admin/superadmin)
// ═══════════════════════════════════════════════
function pgStudents(){
  if(!iA())return na();
  const fc=window._scls||'Toutes',q=(window._sq||'').toLowerCase();
  const list=DB.students.filter(s=>(fc==='Toutes'||s.cls===fc)&&(s.nom+' '+s.pre+' '+s.mat).toLowerCase().includes(q));
  return`
  <div class="sg">
    <div class="sc scg"><div class="sci">🎓</div><div class="scl">Inscrits</div><div class="scv vg">${DB.students.length}</div></div>
    <div class="sc scgr"><div class="sci">✅</div><div class="scl">Payé</div><div class="scv vgr">${DB.students.filter(s=>s.stat==='Payé').length}</div></div>
    <div class="sc scr"><div class="sci">❌</div><div class="scl">Impayés</div><div class="scv vr">${DB.students.filter(s=>s.stat==='Impayé').length}</div></div>
    <div class="sc scb"><div class="sci">⏳</div><div class="scl">En attente</div><div class="scv vb">${DB.students.filter(s=>s.stat==='En attente').length}</div></div>
  </div>
  <div class="card">
    <div class="fl2 fic fsb mb16 fw g8">
      <div class="fl2 fic g8 fw">
        <div class="srch" style="width:220px"><span class="si">🔍</span><input class="fi" style="padding-left:33px" placeholder="Nom, matricule..." value="${window._sq||''}" oninput="window._sq=this.value;re()"></div>
        <div class="tabs">${['Toutes',...CLS].map(c=>`<button class="tab${fc===c?' on':''}" onclick="window._scls='${c}';re()">${c}</button>`).join('')}</div>
      </div>
      <div class="fl2 g8">
        <button class="btn bi" onclick="mAddStu()">＋ Nouvelle inscription</button>
        <button class="excel-btn" onclick="exportStudentsList(window._scls||'Toutes')">📊 Exporter Excel</button>
        <button class="excel-btn import" onclick="importStudents()">📥 Importer Excel</button>
        ${isSA()?`<button class="btn bpu sm" onclick="mAddStudentAccount()"><svg class="vico bico" aria-hidden="true"><use href="#lc-lock"/></svg>Créer compte élève</button>`:''}
      </div>
    </div>
    <div class="tw"><table>
    <thead><tr><th>Matricule</th><th>Élève</th><th>Classe</th><th>Parent</th><th>Frais/mois</th><th>Statut</th><th>Actions</th></tr></thead>
    <tbody>${list.map(s=>`<tr>
      <td class="mono xs2" style="color:var(--gold)">${s.mat}</td>
      <td><div class="fl2 fic g9">${s.photo?'<img src="'+s.photo+'" style="width:34px;height:34px;border-radius:50%;object-fit:cover;border:2px solid '+(s.sex==='F'?'var(--pud)':'var(--bld)')+';flex-shrink:0;cursor:pointer" onclick="event.stopPropagation();uploadStudentPhoto(\''+s.id+'\')" title="Cliquer pour changer la photo">':'<div class="av" style="width:34px;height:34px;background:'+(s.sex==='F'?'var(--pub)':'var(--blb)')+';color:'+(s.sex==='F'?'var(--pu)':'var(--bl)')+';border:1.5px solid '+(s.sex==='F'?'var(--pud)':'var(--bld)')+';font-size:13px;cursor:pointer" onclick="event.stopPropagation();uploadStudentPhoto(\''+s.id+'\')" title="Ajouter une photo">'+s.pre[0]+'</div>'}
        <div><div class="bold s">${s.pre} ${s.nom}</div><div class="xs2 mut">${s.sex==='F'?'♀':'♂'} · ${s.dob||'—'}</div></div></div></td>
      <td><span class="bg bgd">${s.cls}</span></td>
      <td><div class="bold s">${s.parent||'—'}</div><div class="mono xs2" style="color:${s.ptel?'var(--bl)':'var(--re)'}">${s.ptel||'⚠ Non renseigné'}</div></td>
      <td class="mono" style="color:var(--gold)">${fmt(s.frais)}</td>
      <td><span class="bg ${s.stat==='Payé'?'bgg':s.stat==='Impayé'?'bgr':'bgo'}">${s.stat}</span></td>
      <td><div class="fl2 g4">
        <button class="btn bo xs" onclick="viewStu('${s.id}')">👁</button>
        <button class="btn bg2 xs" onclick="editStu('${s.id}')"><svg class="vico bico" aria-hidden="true"><use href="#lc-pencil"/></svg>️</button>
        ${isSA()?`<button class="btn br2 xs" onclick="delStu('${s.id}')">🗑</button>`:''}
      </div></td>
    </tr>`).join('')}
    ${list.length===0?`<tr><td colspan="7"><div class="empty"><div class="empty-ico">🔍</div>Aucun résultat</div></td></tr>`:''}
    </tbody></table></div>
  </div>`;
}

function mAddStudentAccount(){
  const existing=DB.studentAccounts?.map(sa=>sa.eid)||[];
  const noAccount=DB.students.filter(s=>!existing.includes(s.id));
  if(noAccount.length===0){toast('Tous les élèves ont déjà un compte','warn');return;}
  M('Créer compte élève','Accès espace élève',`<div class="fg2">
    <div class="fg full"><span class="fl">Élève *</span><select class="fi" id="saEtu">${noAccount.map(s=>`<option value="${s.id}">${s.pre} ${s.nom} (${s.mat})</option>`).join('')}</select></div>
    <div class="fg"><span class="fl">Identifiant *</span><input class="fi" id="saUser" placeholder="Ex: VRT-006" oninput="autoFillSaPwd()"></div>
    <div class="fg"><span class="fl">Mot de passe *</span><input class="fi" id="saPwd2" placeholder="Ex: Nom2024!"></div>
  </div><div class="ib ibt mb0 mt8"><span>ℹ️</span><span>L\'identifiant par défaut est le matricule de l\'élève.</span></div>`,
  `<button class="btn bo" onclick="cm()">Annuler</button><button class="btn bi" onclick="createStudentAccount()"><svg class="vico bico" aria-hidden="true"><use href="#lc-check"/></svg>Créer le compte</button>`);
  setTimeout(()=>{
    const sel=document.getElementById('saEtu');
    if(sel){sel.addEventListener('change',()=>autoFillSaPwd());}
    autoFillSaPwd();
  },100);
}
function autoFillSaPwd(){const sel=document.getElementById('saEtu');if(!sel)return;const sid=sel.value;const st=S(sid);if(st){const u=document.getElementById('saUser');const p=document.getElementById('saPwd2');if(u)u.value=st.mat;if(p)p.value=st.nom+'2024!';}}
function createStudentAccount(){
  const eid=document.getElementById('saEtu')?.value;
  const user=(document.getElementById('saUser')?.value||'').trim();
  const pwd=document.getElementById('saPwd2')?.value||'';
  if(!eid||!user||!pwd){toast('Tous les champs requis','warn');return;}
  if(DB.studentAccounts?.find(sa=>sa.user.toLowerCase()===user.toLowerCase())){toast('Identifiant déjà utilisé','warn');return;}
  if(!DB.studentAccounts)DB.studentAccounts=[];
  DB.studentAccounts.push({id:gid(),eid,user,pwd,lastLogin:null});
  save();cm();re();toast('✓ Compte élève créé');
}

function mAddStu(){
  const n=String(DB.students.length+1).padStart(3,'0');
  M('Nouvelle inscription','Enregistrement d\'un nouvel élève',`<div class="ib ibt mb14"><span>💡</span><span>Le <strong>numéro WhatsApp parent</strong> est essentiel pour les envois automatiques.</span></div>
  <div class="fg2">
  <div class="fg"><span class="fl">Matricule (auto)</span><input class="fi" id="sM" value="VRT-${n}" readonly style="opacity:.6"></div>
  <div class="fg"><span class="fl">Sexe</span><select class="fi" id="sSx"><option value="M">♂ Masculin</option><option value="F">♀ Féminin</option></select></div>
  <div class="fg"><span class="fl">Nom de famille *</span><input class="fi" id="sN" placeholder="En MAJUSCULES"></div>
  <div class="fg"><span class="fl">Prénom(s) *</span><input class="fi" id="sP"></div>
  <div class="fg"><span class="fl">Date de naissance</span><input class="fi" id="sD" type="date"></div>
  <div class="fg"><span class="fl">Classe *</span><select class="fi" id="sCl">${CLS.map(c=>`<option>${c}</option>`).join('')}</select></div>
  <div class="fg"><span class="fl">Téléphone élève</span><input class="fi" id="sTl" type="tel" placeholder="+237 6 00 00 00 00"></div>
  <div class="fg"><span class="fl">Nom du parent / tuteur *</span><input class="fi" id="sPr" placeholder="M./Mme ..."></div>
  <div class="fg full" style="background:var(--blb);padding:10px;border-radius:var(--r);border:1px solid var(--bld)">
    <span class="fl" style="color:var(--bl)">📱 Tél. parent WhatsApp +237</span>
    <input class="fi" id="sPT" type="tel" placeholder="+237 6 00 00 00 00" style="border-color:var(--bld);margin-top:6px">
  </div>
  <div class="fg"><span class="fl">Frais mensuels (FCFA)</span><input class="fi" id="sF" type="number" value="25000" min="0"></div>
  <div class="fg"><span class="fl">Statut paiement</span><select class="fi" id="sSt"><option>En attente</option><option>Payé</option><option>Impayé</option></select></div>
  <div class="fg full"><span class="fl">📸 Photo de l&#39;élève</span>
    <div class="fl2 fic g12 mt8"><div id="newStuPhotoPreview" class="photo-upload-zone" onclick="pickNewStuPhoto()">📷</div>
    <div class="xs2 mut">Cliquer pour sélectionner une photo<br>(max 500Ko, format JPG/PNG)</div>
    <input type="file" id="newStuPhotoInput" accept="image/*" style="display:none" onchange="previewNewStuPhoto(this)"></div>
  </div>
  </div>`,
  `<button class="btn bo" onclick="cm()">Annuler</button><button class="btn bi" onclick="saveStu()"><svg class="vico bico" aria-hidden="true"><use href="#lc-check"/></svg>Enregistrer</button>`);
}
function pickNewStuPhoto(){document.getElementById('newStuPhotoInput')?.click();}
function previewNewStuPhoto(input){
  const file=input.files[0];if(!file)return;
  if(file.size>500000){toast('Photo trop lourde (max 500Ko)','warn');input.value='';return;}
  const reader=new FileReader();
  reader.onload=function(e){
    const preview=document.getElementById('newStuPhotoPreview');
    if(preview){preview.innerHTML='<img src="'+e.target.result+'" style="width:100%;height:100%;object-fit:cover;border-radius:50%">';
    preview.dataset.photo=e.target.result;}
  };reader.readAsDataURL(file);
}
function saveStu(){
  const nom=document.getElementById('sN').value.trim(),pre=document.getElementById('sP').value.trim();
  if(!nom||!pre){toast('Nom et prénom requis','warn');return;}
  const dob=document.getElementById('sD').value?new Date(document.getElementById('sD').value).toLocaleDateString('fr-FR'):'';
  const newId=gid();
  const photoData=document.getElementById('newStuPhotoPreview')?.dataset?.photo||'';
  DB.students.push({id:newId,mat:document.getElementById('sM').value,nom,pre,sex:document.getElementById('sSx').value,dob,cls:document.getElementById('sCl').value,tel:document.getElementById('sTl').value,parent:document.getElementById('sPr').value,ptel:document.getElementById('sPT').value.trim(),frais:+document.getElementById('sF').value,ins:today(),stat:document.getElementById('sSt').value,photo:photoData});
  save();cm();re();toast('✓ Élève inscrit avec succès');
}
function delStu(id){if(!confirm('Supprimer cet élève ? Cette action est irréversible.'))return;DB.students=DB.students.filter(s=>s.id!==id);DB.studentAccounts=DB.studentAccounts?.filter(sa=>sa.eid!==id)||[];DB.grades=DB.grades.filter(g=>g.eid!==id);DB.payments=DB.payments.filter(p=>p.eid!==id);DB.absences=DB.absences?.filter(a=>a.eid!==id)||[];save();re();toast('Élève supprimé','warn');}
function editStu(id){
  const s=S(id);if(!s)return;
  let dobVal='';try{if(s.dob){const p=s.dob.split('/');if(p.length===3)dobVal=`${p[2]}-${p[1]}-${p[0]}`;}}catch(e){}
  M('✏️ Modifier inscription',s.mat,`<div class="fg2">
  <div class="fg"><span class="fl">Sexe</span><select class="fi" id="eSx"><option${s.sex==='M'?' selected':''} value="M">♂ Masculin</option><option${s.sex==='F'?' selected':''} value="F">♀ Féminin</option></select></div>
  <div class="fg"><span class="fl">Nom de famille *</span><input class="fi" id="eN" value="${s.nom}"></div>
  <div class="fg"><span class="fl">Prénom(s) *</span><input class="fi" id="eP" value="${s.pre}"></div>
  <div class="fg"><span class="fl">Date de naissance</span><input class="fi" id="eD" type="date" value="${dobVal}"></div>
  <div class="fg"><span class="fl">Classe *</span><select class="fi" id="eCl">${CLS.map(c=>`<option${c===s.cls?' selected':''}>${c}</option>`).join('')}</select></div>
  <div class="fg"><span class="fl">Téléphone élève</span><input class="fi" id="eTl" type="tel" value="${s.tel||''}"></div>
  <div class="fg"><span class="fl">Nom du parent</span><input class="fi" id="ePr" value="${s.parent||''}"></div>
  <div class="fg"><span class="fl">Tél. parent WhatsApp</span><input class="fi" id="ePT" type="tel" value="${s.ptel||''}"></div>
  <div class="fg"><span class="fl">Frais mensuels (FCFA)</span><input class="fi" id="eF" type="number" value="${s.frais}" min="0"></div>
  <div class="fg"><span class="fl">Statut paiement</span><select class="fi" id="eSt"><option${s.stat==='En attente'?' selected':''}>En attente</option><option${s.stat==='Payé'?' selected':''}>Payé</option><option${s.stat==='Impayé'?' selected':''}>Impayé</option></select></div>
  </div>`,
  `<button class="btn bo" onclick="cm()">Annuler</button><button class="btn bi" onclick="saveEditStu('${id}')"><svg class="vico bico" aria-hidden="true"><use href="#lc-check"/></svg>Enregistrer</button>`,true);
}
function saveEditStu(id){
  const s=S(id);if(!s)return;
  const nom=document.getElementById('eN').value.trim(),pre=document.getElementById('eP').value.trim();
  if(!nom||!pre){toast('Nom et prénom requis','warn');return;}
  s.nom=nom;s.pre=pre;s.sex=document.getElementById('eSx').value;
  const dv=document.getElementById('eD').value;if(dv)s.dob=new Date(dv).toLocaleDateString('fr-FR');
  s.cls=document.getElementById('eCl').value;s.tel=document.getElementById('eTl').value;
  s.parent=document.getElementById('ePr').value;s.ptel=document.getElementById('ePT').value.trim();
  s.frais=+document.getElementById('eF').value;s.stat=document.getElementById('eSt').value;
  save();cm();re();toast('✓ Informations mises à jour');
}
function viewStu(id){
  const s=S(id);if(!s)return;
  const pays=DB.payments.filter(p=>p.eid===s.id);
  const tpays=pays.filter(p=>p.stat==='Payé').reduce((a,p)=>a+p.mnt,0);
  const gr=DB.grades.filter(g=>g.eid===s.id&&g.tri===TRS[0]);
  const tc=gr.reduce((a,g)=>a+(+g.coef||1),0)||1;
  const moy=gr.length?gr.reduce((a,g)=>a+(_subMoy(g))*g.coef,0)/tc:null;
  const ap=moy!==null?getAppr(moy):null;
  const absE=DB.absences?.filter(a=>a.eid===s.id)||[];
  M('Fiche élève',s.mat,`
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:9px;padding:13px;background:var(--bg2);border-radius:var(--r);margin-bottom:14px">
    ${[['Prénom & Nom',s.pre+' '+s.nom],['Classe',s.cls],['Matricule',s.mat],['Date naissance',s.dob||'—'],['Sexe',s.sex==='F'?'♀ Féminin':'♂ Masculin'],['Inscrit le',s.ins],['Tél. élève',s.tel||'—'],['Parent',s.parent||'—']].map(([l,v])=>`<div><div class="xs2 mut mb4">${l}</div><div class="semi s">${v}</div></div>`).join('')}
  </div>
  <div class="fl2 g8 mb14 fw">
    <div style="flex:1;min-width:90px;padding:11px;background:var(--gp);border-radius:var(--r);border:1px solid var(--gb);text-align:center"><div class="xs2 mut mb3">Frais/mois</div><div class="mono bold" style="color:var(--gold)">${fmt(s.frais)}</div></div>
    <div style="flex:1;min-width:90px;padding:11px;background:var(--grb);border-radius:var(--r);border:1px solid var(--grd);text-align:center"><div class="xs2 mut mb3">Total versé</div><div class="mono bold" style="color:var(--gr)">${fmt(tpays)}</div></div>
    <div style="flex:1;min-width:90px;padding:11px;background:${s.stat==='Payé'?'var(--grb)':s.stat==='Impayé'?'var(--reb)':'var(--orb)'};border-radius:var(--r);text-align:center"><div class="xs2 mut mb3">Statut</div><div class="semi" style="color:${s.stat==='Payé'?'var(--gr)':s.stat==='Impayé'?'var(--re)':'var(--or)'}">${s.stat}</div></div>
    ${moy!==null?`<div style="flex:1;min-width:90px;padding:11px;background:${ap.col}18;border-radius:var(--r);text-align:center"><div class="xs2 mut mb3">Moy. T1</div><div class="mono bold" style="color:${ap.col}">${moy.toFixed(2)}/20</div><div class="xs2" style="color:${ap.col}">${ap.lbl}</div></div>`:''}
    <div style="flex:1;min-width:90px;padding:11px;background:var(--reb);border-radius:var(--r);text-align:center"><div class="xs2 mut mb3">Absences</div><div class="mono bold" style="color:var(--re)">${absE.reduce((a,b)=>a+b.heures,0)}h</div></div>
  </div>`,
  `<button class="btn bo sm" onclick="cm()">Fermer</button><button class="btn bg2 sm" onclick="cm();editStu('${id}')"><svg class="vico bico" aria-hidden="true"><use href="#lc-pencil"/></svg>Modifier</button>${pays.some(p=>p.stat==='Payé')?`<button class="btn bg2 sm" onclick="printLastRec('${id}')"><svg class="vico bico" aria-hidden="true"><use href="#lc-doc"/></svg>Reçu</button>`:''}`);
}
function printLastRec(sid){const pays=DB.payments.filter(p=>p.eid===sid&&p.stat==='Payé');if(!pays.length){toast('Aucun paiement','warn');return;}cm();printRec(pays[pays.length-1].id);}

// ═══════════════════════════════════════════════
// PAIEMENTS
// ═══════════════════════════════════════════════
function pgPayments(){
  if(!iA())return na();
  const q=(window._pq||'').toLowerCase(),f=window._pf||'Tous';
  const list=DB.payments.filter(p=>p.enom.toLowerCase().includes(q)&&(f==='Tous'||p.stat===f));
  const tP=DB.payments.filter(p=>p.stat==='Payé').reduce((s,p)=>s+p.mnt,0);
  const tI=DB.payments.filter(p=>p.stat==='Impayé').reduce((s,p)=>s+p.mnt,0);
  return`
  <div class="sg" style="grid-template-columns:repeat(3,1fr)">
    <div class="sc scgr"><div class="sci">💰</div><div class="scl">Total encaissé</div><div class="scv vgr" style="font-size:18px">${fmt(tP)}</div><div class="scs">${DB.payments.filter(p=>p.stat==='Payé').length} paiements</div></div>
    <div class="sc scr"><div class="sci">❌</div><div class="scl">Impayés</div><div class="scv vr" style="font-size:18px">${fmt(tI)}</div></div>
    <div class="sc scb"><div class="sci">⏳</div><div class="scl">En attente</div><div class="scv vb" style="font-size:18px">${fmt(DB.payments.filter(p=>p.stat==='En attente').reduce((s,p)=>s+p.mnt,0))}</div></div>
  </div>
  <div class="card">
    <div class="fl2 fic fsb mb16 fw g8">
      <div class="fl2 fic g8 fw">
        <div class="srch" style="width:210px"><span class="si">🔍</span><input class="fi" style="padding-left:33px" placeholder="Rechercher..." value="${window._pq||''}" oninput="window._pq=this.value;re()"></div>
        <div class="tabs">${['Tous','Payé','Impayé','En attente'].map(s=>`<button class="tab${f===s?' on':''}" onclick="window._pf='${s}';re()">${s}</button>`).join('')}</div>
      </div>
      <div class="fl2 fic g8">
        <button class="btn bo" onclick="mEcheanciers()" title="Paiement fractionné : petites tranches plutôt qu'une somme d'un coup">🗓️ Échéanciers</button>
        <div class="fl2 fic g8">
        <button class="btn bo" onclick="mEcheanciers()" title="Paiement fractionné : 1 000 F par semaine plutôt que 45 000 F d’un coup">🗓️ Échéanciers</button>
        <button class="btn bi" onclick="mAddPay()">＋ Paiement</button>
      </div>
      </div>
    </div>
    <div class="tw"><table>
    <thead><tr><th>Élève</th><th>Classe</th><th>Période</th><th>Montant</th><th>Mode</th><th>Date</th><th>Statut</th><th>Actions</th></tr></thead>
    <tbody>${list.map(p=>{const sv=S(p.eid);return`<tr>
      <td><div class="fl2 fic g9"><div class="av" style="width:28px;height:28px;background:var(--gp);color:var(--gold);border:1.5px solid var(--gb);font-size:12px">${p.enom[0]}</div>
        <div><div class="bold s">${p.enom}</div></div></div></td>
      <td><span class="bg bgd">${p.cls||'—'}</span></td>
      <td class="xs2">${p.mo}</td>
      <td class="mono bold" style="color:var(--gold)">${fmt(p.mnt)}</td>
      <td class="xs2">${p.mode}</td>
      <td class="xs2 mut">${p.dt||'—'}</td>
      <td><span class="bg ${p.stat==='Payé'?'bgg':p.stat==='Impayé'?'bgr':'bgo'}">${p.stat}</span></td>
      <td><div class="fl2 g4">
        ${p.stat==='Payé'?`<button class="btn bo xs" onclick="printRec('${p.id}')">🧾</button>`:`<button class="btn bgr2 xs" onclick="markP('${p.id}')"><svg class="vico bico" aria-hidden="true"><use href="#lc-check"/></svg>Payé</button>`}
        ${isSA()?`<button class="btn br2 xs" onclick="delPay('${p.id}')">🗑</button>`:''}
      </div></td>
    </tr>`;}).join('')}
    ${list.length===0?`<tr><td colspan="8"><div class="empty">Aucun résultat</div></td></tr>`:''}
    </tbody></table></div>
  </div>`;
}
function mAddPay(){
  M('Nouveau paiement','Enregistrement d\'un règlement',`<div class="fg2">
  <div class="fg full"><span class="fl">Élève *</span><select class="fi" id="pEtu" onchange="autoFillPay()">${DB.students.map(s=>`<option value="${s.id}">${s.pre} ${s.nom} (${s.cls})</option>`).join('')}</select></div>
  <div class="fg"><span class="fl">Montant (FCFA) *</span><input class="fi" id="pMnt" type="number" min="0"></div>
  <div class="fg"><span class="fl">Période *</span><input class="fi" id="pMo" placeholder="Ex: Novembre 2024"></div>
  <div class="fg"><span class="fl">Mode de paiement</span><select class="fi" id="pMode"><option>Espèces</option><option>Mobile Money</option><option>Virement</option><option>Chèque</option></select></div>
  <div class="fg"><span class="fl">Date</span><input class="fi" id="pDt" type="date" value="${new Date().toISOString().split('T')[0]}"></div>
  <div class="fg"><span class="fl">Statut</span><select class="fi" id="pSt"><option>Payé</option><option>En attente</option><option>Impayé</option></select></div>
  </div>`,
  `<button class="btn bo" onclick="cm()">Annuler</button><button class="btn bi" onclick="savePay()"><svg class="vico bico" aria-hidden="true"><use href="#lc-check"/></svg>Enregistrer</button>`);
  setTimeout(()=>autoFillPay(),100);
}
function autoFillPay(){const s=S(document.getElementById('pEtu')?.value);const m=document.getElementById('pMnt');if(s&&m&&!m.value)m.value=s.frais;}
function savePay(){
  const eid=document.getElementById('pEtu')?.value;if(!eid){toast('Sélectionnez un élève','warn');return;}
  const s=S(eid);
  const mnt=+document.getElementById('pMnt').value;
  if(!mnt){toast('Montant requis','warn');return;}
  const ref='REF-'+Math.floor(Math.random()*90000+10000);
  const dtV=document.getElementById('pDt').value;
  const stat=document.getElementById('pSt').value;
  DB.payments.push({id:gid(),eid,enom:`${s?.pre||''} ${s?.nom||''}`.trim(),cls:s?.cls||'',mo:document.getElementById('pMo').value,mnt,mode:document.getElementById('pMode').value,dt:dtV?new Date(dtV).toLocaleDateString('fr-FR'):'',stat,ref});
  if(s&&stat==='Payé')s.stat='Payé';
  save();cm();re();autoNotify('💳 Paiement reçu','Paiement de '+fmt(mnt)+' enregistré pour '+s.pre+' '+s.nom,'admin');toast('✓ Paiement enregistré');
}
function markP(pid){const p=DB.payments.find(x=>x.id===pid);if(!p)return;p.stat='Payé';p.dt=today();const s=S(p.eid);if(s)s.stat='Payé';save();re();toast('✓ Paiement marqué comme Payé');}
function delPay(pid){if(!confirm('Supprimer ce paiement ?'))return;DB.payments=DB.payments.filter(p=>p.id!==pid);save();re();}

function printRec(pid){
  const p=DB.payments.find(x=>x.id===pid);if(!p)return;
  const sv=S(p.eid);
  const num=p.ref||('REC-'+Math.floor(Math.random()*90000+10000));
  printDoc(`<div style="max-width:660px;margin:0 auto;font-family:'Inter',sans-serif;color:#1c1814;background:#fff;border:1px solid #ddd8d0">
  ${docHeader('Reçu de Paiement')}
  <div style="background:#f5f3ef;padding:14px 26px;border-bottom:2px solid #ddd8d0">
    <table style="width:100%"><tr>
      ${[['Nom complet',(sv?.nom||'')+' '+(sv?.pre||p.enom)],['Matricule',sv?.mat||'—'],['Classe',p.cls||sv?.cls||'—'],['Parent',sv?.parent||'—'],['Tél.',sv?.ptel||'—']].map(([l,v])=>`<td style="padding-right:14px"><div style="font-size:13px;text-transform:uppercase;letter-spacing:1px;color:#a89888;font-weight:700">${l}</div><div style="font-size:13px;font-weight:700">${v}</div></td>`).join('')}
    </tr></table>
  </div>
  <div style="padding:20px 26px">
    <table style="width:100%;border-collapse:collapse">
      <thead><tr style="background:#f0ede7"><th style="padding:7px 11px;text-align:left;font-size:13px;text-transform:uppercase;color:#6b5e52;border:1px solid #ddd8d0">Désignation</th><th style="padding:7px 11px;text-align:center;font-size:13px;text-transform:uppercase;color:#6b5e52;border:1px solid #ddd8d0">Période</th><th style="padding:7px 11px;text-align:center;font-size:13px;text-transform:uppercase;color:#6b5e52;border:1px solid #ddd8d0">Mode</th><th style="padding:7px 11px;text-align:right;font-size:13px;text-transform:uppercase;color:#6b5e52;border:1px solid #ddd8d0">Montant</th></tr></thead>
      <tbody><tr><td style="padding:11px;border:1px solid #e8e4dc;font-size:13px;font-weight:600">Frais de scolarité / répétition</td><td style="padding:11px;border:1px solid #e8e4dc;text-align:center">${p.mo}</td><td style="padding:11px;border:1px solid #e8e4dc;text-align:center;font-size:12px">${p.mode}</td><td style="padding:11px;border:1px solid #e8e4dc;text-align:right;font-weight:700;font-family:'Fira Code',monospace">${fmt(p.mnt)}</td></tr></tbody>
    </table>
    <div style="background:#142554;color:#fff;padding:12px 16px;display:flex;justify-content:space-between;align-items:center">
      <span style="font-size:13px;font-weight:700;text-transform:uppercase">TOTAL VERSÉ</span>
      <span style="font-family:'Fira Code',monospace;font-size:22px;font-weight:700;color:#FFC93C">${fmt(p.mnt)}</span>
    </div>
  </div>
  <div style="padding:0 26px 20px;display:grid;grid-template-columns:1fr 1fr;gap:12px">
    <div style="padding:12px;border:1.5px solid #ddd8d0;border-radius:7px"><div style="font-size:13px;text-transform:uppercase;color:#a89888">Mode</div><div style="font-size:13px;font-weight:700">${p.mode}</div><div style="font-size:13px;color:#a89888;margin-top:2px">Date : ${p.dt||today()}</div></div>
    <div style="padding:12px;border:2.5px solid #1a6e40;border-radius:7px;background:#edf7f1;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center"><div style="font-size:28px;color:#1a6e40">✓</div><div style="font-size:15px;font-weight:900;color:#1a6e40;letter-spacing:2px">PAYÉ</div></div>
  </div>
  <div style="padding:8px 26px 18px;border-top:1px solid #e8e4dc;display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px">
    ${[['Signature du Caissier','Nom & Signature'],['Signature du Parent','Lu et approuvé'],['Cachet du Directeur',DB.school?.directeur||'Le Directeur']].map(([t,s])=>`<div style="text-align:center"><div style="font-size:13px;text-transform:uppercase;color:#a89888;margin-bottom:24px">${t}</div><div style="border-top:1px solid #c8c0b4;padding-top:4px;font-size:13px;color:#c8c0b4">${s}</div></div>`).join('')}
  </div>
  <div style="background:#f0ede7;border-top:1px solid #ddd8d0;padding:8px 26px;display:flex;justify-content:space-between">
    <span style="font-size:13px;color:#c8c0b4">${DB.school?.nom||'VÉRITAS Academy'} · ${DB.school?.ville||'Cameroun'}</span>
    <span style="font-size:13px;font-family:'Fira Code',monospace;color:#c8c0b4">${num} · ${today()}</span>
  </div>
</div>`,`Reçu ${num} — ${p.enom}`);
}

