            const appText=m>=16?'Excellent / Excellent':m>=14?'Très bien / Very good':m>=12?'Bien / Good':m>=10?'Passable / Pass':m>=8?'Insuffisant / Below average':'Très insuffisant / Very poor';
            const isLow=m<10;
