async function _runAICorrect(){
  if(!_aiGate('correct'))return;
  var en=(document.getElementById('corEn')?.value||'').trim();
  if(en.length<10){toast('Collez l\'énoncé de l\'exercice','warn');return;}
  var btn=document.getElementById('aiBtnC'),res=document.getElementById('aiResC');
  if(btn){btn.disabled=true;btn.innerHTML='⏳ Correction en cours…';}
  var mat=document.getElementById('corMat').value;
  var rep=(document.getElementById('corRep')?.value||'').trim();
  var sysCtx='Tu es un professeur agrégé de '+mat+' au lycée camerounais, expert du programme MINESEC. '+
    'Tu maîtrises les curricula officiels, les barèmes BEPC et BAC (séries A/C/D/E), '+
    'et les méthodes pédagogiques adaptées aux élèves camerounais. ';
  var prompt=sysCtx+
    'Énoncé : «'+en+'». '+
    (rep?
      'Réponse de l\'élève : «'+rep+'». '+
      'Analyse structurée (utilise ** pour les titres) : '+
      '**Note estimée /20** avec justification. '+
      '**Points positifs** : ce que l\'élève a réussi. '+
      '**Erreurs identifiées** : liste et explique chaque erreur. '+
      '**Correction complète** : solution étape par étape selon le programme camerounais. '+
      '**Conseil** : astuce pour éviter cette erreur à l\'examen.':
      'Solution complète (utilise ** pour les titres) : '+
      '**Type d\'exercice** : identifie les concepts du programme camerounais mobilisés. '+
      '**Résolution étape par étape** : méthode attendue au BEPC/BAC. '+
      '**Méthode à retenir** : technique clé pour ce type de sujet. '+
      '**Piège classique** : erreur fréquente des élèves camerounais sur ce sujet.'
    )+' Maximum 450 mots. En français.';
  try{
    var txt=await callAmbassaIA(prompt);
    // FIX v1.2 : _aiGate() a déjà incrémenté — pas de second _aiInc
    var rem=Math.max(0,_aiLimit('correct')-_aiUsed('correct'));
    if(res){res.style.display='block';res.style.whiteSpace='normal';res.innerHTML='<div class="ai-md">'+(typeof _aiMarkdown==='function'?_aiMarkdown(txt):_esc(txt).replace(/\n/g,'<br>'))+'</div>';}
    if(btn){btn.disabled=false;btn.innerHTML='🔄 Autre correction ('+(rem>0?rem+' restant'+(rem>1?'s':''):'0 restant')+')';}
  }catch(e){
    toast('Erreur IA : '+e.message,'err');
    if(btn){btn.disabled=false;btn.innerHTML='📝 Réessayer';}
  }
}

// ─── PACKS MANAGER ────────────────────────────────────────────────
function mManagePacks(){
  if(!iA())return;
  var el=DB.elearning||{};
  if(!el.plans)el.plans=[];
  var cards=(el.plans||[]).map(function(p){
    return'<div class="card" style="--vcol:#3C8DFF">'+
      '<div class="fl2 fic fsb mb8"><span class="bold">'+p.nom+'</span>'+
      '<div class="fl2 g4">'+
      '<button class="btn bo xs" data-pid="'+encodeURIComponent(p.id)+'" onclick="_editPk(decodeURIComponent(this.dataset.pid))"><svg class="vico bico" aria-hidden="true"><use href="#lc-pencil"/></svg>️</button>'+
      '<button class="btn br2 xs" data-pid="'+encodeURIComponent(p.id)+'" onclick="(function(b){if(!confirm(\'Supprimer ?\'))return;DB.elearning.plans=(DB.elearning.plans||[]).filter(function(x){return x.id!==decodeURIComponent(b.dataset.pid);});save();cm();toast(\'Supprimé\');})(this)">🗑</button>'+
      '</div></div>'+
      '<div style="font-family:Georgia,serif;font-size:20px;font-weight:700;color:var(--gold2)">'+fmtN(p.prix)+' XAF/an</div>'+
      '<div class="xs2 mut">'+p.cible+'</div></div>';
  }).join('');
  M('📦 Packs d\'abonnement','',
    '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin-bottom:16px">'+(cards||'<div class="empty"><div class="empty-ico">📦</div>Aucun pack</div>')+'</div>'+
    '<button class="btn bi sm" onclick="_newPk()"><svg class="vico bico" aria-hidden="true"><use href="#lc-plus"/></svg>Nouveau pack</button>',
    '<button class="btn bo" onclick="cm()">Fermer</button>',true);
}
function _newPk(){window._editPkId=null;_pkForm(null);}
function _editPk(pid){
  var p=(DB.elearning&&DB.elearning.plans||[]).find(function(x){return x.id===pid;});
  if(!p){toast('Pack introuvable','warn');return;}
  window._editPkId=pid;_pkForm(p);
}
function _pkForm(p){
  M(p?'✏️ Modifier pack':'➕ Nouveau pack','',
    '<div class="fg2">'+
    '<div class="fg"><span class="fl">Nom *</span><input class="fi" id="pkNom" value="'+(p?p.nom:'')+'" placeholder="Pack EXAMEN"></div>'+
    '<div class="fg"><span class="fl">ID</span><input class="fi" id="pkId" value="'+(p?p.id:'pk_'+Date.now())+'" '+(p?'disabled':'')+' placeholder="pk_xxx"></div>'+
    '<div class="fg"><span class="fl">Cible</span><input class="fi" id="pkCible" value="'+(p?p.cible||'':'')+'" placeholder="Pour les Terminales"></div>'+
    '<div class="fg"><span class="fl">Prix XAF/an *</span><input class="fi" id="pkPrix" type="number" value="'+(p?p.prix:'')+'" placeholder="15000"></div>'+
    '<div class="fg"><span class="fl">Ancien prix barré</span><input class="fi" id="pkAncien" type="number" value="'+(p&&p.ancien?p.ancien:'')+'" placeholder="25000"></div>'+
    '<div class="fg full"><span class="fl">Avantages (un par ligne) *</span>'+
    '<textarea class="fi" id="pkAv" rows="5" placeholder="Accès toutes les épreuves\nCours vidéos\nIA Correction illimitée">'+
    (p?(p.avantages||[]).join('\n'):'')+'</textarea></div>'+
    '<div class="fg"><label class="fl2" style="cursor:pointer;gap:8px"><input type="checkbox" id="pkPop"'+(p&&p.populaire?' checked':'')+'>  ⭐ Populaire (meilleure vente)</label></div>'+
    '</div>',
    '<button class="btn bo" onclick="cm()">Annuler</button>'+
    '<button class="btn bi" onclick="_savePk()"><svg class="vico bico" aria-hidden="true"><use href="#lc-checkcircle"/></svg>'+(p?'Modifier':'Créer')+'</button>',true);
}
function _savePk(){
  var nom=(document.getElementById('pkNom')?.value||'').trim();
  var prix=parseInt(document.getElementById('pkPrix')?.value)||0;
  if(!nom||!prix){toast('Nom et prix requis','warn');return;}
  if(!DB.elearning)DB.elearning=defaultDB().elearning;
  if(!DB.elearning.plans)DB.elearning.plans=[];
  var av=(document.getElementById('pkAv')?.value||'').split('\n').map(function(a){return a.trim();}).filter(Boolean);
  var pid=window._editPkId;
  if(pid){
    var p=DB.elearning.plans.find(function(x){return x.id===pid;});
    if(p){p.nom=nom;p.cible=document.getElementById('pkCible')?.value||'';p.prix=prix;p.ancien=parseInt(document.getElementById('pkAncien')?.value)||0;p.avantages=av;p.populaire=document.getElementById('pkPop')?.checked||false;}
    toast('✅ Pack mis à jour');
  } else {
    var id=(document.getElementById('pkId')?.value||'').replace(/[^a-z0-9_]/gi,'_');
    if(DB.elearning.plans.find(function(x){return x.id===id;})){toast('ID existe déjà','warn');return;}
    DB.elearning.plans.push({id:id,nom:nom,cible:document.getElementById('pkCible')?.value||'',prix:prix,ancien:parseInt(document.getElementById('pkAncien')?.value)||0,avantages:av,populaire:document.getElementById('pkPop')?.checked||false});
    toast('✅ Pack créé');
  }
  save();cm();re();
}

// ─── SECURE VIEWER ────────────────────────────────────────────────
function viewSecure(item){
  if(!item)return;
  function show(dataUrl,fname,ftype){
    var ext=(fname||'').split('.').pop().toLowerCase();
    var isVid=['mp4','mov','avi','mkv','webm'].includes(ext);
    var isPdf=ext==='pdf';
    var isImg=['jpg','jpeg','png','gif','webp'].includes(ext);
    var isAud=['mp3','m4a','wav'].includes(ext);
    var inner='';
    if(isVid){inner='<video controls controlsList="nodownload" disablePictureInPicture oncontextmenu="return false" style="width:100%;max-height:400px;border-radius:12px;background:#000;display:block"><source src="'+dataUrl+'" type="'+(ftype||'video/mp4')+'"></video><div class="xs2 mut mt6" style="text-align:center">🔒 Lecture protégée VÉRITAS</div>';}
    else if(isPdf){
      var _isMobSub=/Mobi|Android|iPhone|iPad/i.test(navigator.userAgent||'');
      if(_isMobSub){
        var _subBlob='';
        try{
          if(dataUrl.startsWith('data:')){
            var _sa=dataUrl.split(','),_sm=(_sa[0].match(/:(.*?);/)||['','application/pdf'])[1];
            var _ss=atob(_sa[1]),_sn=_ss.length,_su=new Uint8Array(_sn);
            while(_sn--)_su[_sn]=_ss.charCodeAt(_sn);
            _subBlob=URL.createObjectURL(new Blob([_su],{type:_sm}));
            setTimeout(function(){URL.revokeObjectURL(_subBlob);},60000);
          }else{_subBlob=dataUrl;}
        }catch(_se){_subBlob=dataUrl;}
        inner='<div style="text-align:center;padding:28px 16px;background:var(--bg2);border-radius:12px">'
          +'<div style="font-size:56px;margin-bottom:12px">🔒</div>'
          +'<div style="font-size:13px;font-weight:700;color:var(--bl);margin-bottom:16px">'+_esc(fname||'Document PDF')+'</div>'
          +'<button class="btn bi" style="font-size:14px;padding:12px 24px;width:100%;max-width:260px;cursor:pointer" onclick="window.open(\''+_subBlob+'\',\'_blank\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-bookopen"/></svg>Ouvrir le PDF</button>'
          +'<div class="xs2 mut mt8">🔒 PDF protégé VÉRITAS</div>'
          +'</div>';
      }else{
        inner='<embed src="'+dataUrl+'#toolbar=0&navpanes=0" type="application/pdf" style="width:100%;height:500px;border-radius:8px;border:1px solid var(--bg3)" oncontextmenu="return false"><div class="xs2 mut mt6" style="text-align:center">🔒 PDF protégé VÉRITAS</div>';
      }
    }
    else if(isImg){inner='<img src="'+dataUrl+'" oncontextmenu="return false" draggable="false" style="max-width:100%;max-height:400px;border-radius:10px;display:block;margin:0 auto"><div class="xs2 mut mt6" style="text-align:center">🔒 Image protégée</div>';}
    else if(isAud){inner='<audio controls controlsList="nodownload" oncontextmenu="return false" style="width:100%;margin:16px 0"><source src="'+dataUrl+'"></audio><div class="xs2 mut" style="text-align:center">🔒 Audio protégé</div>';}
    else{inner='<div class="ib ibt">📄 Aperçu non disponible pour ce format.</div>';}
    M('🔒 '+item.titre,fname||'',inner,'<button class="btn bo" onclick="cm()">Fermer</button>');
  }
  // S3 v1.2.x (Étape 2) : porte serveur prioritaire si active (média jamais
  // injecté en data: dans le DOM). Repli transparent sur l'ancien comportement.
  var _gate=_serverGateUrl(item);
  if(_gate){show(_gate.url,_gate.name,_gate.type);return;}
  if(item.fichierData&&item.fichierData.length>100){show(item.fichierData,item.fichier,item.fileType);}
  else if(item.idbKey){idbGetFile(item.idbKey,function(rec){if(!rec){toast('Ressource introuvable','warn');return;}show(rec.data,rec.name,rec.type);});}
  else if(item.fichierUrl){show(item.fichierUrl,item.fichier||item.fichierUrl.split('/').pop(),item.fileType||'');}
  else{toast('Aucun fichier disponible','warn');}
}

