    h+='<td style="padding:12px 14px"><span style="background:linear-gradient(135deg,#E8EEFF,#DBEAFE);color:#1E3A8A;padding:4px 12px;border-radius:12px;font-weight:800;font-size:11.5px;border:1px solid rgba(30,58,138,.2)">'+_esc(ex.niveaux)+'</span></td>';
