// ── Admin Login hidden access ──────────────────────────────
function _showAdminLogin(){
  var tabs = document.getElementById('lTabs');
  var btnA = document.getElementById('ltbA');
  var btnSA = document.getElementById('ltbSA');
  if(btnA) btnA.style.display='';
  if(btnSA) btnSA.style.display='';
  // Show OTP prompt
  M('🔐 Accès Administration','Authentification sécurisée',
    '<div class="ib ibt mb12"><span>🛡️</span><span>Pour accéder aux panneaux administratifs, entrez le code d\'acces envoye par WhatsApp ou Email.</span></div>'+
    '<div class="fg mb10"><span class="fl">Type d\'accès</span><select class="fi" id="otpRole"><option value="admin">Administrateur</option><option value="superadmin">Super Administrateur</option></select></div>'+
    '<div class="fg mb10"><span class="fl">Identifiant *</span><input class="fi" id="otpUser" placeholder="directeur ou secretaire"></div>'+
    '<div class="fg mb10"><span class="fl">Mot de passe *</span><input class="fi" id="otpPwd" type="password" placeholder="••••••••"></div>'+
    '<div style="background:var(--grb);border:1px solid var(--grd);border-radius:var(--r);padding:10px;font-size:12px;color:var(--gr);margin-bottom:10px">ℹ️ <strong>Note OTP :</strong> En production, un SMS/WhatsApp serait envoyé au numéro enregistré. Pour cette démo, saisir directement les identifiants.</div>',
    '<button class="btn bo" onclick="cm()">Annuler</button>'+
    '<button class="btn bi" onclick="_doAdminLogin()"><svg class="vico bico" aria-hidden="true"><use href="#lc-lock"/></svg>Connexion sécurisée</button>');
}

function _doAdminLogin(){
  var role = document.getElementById('otpRole')?.value || 'admin';
  var user = (document.getElementById('otpUser')?.value || '').trim();
  var pwd = document.getElementById('otpPwd')?.value || '';
  cm();
  swLR(role);
  // Pre-fill the login form
  setTimeout(function(){
    var lu = document.getElementById('lu');
    var lp = document.getElementById('lp');
    if(lu) lu.value = user;
    if(lp) lp.value = pwd;
    if(user && pwd) doLogin();
  }, 200);
}

// ── Ticker speed fix — vitesse normale ──────────────────────
function initTickerFixed(){
  var bar=document.getElementById('tickerBar');
  var sc=document.getElementById('tkScroll');
  if(!bar||!sc)return;
  var items=(DB&&DB.tickerItems&&DB.tickerItems.length)?DB.tickerItems:_DEFAULT_TICKER;
  bar.style.display='block'; bar.style.visibility='visible';
  var html=items.map(function(it){return'<span class="t-item">'+it.t+'</span><span class="t-dot">●</span>';}).join('');
  sc.innerHTML=html+html; // duplicate pour boucle sans couture
  // Vitesse RALENTIE (demande Jacques) : 8s par item, minimum 70s
  var dur=Math.max(70, items.length*8);
  // Reset animation proprement
  sc.style.animation='none';
  sc.offsetWidth; // force reflow
  sc.style.animation='tkScroll '+dur+'s linear infinite';
}

// Override initTicker
var _origInitTicker = initTicker;
initTicker = initTickerFixed;

