function mEditPartner(idx){
  var p = (DB.partners||[])[idx];
  if(!p) return;
  M('✏️ Modifier Partenaire','',
    '<div class="fg2">'+
    '<div class="fg"><span class="fl">Nom *</span><input class="fi" id="pNom" value="'+p.nom+'"></div>'+
    '<div class="fg"><span class="fl">Emoji</span><input class="fi" id="pEmoji" value="'+(p.emoji||'🤝')+'" maxlength="2"></div>'+
    '<div class="fg full"><span class="fl">Catégorie</span><select class="fi" id="pCat">'+
    ['gold','silver','bronze'].map(function(t){return'<option value="'+t+'"'+(p.type===t?' selected':'')+'>'+({'gold':'Partenaire Or','silver':'Partenaire Argent','bronze':'Sponsor Officiel'}[t])+'</option>';}).join('')+
    '</select></div>'+
    '<div class="fg full"><span class="fl">Description</span><textarea class="fi" id="pDesc" rows="2">'+(p.desc||'')+'</textarea></div>'+
    '<div class="fg full"><span class="fl">Site web</span><input class="fi" id="pSite" value="'+(p.site||'')+'"></div>'+
    '</div>',
    '<button class="btn bo" onclick="cm()">Annuler</button><button class="btn bi" onclick="_savePartner('+idx+')"><svg class="vico bico" aria-hidden="true"><use href="#lc-checkcircle"/></svg>Modifier</button>');
}

function _savePartner(idx){
  var nom = (document.getElementById('pNom')?.value||'').trim();
  if(!nom){toast('Nom requis','warn');return;}
  if(!DB.partners) DB.partners = [];
  var p = {nom:nom,emoji:document.getElementById('pEmoji')?.value||'🤝',type:document.getElementById('pCat')?.value||'silver',
    categorie:{'gold':'Partenaire Or','silver':'Partenaire Argent','bronze':'Sponsor Officiel'}[document.getElementById('pCat')?.value||'silver'],
    desc:document.getElementById('pDesc')?.value||'',site:document.getElementById('pSite')?.value||''};
  if(idx<0){DB.partners.push(p);}
  else{DB.partners[idx]=p;}
  save();cm();toast('✓ Partenaire enregistré');mManagePartners();
}

function delPartner(idx){
  if(!confirm('Supprimer ce partenaire ?')) return;
  if(DB.partners) DB.partners.splice(idx,1);
  save();cm();toast('Supprimé');
}

