function _calEvtAdd(){
  var titre=(document.getElementById("calEvtT")?.value||"").trim();
  var date=(document.getElementById("calEvtD")?.value||"").trim();
  if(!titre||!date){toast("Titre et date requis","warn");return;}
  if(!DB.calendrierCustom)DB.calendrierCustom={};
  if(!DB.calendrierCustom.evenements)DB.calendrierCustom.evenements=[];
  DB.calendrierCustom.evenements.push({
    titre:titre,date:date,
    niveaux:document.getElementById("calEvtN")?.value||"",
    matieres:document.getElementById("calEvtM")?.value||"",
    desc:document.getElementById("calEvtDesc")?.value||"",
    type:document.getElementById("calEvtType")?.value||"autre"
  });
  save();cm();setTimeout(mEditCalendrier,80);toast("Evenement ajoute");
}
function _calEvtDel(btn){
  var i=parseInt(btn.dataset.ci);
  if(isNaN(i)||!DB.calendrierCustom?.evenements)return;
  DB.calendrierCustom.evenements.splice(i,1);
  save();cm();setTimeout(mEditCalendrier,80);toast("Supprime");
}

function idbSave(key, data, name, type, cb){
  var req = indexedDB.open('veritasDB',1);
  req.onupgradeneeded = function(e){
    e.target.result.createObjectStore('files',{keyPath:'key'});
  };
  req.onsuccess = function(e){
    var tx = e.target.result.transaction('files','readwrite');
    tx.objectStore('files').put({key:key,data:data,name:name,type:type});
    tx.oncomplete = function(){if(cb)cb(true);};
    tx.onerror = function(){if(cb)cb(false);};
  };
  req.onerror = function(){if(cb)cb(false);};
}

function idbGetFile(key, cb){
  var req = indexedDB.open('veritasDB',1);
  req.onupgradeneeded = function(e){
    e.target.result.createObjectStore('files',{keyPath:'key'});
  };
  req.onsuccess = function(e){
    var tx = e.target.result.transaction('files','readonly');
    var r = tx.objectStore('files').get(key);
    r.onsuccess = function(){cb(r.result||null);};
    r.onerror = function(){cb(null);};
  };
  req.onerror = function(){cb(null);};
}

// ── File upload with size limits ──────────────────────────────
// Image max: 5MB, PDF max: 20MB, Video max: 100MB
function _uploadFile(inputEl, opts, cb){
  var file = inputEl.files[0];
  if(!file) return;
  var ext = file.name.split('.').pop().toLowerCase();
  var isVid = ['mp4','webm','mov','avi','mkv'].indexOf(ext) >= 0;
  var isPdf = ext === 'pdf';
  var isImg = ['jpg','jpeg','png','gif','webp'].indexOf(ext) >= 0;
  var maxSize = isVid ? 100*1024*1024 : isPdf ? 20*1024*1024 : 5*1024*1024;
  var maxLabel = isVid ? '100 Mo' : isPdf ? '20 Mo' : '5 Mo';
  
  if(file.size > maxSize){
    toast('Fichier trop lourd (max '+maxLabel+')','warn');
    inputEl.value='';
    return;
  }
  
  toast('⏳ Chargement en cours...');
  
  // For large files (>2MB), use IndexedDB
  if(file.size > 2*1024*1024){
    var reader = new FileReader();
    reader.onload = function(e){
      var key = 'file_' + gid();
      idbSave(key, e.target.result, file.name, file.type, function(ok){
        if(ok){
          toast('✅ Fichier chargé (IndexedDB)');
          if(cb) cb(null, key, file.name, file.type, file.size);
        } else {
          // Fallback to direct storage
          toast('✅ Fichier chargé');
          if(cb) cb(e.target.result, null, file.name, file.type, file.size);
        }
      });
    };
    reader.readAsDataURL(file);
  } else {
    var reader = new FileReader();
    reader.onload = function(e){
      toast('✅ Fichier chargé');
      if(cb) cb(e.target.result, null, file.name, file.type, file.size);
    };
    reader.readAsDataURL(file);
  }
}

