// CORRECTION DE DEVOIRS PAR IA (v1.2 OPTIMISATION — Priorité 1 #4)
// Permet à un élève de soumettre un devoir (rédaction, exo maths, dissertation)
// et de recevoir une correction détaillée, note /20, points forts/faibles.
// ═══════════════════════════════════════════════════════════════════════════
window.mDevoirCorrectionIA = function(){
  if(typeof M !== 'function') return;
  // FIX v1.2 : ne pas gater à l'ouverture du modal, seulement à l'exécution
  var u = (typeof _aiUsed==='function')?_aiUsed('devoir'):0;
  var lim = (typeof _aiLimit==='function')?_aiLimit('devoir'):3;
  if(lim!==-1 && u>=lim && typeof _showQuotaExceeded==='function'){ _showQuotaExceeded('devoir', (typeof _aiTier==='function'?_aiTier():'free'), u, lim); return; }
  var rem = Math.max(0, lim-u);
  var badge = lim>=999 ? '∞ Illimité' : rem+' correction'+(rem>1?'s':'')+' aujourd\'hui';

  M('📝 Correction de devoir par IA','Soumets ton devoir, l\'IA te corrige en 30 s',
    '<div class="ib ibt mb12"><span>🎯</span><span>Idéal pour : <b>rédactions, dissertations, commentaires, exercices de maths, problèmes physique-chimie</b>. Tu reçois une note /20, les points forts, les axes d\'amélioration. <b>'+badge+'</b>.</span></div>'+
    '<div class="fg mb10"><span class="fl">Matière *</span>'+
      '<select class="fi" id="dvSub">'+
        ['Français — Rédaction','Français — Dissertation','Français — Commentaire composé','Français — Résumé','Anglais — Essay','Mathématiques','Physique-Chimie','SVT','Histoire-Géographie','Philosophie','Économie','Informatique','Autre']
        .map(function(s){return '<option>'+s+'</option>';}).join('')+
      '</select></div>'+
    '<div class="fg mb10"><span class="fl">Niveau *</span>'+
      '<select class="fi" id="dvLvl">'+
        ['6ème','5ème','4ème','3ème','2nde','1ère A','1ère C','1ère D','Tle A','Tle C','Tle D','Probatoire','BAC blanc','BAC officiel']
        .map(function(s){return '<option>'+s+'</option>';}).join('')+
      '</select></div>'+
    '<div class="fg mb10"><span class="fl">Sujet / Consigne du devoir *</span>'+
      '<textarea class="fi" id="dvConsigne" rows="2" placeholder="Ex: Dissertez sur la phrase de Mongo Beti..."></textarea></div>'+
    '<div class="fg mb10"><span class="fl">Ton travail (texte ou réponse) *</span>'+
      '<textarea class="fi" id="dvTravail" rows="8" placeholder="Colle ici ta rédaction, ta dissertation ou la résolution de ton exercice..." style="font-family:Georgia,serif;font-size:13.5px;line-height:1.6"></textarea></div>'+
    '<div id="dvRes" class="ai-res" style="display:none"></div>',
    '<button class="btn bo" onclick="cm()">Annuler</button>'+
    '<button class="btn bgr2" id="dvBtn" onclick="_runCorrectionIA()"><svg class="vico bico" aria-hidden="true"><use href="#lc-brain"/></svg>Corriger ('+rem+' restant'+(rem>1?'s':'')+')</button>',true);
};

window._runCorrectionIA = async function(){
  if(typeof _aiGate==='function' && !_aiGate('devoir')) return;
  var sub = (document.getElementById('dvSub')?.value||'').trim();
  var lvl = (document.getElementById('dvLvl')?.value||'').trim();
  var con = (document.getElementById('dvConsigne')?.value||'').trim();
  var trv = (document.getElementById('dvTravail')?.value||'').trim();
  if(!con){toast('Indique la consigne du devoir','warn');return;}
  if(trv.length<40){toast('Ton travail doit faire au moins 40 caractères','warn');return;}
  var btn=document.getElementById('dvBtn'),res=document.getElementById('dvRes');
  if(btn){btn.disabled=true;btn.innerHTML='⏳ Correction en cours…';}

  var prompt =
    'Tu es un enseignant expert du système éducatif camerounais (MINESEC), bienveillant et exigeant. '+
    'Tu vas corriger le travail d\'un élève de '+lvl+' en '+sub+'. '+
    '\n\n=== CONSIGNE DU DEVOIR ===\n'+con+
    '\n\n=== TRAVAIL DE L\'ÉLÈVE ===\n'+trv+
    '\n\n=== TA CORRECTION (structure obligatoire avec ** pour les titres) ===\n'+
    '**📊 Note proposée : X/20** (sois juste, ni trop sévère ni complaisant)\n\n'+
    '**✅ Points forts** — Liste 2-3 points concrets que l\'élève maîtrise bien.\n\n'+
    '**⚠️ Points à améliorer** — Liste 3-4 erreurs précises (fautes de langue, manques d\'analyse, défauts de structure…) avec des CITATIONS du texte de l\'élève si possible.\n\n'+
    '**💡 Conseils pour progresser** — 3 conseils concrets et actionnables, adaptés au niveau '+lvl+'.\n\n'+
    '**✨ Si je devais réécrire un paragraphe** — Propose une réécriture améliorée d\'un passage faible (max 60 mots).\n\n'+
    'Sois précis, encourageant, et toujours pédagogique. Max 500 mots. En français standard.';

  try{
    var txt = await callAmbassaIA(prompt);
    // FIX v1.2 : _aiGate() a déjà incrémenté le compteur — ne pas appeler _aiInc() une 2ème fois
    var rem2 = (typeof _aiLimit==='function' && typeof _aiUsed==='function')
      ? Math.max(0, _aiLimit('devoir')-_aiUsed('devoir')) : 0;
    if(res){
      res.style.display='block';
      // Formatter le markdown léger ** ** → <strong>
      var html = (typeof _aiMarkdown==='function') ? _aiMarkdown(txt) : _esc(txt).replace(/\n/g,'<br>');
      res.innerHTML = '<div class="ai-md" style="background:linear-gradient(135deg,#FAF5FF,#EDE9FE);border-radius:12px;padding:16px 20px">'+html+'</div>'+
        '<div style="margin-top:12px;font-size:11px;color:#64748B;text-align:right;font-style:italic">Correction générée par IA pédagogique — Centre VÉRITAS</div>';
      res.scrollIntoView({behavior:'smooth',block:'nearest'});
    }
    // Sauvegarder la correction dans l'historique de l'utilisateur
    if(SES && SES.id){
      DB._aiCorrections = DB._aiCorrections || [];
      DB._aiCorrections.unshift({
        id:'corr_'+Date.now(),
        userId: SES.id,
        sub: sub, lvl: lvl, consigne: con,
        date: new Date().toISOString(),
        correction: txt.substring(0,2000) // limite stockage
      });
      if(DB._aiCorrections.length>50) DB._aiCorrections.length=50;
      if(typeof save==='function') save();
    }
    if(btn){btn.disabled=false;btn.innerHTML='🔄 Corriger un autre devoir ('+rem2+' restant'+(rem2>1?'s':'')+')';}
  }catch(e){
    toast('Erreur IA : '+e.message,'err');
    if(btn){btn.disabled=false;btn.innerHTML='🤖 Réessayer';}
  }
};

// Cœur de l'IA Prof. Ambassa. Aucun moteur propriétaire unique : route via
// api/ia_proxy.php, qui enchaîne Gemini → DeepSeek (OpenRouter) → Groq → Mistral,
// clés jamais exposées au client. (Le nom historique vendeur a été retiré en v1.2.x.)
async function callAmbassaIA(prompt, sysPrompt){
  // v2.9.10 — Avec logs de diagnostic pour identifier où ça échoue côté client
  console.log("[IA] callAmbassaIA appelée — prompt=" + (prompt||'').length + " chars, sys=" + (sysPrompt||'').length + " chars");
  var sys = sysPrompt || "Tu es un assistant pédagogique expert du système éducatif camerounais (MINESEC/MINESUP). Tu connais les programmes BEPC et BAC séries A/C/D, les grandes écoles camerounaises et tu contextualises dans la réalité camerounaise.";

  // ── v1.2.1 : IA routée via le SERVEUR (api/ia_proxy.php) ──────────────────────
  // Pollinations.ai (appel direct navigateur) a été DÉPRÉCIÉ en 2026 : il renvoie un
  // message « legacy text API deprecated » au lieu d'une réponse. On passe donc par
  // notre proxy serveur (clé IA gratuite côté serveur, jamais exposée au client).
  try {
    var _base=(DB&&DB.cloudConfig&&DB.cloudConfig.url|| ((location.origin.indexOf('veritas-school.com')>=0)?location.origin+'/api':'https://veritas-school.com/api')).replace(/\/+$/,'');
    var _ses=(typeof SES!=='undefined'&&SES)?SES:null;
    // v1.2.1 : RAG — chercher des passages d'annales/corpus (rag.php) pour ancrer la réponse.
    // Dégradé proprement (contexte vide) si biblio_index.db n'est pas encore déposé sur le serveur.
    var _ragCtx='';
    try{
      var _rr=await fetch(_base+'/rag.php?limit=4&q='+encodeURIComponent(String(prompt||'').slice(0,180)),{method:'GET'});
      if(_rr.ok){ var _rj=await _rr.json(); if(_rj&&_rj.ok&&_rj.passages&&_rj.passages.length){ _ragCtx=_rj.passages.map(function(p){return '— '+(p.auteur||'?')+', '+(p.titre||'?')+(p.annee?(' ('+p.annee+')'):'')+' : '+p.extrait;}).join('\n'); } }
    }catch(_eRag){}
    // `token` = jeton de compte signé par le serveur (émis à la connexion élève).
    // Sans lui, ia_proxy.php écrête volontairement le palier : un `userId` seul
    // ne prouve rien et ne doit plus ouvrir le quota enseignant/admin.
    var _iaTok=''; try{ if(typeof _contentToken==='function') _iaTok=_contentToken(); }catch(e){}
    var _r=await fetch(_base+'/ia_proxy.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:String(prompt||''),sysPrompt:sys,ragContext:_ragCtx,userId:_ses&&_ses.id?_ses.id:'',plan:_ses&&_ses.type?_ses.type:'anon',token:_iaTok})});
    if(_r.ok){
      var _j=await _r.json();
      // v1.5 : mémoriser la source — permet d'afficher le badge « ✓ Vérifié par
      // un enseignant » quand la réponse vient du cache validé (admin_validate).
      try{ window._iaLastSource=_j&&_j.source||''; }catch(_eS){}
      try{ if(typeof _track==='function') _track('ia_try'); }catch(_eT){}
      if(_j&&_j.text&&!/legacy text API|deprecat|enter\.pollinations/i.test(_j.text)){ console.log('[IA] via ia_proxy ('+(_j.source||'?')+')'); return _j.text; }
      if(_j&&_j.error){ console.warn('[IA] ia_proxy:',_j.error); return "⚠️ "+_j.error; }
    } else { console.warn('[IA] ia_proxy HTTP '+_r.status); }
  } catch(_eP){ console.warn('[IA] ia_proxy injoignable:',_eP.message); }
  // v1.3.3 : message VISITEUR neutre — aucun détail technique/serveur exposé.
  // Le diagnostic admin reste dans la console ([IA] …) et les logs serveur.
  return "⚠️ Le Professeur Ambassa est momentanément indisponible. Vérifiez votre connexion et réessayez dans quelques instants.";
  // v1.3.2 : le code mort Pollinations (3 essais navigateur, inatteignables après le
  // return ci-dessus) a été SUPPRIMÉ. Toute l'IA passe par ia_proxy.php côté serveur :
  // Gemini → DeepSeek (OpenRouter) → Groq → Mistral, clés jamais exposées au client.
}

// v1.5 — Badge de CONFIANCE : affiché quand la réponse IA provient du cache des
// réponses VALIDÉES par un enseignant (admin_validate.php). Transforme le
// mécanisme de validation en argument visible pour l'élève et le parent.
window._iaBadgeHtml = function(){
  if(window._iaLastSource!=='cache_validated') return '';
  return '<div style="display:inline-flex;align-items:center;gap:6px;background:linear-gradient(135deg,#ECFDF5,#D1FAE5);border:1px solid #6EE7B7;color:#047857;font-size:11px;font-weight:800;padding:5px 12px;border-radius:99px;margin-bottom:10px">'
    +'<span style="background:#059669;color:#fff;border-radius:50%;width:16px;height:16px;display:inline-flex;align-items:center;justify-content:center;font-size:10px">✓</span>'
    +'Corrigé vérifié par un enseignant VÉRITAS</div>';
};

// ══ v1.5 — RÉPÉTITION ESPACÉE : « Mes erreurs à revoir » ════════════════════
// Chaque question ratée (quiz, battle, positionnement) est mémorisée (50 max,
// dédupliquée). Calibré sur les intervalles EXPANSIFS de Cepeda et al. (2006) :
// une bonne réponse n'efface plus la question — elle la replanifie PLUS LOIN
// (≈2 j → 10 j → 28 j). Il faut plusieurs récupérations espacées réussies avant
// qu'elle soit « maîtrisée » (retrait) ; une erreur remet l'espacement à zéro.
// La fenêtre ne montre que les questions ARRIVÉES À ÉCHÉANCE : l'effort de
// récupération tombe au bon moment, au lieu d'une boucle immédiate qui glisse
// vers la simple re-lecture (peu d'effet sur la mémoire).
var _SR_INTERVALS=[2,10,28]; // jours : 1re révision ~2j, puis ~10j, puis ~4 sem
var _SR_DAY=86400000;
window._srDueList=function(arr){ // questions à échéance, la plus en retard d'abord
  var now=Date.now();
  return (arr||[]).map(function(q,i){return {q:q,i:i};})
    .filter(function(o){return (o.q.due||0)<=now;})
    .sort(function(a,b){return (a.q.due||0)-(b.q.due||0);});
};
window._recordMissed=function(q){
  try{
    if(!q||!q.q) return;
    if(!DB._missedQ) DB._missedQ={};
    var uid=(typeof SES!=='undefined'&&SES&&SES.id)?SES.id:'anon';
    var arr=DB._missedQ[uid]=DB._missedQ[uid]||[];
    var key=String(q.q).substring(0,80);
    if(arr.some(function(x){return String(x.q).substring(0,80)===key;})) return; // dédup
    q.ts=Date.now(); q.box=0; q.due=Date.now(); // à réviser dès maintenant
    arr.push(q);
    if(arr.length>50) arr.shift();
    save();
  }catch(e){}
};
window._missedCount=function(){ // total en cours d'apprentissage
  var uid=(typeof SES!=='undefined'&&SES&&SES.id)?SES.id:'anon';
  return ((DB._missedQ||{})[uid]||[]).length;
};
window._missedDueCount=function(){ // combien sont à réviser maintenant
  var uid=(typeof SES!=='undefined'&&SES&&SES.id)?SES.id:'anon';
  return _srDueList((DB._missedQ||{})[uid]||[]).length;
};
window.mErreursARevoir=function(){
  var uid=(typeof SES!=='undefined'&&SES&&SES.id)?SES.id:'anon';
  var arr=((DB._missedQ||{})[uid]||[]);
  if(!arr.length){
    M('🎯 Mes erreurs à revoir','',
      '<div style="text-align:center;padding:26px"><div style="font-size:46px;margin-bottom:10px">🏆</div>'
      +'<div class="semi">Aucune erreur en attente — bravo !</div>'
      +'<div class="xs2 mut mt8">Vos questions ratées en quiz et en battle apparaîtront ici pour être retravaillées au bon moment.</div></div>',
      '<button class="btn bo" onclick="cm()">Fermer</button>');
    return;
  }
  var due=_srDueList(arr);
  if(!due.length){ // rien à échéance : indiquer la prochaine date de révision
    var next=arr.reduce(function(m,q){var d=q.due||0;return (m===null||d<m)?d:m;},null);
    var dStr=next?new Date(next).toLocaleDateString('fr-FR'):'bientôt';
    M('🎯 Mes erreurs à revoir','',
      '<div style="text-align:center;padding:24px"><div style="font-size:44px;margin-bottom:10px">✅</div>'
      +'<div class="semi">Rien à réviser pour le moment.</div>'
      +'<div class="xs2 mut mt8">'+arr.length+' question'+(arr.length>1?'s':'')+' à consolider. Espacer les révisions renforce la mémoire — prochaine échéance le <b>'+dStr+'</b>.</div></div>',
      '<button class="btn bo" onclick="cm()">Fermer</button>');
    return;
  }
  var q=due[0].q;
  var opts=q.opts||['a','b','c','d'].filter(function(k){return q[k];}).map(function(k){return q[k];});
  var ansIdx=(typeof q.ans==='number')?q.ans:['a','b','c','d'].indexOf(q.ok||'a');
  M('🎯 Mes erreurs à revoir',due.length+' à réviser maintenant · '+_esc(q.src||''),
    '<div class="semi mb12" style="font-size:14.5px;line-height:1.5">'+_esc(q.q)+'</div>'
    +opts.map(function(o,i){
      return '<button class="btn" style="display:block;width:100%;text-align:left;padding:11px 14px;margin-bottom:8px;background:#fff;border:2px solid #E5E7EB;border-radius:10px;color:#142554;font-size:13.5px;font-weight:600" onclick="_missedAnswer('+i+','+ansIdx+')">'+String.fromCharCode(65+i)+'. '+_esc(o)+'</button>';
    }).join('')
    +'<div id="missedExpl" style="display:none;margin-top:10px;padding:12px;border-radius:10px;font-size:13px;line-height:1.6"></div>',
    '<button class="btn bo" onclick="cm()">Plus tard</button>');
};
window._missedAnswer=function(i,ansIdx){
  var uid=(typeof SES!=='undefined'&&SES&&SES.id)?SES.id:'anon';
  var arr=(DB._missedQ||{})[uid]||[];
  var due=_srDueList(arr);
  if(!due.length){ cm(); return; }
  var idx=due[0].i, q=arr[idx]||{};
  var box=document.getElementById('missedExpl');
  var good=(i===ansIdx);
  var nb=(q.box||0)+1, mastered=false, nextTxt='';
  if(good){
    if(nb>_SR_INTERVALS.length){ mastered=true; }
    else { q.box=nb; q.due=Date.now()+_SR_INTERVALS[nb-1]*_SR_DAY; nextTxt='Prochaine révision dans '+_SR_INTERVALS[nb-1]+' jours.'; }
  } else {
    q.box=0; q.due=Date.now(); // lapsus : on recommence l'espacement à zéro
  }
  if(box){
    box.style.display='block';
    box.style.background=good?'#ECFDF5':'#FEF2F2';
    box.style.border=good?'1px solid #6EE7B7':'1px solid #FCA5A5';
    box.innerHTML=(good
        ?(mastered?'🏆 <b>Maîtrisée !</b> Cette question quitte définitivement votre liste.'
                  :'✅ <b>Bien !</b> '+nextTxt+' (espacer renforce la mémoire)')
        :'❌ Pas encore. La bonne réponse était <b>'+String.fromCharCode(65+ansIdx)+'</b>.'+(q.exp?'<br>💡 '+_esc(q.exp):''))
      +'<div style="margin-top:10px"><button class="btn bi sm" onclick="cm();mErreursARevoir()">Continuer →</button></div>';
  }
  if(good && mastered){ arr.splice(idx,1); }
  save();
};

