function _buildOrientationSection(){
  var h="<div class='vsec'>";
  h+="<div class='vsec-title'><span class='vsec-ico'><svg class='vico vico-21' aria-hidden='true'><use href='#lc-compass'/></svg></span>Orientation Scolaire</div>";
  h+="<div class='vsec-sub'>Trouvez la filière et l'école adaptées à votre profil, selon le système éducatif camerounais.</div>";
  h+="<div style='display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-bottom:22px'>";
  // Les libellés étaient écrits SANS ACCENTS (« filière », « école », « Médecine »)
  // sur la page d'orientation d'un centre de français — rétablis.
  var cards=[
    // Pictogrammes du sprite embarqué VRT_SPRITE (#i-*) — voir ICO() ; aucun émoji.
    {ico:"i-target",tint:"or",titre:"Orientation personnalisée",desc:"Remplissez un formulaire pour une analyse complète de votre profil",action:"showOrientationForm()"},
    {ico:"i-school",tint:"bleu",titre:"Grandes écoles",desc:"ENAM, Polytechnique, FASA, IRIC, ESSEC, EMIA — conditions d'admission",action:"_showGrandesEcoles()"},
    {ico:"i-flask",tint:"vert",titre:"Filières scientifiques",desc:"BAC C/D, médecine, ingénierie, agriculture, sciences naturelles",action:"showOrientationForm()"},
    {ico:"i-book-open",tint:"violet",titre:"Filières littéraires",desc:"BAC A, droit, lettres, journalisme, sciences humaines",action:"showOrientationForm()"},
    {ico:"i-tool",tint:"cyan",titre:"Filières techniques",desc:"BAC TI/TC, BTS/HND, commerce, industrie, informatique",action:"showOrientationForm()"},
    {ico:"i-graduation",tint:"or",titre:"Bourses & concours",desc:"Calendrier des concours nationaux et opportunités de bourses",action:"_showBourses()"},
    {ico:"i-users",tint:"rose",titre:"Coaching & accompagnement",desc:"Soutien scolaire, gestion du stress, développement personnel et bien-être",action:"showPacksCoaching()"},
  ];
  cards.forEach(function(c){
    h+="<div class='vcard vori-card' style='cursor:pointer' onclick='"+c.action+"'>"
      +"<div class='vori-ico t-"+c.tint+"'>"+ICO(c.ico)+"</div>"
      +"<div style='font-family:Montserrat,sans-serif;font-size:14px;font-weight:800;color:#142554;margin-bottom:6px'>"+c.titre+"</div>"
      +"<div style='font-size:11px;color:#6B7A99;line-height:1.55'>"+c.desc+"</div>"
      +"</div>";
  });
  h+="</div></div>";
  return h;
}

