// ── SECTION ELEARNING AMÉLIORÉE — ONGLET ÉPREUVES + LABOS ────────
// Patcher vShowSec pour exposer les épreuves et labos dans elearning
var _origVShowSecEl=window.vShowSec;
(function(){
  var _ov=window.vShowSec;
  window.vShowSec=function(sec,btn){
    // v1.2.4 : après chaque navigation, remonter en haut du contenu. Sans cela la
    // section s'ouvrait « loin en bas » et échappait à l'utilisateur (surtout mobile
    // où le menu pousse le contenu sous la ligne de flottaison).
    // v1.3.1 perf : remontée INSTANTANÉE (behavior:'auto') — le défilement lissé
    // sur une longue distance après un re-rendu donnait une impression de lenteur.
    setTimeout(function(){ try{ var c=document.getElementById('vContent'); if(c){ var y=c.getBoundingClientRect().top+window.pageYOffset-72; window.scrollTo({top:y<0?0:y,behavior:'auto'}); } }catch(e){} },80);
    // Reposer la traduction des sous-titres après chaque navigation (EN persistant)
    setTimeout(function(){ try{ if(typeof _translateSubs==='function') _translateSubs(); }catch(e){} },120);
    if(sec!=="epreuves"){
      // Réinitialiser les filtres épreuves quand on navigue ailleurs
      window._epMat='';window._epClasse='';window._epSeq='';
    }
    if(sec==="epreuves"){
      document.querySelectorAll(".vnav-btn").forEach(function(b){b.classList.remove("on");});
      if(btn)btn.classList.add("on");
      showEpreuves();return;
    }
    if(sec==="labos"){
      document.querySelectorAll(".vnav-btn").forEach(function(b){b.classList.remove("on");});
      if(btn)btn.classList.add("on");
      showLabosVirtuels();return;
    }
    if(_ov) _ov.call(this,sec,btn);
    // v1.4.6 FIX CRITIQUE : ré-observer les éléments « reveal » créés par CE rendu.
    // L'observer de la coquille (initReveal) ne couvre que le boot → les grilles
    // re-rendues (catégories e-learning, stats…) restaient en opacity:0 = la
    // « partie vide qui ne charge pas ». Ici : visible à l'écran → cascade
    // immédiate ; plus bas → déclenchée au scroll (effet de déroulement).
    // v1.9.1 FIX « retour à l'accueil tarde à charger » : les .v-reveal / .v-stagger
    // RE-RENDUS restaient en opacity:0 car on ajoutait .is-visible alors que leur CSS
    // se révèle avec .visible -> contenu invisible après navigation (« partie vide »).
    // On ajoute DÉSORMAIS les deux classes (+ .v-stagger), et plus vite (60ms) pour un
    // affichage quasi instant. Les éléments déjà à l'écran sont révélés immédiatement.
    setTimeout(function(){
      try{
        var els=document.querySelectorAll('.v-reveal:not(.visible), .v-stagger:not(.visible), .lx-catgrid:not(.is-visible)');
        if(!els.length) return;
        if(!('IntersectionObserver' in window)){ els.forEach(function(el){el.classList.add('is-visible','visible');}); return; }
        var io=new IntersectionObserver(function(es){
          es.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('is-visible','visible'); io.unobserve(e.target); } });
        },{threshold:.12,rootMargin:'0px 0px -40px 0px'});
        els.forEach(function(el){
          var r=el.getBoundingClientRect();
          if(r.top<(window.innerHeight||800)*0.96&&r.bottom>0){ el.classList.add('is-visible','visible'); }
          else io.observe(el);
        });
      }catch(e){}
    },60);
  };
})();
