function showLabosVirtuels(){
  // Porte d'entrée du module : la base des labos est chargée à la demande.
  // On la récupère puis on rejoue l'appel — l'utilisateur ne voit qu'un
  // court message d'attente au lieu de payer 88 Ko à chaque visite du site.
  if(typeof window.LABO_DB==='undefined'){
    toast('Chargement des laboratoires…','info');
    _lazyChunk('labo')
      .then(function(){ showLabosVirtuels(); })
      .catch(function(){ toast('Laboratoires momentanément indisponibles','err'); });
    return;
  }
  // v1.4.3 : catégorie initiale alignée sur le PARCOURS (anglophone → English,
  // technique/CAP → Technique) ; l'apprenant reste libre de changer.
  var cat=window._laboCat||(function(){
    var g=(typeof _profileGroup==='function')?_profileGroup():'';
    return g==='en'?'english':(g==='fr_tech'||g==='cap')?'technique':'tous';
  })();
  // v1.4.2 : + catégories Anglophone (GCE) et Enseignement technique
  var cats=["tous","physique","chimie","svt","maths","english","technique","geo","histoire","info","langues"];
  var catLabels={"tous":"Tous","physique":"⚡ Physique","chimie":"⚗️ Chimie","svt":"🧬 SVT","maths":"📐 Maths","english":"🇬🇧 English (GCE)","technique":"🔧 Technique","geo":"🗺️ Géo","histoire":"🏛️ Histoire","info":"💻 Info","langues":"✍️ Langues"};
  var _hiddenLV=DB.hiddenLabos||[];
  var _purgedLV=DB.purgedLabos||[];
  var _visibleLabo=window.LABO_DB.filter(function(l){return _hiddenLV.indexOf(l.id)<0&&_purgedLV.indexOf(l.id)<0;});
  var list=_visibleLabo.filter(function(l){return cat==="tous"||l.cat===cat;});
  var gratuits=list.filter(function(l){return l.gratuit;}).length;

  var h="<div class='vsec'>";
  h+="<div class='vsec-title vsec-title-hero'>🔬 Laboratoires Virtuels</div>";
  h+="<div class='vsec-sub'>"+_visibleLabo.length+" expériences interactives basées sur le programme MINESEC — Sans risque, sans matériel</div>";

  // Bandeau stats
  h+="<div style='display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:20px'>";
  [{n:_visibleLabo.length,l:"Expériences",c:"#142554",i:"🔬"},{n:gratuits,l:"Gratuites",c:"#059669",i:"✅"},{n:_visibleLabo.filter(function(l){return !l.gratuit;}).length,l:"Premium",c:"#6C56A6",i:"⭐"}].forEach(function(s){
    h+="<div style='background:"+s.c+"0f;border:0;border-radius:16px;padding:16px 12px;text-align:center;box-shadow:0 8px 22px -15px rgba(20,37,84,.22)'>";
    h+="<div style='font-size:22px;margin-bottom:4px'>"+s.i+"</div>";
    h+="<div style='font-family:Montserrat,sans-serif;font-size:24px;font-weight:900;color:"+s.c+";line-height:1'>"+s.n+"</div>";
    h+="<div style='font-size:11px;color:#6B7A99;margin-top:3px;font-weight:600'>"+s.l+"</div>";
    h+="</div>";
  });
  h+="</div>";

  // Filtres catégories
  h+="<div class='fl2 g6 mb16' style='flex-wrap:wrap'>";
  cats.forEach(function(c){
    h+="<button onclick=\"window._laboCat='"+c+"';showLabosVirtuels()\" style='padding:7px 16px;border-radius:20px;font-size:12px;font-weight:700;cursor:pointer;border:none;transition:.2s;background:"+(cat===c?"#142554":"#F0F4FF")+";color:"+(cat===c?"#fff":"#142554")+"'>"+(catLabels[c]||c)+"</button>";
  });
  h+="</div>";

  // Grille de labos
  // v2.0 FIX débordement mobile : minmax(min(270px,100%),1fr) → la colonne se réduit
  // à 100% sous 270px au lieu de forcer 270px (qui poussait la carte + son badge
  // « GRATUIT » hors écran et créait un défilement horizontal). + overflow-x clos.
  h+="<div style='display:grid;grid-template-columns:repeat(auto-fill,minmax(min(270px,100%),1fr));gap:16px;margin-bottom:28px;max-width:100%'>";
  list.forEach(function(lv){
    var locked=!lv.gratuit&&!SES;
    h+="<div onclick='lancerLabo(\""+lv.id+"\")' style='background:#fff;border-radius:18px;border:0;--vcol:"+lv.color+";overflow:hidden;cursor:pointer;transition:transform .25s cubic-bezier(.34,1.56,.64,1),box-shadow .25s;box-shadow:0 10px 26px -16px rgba(20,37,84,.16)' onmouseover=\"this.style.transform='translateY(-5px)';this.style.boxShadow='0 20px 40px -18px "+lv.color+"55'\" onmouseout=\"this.style.transform='';this.style.boxShadow='0 10px 26px -16px rgba(20,37,84,.16)'\">";
    h+="<div style='background:linear-gradient(135deg,"+lv.color+"1f,"+lv.color+"08);padding:18px 18px 16px;position:relative'>";
    h+="<div style='position:absolute;top:10px;right:10px;background:"+(lv.gratuit?"#059669":"#6C56A6")+";color:#fff;font-size:9px;font-weight:800;padding:3px 9px;border-radius:10px'>"+(lv.gratuit?"GRATUIT":lv.plan||"PREMIUM")+"</div>";
    h+="<div style='width:52px;height:52px;border-radius:14px;background:"+lv.color+"26;display:flex;align-items:center;justify-content:center;font-size:30px;margin-bottom:10px'>"+lv.ico+"</div>";
    h+="<div style='font-family:var(--ds-font-display,Montserrat),sans-serif;font-size:14px;font-weight:800;color:#142554'>"+lv.titre+"</div>";
    h+="<div style='font-size:11px;color:#6B7A99;margin-top:3px;font-weight:600'>"+lv.matiere+" · "+lv.classe+"</div>";
    h+="</div>";
    h+="<div style='padding:14px'>";
    h+="<div style='font-size:12px;color:#6B7A99;line-height:1.6;margin-bottom:10px'>"+lv.desc+"</div>";
    h+="<div class='fl2 fic fsb'>";
    h+="<div style='font-size:11px;color:#9CA3AF'>"+lv.experience.length+" étapes · "+lv.quiz.length+" quiz</div>";
    h+="<button style='background:"+lv.color+";color:#fff;border:none;border-radius:10px;padding:6px 14px;font-size:11px;font-weight:700;cursor:pointer'>"+(locked?"🔒 Premium":"▶ Lancer")+"</button>";
    h+="</div></div></div>";
  });
  h+="</div>";

  // Section Packs d'abonnement
  h+="<div style='background:linear-gradient(135deg,#0F172A,#1E3A8A);border-radius:20px;padding:28px;margin-bottom:20px'>";
  h+="<div style='font-size:11px;font-weight:800;color:#FFC93C;letter-spacing:3px;text-transform:uppercase;margin-bottom:8px'>⭐ Abonnements Labos</div>";
  h+="<div style='font-family:Georgia,serif;font-size:15px;color:rgba(255,255,255,.8);margin-bottom:20px'>Accède à tous les labos, quiz et fiches de révision</div>";
  h+="<div style='display:grid;grid-template-columns:repeat(auto-fit,minmax(min(220px,100%),1fr));gap:14px'>";
  LABO_PACKS.forEach(function(pk){
    h+="<div style='background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,."+(pk.populaire?"3":"15")+");border-radius:16px;padding:18px;position:relative'>";
    if(pk.populaire) h+="<div style='position:absolute;top:-10px;left:50%;transform:translateX(-50%);background:#FFC93C;color:#0F172A;font-size:9px;font-weight:800;padding:3px 12px;border-radius:10px;white-space:nowrap'>⭐ PLUS POPULAIRE</div>";
    h+="<div style='font-family:Montserrat,sans-serif;font-size:15px;font-weight:800;color:#fff;margin-bottom:6px'>"+pk.nom+"</div>";
    h+="<div style='font-family:Georgia,serif;font-size:20px;font-weight:700;color:#FFC93C;margin-bottom:12px'>"+(pk.prix===0?"Gratuit":pk.badge)+"</div>";
    h+=pk.avantages.map(function(a){return "<div style='font-size:12px;color:rgba(255,255,255,.7);margin-bottom:5px;display:flex;align-items:center;gap:6px'><span style='color:#FFC93C'>✓</span>"+a+"</div>";}).join("");
    h+="<button onclick=\"vShowSec('contact',null)\" style='width:100%;margin-top:12px;background:"+(pk.populaire?"#FFC93C":"rgba(255,255,255,.15)")+";color:"+(pk.populaire?"#0F172A":"#fff")+";border:none;border-radius:12px;padding:10px;font-size:12px;font-weight:700;cursor:pointer'>"+(pk.prix===0?"Commencer gratuitement":"S'abonner")+"</button>";
    h+="</div>";
  });
  h+="</div></div>";

  // Lien MINESEC
  h+="<div class='vcard' style='background:linear-gradient(135deg,#EFF6FF,#EDE9FE);border:1px solid #C7D2FE'>";
  h+="<div class='fl2 fic g12'><span style='font-size:32px'>🌐</span><div>";
  h+="<div style='font-family:Montserrat,sans-serif;font-size:14px;font-weight:800;color:#142554;margin-bottom:4px'>Cours vidéo officiels MINESEC</div>";
  h+="<div style='font-size:12px;color:#6B7A99;margin-bottom:10px'>La plateforme officielle propose des vidéos pour toutes les matières de la 6ème à la Terminale.</div>";
  h+="<a href='https://minesec-distancelearning.cm' target='_blank' rel='noopener' style='background:#142554;color:#fff;border-radius:12px;padding:9px 18px;font-size:12px;font-weight:700;text-decoration:none;display:inline-block'>🎬 Accéder aux cours officiels</a>";
  h+="</div></div></div>";
  h+="</div>";
  _vc(h);
}

function lancerLabo(id){
  // Un lien direct vers un labo peut arriver avant que le module soit là.
  if(typeof window.LABO_DB==='undefined'){
    toast('Chargement du laboratoire…','info');
    _lazyChunk('labo')
      .then(function(){ lancerLabo(id); })
      .catch(function(){ toast('Laboratoire momentanément indisponible','err'); });
    return;
  }
  var lv=window.LABO_DB.find(function(x){return x.id===id;});
  if(!lv)return;
  // v1.2.2 : labo premium → accès selon le PLAN (pas seulement "connecté")
  // v1.14.1 : la relance NOMME le labo qu'on vient de toucher et le plan qui
  // l'ouvre, au lieu du message générique « réservé aux abonnés » qui laissait
  // le visiteur faire lui-même le lien avec le catalogue.
  if(!lv.gratuit && typeof _planAccess==='function' && !_planAccess('labos')
     && !(typeof iA==='function' && iA())){
    // v1.16 : on offre d'abord les essais réglés dans l'admin ; la relance
    // premium (message nominatif ci-dessous) ne sert que s'ils sont épuisés.
    if(typeof _pwGate==='function' && typeof _pwEtat==='function' && _pwEtat('labo',lv.id).ouvert
       && _pwGate('labo', lv.titre||'Ce laboratoire', lv.id)){
      _lancerLaboComplet(lv); return;
    }
    if(typeof _relancePremium==='function'){
      var _autres = (window.LABO_DB||[]).filter(function(x){ return !x.gratuit && x.id!==lv.id; }).length;
      _relancePremium({
        titre:   lv.titre,
        sous:    lv.matiere + ' · ' + lv.classe,
        ico:     lv.ico,
        role:    'eleve',
        feature: 'labos',
        aussi:   _autres ? ('les ' + _autres + ' autres laboratoires premium') : ''
      });
      return;
    }
    if(typeof _requirePlan==='function'){ _requirePlan('labos','Les laboratoires virtuels premium'); return; }
  }
  // Filet : si le contrôle par plan venait à manquer, un labo premium ne doit
  // pas s'ouvrir pour autant à un visiteur non identifié.
  if(!lv.gratuit && typeof _planAccess!=='function' && !SES){
    toast('Ce laboratoire est réservé aux abonnés','warn'); return;
  }
  _lancerLaboComplet(lv);
}

function _lancerLaboComplet(lv){
  var step=window._laboStep||0;
  var quizMode=window._laboQuiz||false;
  var score=window._laboScore||0;
  var qIdx=window._laboQIdx||0;
  var savedNote=DB.laboNotes&&DB.laboNotes[lv.id];

  function render(){
    var h="<div class='vsec'>";
    h+="<button class='back-btn' onclick='showLabosVirtuels()'>← Laboratoires</button>";

    // En-tête lab
    h+="<div style='background:linear-gradient(135deg,"+lv.color+","+lv.color+"BB);border-radius:18px;padding:22px;color:#fff;margin-bottom:20px'>";
    h+="<div style='font-size:11px;font-weight:800;color:rgba(255,255,255,.6);text-transform:uppercase;letter-spacing:2px;margin-bottom:6px'>"+lv.matiere+" · "+lv.classe+"</div>";
    h+="<div style='font-family:Montserrat,sans-serif;font-size:20px;font-weight:900;margin-bottom:8px'>"+lv.ico+" "+lv.titre+"</div>";
    h+="<div style='font-family:Georgia,serif;font-size:13px;opacity:.85;line-height:1.7'>"+lv.desc+"</div>";
    h+="</div>";

    // Onglets
    h+="<div class='fl2 g8 mb16'>";
    [{k:"theorie",l:"📖 Théorie"},{k:"experience",l:"🔬 Expérience"},{k:"quiz",l:"🧠 Quiz"},{k:"notes",l:"📓 Notes"}].forEach(function(tab){
      var active=window._laboTab===tab.k||((!window._laboTab)&&tab.k==="theorie");
      h+="<button onclick=\"window._laboTab='"+tab.k+"';window._laboQIdx=0;window._laboScore=0;_lancerLaboComplet(window._laboDBItem)\" style='padding:9px 18px;border-radius:20px;font-size:12px;font-weight:700;cursor:pointer;border:none;transition:.2s;background:"+(active?"#142554":"#F0F4FF")+";color:"+(active?"#fff":"#142554")+"'>"+tab.l+"</button>";
    });
    h+="</div>";

    var activeTab=window._laboTab||"theorie";

    if(activeTab==="theorie"){
      h+="<div class='card'>";
      h+="<div class='ct mb12'><span class='ct-ico'><svg class='vico' aria-hidden='true'><use href='#lc-bookopen'/></svg></span>Cours théorique</div>";
      h+="<div style='font-family:Georgia,serif;font-size:14px;color:#374151;line-height:1.9;padding:16px;background:linear-gradient(135deg,#F8FAFF,#EDE9FE1A);border-radius:12px;'>";
      h+=lv.theorie;
      h+="</div>";
      h+="<button class='btn bi mt14' onclick=\"window._laboTab='experience';_lancerLaboComplet(window._laboDBItem)\">Passer à l'expérience →</button>";
      h+="</div>";
    } else if(activeTab==="experience"){
      h+="<div class='card'>";
      h+="<div class='ct mb12'><span class='ct-ico'><svg class='vico' aria-hidden='true'><use href='#lc-flask'/></svg></span>Protocole expérimental</div>";
      h+="<div class='ib ibt mb14'><span>🥽</span><span>Observe la simulation animée puis suis le protocole étape par étape.</span></div>";

      // ── SIMULATION ANIMÉE ──
      h+="<div id='laboSimWrap' style='background:linear-gradient(135deg,#0F172A,#1E293B);border-radius:16px;overflow:hidden;margin-bottom:18px;position:relative'>";
      h+="<div style='padding:10px 16px;display:flex;align-items:center;justify-content:space-between;background:rgba(255,255,255,.06)'>";
      h+="<div style='font-family:Montserrat,sans-serif;font-size:12px;font-weight:700;color:rgba(255,255,255,.7)'>"+lv.ico+" Simulation — "+_esc(lv.titre)+"</div>";
      h+="<div style='display:flex;gap:6px'>";
      h+="<button id='simPlayBtn' onclick='_simToggle()' style='background:rgba(255,255,255,.12);border:none;color:#FFC93C;border-radius:8px;padding:5px 12px;font-size:11px;font-weight:700;cursor:pointer'>⏸ Pause</button>";
      h+="<button onclick='_simReset()' style='background:rgba(255,255,255,.08);border:none;color:#fff;border-radius:8px;padding:5px 12px;font-size:11px;font-weight:700;cursor:pointer'>🔄 Reset</button>";
      h+="</div></div>";
      h+="<canvas id='laboCnv' width='680' height='340' style='width:100%;display:block;cursor:crosshair'></canvas>";
      h+="<div id='simValues' style='padding:8px 16px;font-family:Fira Code,monospace;font-size:11px;color:#FFC93C;background:rgba(0,0,0,.3);display:flex;gap:16px;flex-wrap:wrap'></div>";
      h+="</div>";

      // Contrôle interactif
      h+="<div id='simControls' style='display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px;padding:12px;background:#F0F4FF;border-radius:12px'></div>";

      lv.experience.forEach(function(e,i){
        h+="<div style='display:flex;align-items:flex-start;gap:12px;padding:12px;background:"+(i%2===0?"#F8FAFF":"#fff")+";border-radius:10px;margin-bottom:8px;'>";
        h+="<div style='font-size:18px;flex-shrink:0'>"+e.charAt(0)+e.charAt(1)+"</div>";
        h+="<div style='font-family:Georgia,serif;font-size:13px;color:#374151;line-height:1.7'>"+e.substring(3)+"</div>";
        h+="</div>";
      });
      h+="<div class='fl2 g8 mt14'>";
      h+="<button class='btn' style='background:#F0F4FF;color:#142554;border-radius:12px;padding:9px 18px;font-weight:700' onclick=\"window._laboTab='theorie';_lancerLaboComplet(window._laboDBItem)\">← Théorie</button>";
      h+="<button class='btn bi' onclick=\"window._laboTab='quiz';window._laboQIdx=0;window._laboScore=0;_lancerLaboComplet(window._laboDBItem)\">Passer au quiz →</button>";
      h+="</div></div>";
    } else if(activeTab==="quiz"){
      var qi=window._laboQIdx||0;
      var qs=lv.quiz;
      if(qi>=qs.length){
        var pct=Math.round((window._laboScore/qs.length)*100);
        h+="<div class='card' style='text-align:center;padding:32px'>";
        h+="<div style='font-size:52px;margin-bottom:16px'>"+(pct>=80?"🏆":pct>=60?"✅":"📚")+"</div>";
        h+="<div style='font-family:Montserrat,sans-serif;font-size:22px;font-weight:800;color:#142554;margin-bottom:8px'>Quiz terminé !</div>";
        h+="<div style='font-family:Georgia,serif;font-size:16px;color:"+(pct>=80?"#059669":pct>=60?"#D97706":"#AE5353")+"';>Score : "+window._laboScore+"/"+qs.length+" ("+pct+"%)</div>";
        h+="<div style='font-size:13px;color:#6B7A99;margin:10px 0 20px'>"+(pct>=80?"Excellent ! Tu maîtrises ce chapitre.":pct>=60?"Bien ! Revois quelques points.":"Continue à étudier la théorie.")+"</div>";
        h+="<div class='fl2 g8' style='justify-content:center'>";
        h+="<button class='btn' style='background:#F0F4FF;color:#142554;border-radius:12px;padding:9px 18px;font-weight:700' onclick=\"window._laboQIdx=0;window._laboScore=0;_lancerLaboComplet(window._laboDBItem)\"><svg class='vico bico' aria-hidden='true'><use href='#lc-refresh'/></svg>Recommencer</button>";
        h+="<button class='btn bi' onclick='showLabosVirtuels()'>← Tous les labos</button>";
        h+="</div></div>";
      } else {
        var q=qs[qi];
        h+="<div class='card'>";
        h+="<div style='font-size:12px;color:#9CA3AF;margin-bottom:12px'>Question "+(qi+1)+"/"+qs.length+" · Score: "+(window._laboScore||0)+"</div>";
        h+="<div style='font-family:Montserrat,sans-serif;font-size:15px;font-weight:700;color:#142554;margin-bottom:20px;line-height:1.5'>"+q.q+"</div>";
        h+="<div style='display:grid;grid-template-columns:1fr 1fr;gap:10px'>";
        q.opts.forEach(function(opt,i){
          h+="<button onclick='_laboAnswer("+i+")' style='background:#F0F4FF;color:#142554;border:2px solid #E8EEFF;border-radius:12px;padding:12px 16px;font-size:13px;font-weight:600;cursor:pointer;transition:.2s;text-align:left' onmouseover=\"this.style.background='#E0EAFF'\" onmouseout=\"this.style.background='#F0F4FF'\">"+opt+"</button>";
        });
        h+="</div><div id='laboFb' style='margin-top:14px;min-height:24px'></div>";
        h+="</div>";
      }
    } else if(activeTab==="notes"){
      var saved=DB.laboNotes&&DB.laboNotes[lv.id];
      h+="<div class='card'>";
      h+="<div class='ct mb12'><span class='ct-ico'><svg class='vico' aria-hidden='true'><use href='#lc-book'/></svg></span>Carnet de laboratoire</div>";
      h+="<div style='display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px'>";
      h+="<div style='background:#F8FAFF;border-radius:10px;padding:12px'><div style='font-size:11px;font-weight:700;color:#6B7A99;margin-bottom:6px;text-transform:uppercase;letter-spacing:1px'>💡 Hypothèse</div><textarea id='labHypo' class='fi' rows='4' style='font-size:12px;line-height:1.7' placeholder='Selon moi...'>"+((saved&&saved.hypo)||"")+"</textarea></div>";
      h+="<div style='background:#F8FAFF;border-radius:10px;padding:12px'><div style='font-size:11px;font-weight:700;color:#6B7A99;margin-bottom:6px;text-transform:uppercase;letter-spacing:1px'>👁️ Observations</div><textarea id='labObs' class='fi' rows='4' style='font-size:12px;line-height:1.7' placeholder='J\u0027observe que...'>"+((saved&&saved.obs)||"")+"</textarea></div>";
      h+="</div>";
      h+="<div style='background:#F8FAFF;border-radius:10px;padding:12px;margin-bottom:12px'><div style='font-size:11px;font-weight:700;color:#6B7A99;margin-bottom:6px;text-transform:uppercase;letter-spacing:1px'>🏁 Conclusion</div><textarea id='labConc' class='fi' rows='3' style='font-size:12px;line-height:1.7' placeholder='En conclusion...'>"+((saved&&saved.conc)||"")+"</textarea></div>";
      if(saved) h+="<div style='font-size:11px;color:#059669;margin-bottom:8px'>✅ Dernière sauvegarde: "+saved.date+"</div>";
      h+="<button class='btn bi' onclick='_saveLaboNote(\""+lv.id+"\")'><svg class='vico bico' aria-hidden='true'><use href='#lc-save'/></svg>Sauvegarder mes notes</button>";
      h+="</div>";
    }
    h+="</div>";
    _vc(h);
    window._laboDBItem=lv;
    // Lancer la simulation animée si onglet expérience
    // Le moteur de simulation vit désormais dans chunks/labo.js. On ne peut
    // arriver ici qu'en passant par lancerLabo(), qui a chargé le module — le
    // repli ne sert que si un appel direct court-circuitait cette porte.
    if(activeTab==="experience") setTimeout(function(){
      if(typeof window._initLaboSim==='function'){ window._initLaboSim(lv); return; }
      _lazyChunk('labo').then(function(){ window._initLaboSim && window._initLaboSim(lv); })
                        .catch(function(){ toast('Simulation indisponible','err'); });
    },50);
  }

  window._laboAnswer=function(i){
    var qi=window._laboQIdx||0;
    var q=lv.quiz[qi];
    var fb=document.getElementById("laboFb");
    var btns=document.querySelectorAll("[onclick^='_laboAnswer']");
    btns.forEach(function(b,idx){
      b.style.background=idx===q.ans?"#D1FAE5":idx===i&&i!==q.ans?"#FEE2E2":"#F0F4FF";
      b.style.borderColor=idx===q.ans?"#059669":idx===i&&i!==q.ans?"#AE5353":"#E8EEFF";
      b.style.cursor="default";
      b.onclick=null;
    });
    if(i===q.ans) window._laboScore=(window._laboScore||0)+1;
    if(fb) fb.innerHTML="<div style='padding:10px;background:"+(i===q.ans?"#D1FAE5":"#FEE2E2")+";border-radius:10px;font-size:13px;color:"+(i===q.ans?"#059669":"#AE5353")+";line-height:1.6'>"+(i===q.ans?"✅ ":"❌ ")+q.exp+"</div>";
    setTimeout(function(){window._laboQIdx=(window._laboQIdx||0)+1;render();},2000);
  };

  render();
}

// Polyfill roundRect for older browsers
if(typeof CanvasRenderingContext2D!=='undefined'&&!CanvasRenderingContext2D.prototype.roundRect){
  CanvasRenderingContext2D.prototype.roundRect=function(x,y,w,h,r){
    r=typeof r==='number'?r:5;this.moveTo(x+r,y);this.lineTo(x+w-r,y);this.quadraticCurveTo(x+w,y,x+w,y+r);
    this.lineTo(x+w,y+h-r);this.quadraticCurveTo(x+w,y+h,x+w-r,y+h);this.lineTo(x+r,y+h);
    this.quadraticCurveTo(x,y+h,x,y+h-r);this.lineTo(x,y+r);this.quadraticCurveTo(x,y,x+r,y);return this;
  };
}
// ═══════════════════════════════════════════════════════════════════
// MOTEUR DE SIMULATIONS ANIMÉES — LABORATOIRES VIRTUELS v1.0
// ═══════════════════════════════════════════════════════════════════
window._sim={running:true,raf:0,t:0,params:{}};

function _simToggle(){
  window._sim.running=!window._sim.running;
  var b=document.getElementById('simPlayBtn');
  if(b) b.textContent=window._sim.running?'⏸ Pause':'▶ Lecture';
  if(window._sim.running && window._sim._draw) _simLoop();
}
function _simReset(){
  window._sim.t=0;
  window._sim.params=Object.assign({},window._sim.defaults||{});
  _simUpdateControls();
  if(window._sim._draw) window._sim._draw();
}
function _simLoop(){
  if(!window._sim.running) return;
  window._sim.t+=0.016;
  if(window._sim._draw) window._sim._draw();
  window._sim.raf=requestAnimationFrame(_simLoop);
}
function _simUpdateControls(){
  var cw=document.getElementById('simControls');
  if(!cw||!window._sim.controlsDef) return;
  // Ne pas reconstruire si l'utilisateur interagit (glisse un slider, tape du texte...)
  var _act=document.activeElement;
  if(_act&&cw.contains(_act)) return;
  var _newHtml=window._sim.controlsDef();
  if(window._sim._lastCtrlHtml===_newHtml) return;
  window._sim._lastCtrlHtml=_newHtml;
  cw.innerHTML=_newHtml;
}

/* _initLaboSim → chunks/labo.js (88 Ko, moteur de simulation).
   Il ne s'atteint que par lancerLabo(), qui charge déjà le module ; le sortir
   d'ici retire 88 Ko du démarrage sans ajouter la moindre attente. */

function _saveLaboNote(laboId){
  var hypo=document.getElementById("labHypo")?.value||"";
  var obs=document.getElementById("labObs")?.value||"";
  var conc=document.getElementById("labConc")?.value||"";
  if(!DB.laboNotes)DB.laboNotes={};
  DB.laboNotes[laboId]={hypo:hypo,obs:obs,conc:conc,date:new Date().toLocaleDateString("fr-FR")};
  save();toast("Notes sauvegardées !");
}


