function _saveRessourceMulti(){
  var titre=(_ge('riTitre')?.value||'').trim();
  var mat=(_ge('riMat')?.value||'').trim();
  if(!titre||!mat){toast('Titre et matière requis','warn');return;}
  var url=(_ge('riUrl')?.value||'').trim();
  var file=_ge('riFichier')?.files?.[0];
  var exam=_ge('riExam')?.value||'BAC';
  var serie=(_ge('riSerie')?.value||'').trim();
  var annee=parseInt(_ge('riAnnee')?.value)||new Date().getFullYear();
  var gratuit=_ge('riGratuit')?.checked||false;
  var cat=_ge('riCat')?.value||'cat1';
  var cls=_ge('riCls')?.value||'3ème';
  var plans=['plan1','plan2','plan3','plan4'].filter(function(p){return _ge('ri'+p.charAt(0).toUpperCase()+p.slice(1))?.checked;});
  if(!url&&!file){toast('Choisissez un fichier ou entrez une URL','warn');return;}

  function _detFmt(name){
    var ext=(name||'').split('.').pop().toLowerCase().split('?')[0];
    return ext==='pdf'?'pdf':(ext==='doc'||ext==='docx')?'word':ext==='html'||ext==='htm'?'html':'autre';
  }

  function _pushToElearning(fmt,fichierData,fichierNom,idbKey,extUrl){
    // Also add to DB.elearning.contenus so it appears in visitor catalog
    if(!DB.elearning)DB.elearning=defaultDB().elearning;
    if(!DB.elearning.contenus)DB.elearning.contenus=[];
    var existCheck=DB.elearning.contenus.find(function(c){return c._srcEp&&c._srcEp===('ep_'+Date.now());});
    DB.elearning.contenus.push({
      id:'elep_'+Date.now()+'_'+Math.random().toString(36).slice(2,5),
      cat:cat,titre:titre,classe:cls,matiere:mat,
      seq:exam+(serie?' '+serie:'')+(annee?' '+annee:''),
      prix:gratuit?0:500,gratuit:gratuit,plans:plans,
      apercu:exam+' '+mat+(serie?' — '+serie:'')+(annee?' '+annee:''),
      fichier:fichierNom||'',fichierData:fichierData||'',
      fileType:fmt,idbKey:idbKey||'',externalUrl:extUrl||'',
      desc:exam+(serie?' '+serie:'')+' — '+mat+(annee?' ('+annee+')':''),
      dateAjout:today(),_fromImport:true
    });
  }

  function _persist(fmt,idbKey,extUrl,fichierData,fichierNom){
    if(!DB.customEpreuves)DB.customEpreuves=[];
    var epId='ep_'+Date.now();
    DB.customEpreuves.push({
      id:epId,titre:titre,exam:exam,serie:serie,matiere:mat,
      annee:annee,duree:120,coef:1,extrait:'',gratuit:gratuit,
      type:'epreuve',format:fmt,idbKey:idbKey||'',
      externalUrl:extUrl||'',fichierData:fichierData||''
    });
    _pushToElearning(fmt,fichierData,fichierNom,idbKey,extUrl);
    save();cm();
    toast('&#9989; Ressource importée ('+fmt.toUpperCase()+') — visible dans le catalogue');
    setTimeout(mManageEpreuves,80);
  }

  if(url&&!file){_persist(_detFmt(url),'',url,'',url);return;}

  var fmt=_detFmt(file.name);
  var ikey='ep_res_'+Date.now();

  if(fmt==='html'){
    var r=new FileReader();
    r.onload=function(ev){
      if(!DB.customEpHtml)DB.customEpHtml={};
      DB.customEpHtml[ikey]=ev.target.result;
      _persist('html',ikey,'',ev.target.result,file.name);
    };
    r.readAsText(file,'utf-8');
  } else {
    var r2=new FileReader();
    r2.onload=function(ev){
      var dataUrl=ev.target.result;
      try{
        idbSave(ikey,dataUrl,file.name,file.type,function(ok){
          _persist(fmt,ikey,'','',file.name);
        });
      } catch(e2){
        if(!DB.customEpHtml)DB.customEpHtml={};
        DB.customEpHtml[ikey]=dataUrl;
        _persist(fmt,ikey,'',dataUrl,file.name);
      }
    };
    r2.readAsDataURL(file);
  }
}

function _openRessource(id){
  var allEp=[];
  if(typeof EPREUVES_DB!=="undefined")allEp=allEp.concat(EPREUVES_DB);
  allEp=allEp.concat((DB.elearningLibrary||[]).filter(function(e){return e.cat==="cat1"||e.cat==="cat4"||e.cat==="cat6";}));
  allEp=allEp.concat(DB.customEpreuves||[]);
  var ep=allEp.find(function(e){return e.id===id;});
  if(!ep){toast('Ressource introuvable','warn');return;}

  var fmt=ep.format||'html';

  // ─ URL externe ─
  if(ep.externalUrl){
    if(fmt==='pdf'){_showPDFViewer(ep.externalUrl,ep.titre,true);return;}
    if(fmt==='word'){toast('Ouverture du document Word…');window.open(ep.externalUrl,'_blank');return;}
    _openHtmlWithWatermark(null,ep.titre,ep.externalUrl);
    return;
  }

  var ikey=ep.idbKey||id;

  // ─ Fichier HTML en mémoire (DB.customEpHtml) ─
  if(fmt==='html'){
    var htmlSrc=DB.customEpHtml&&(DB.customEpHtml[ikey]||DB.customEpHtml[id]);
    if(htmlSrc){_openHtmlWithWatermark(htmlSrc,ep.titre,null);return;}
    // Legacy htmlLocal
    if(ep.htmlLocal){toast('Fichier HTML non trouvé (peut-être sur un autre appareil)','warn');}
    else toast('Aucun fichier HTML associé','warn');
    return;
  }

  // ─ PDF / Word en IndexedDB ─
  if(ep.idbKey){
    idbGetFile(ep.idbKey,function(rec){
      if(rec&&rec.data){
        if(fmt==='pdf'){_showPDFViewer(rec.data,ep.titre,true);return;}
        _downloadWordWithWatermark(rec.data,ep);
      } else {
        // Fallback: customEpHtml (base64 stocké en localStorage)
        var fb=DB.customEpHtml&&DB.customEpHtml[ep.idbKey];
        if(fb){
          if(fmt==='pdf'){_showPDFViewer(fb,ep.titre,true);return;}
          _downloadWordWithWatermark(fb,ep);
        } else {
          toast('Fichier non trouvé — il a peut-être été importé sur un autre appareil.','warn');
        }
      }
    });
    return;
  }

  toast('Aucun fichier associé à cette ressource','warn');
}

// ── Viewer PDF modal avec filigrane CSS en overlay ──
function _showPDFViewer(src,titre,canDownload){
  // Générer un blob URL depuis data: URL (Chrome bloque data: dans les iframes)
  var displaySrc=src;
  try{
    if(src&&src.startsWith('data:')){
      var _ba=src.split(','),_bm=(_ba[0].match(/:(.*?);/)||['','application/pdf'])[1];
      var _bs=atob(_ba[1]),_bn=_bs.length,_bu=new Uint8Array(_bn);
      while(_bn--)_bu[_bn]=_bs.charCodeAt(_bn);
      displaySrc=URL.createObjectURL(new Blob([_bu],{type:_bm}));
    }
  }catch(e){displaySrc=src;}
  // Mémoriser pour boutons onclick (blob URL ne peut pas être interpolé en attribut inline)
  window._pdfVwSrc=displaySrc;
  window._pdfVwTitre=titre;
  // Sur mobile : l'iframe PDF provoque une navigation (redirect). Afficher des boutons à la place.
  var _isMobPDF=/Mobi|Android|iPhone|iPad/i.test(navigator.userAgent||'');
  if(_isMobPDF){
    var _mBody='<div style="background:linear-gradient(135deg,#142554,#1e3a7a);padding:8px 14px;border-radius:8px 8px 0 0;margin-bottom:0">'
      +'<span style="color:#FFC93C;font-weight:800;font-size:13px">📄 '+_esc(titre)+'</span></div>'
      +'<div style="padding:32px 20px;text-align:center;background:var(--bg)">'
      +'<div style="font-size:64px;margin-bottom:16px">📄</div>'
      +'<div style="font-size:16px;font-weight:700;color:var(--bl);margin-bottom:20px">'+_esc(titre)+'</div>'
      +'<button class="btn bi" style="font-size:15px;padding:14px 28px;margin:6px;width:100%;max-width:280px;cursor:pointer;border:none" onclick="window.open(window._pdfVwSrc,\'_blank\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-bookopen"/></svg>Ouvrir le PDF</button><br>'
      +(canDownload?'<button class="btn bo" style="font-size:14px;padding:12px 24px;margin:6px;width:100%;max-width:280px;cursor:pointer;border:none" onclick="window.open(window._pdfVwSrc,\'_blank\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-download"/></svg>Télécharger</button><br>':'')
      +'<div style="font-size:11px;color:var(--ink4);margin-top:12px;font-style:italic">© VÉRITAS · Usage pédagogique uniquement</div>'
      +'</div>';
    M('','',_mBody,'<button class="btn bo" onclick="cm()">Fermer</button>',false);
    return;
  }
  var school=DB.school||{};
  var body=''
    +'<div style="background:linear-gradient(135deg,#142554,#1e3a7a);padding:8px 14px;display:flex;align-items:center;justify-content:space-between;border-radius:8px 8px 0 0">'
    +'<span style="color:#FFC93C;font-weight:800;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:70%">📄 '+_esc(titre)+'</span>'
    +'<span style="color:rgba(255,255,255,.6);font-size:9px;white-space:nowrap">© VÉRITAS · Usage pédagogique</span>'
    +'</div>'
    +'<div style="position:relative;height:65vh;background:#525659;overflow:hidden">'
    // Filigrane en grille (plus visible qu'un seul élément centré)
    +(function(){
      var rows='';
      for(var ri=0;ri<5;ri++){
        rows+='<div style="display:flex;gap:80px;margin-bottom:60px;transform:rotate(-35deg)">';
        for(var ci=0;ci<4;ci++){
          rows+='<span style="font-size:28px;font-weight:900;color:rgba(20,37,84,0.09);white-space:nowrap;letter-spacing:6px;user-select:none;font-family:Arial,sans-serif">VÉRITAS</span>';
        }
        rows+='</div>';
      }
      return '<div style="position:absolute;inset:0;pointer-events:none;z-index:5;overflow:hidden;display:flex;align-items:center;justify-content:center">'+
             '<div style="position:absolute;top:-40px;left:-60px;right:-60px;bottom:-40px;display:flex;flex-direction:column;gap:0">'+rows+'</div></div>';
    })()
    +'<iframe id="_pdfVwIfr" src="'+displaySrc+'" style="width:100%;height:100%;border:none;display:block" '
    +'title="'+_esc(titre)+'" allowfullscreen>'
    +'<p style="color:#fff;text-align:center;padding-top:40px">Votre navigateur ne supporte pas l\'affichage PDF intégré. '
    +'<a href="'+displaySrc+'" target="_blank" style="color:#FFC93C">Ouvrir le PDF →</a></p>'
    +'</iframe>'
    +'</div>'
    +'<div style="background:#142554;color:rgba(255,255,255,.55);text-align:center;padding:5px 8px;font-size:10px;border-radius:0 0 8px 8px;line-height:1.4">'
    +(school.nom||'VÉRITAS Academy')+' · veritas-school.com · Usage pédagogique uniquement'
    +'</div>';
  var footer='<button class="btn bo" onclick="cm()">Fermer</button>';
  if(canDownload){
    footer+='<button class="btn" style="background:#6C56A6;color:#fff" onclick="window.open(window._pdfVwSrc,\'_blank\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-download"/></svg>Ouvrir PDF</button>';
    footer+='<button class="btn" style="background:#AE5353;color:#fff" onclick="(function(){var a=document.createElement(\'a\');a.href=window._pdfVwSrc;a.download=(window._pdfVwTitre||\'document\').replace(/[^a-z0-9]/gi,\'_\')+\'.pdf\';a.click();})()"><svg class="vico bico" aria-hidden="true"><use href="#lc-download"/></svg>Télécharger PDF</button>';
  }
  M('','',body,footer,true);

  // ── v1.2 — Si l'URL est HTTP, basculer en stratégie fetch+blob pour contourner X-Frame-Options ──
  if(src && src.indexOf('http')===0){
    setTimeout(function(){
      var ifr = document.getElementById('_pdfVwIfr');
      if(!ifr) return;
      // Timeout : si rien ne se charge en 5s → bascule PDF.js
      var didLoad = false;
      ifr.addEventListener('load', function(){ didLoad = true; });
      var fbTimer = setTimeout(function(){
        if(!didLoad){
          console.warn('[_showPDFViewer] iframe direct timeout, bascule PDF.js');
          ifr.src = 'https://mozilla.github.io/pdf.js/web/viewer.html?file=' + encodeURIComponent(src);
        }
      }, 5000);
      // Stratégie principale : fetch → blob → iframe (contourne X-Frame-Options)
      fetch(src, {mode:'cors', credentials:'omit'})
        .then(function(r){ if(!r.ok) throw new Error('HTTP '+r.status); return r.blob(); })
        .then(function(blob){
          clearTimeout(fbTimer);
          var blobUrl = URL.createObjectURL(blob);
          window._pdfVwSrc = blobUrl;
          ifr.src = blobUrl;
          didLoad = true;
          setTimeout(function(){ try{URL.revokeObjectURL(blobUrl);}catch(e){} }, 10*60*1000);
        })
        .catch(function(err){
          console.warn('[_showPDFViewer] fetch échoué:',err.message,'→ Plan B PDF.js');
          clearTimeout(fbTimer);
          if(!didLoad){
            ifr.src = 'https://mozilla.github.io/pdf.js/web/viewer.html?file=' + encodeURIComponent(src);
          }
        });
    }, 200);
  }
}

// ── Ouvre HTML avec filigrane injecté (nouveau onglet) ──
function _openHtmlWithWatermark(htmlText,titre,externalUrl){
  var school=DB.school||{};
  var schoolNom=_esc(school.nom||'VÉRITAS Academy');
  // Tiled diagonal watermark via SVG data-URI (non-removable with DevTools CSS toggle)
  var wmSvg='<svg xmlns="http://www.w3.org/2000/svg" width="260" height="140">'
    +'<text x="10" y="55" font-family="Arial,sans-serif" font-size="22" font-weight="900" '
    +'fill="rgba(20,37,84,0.10)" transform="rotate(-30,130,70)" letter-spacing="4">VÉRITAS</text>'
    +'<text x="20" y="110" font-family="Arial,sans-serif" font-size="10" '
    +'fill="rgba(20,37,84,0.07)" transform="rotate(-30,130,70)">'+schoolNom+'</text>'
    +'</svg>';
  var wmUrl='data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(wmSvg)));
  var banner='<div id="_vWm" style="position:fixed;top:0;left:0;right:0;background:linear-gradient(135deg,#142554,#1e3a7a);color:#FFC93C;text-align:center;padding:7px 16px;font-size:12px;font-weight:700;z-index:2147483647;box-shadow:0 2px 8px rgba(0,0,0,.3);letter-spacing:.5px">&#127891; '+schoolNom+' · veritas-school.com · Usage pédagogique uniquement</div>'
    +'<div style="height:37px"></div>'
    +'<style>'
    +'body::after{'
    +'content:"";position:fixed;inset:0;'
    +'background-image:url("'+wmUrl+'");background-repeat:repeat;background-size:260px 140px;'
    +'pointer-events:none;z-index:2147483646;opacity:1;'
    +'}'
    +'</style>'
    +'<script>document.addEventListener("contextmenu",function(e){if(e.target.tagName!=="A")e.preventDefault();});<\/script>';

  if(externalUrl&&!htmlText){
    var wrapper='<!DOCTYPE html><html><head><meta charset="utf-8">'
      +'<style>*{margin:0;padding:0;box-sizing:border-box}body{overflow:hidden;background:#1a1a2e}</style></head><body>'
      +banner.replace('height:37px','height:40px')
      +'<iframe src="'+externalUrl+'" style="width:100%;height:calc(100vh - 40px);border:none;display:block" sandbox="allow-scripts allow-same-origin allow-forms allow-popups"></iframe></body></html>';
    var b=new Blob([wrapper],{type:'text/html'});
    window.open(URL.createObjectURL(b),'_blank');
    return;
  }

  var injected=htmlText||'';
  var bodyMatch=/<body([^>]*)>/i.exec(injected);
  if(bodyMatch) injected=injected.replace(bodyMatch[0],bodyMatch[0]+banner);
  else injected='<!DOCTYPE html><html><head><meta charset="utf-8"></head><body>'+banner+injected+'</body></html>';
  var b2=new Blob([injected],{type:'text/html'});
  window.open(URL.createObjectURL(b2),'_blank');
}

function _downloadPDFCover(encodedTitre){
  var titre=decodeURIComponent(encodedTitre||'');
  var jsPDFCls=(typeof jspdf!=='undefined'&&jspdf.jsPDF)?jspdf.jsPDF:(typeof jsPDF!=='undefined'?jsPDF:null);
  if(!jsPDFCls){toast('jsPDF non disponible','warn');return;}
  var doc=new jsPDFCls({orientation:'portrait',unit:'mm',format:'a4'});
  var pw=210,ph=297,school=DB.school||{};

  // Fond navy
  doc.setFillColor(20,37,84);doc.rect(0,0,pw,ph,'F');
  // Filigrane répété
  doc.setFont(undefined,'bold');doc.setFontSize(55);doc.setTextColor(255,255,255);
  var wAlpha=0.04;
  [40,100,160,220].forEach(function(y){
    doc.setFillColor(255,255,255); // placeholder — just text with light color
    doc.setTextColor(40,60,110);
    doc.text('VÉRITAS',pw/2,y,{align:'center',angle:30});
  });
  // En-tête
  doc.setTextColor(255,201,60);doc.setFontSize(26);doc.setFont(undefined,'bold');
  doc.text(school.nom||'VÉRITAS Academy',pw/2,55,{align:'center'});
  doc.setFontSize(11);doc.setTextColor(180,200,255);doc.setFont(undefined,'normal');
  doc.text(school.slogan||'Centre d\'Excellence Scolaire',pw/2,65,{align:'center'});
  doc.text('Yaoundé, Cameroun',pw/2,72,{align:'center'});
  // Séparateur
  doc.setDrawColor(255,201,60);doc.setLineWidth(0.8);doc.line(25,79,pw-25,79);
  // Titre ressource
  doc.setFontSize(18);doc.setTextColor(255,255,255);doc.setFont(undefined,'bold');
  var tl=doc.splitTextToSize(titre||'Ressource pédagogique',160);
  doc.text(tl,pw/2,96,{align:'center'});
  // Métadonnées
  doc.setFontSize(10);doc.setFont(undefined,'italic');doc.setTextColor(180,200,255);
  doc.text('Document protégé — Usage pédagogique uniquement',pw/2,125,{align:'center'});
  doc.text('© '+new Date().getFullYear()+' '+( school.nom||'VÉRITAS Academy')+' · veritas-school.com',pw/2,133,{align:'center'});
  doc.text('Tél : '+(school.tel||'656 720 476')+' · contact@veritas.cm',pw/2,141,{align:'center'});
  // Encadré or
  doc.setFillColor(255,201,60);doc.roundedRect(20,ph-75,pw-40,36,4,4,'F');
  doc.setTextColor(20,37,84);doc.setFontSize(10);doc.setFont(undefined,'bold');
  doc.text('📄 Page de garde officielle VÉRITAS',pw/2,ph-60,{align:'center'});
  doc.setFont(undefined,'normal');doc.setFontSize(9);
  doc.text('Ce document accompagne la ressource pédagogique.',pw/2,ph-52,{align:'center'});
  doc.text('Toute reproduction non autorisée est interdite.',pw/2,ph-45,{align:'center'});

  doc.save((titre||'ressource').replace(/[^a-z0-9]/gi,'_')+'_VERITAS.pdf');
  toast('📄 Page de garde PDF téléchargée');
}

