// ── Page visiteur : liste des extraits disponibles ──
function showExtraits(){
  var extraits=(DB.extraits||[]);
  var niveaux=['Tous','3ème','2nde','1ère','Terminale'];
  var fNiv=window._extFNiv||'Tous';
  var fMat=window._extFMat||'Tous';
  var matieres=['Tous'].concat([].concat.apply([],extraits.map(function(e){return e.matiere||'';}).filter(Boolean)).filter(function(v,i,a){return a.indexOf(v)===i;}));
  var list=extraits.filter(function(e){
    var okN=(fNiv==='Tous'||e.niveau===fNiv);
    var okM=(fMat==='Tous'||e.matiere===fMat);
    return okN&&okM;
  });
  var h="<div class='vsec'>";
  h+="<div class='vsec-title'><span class='vsec-ico'><svg class='vico vico-21' aria-hidden='true'><use href='#lc-bookopen'/></svg></span>Extraits de Livres</div>";
  h+="<div class='vsec-sub'>Découvrez des extraits d'œuvres sélectionnées — téléchargeables en PDF ou Word</div>";
  // Filtres niveau
  h+="<div style='display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px'>";
  niveaux.forEach(function(n){
    h+="<button style='padding:4px 12px;border-radius:16px;border:1.5px solid "+(fNiv===n?"#142554":"var(--bg3)")+";background:"+(fNiv===n?"#142554":"#fff")+";color:"+(fNiv===n?"#FFC93C":"var(--ink3)")+";font-size:11px;font-weight:700;cursor:pointer' onclick='window._extFNiv=\""+n+"\";showExtraits()'>"+n+"</button>";
  });
  h+="</div>";
  if(!list.length){
    h+="<div class='vcard' style='text-align:center;padding:48px 24px'>";
    if(!extraits.length){
      h+="<div style='font-size:48px;margin-bottom:12px'>📚</div><div style='font-size:16px;font-weight:700;color:#142554'>Aucun extrait disponible pour le moment</div>";
      h+="<div style='font-size:13px;color:var(--ink4);margin-top:8px'>Les extraits de livres seront ajoutés prochainement par vos professeurs.</div>";
    } else {
      h+="<div style='font-size:13px;color:var(--ink4)'>Aucun extrait pour ce filtre.</div>";
    }
    h+="</div>";
  } else {
    h+="<div style='display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px;margin-top:4px'>";
    list.forEach(function(e){
      var cov=e.couverture?("background-image:url('"+e.couverture+"');background-size:cover;background-position:center;"):"background:linear-gradient(135deg,#142554,#1e3a7a);";
      h+="<div style='background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 16px rgba(0,0,0,0.08);border:1px solid var(--bg3);cursor:pointer' onclick='_viewExtraitModal(\""+e.id+"\")'>";
      h+="<div style='height:100px;"+cov+"display:flex;align-items:center;justify-content:center;position:relative'>";
      if(!e.couverture)h+="<span style='font-size:38px'>📖</span>";
      h+="<span style='position:absolute;top:8px;right:8px;background:"+(e.gratuit?"#059669":"#6C56A6")+";color:#fff;font-size:9px;font-weight:800;padding:2px 7px;border-radius:8px'>"+(e.gratuit?"GRATUIT":"PREMIUM")+"</span>";
      h+="</div>";
      h+="<div style='padding:12px 14px'>";
      h+="<div style='font-weight:800;color:#142554;font-size:14px;margin-bottom:3px'>"+_esc(e.titre)+"</div>";
      h+="<div style='font-size:12px;color:var(--ink4);margin-bottom:6px'>"+_esc(e.auteur||'')+(e.pages?" · "+e.pages+" p.":"")+"</div>";
      if(e.resume)h+="<div style='font-size:11px;color:var(--ink3);line-height:1.5;margin-bottom:8px'>"+_esc(e.resume.slice(0,90))+(e.resume.length>90?"…":"")+"</div>";
      h+="<div style='display:flex;gap:6px;flex-wrap:wrap'>";
      if(e.niveau)h+="<span style='background:#EDE9FE;color:#6C56A6;font-size:9px;font-weight:800;padding:2px 7px;border-radius:8px'>"+_esc(e.niveau)+"</span>";
      if(e.matiere)h+="<span style='background:#E0F2FE;color:#0369A1;font-size:9px;font-weight:800;padding:2px 7px;border-radius:8px'>"+_esc(e.matiere)+"</span>";
      h+="</div></div></div>";
    });
    h+="</div>";
  }
  h+="</div>";
  _vc(h);
}

// ── Modale de lecture d'un extrait ──
function _viewExtraitModal(id){
  var e=(DB.extraits||[]).find(function(x){return x.id===id;});
  if(!e){toast('Extrait introuvable','err');return;}
  var locked=!e.gratuit&&!SES;
  var body="<div style='max-height:50vh;overflow-y:auto;padding:8px 0'>";
  body+="<div style='margin-bottom:12px;padding-bottom:12px;border-bottom:2px solid #FFC93C'>";
  body+="<div style='font-size:18px;font-weight:800;color:#142554'>"+_esc(e.titre)+"</div>";
  if(e.auteur)body+="<div style='font-size:13px;color:var(--ink4);margin-top:3px'>"+_esc(e.auteur)+(e.niveau?" · "+_esc(e.niveau):"")+(e.pages?" · "+_esc(e.pages)+" pages":"")+"</div>";
  if(e.resume)body+="<div style='font-size:12px;font-style:italic;color:var(--ink3);margin-top:8px;padding:8px 12px;background:#F8FAFF;border-radius:6px'>"+_esc(e.resume)+"</div>";
  body+="</div>";
  if(locked){
    body+="<div style='text-align:center;padding:24px'>";
    body+="<div style='font-size:36px;margin-bottom:8px'>🔒</div>";
    body+="<div style='font-weight:700;color:#142554;margin-bottom:4px'>Contenu réservé aux abonnés</div>";
    body+="<div style='font-size:12px;color:var(--ink4)'>Connectez-vous ou abonnez-vous pour lire l'extrait complet.</div></div>";
  } else {
    var texte=e.texte||'';
    body+="<div style='font-size:14px;line-height:1.9;color:#1e293b;font-family:Georgia,serif;white-space:pre-wrap;background:#FFFDF5;padding:14px;border-radius:8px;border:1px solid #e2e8f0'>"+_esc(texte)+"</div>";
  }
  body+="</div>";
  var footer="<button class='btn bo' onclick='cm()'>Fermer</button>";
  if(!locked){
    footer+="<button class='btn' style='background:#AE5353;color:#fff' onclick='cm();_downloadExtraitPDF(\""+id+"\")'><svg class='vico bico' aria-hidden='true'><use href='#lc-doc'/></svg>PDF</button>";
    footer+="<button class='btn' style='background:#2563EB;color:#fff' onclick='cm();_downloadExtraitWord(\""+id+"\")'><svg class='vico bico' aria-hidden='true'><use href='#lc-pencil'/></svg>Word</button>";
  } else {
    footer+="<button class='btn bi' onclick='cm();vShowSec(\"elearning\",null)'><svg class='vico bico' aria-hidden='true'><use href='#lc-star'/></svg>S'abonner</button>";
  }
  M("📖 Extrait — "+_esc(e.titre),"",body,footer,true);
}

// ── Télécharger PDF avec filigrane ──
function _downloadExtraitPDF(id){
  var e=(DB.extraits||[]).find(function(x){return x.id===id;});
  if(!e||!e.texte){toast('Extrait non disponible','warn');return;}
  if(typeof jspdf==='undefined'&&typeof jsPDF==='undefined'){toast('Module PDF non chargé','warn');return;}
  var jsPDFCls=(typeof jspdf!=='undefined')?jspdf.jsPDF:jsPDF;
  var doc=new jsPDFCls({orientation:'portrait',unit:'mm',format:'a4'});
  var pageW=210,pageH=297,margin=15,contentW=pageW-margin*2;
  var school=DB.school||{};
  var contacts="veritas-school.com · "+(school.tel||'656 720 476')+" · contact@veritas.cm";

  // ── En-tête colorée ──
  doc.setFillColor(20,37,84);
  doc.rect(0,0,pageW,28,'F');
  doc.setTextColor(255,201,60);
  doc.setFontSize(16);doc.setFont(undefined,'bold');
  doc.text(school.nom||'VÉRITAS Academy',pageW/2,11,{align:'center'});
  doc.setFontSize(9);doc.setFont(undefined,'normal');
  doc.setTextColor(200,215,255);
  doc.text(school.slogan||'Centre d\'Excellence Scolaire',pageW/2,18,{align:'center'});
  doc.text('Yaoundé, Cameroun',pageW/2,24,{align:'center'});

  // ── Filigrane diagonal (dessiné tôt, avant le contenu) ──
  doc.setFontSize(55);
  doc.setTextColor(230,230,230);
  doc.setFont(undefined,'bold');
  doc.text('VÉRITAS',pageW/2,pageH/2,{align:'center',angle:45});
  doc.text('VÉRITAS',pageW/2,pageH/2+60,{align:'center',angle:45});

  // ── Titre de l'œuvre ──
  doc.setFont(undefined,'bold');
  doc.setFontSize(17);
  doc.setTextColor(20,37,84);
  doc.text(_esc(e.titre),pageW/2,40,{align:'center'});
  doc.setFont(undefined,'italic');
  doc.setFontSize(11);
  doc.setTextColor(100,100,100);
  var meta='';
  if(e.auteur)meta+=e.auteur;
  if(e.niveau)meta+=(meta?' · ':'')+e.niveau;
  if(e.pages)meta+=(meta?' · ':'')+e.pages+' pages';
  if(meta)doc.text(meta,pageW/2,48,{align:'center'});

  // ── Ligne séparatrice ──
  doc.setDrawColor(255,201,60);doc.setLineWidth(0.7);
  doc.line(margin,53,pageW-margin,53);

  // ── Résumé ──
  var yPos=60;
  if(e.resume){
    doc.setFont(undefined,'italic');doc.setFontSize(10);doc.setTextColor(80,80,80);
    var resumLines=doc.splitTextToSize(e.resume,contentW);
    doc.text(resumLines,margin,yPos);
    yPos+=resumLines.length*5+6;
    doc.setDrawColor(200,200,200);doc.line(margin,yPos-2,pageW-margin,yPos-2);
  }

  // ── Texte de l'extrait ──
  doc.setFont(undefined,'normal');doc.setFontSize(11);doc.setTextColor(30,30,30);
  var lines=doc.splitTextToSize(e.texte,contentW);
  var lineH=5.5;
  var footerY=pageH-14;
  lines.forEach(function(line){
    if(yPos+lineH>footerY){
      _addExtraitPDFFooter(doc,pageW,pageH,contacts);
      doc.addPage();
      // filigrane sur nouvelle page
      doc.setFontSize(55);doc.setTextColor(230,230,230);doc.setFont(undefined,'bold');
      doc.text('VÉRITAS',pageW/2,pageH/2,{align:'center',angle:45});
      doc.setFont(undefined,'normal');doc.setFontSize(11);doc.setTextColor(30,30,30);
      yPos=20;
    }
    doc.text(line,margin,yPos);
    yPos+=lineH;
  });
  _addExtraitPDFFooter(doc,pageW,pageH,contacts);

  doc.save((e.titre||'extrait').replace(/[^a-z0-9]/gi,'_')+'_VERITAS.pdf');
  toast('📄 PDF téléchargé avec filigrane');
}

function _addExtraitPDFFooter(doc,pageW,pageH,contacts){
  doc.setDrawColor(20,37,84);doc.setLineWidth(0.4);
  doc.line(15,pageH-12,pageW-15,pageH-12);
  doc.setFontSize(8);doc.setFont(undefined,'normal');doc.setTextColor(120,120,120);
  doc.text('© VÉRITAS Academy · '+contacts,pageW/2,pageH-6,{align:'center'});
  doc.text('Document protégé — Usage pédagogique uniquement',pageW/2,pageH-2,{align:'center'});
}

// ── Télécharger Word (.doc HTML) avec filigrane ──
function _downloadExtraitWord(id){
  var e=(DB.extraits||[]).find(function(x){return x.id===id;});
  if(!e||!e.texte){toast('Extrait non disponible','warn');return;}
  var school=DB.school||{};
  var contacts="veritas-school.com · "+(school.tel||'656 720 476')+" · contact@veritas.cm";
  var htmlDoc="<html xmlns:o='urn:schemas-microsoft-com:office:office'"
    +" xmlns:w='urn:schemas-microsoft-com:office:word'"
    +" xmlns='http://www.w3.org/TR/REC-html40'>"
    +"<head><meta charset='utf-8'><title>"+_esc(e.titre)+"</title>"
    +"<style>"
    +"body{font-family:'Times New Roman',serif;font-size:12pt;margin:2.5cm;color:#1e293b}"
    +".header{background:#142554;color:#FFC93C;text-align:center;padding:14px;margin-bottom:20px}"
    +".header h1{color:#FFC93C;font-size:18pt;margin:0 0 4px}"
    +".header p{color:rgba(255,255,255,0.8);font-size:10pt;margin:0}"
    +".titre-oeuvre{text-align:center;color:#142554;font-size:18pt;font-weight:bold;margin:16px 0 4px}"
    +".meta{text-align:center;color:#666;font-size:10pt;font-style:italic;margin-bottom:16px}"
    +".resume{background:#F8FAFF;padding:10px 14px;font-style:italic;font-size:10pt;color:#444;margin-bottom:18px}"
    +".content{line-height:1.9;font-size:12pt;text-align:justify;white-space:pre-wrap}"
    +".filigrane{position:fixed;top:45%;left:10%;width:80%;text-align:center;font-size:80pt;"
    +"color:rgba(200,200,200,0.18);font-weight:bold;transform:rotate(-40deg);z-index:-1;pointer-events:none}"
    +".footer{border-top:1px solid #ddd;padding-top:10px;margin-top:40px;text-align:center;font-size:8pt;color:#999}"
    +"</style></head><body>"
    +"<div class='filigrane'>VÉRITAS</div>"
    +"<div class='header'><h1>"+(school.nom||'VÉRITAS Academy')+"</h1>"
    +"<p>"+(school.slogan||'Centre d\'Excellence Scolaire')+" · Yaoundé, Cameroun</p></div>"
    +"<div class='titre-oeuvre'>"+_esc(e.titre)+"</div>"
    +"<div class='meta'>"+(e.auteur?_esc(e.auteur):"")+(e.niveau?" · "+_esc(e.niveau):"")+(e.pages?" · "+_esc(e.pages)+" pages":"")+"</div>"
    +(e.resume?"<div class='resume'>"+_esc(e.resume)+"</div>":"")
    +"<hr style='border:none;border-top:2px solid #FFC93C;margin-bottom:18px'>"
    +"<div class='content'>"+_esc(e.texte)+"</div>"
    +"<div class='footer'>© VÉRITAS Academy · "+contacts+"<br>Document protégé — Usage pédagogique uniquement</div>"
    +"</body></html>";
  var blob=new Blob([htmlDoc],{type:'application/msword'});
  var url=URL.createObjectURL(blob);
  var a=document.createElement('a');
  a.href=url;
  a.download=(e.titre||'extrait').replace(/[^a-z0-9]/gi,'_')+'_VERITAS.doc';
  document.body.appendChild(a);a.click();document.body.removeChild(a);
  URL.revokeObjectURL(url);
  toast('📝 Word téléchargé avec filigrane');
}

