function _impEvFmtChange(fmt){
  // Afficher zone texte pour GIFT/TXT, fichier pour tous
  var showText=fmt==='gift'||fmt==='txt';
  var fw=document.getElementById('impEvFileWrap');
  var tw=document.getElementById('impEvTextWrap');
  if(fw) fw.style.display='block'; // toujours visible
  if(tw) tw.style.display=showText?'block':'none';
}

// ── Parseurs ────────────────────────────────────────────────────────────────

function _parseEvalJSON(text){
  var data=JSON.parse(text);
  // Format array d'évaluations ou objet unique
  var evals=Array.isArray(data)?data:[data];
  var questions=[];
  evals.forEach(function(ev){
    if(ev.questions) questions=questions.concat(ev.questions);
  });
  // Normalisation : {q, opts:[A,B,C,D], ans:index}
  questions=questions.map(function(q){
    if(q.opts&&typeof q.ans==='number') return q; // déjà normalisé
    // Moodle JSON : {question_text, answers:[{answer_text, fraction}]}
    if(q.question_text){
      var opts=(q.answers||[]).map(function(a){return (a.answer_text||'').replace(/<[^>]+>/g,'').trim();});
      var ans=0;
      (q.answers||[]).forEach(function(a,i){if(parseFloat(a.fraction||0)>0) ans=i;});
      return {q:q.question_text.replace(/<[^>]+>/g,'').trim(),opts:opts,ans:ans};
    }
    return null;
  }).filter(Boolean);
  return questions;
}

function _parseEvalCSV(text){
  // Format attendu : Question,OptionA,OptionB,OptionC,OptionD,BonneReponse
  // BonneReponse = A/B/C/D ou 0/1/2/3 ou texte exact de la bonne option
  var lines=text.split('\n').map(function(l){return l.trim();}).filter(Boolean);
  var questions=[];
  // Ignorer en-tête si la 1ère colonne ressemble à un header
  var startLine=0;
  if(lines[0]&&/question|q|enonce/i.test(lines[0].split(/[,;]/)[0])) startLine=1;
  for(var i=startLine;i<lines.length;i++){
    // Support virgule et point-virgule comme séparateur
    var sep=lines[i].indexOf(';')>=0?';':',';
    var cols=lines[i].split(sep).map(function(c){return c.replace(/^["']|["']$/g,'').trim();});
    if(cols.length<5) continue;
    var q=cols[0];
    var opts=cols.slice(1,5);
    var rep=cols[5]||cols[4]||'A';
    var ans=0;
    if(/^[0-3]$/.test(rep)) ans=parseInt(rep);
    else if(/^[A-Da-d]$/.test(rep)) ans=rep.toLowerCase().charCodeAt(0)-97;
    else { // cherche la correspondance de texte
      var idx=opts.findIndex(function(o){return o.toLowerCase()===rep.toLowerCase();});
      if(idx>=0) ans=idx;
    }
    if(q&&opts[0]) questions.push({q:q,opts:opts,ans:ans});
  }
  return questions;
}

function _parseEvalGIFT(text){
  // Format GIFT Moodle : ::Title:: Question { =Bonne ~Mauvaise ~Mauvaise }
  var questions=[];
  var blocks=text.split(/\n\s*\n+/).filter(function(b){return b.trim();});
  blocks.forEach(function(block){
    block=block.replace(/\/\/[^\n]*/g,'').trim();
    if(!block||block.startsWith('$')) return;
    var qText='', opts=[], ans=0;
    var titleMatch=block.match(/^::([^:]+)::/);
    if(titleMatch) block=block.replace(titleMatch[0],'').trim();
    var braceIdx=block.indexOf('{');
    if(braceIdx<0) return;
    qText=block.slice(0,braceIdx).trim();
    var inner=block.slice(braceIdx+1,block.lastIndexOf('}')).trim();
    var optMatches=inner.match(/[=~][^=~#{}]+/g)||[];
    optMatches.forEach(function(o,i){
      var isCorrect=o.charAt(0)==='=';
      var txt=o.slice(1).replace(/#[^#]*#/,'').trim();
      if(txt){
        if(isCorrect) ans=opts.length;
        opts.push(txt);
      }
    });
    if(qText&&opts.length>=2) questions.push({q:qText,opts:opts.slice(0,4),ans:Math.min(ans,3)});
  });
  return questions;
}

function _parseEvalHtml(html){
  // 1. Essayer de détecter un tableau ou une liste structurée dans le HTML
  //    en utilisant un DOMParser (disponible dans le navigateur) ;
  //    côté Node/test on tombe dans le fallback texte.
  try{
    var doc=(typeof DOMParser!=='undefined')
      ?new DOMParser().parseFromString(html,'text/html')
      :null;

    if(doc){
      var questions=[];

      // Cas 1 : liste ordonnée <ol> avec <li> = questions,
      //          et sous-listes <ul>/<ol> avec les options
      var ols=doc.querySelectorAll('ol');
      ols.forEach(function(ol){
        ol.querySelectorAll('li').forEach(function(li){
          var qText='';
          var opts=[];
          var ans=0;
          // Texte direct du <li> (avant la sous-liste)
          li.childNodes.forEach(function(n){
            if(n.nodeType===3) qText+=n.textContent;
            if(n.nodeName==='P'||n.nodeName==='SPAN'||n.nodeName==='B'||n.nodeName==='STRONG') qText+=n.textContent;
          });
          qText=qText.trim();
          // Sous-liste = options
          var subList=li.querySelector('ul,ol');
          if(subList){
            subList.querySelectorAll('li').forEach(function(opt,i){
              var t=opt.textContent.trim();
              // Marque de bonne réponse : [x] ou (x) ou * en début
              if(/^[\[\(\*]/.test(t)||/correct|bonne|answer/i.test(opt.className||'')){ans=i;}
              t=t.replace(/^[\[\(\*xX\]\)\s]+/,'').trim();
              opts.push(t);
            });
          }
          if(qText&&opts.length>=2) questions.push({q:qText,opts:opts.slice(0,4),ans:Math.min(ans,3)});
        });
      });
      if(questions.length) return questions;

      // Cas 2 : paragraphes ou divs avec class quiz/question
      var qEls=doc.querySelectorAll('.question,.quiz-question,[data-question]');
      if(qEls.length){
        qEls.forEach(function(el){
          var qText=(el.querySelector('.question-text,.stem,p')||el).textContent.trim();
          var opts=[];
          var ans=0;
          el.querySelectorAll('.answer,.choice,.option,li').forEach(function(opt,i){
            if(/correct|right|bonne/i.test(opt.className)) ans=i;
            opts.push(opt.textContent.replace(/^[a-dA-D][.\)\-\s]/,'').trim());
          });
          if(qText&&opts.length>=2) questions.push({q:qText,opts:opts.slice(0,4),ans:Math.min(ans,3)});
        });
        if(questions.length) return questions;
      }

      // Cas 3 : fallback — extraire le texte brut du body et passer au parseur TXT
      var bodyText=(doc.body||doc.documentElement).textContent||'';
      return _parseEvalTxt(bodyText);
    }
  }catch(e){ /* ignore, fallback below */ }

  // Fallback : strip les balises manuellement et passer au parseur TXT
  var plain=html
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi,'')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi,'')
    .replace(/<br\s*\/?>/gi,'\n')
    .replace(/<\/p>/gi,'\n')
    .replace(/<\/li>/gi,'\n')
    .replace(/<\/div>/gi,'\n')
    .replace(/<[^>]+>/g,'')
    .replace(/&nbsp;/g,' ')
    .replace(/&amp;/g,'&')
    .replace(/&lt;/g,'<')
    .replace(/&gt;/g,'>')
    .replace(/&quot;/g,'"');
  return _parseEvalTxt(plain);
}

function _parseEvalTxt(text){
  var questions=[];
  var blocks=text.split(/\n(?=\d+[.\)]\s)/).filter(function(b){return b.trim();});
  blocks.forEach(function(block){
    var lines=block.split('\n').map(function(l){return l.trim();}).filter(Boolean);
    if(!lines.length) return;
    var qLine=lines[0].replace(/^\d+[.\)]\s*/,'').trim();
    var opts=[], ans=0;
    var repLine='';
    lines.slice(1).forEach(function(l){
      var optM=l.match(/^([a-dA-D])[.\)\-\s]\s*(.+)/);
      var repM=l.match(/^(?:r[e\u00e9]ponse|bonne\s+r[e\u00e9]ponse)\s*:?\s*([a-dA-D0-3])/i);
      if(optM) opts.push(optM[2].trim());
      else if(repM) repLine=repM[1];
    });
    if(repLine){
      if(/^[0-3]$/.test(repLine)) ans=parseInt(repLine);
      else ans=repLine.toLowerCase().charCodeAt(0)-97;
    }
    if(qLine&&opts.length>=2) questions.push({q:qLine,opts:opts.slice(0,4),ans:Math.max(0,Math.min(ans,opts.length-1))});
  });
  return questions;
}

function _doImportEval(){
  var fmt=document.getElementById('impEvFmt')?.value||'json';
  var titre=(document.getElementById('impEvTitre')?.value||'').trim()||'Évaluation importée';
  var mat=document.getElementById('impEvMat')?.value||'';
  var cls=(document.getElementById('impEvCls')?.value||'').trim();
  var duree=parseInt(document.getElementById('impEvDuree')?.value)||30;

  function _finalize(questions){
    if(!questions||!questions.length){toast('Aucune question trouvée dans le fichier','warn');return;}
    _initEvals();
    var ev={id:'eval_'+Date.now(),titre:titre,matiere:mat,classe:cls,
      duree:duree,questions:questions,reponses:[],actif:true,
      date:new Date().toLocaleDateString('fr-FR')};
    DB.evaluations.push(ev);
    save();cm();
    toast('&#9989; '+questions.length+' question(s) import&eacute;e(s) — '+titre);
    setTimeout(mManageEvaluations,80);
  }

  function _parse(text){
    try{
      var q=[];
      if(fmt==='json') q=_parseEvalJSON(text);
      else if(fmt==='csv') q=_parseEvalCSV(text);
      else if(fmt==='gift') q=_parseEvalGIFT(text);
      else if(fmt==='html') q=_parseEvalHtml(text);
      else q=_parseEvalTxt(text);
      // Aperçu dans le modal
      var prev=document.getElementById('impEvPreview');
      if(prev){
        prev.style.display='block';
        prev.innerHTML='<strong>&#128202; '+q.length+' question(s) d&eacute;tect&eacute;e(s)</strong>'
          +(q.length?'<ul style="margin:6px 0 0 14px;max-height:100px;overflow-y:auto">'
            +q.slice(0,5).map(function(x,i){return '<li>Q'+(i+1)+': '+_esc(x.q).slice(0,60)+(x.q.length>60?'…':'')+'</li>';}).join('')
            +(q.length>5?'<li style="color:#6B7A99">… et '+(q.length-5)+' autre(s)</li>':'')+'</ul>':'');
      }
      _finalize(q);
    }catch(err){toast('Erreur de lecture : '+err.message,'warn');}
  }

  // Lire depuis le textarea collé ou depuis le fichier
  var textArea=document.getElementById('impEvText');
  var pastedText=(textArea?.value||'').trim();
  if(pastedText){_parse(pastedText);return;}

  var fileEl=document.getElementById('impEvFile');
  if(!fileEl||!fileEl.files[0]){toast('Choisissez un fichier ou collez le texte','warn');return;}
  var reader=new FileReader();
  reader.onload=function(ev){_parse(ev.target.result);};
  reader.readAsText(fileEl.files[0],'utf-8');
}

// ── Export évaluations ───────────────────────────────────────────────────────

function _exportEvalJSON(idx){
  _initEvals();
  var ev=DB.evaluations[idx];
  if(!ev) return;
  var blob=new Blob([JSON.stringify(ev,null,2)],{type:'application/json'});
  var a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download=ev.titre.replace(/[^a-z0-9]/gi,'_').toLowerCase()+'_VERITAS.json';
  document.body.appendChild(a);a.click();document.body.removeChild(a);
  toast('&#8659; Export JSON : '+ev.titre);
}

function _exportEvalCSV(idx){
  _initEvals();
  var ev=DB.evaluations[idx];
  if(!ev) return;
  var rows=['Question,Option A,Option B,Option C,Option D,Bonne réponse'];
  (ev.questions||[]).forEach(function(q){
    var opts=q.opts||[];
    var ans=(q.ans||0);
    var ansLetter=String.fromCharCode(65+ans); // A/B/C/D
    rows.push([q.q,opts[0]||'',opts[1]||'',opts[2]||'',opts[3]||'',ansLetter]
      .map(function(c){return '"'+String(c).replace(/"/g,'""')+'"';}).join(','));
  });
  var blob=new Blob([rows.join('\n')],{type:'text/csv;charset=utf-8'});
  var a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download=ev.titre.replace(/[^a-z0-9]/gi,'_').toLowerCase()+'_VERITAS.csv';
  document.body.appendChild(a);a.click();document.body.removeChild(a);
  toast('&#8659; Export CSV : '+ev.questions.length+' questions');
}

function _newEval(){window._editEvalIdx=-1;_evalFormUI(null);}
function _editEval(i){window._editEvalIdx=i;_evalFormUI(DB.evaluations[i]);}
function _evalFormUI(ev){
  var mats=["Mathématiques","Français","Anglais","Physique-Chimie","SVT","Histoire-Géo","Philosophie","Informatique"];
  var existing_q=ev?(ev.questions||[]).map(function(q,qi){
    return "<div style='background:#F8FAFF;border-radius:8px;padding:10px;margin-bottom:8px;'>"
      +"<div style='font-size:12px;font-weight:700;margin-bottom:4px'>Q"+(qi+1)+": "+q.q+"</div>"
      +"<div style='font-size:11px;color:#6B7A99'>"+(_evalIsOpen(q)?("✍️ Réponse libre · barème "+(q.bareme||q.points||"?")+" pts"):("Options: "+(q.opts||[]).join(" / ")+" | Bonne: "+((q.opts||[])[q.ans]||"?")))+"</div>"
      +"<button class='btn br2 xs' onclick='_delEvalQ("+qi+")' style='margin-top:4px'><svg class='vico bico' aria-hidden='true'><use href='#lc-trash'/></svg>Supprimer</button>"
      +"</div>";
  }).join(""):"";
  window._evalFormQuestions=ev?(ev.questions||[]).slice():[];
  M(ev?"✏️ Modifier l'évaluation":"➕ Nouvelle évaluation","",
    "<div class='fg2 mb14'>"
    +"<div class='fg'><span class='fl'>Titre *</span><input class='fi' id='evTitre' value='"+(ev?ev.titre:"")+"' placeholder='Évaluation Maths — 3ème'></div>"
    +"<div class='fg'><span class='fl'>Matière</span><select class='fi' id='evMat'>"
    +mats.map(function(m){return "<option value='"+m+"'"+(ev&&ev.matiere===m?" selected":"")+">"+m+"</option>";}).join("")
    +"</select></div>"
    +"<div class='fg'><span class='fl'>Classe</span><input class='fi' id='evCls' value='"+(ev?ev.classe||"":"")+"' placeholder='3ème, 1ère C...'></div>"
    +"<div class='fg'><span class='fl'>Durée (min)</span><input class='fi' id='evDuree' type='number' value='"+(ev?ev.duree||30:30)+"'></div>"
    +"</div>"
    +"<div id='evQList' style='max-height:180px;overflow-y:auto;margin-bottom:10px'>"+existing_q+"</div>"
    +"<div style='border-top:var(--br);padding-top:12px'>"
    +"<div class='fl mb8' style='font-weight:700;font-size:13px'>➕ Ajouter une question</div>"
    +"<div class='fg mb8'><span class='fl'>Question *</span><input class='fi' id='evQ' placeholder='Quelle est la formule de l'eau ?'></div>"
    +"<div class='fg mb8'><span class='fl'>Type de question</span><select class='fi' id='evType' onchange='_evalTypeToggle()'><option value='qcm'>QCM (choix multiple)</option><option value='ouverte'>Réponse libre — notée par l'IA</option></select></div>"
    +"<div id='openFields' style='display:none'>"
    +"<div class='fg2 mb8'><div class='fg'><span class='fl'>Barème (points)</span><input class='fi' id='evBareme' type='number' value='4' min='1'></div></div>"
    +"<div class='fg full mb8'><span class='fl'>Éléments de réponse attendus (corrigé pour l'IA)</span><textarea class='fi' id='evAttendu' rows='3' placeholder='Liste les points clés attendus : Ambassa s'en sert pour noter équitablement.'></textarea></div>"
    +"</div>"
    +"<div id='qcmFields'>"
    +"<div class='fg2 mb8'>"
    +"<div class='fg'><span class='fl'>Option A</span><input class='fi' id='evA0' placeholder='H2O'></div>"
    +"<div class='fg'><span class='fl'>Option B</span><input class='fi' id='evA1' placeholder='CO2'></div>"
    +"<div class='fg'><span class='fl'>Option C</span><input class='fi' id='evA2' placeholder='O3'></div>"
    +"<div class='fg'><span class='fl'>Option D</span><input class='fi' id='evA3' placeholder='H2SO4'></div>"
    +"</div>"
    +"<div class='fg mb8'><span class='fl'>Bonne réponse</span><select class='fi' id='evAns'>"
    +"<option value='0'>A</option><option value='1'>B</option><option value='2'>C</option><option value='3'>D</option>"
    +"</select></div>"
    +"<div class='fg full mb8'><span class='fl'>Explication (optionnel)</span><input class='fi' id='evExp' placeholder='Explication de la bonne réponse'></div>"
    +"</div>"
    +"<button class='btn' style='background:#E8EEFF;color:#142554;border-radius:10px;padding:8px 16px;font-size:12px;font-weight:700;border:none;cursor:pointer' onclick='_addEvalQ()'><svg class='vico bico' aria-hidden='true'><use href='#lc-plus'/></svg>Ajouter cette question</button>"
    +"</div>",
    "<button class='btn bo' onclick='cm()'>Annuler</button>"
    +"<button class='btn bi' onclick='_saveEval()'>"+(ev?"Modifier":"Créer l'évaluation")+"</button>",true);
}
function _addEvalQ(){
  var q=document.getElementById("evQ")?.value.trim()||"";
  var _qtype=document.getElementById("evType")?.value||"qcm";
  if(_qtype==='ouverte'){
    if(!q){toast("Question requise","warn");return;}
    var _bar=parseInt(document.getElementById("evBareme")?.value)||4;
    var _att=document.getElementById("evAttendu")?.value||"";
    window._evalFormQuestions.push({q:q,type:'ouverte',bareme:_bar,attendu:_att});
    var _qlo=document.getElementById("evQList");
    if(_qlo){
      var _qio=window._evalFormQuestions.length-1;
      var _dvo=document.createElement("div");
      _dvo.style.cssText="background:#F8FAFF;border-radius:8px;padding:10px;margin-bottom:8px;";
      _dvo.innerHTML="<div style='font-size:12px;font-weight:700;margin-bottom:4px'>Q"+(_qio+1)+": "+q+"</div><div style='font-size:11px;color:#6B7A99'>✍️ Réponse libre · barème "+_bar+" pts</div>";
      _qlo.appendChild(_dvo); _qlo.scrollTop=_qlo.scrollHeight;
    }
    var _eqo=document.getElementById("evQ"); if(_eqo)_eqo.value="";
    var _ato=document.getElementById("evAttendu"); if(_ato)_ato.value="";
    toast("Question "+(window._evalFormQuestions.length)+" ajoutée");
    return;
  }
  var a0=document.getElementById("evA0")?.value.trim()||"";
  var a1=document.getElementById("evA1")?.value.trim()||"";
  var a2=document.getElementById("evA2")?.value.trim()||"";
  var a3=document.getElementById("evA3")?.value.trim()||"";
  if(!q||!a0||!a1){toast("Question et options A/B requis","warn");return;}
  var ans=parseInt(document.getElementById("evAns")?.value||"0");
  var exp=document.getElementById("evExp")?.value||"";
  var opts=[a0,a1,a2||"",a3||""].filter(Boolean);
  window._evalFormQuestions.push({q:q,opts:opts,ans:Math.min(ans,opts.length-1),exp:exp});
  var qList=document.getElementById("evQList");
  if(qList){
    var qi=window._evalFormQuestions.length-1;
    var div=document.createElement("div");
    div.style.cssText="background:#F8FAFF;border-radius:8px;padding:10px;margin-bottom:8px;";
    div.innerHTML="<div style='font-size:12px;font-weight:700;margin-bottom:4px'>Q"+(qi+1)+": "+q+"</div>"
      +"<div style='font-size:11px;color:#6B7A99'>"+opts.join(" / ")+" | ✓ "+opts[Math.min(ans,opts.length-1)]+"</div>";
    qList.appendChild(div);
    qList.scrollTop=qList.scrollHeight;
  }
  ["evQ","evA0","evA1","evA2","evA3","evExp"].forEach(function(id){var el=document.getElementById(id);if(el)el.value="";});
  toast("Question "+(window._evalFormQuestions.length)+" ajoutée");
}
function _delEvalQ(qi){
  window._evalFormQuestions.splice(qi,1);
  toast("Question supprimée");
  // Refresh
  var ev=window._editEvalIdx>=0?DB.evaluations[window._editEvalIdx]:null;
  if(ev)ev.questions=window._evalFormQuestions.slice();
  _evalFormUI(ev);
}
function _saveEval(){
  var titre=document.getElementById("evTitre")?.value.trim()||"";
  if(!titre){toast("Titre requis","warn");return;}
  if(!window._evalFormQuestions||!window._evalFormQuestions.length){toast("Ajoutez au moins une question","warn");return;}
  _initEvals();
  var ev={
    id:"eval_"+Date.now(),titre:titre,
    matiere:document.getElementById("evMat")?.value||"",
    classe:document.getElementById("evCls")?.value||"",
    duree:parseInt(document.getElementById("evDuree")?.value)||30,
    questions:window._evalFormQuestions.slice(),
    reponses:[],actif:true,
    date:new Date().toLocaleDateString("fr-FR")
  };
  if(window._editEvalIdx>=0) DB.evaluations[window._editEvalIdx]=ev;
  else DB.evaluations.push(ev);
  save();cm();
  toast(window._editEvalIdx>=0?"✅ Évaluation modifiée":"✅ Évaluation créée ("+ev.questions.length+" questions)");
  setTimeout(mManageEvaluations,80);
}

// ── ÉVALUATION CÔTÉ ÉLÈVE (passer une évaluation) ─────────────────
function showMesEvaluations(){
  _initEvals();
  var actives=DB.evaluations.filter(function(ev){return ev.actif;});
  var h="<div class='vsec'>";
  h+="<div class='vsec-title'><span class='vsec-ico'><svg class='vico vico-21' aria-hidden='true'><use href='#lc-chart'/></svg></span>Évaluations en ligne</div>";
  h+="<div class='vsec-sub'>Passez des évaluations créées par votre établissement — résultats instantanés</div>";
  if(!actives.length){
    h+="<div class='vcard' style='text-align:center;padding:40px'><div style='font-size:48px;margin-bottom:16px'>📭</div><div style='font-size:15px;color:#6B7A99'>Aucune évaluation disponible pour le moment.<br>Revenez plus tard.</div></div>";
  }else{
    h+="<div style='display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:16px'>";
    actives.forEach(function(ev){
      var maDeja=(ev.reponses||[]).find(function(r){return SES&&r.eid===SES.id;});
      h+="<div class='vcard' style='--vcol:#142554'>";
      h+="<div style='font-family:Montserrat,sans-serif;font-size:15px;font-weight:800;color:#142554;margin-bottom:6px'>"+ev.titre+"</div>";
      h+="<div style='font-size:12px;color:#6B7A99;margin-bottom:12px'>"+ev.matiere+(ev.classe?" · "+ev.classe:"")+" · "+(ev.questions||[]).length+" questions · "+ev.duree+" min</div>";
      if(maDeja){
        var pct=Math.round((maDeja.score/(ev.questions||[]).length)*100);
        h+="<div style='background:"+(pct>=60?"#D1FAE5":"#FEE2E2")+";border-radius:10px;padding:10px;font-size:13px;font-weight:700;color:"+(pct>=60?"#059669":"#AE5353")+";text-align:center;margin-bottom:10px'>Score: "+maDeja.score+"/"+(ev.questions||[]).length+" ("+pct+"%)</div>";
        h+="<button class='btn sm' style='background:#F0F4FF;color:#142554;border-radius:10px;font-weight:700;border:none;cursor:pointer' onclick='_passerEval(\""+ev.id+"\",true)'><svg class='vico bico' aria-hidden='true'><use href='#lc-refresh'/></svg>Recommencer</button>";
      }else{
        h+="<button class='btn bi' onclick='_passerEval(\""+ev.id+"\",false)'>▶ Commencer l'évaluation</button>";
      }
      h+="</div>";
    });
    h+="</div>";
  }
  h+="</div>";
  _vc(h);
}

// v1.2.2 : "X élèves composent" — présence simulée crédible (varie avec l'heure
// + petite marche aléatoire), pour la mise en situation réelle. Sans backend.
window._evalLiveBase = null;
function _evalLiveCount(){
  if(_evalLiveBase===null){
    var h=new Date().getHours();
    // plus d'activité 7h-21h, creux la nuit
    var peak=(h>=7&&h<=21)?1:0.3;
    _evalLiveBase=Math.round((8+Math.random()*30)*peak)+3;
  } else {
    _evalLiveBase += Math.round((Math.random()-0.45)*3); // marche aléatoire douce
    if(_evalLiveBase<4)_evalLiveBase=4; if(_evalLiveBase>60)_evalLiveBase=60;
  }
  return _evalLiveBase;
}
function _passerEval(evalId,force){
  _evalLiveBase=null; // réinitialiser la présence pour cette session d'éval
  _initEvals();
  var ev=DB.evaluations.find(function(e){return e.id===evalId;});
  if(!ev)return;
  if(!SES&&!force){toast("Connectez-vous pour passer l'évaluation","warn");return;}
  var qi=0; var score=0; var timer=null; var elapsed=0;
  var totalSec=ev.duree*60;
  var userAnswers=[];

  function renderQ(){
    if(qi>=ev.questions.length){
      clearInterval(timer);
      // v1.10 : si l'éval contient des questions OUVERTES → correction IA (Ambassa).
      // Sinon (QCM pur, déjà auto-noté) → carte de score instantanée (zéro coût IA).
      if(_evalHasOpen(ev)){
        var _byQi={}; userAnswers.forEach(function(a){ _byQi[a.qi]=a; });
        var _qa=ev.questions.map(function(q,i){
          var a=_byQi[i]||{};
          return _evalIsOpen(q)?{type:'open',text:a.text||""}:{type:'qcm',ans:(typeof a.ans==='number'?a.ans:-1),correct:!!a.correct};
        });
        var _who=SES?{id:SES.id,nom:(SES.pre||"")+" "+(SES.nom||""),tel:SES.tel||SES.phone||""}:{id:"",nom:"Élève",tel:""};
        _evalRunCorrection(ev,_qa,_who,function(result){
          if(SES){
            if(!ev.reponses)ev.reponses=[];
            ev.reponses=ev.reponses.filter(function(r){return r.eid!==SES.id;});
            ev.reponses.push({eid:SES.id,nom:(SES.pre||"")+" "+(SES.nom||""),score:score,total:ev.questions.length,noteSur20:result.noteSur20,bilanIA:result,date:new Date().toLocaleDateString("fr-FR"),answers:userAnswers});
            save();
          }
        });
        return;
      }
      // QCM pur : comportement d'origine (score instantané)
      if(SES){
        if(!ev.reponses)ev.reponses=[];
        ev.reponses=ev.reponses.filter(function(r){return r.eid!==SES.id;});
        ev.reponses.push({eid:SES.id,nom:SES.pre+" "+SES.nom,score:score,total:ev.questions.length,date:new Date().toLocaleDateString("fr-FR"),answers:userAnswers});
        save();
      }
      var pct=Math.round((score/ev.questions.length)*100);
      var _tm=Math.floor(elapsed/60),_ts=elapsed%60;
      var _tmps=String(_tm).padStart(2,'0')+":"+String(_ts).padStart(2,'0');
      _vc("<div class='vsec'><div class='vcard' style='text-align:center;padding:40px'>"
        +"<div style='font-size:56px;margin-bottom:14px'>"+(pct>=80?"🏆":pct>=60?"✅":"📚")+"</div>"
        +"<div style='font-family:Montserrat,sans-serif;font-size:24px;font-weight:800;color:#142554;margin-bottom:8px'>Évaluation terminée !</div>"
        +"<div style='font-family:Georgia,serif;font-size:18px;color:"+(pct>=60?"#059669":"#AE5353")+";font-weight:700;margin-bottom:10px'>"+score+"/"+ev.questions.length+" ("+pct+"%)</div>"
        +"<div style='display:flex;gap:10px;justify-content:center;margin-bottom:18px;flex-wrap:wrap'>"
          +"<div style='background:#F0F4FF;border-radius:10px;padding:8px 14px'><div style='font-size:10px;color:#6B7A99;text-transform:uppercase;letter-spacing:.5px'>⏱️ Temps</div><div style='font-family:monospace;font-weight:800;color:#142554'>"+_tmps+"</div></div>"
          +"<div style='background:#F0F4FF;border-radius:10px;padding:8px 14px'><div style='font-size:10px;color:#6B7A99;text-transform:uppercase;letter-spacing:.5px'>✅ Réussite</div><div style='font-weight:800;color:"+(pct>=60?"#059669":"#AE5353")+"'>"+pct+"%</div></div>"
        +"</div>"
        +"<div style='font-size:13px;color:#6B7A99;margin-bottom:24px'>"+(pct>=80?"Excellent travail ! Tu maîtrises ce chapitre.":pct>=60?"Bon résultat, continue sur ta lancée !":"Révise ce chapitre puis retente l'évaluation.")+"</div>"
        +"<button class='btn bi' onclick='showMesEvaluations()'>← Retour aux évaluations</button>"
        +"</div></div>");
      return;
    }
    var q=ev.questions[qi];
    if(_evalIsOpen(q)){ _passerEvalOpen(q); return; }
    var remaining=totalSec-elapsed;
    var mn=Math.floor(remaining/60);var sc=remaining%60;
    var pctT=Math.round((elapsed/totalSec)*100);
    var col=remaining<120?"#AE5353":remaining<600?"#D97706":"#059669";
    _vc("<div class='vsec'>"
      +"<div style='background:linear-gradient(135deg,#142554,#1E3A8A);border-radius:16px;padding:16px 20px;color:#fff;margin-bottom:16px'>"
        +"<div class='fl2 fic fsb'>"
          +"<div style='font-size:13px;opacity:.7'>"+ev.titre+"</div>"
          +"<div style='font-family:monospace;font-size:18px;font-weight:700;color:"+col+"'>"+String(mn).padStart(2,'0')+":"+String(sc).padStart(2,'0')+"</div>"
        +"</div>"
        +"<div style='background:rgba(255,255,255,.1);border-radius:20px;height:6px;margin-top:10px'><div style='background:"+col+";height:100%;width:"+pctT+"%;border-radius:20px;transition:width .5s'></div></div>"
        +"<div class='fl2 fic fsb' style='margin-top:6px'>"
          +"<div style='font-size:11px;opacity:.6'>Question "+(qi+1)+"/"+ev.questions.length+"</div>"
          +"<div style='font-size:11px;font-weight:700;color:#86EFAC;display:flex;align-items:center;gap:5px'><span style='width:7px;height:7px;border-radius:50%;background:#3A8F73;display:inline-block;box-shadow:0 0 0 0 rgba(16,185,129,.7);animation:vgzPing 1.6s infinite'></span><span id='evalLiveCount'>"+_evalLiveCount()+"</span> élèves composent</div>"
        +"</div>"
      +"</div>"
      +"<div class='vcard'>"
        +"<div style='font-family:Montserrat,sans-serif;font-size:15px;font-weight:700;color:#142554;margin-bottom:20px;line-height:1.6'>"+q.q+"</div>"
        +"<div style='display:grid;grid-template-columns:1fr 1fr;gap:10px'>"
          +q.opts.map(function(opt,i){
            return "<button onclick='_answerEval("+i+")' style='background:#F0F4FF;color:#142554;border:2px solid #E8EEFF;border-radius:12px;padding:12px 16px;font-size:13px;font-weight:600;cursor:pointer;text-align:left;transition:.2s' onmouseover=\"this.style.background='#E0EAFF'\" onmouseout=\"this.style.background='#F0F4FF'\">"+opt+"</button>";
          }).join("")
        +"</div>"
        +"<div id='evalFb' style='margin-top:14px;min-height:24px'></div>"
      +"</div>"
      +"</div>");
  }

  window._answerEval=function(i){
    var q=ev.questions[qi];
    var fb=document.getElementById("evalFb");
    var btns=document.querySelectorAll("[onclick^='_answerEval']");
    btns.forEach(function(b,idx){
      b.style.background=idx===q.ans?"#D1FAE5":idx===i&&i!==q.ans?"#FEE2E2":"#F0F4FF";
      b.style.borderColor=idx===q.ans?"#059669":idx===i&&i!==q.ans?"#AE5353":"#E8EEFF";
      b.onclick=null;b.onmouseover=null;b.onmouseout=null;
    });
    if(i===q.ans)score++;
    userAnswers.push({qi:qi,ans:i,correct:i===q.ans});
    // v1.2.2 : question ratée → file de révision espacée (J+1/J+3/J+7)
    if(i!==q.ans && typeof _srsAdd==='function'){ try{ _srsAdd(q, ev.matiere||ev.titre||''); }catch(e){} }
    if(fb)fb.innerHTML="<div style='padding:10px;background:"+(i===q.ans?"#D1FAE5":"#FEE2E2")+";border-radius:10px;font-size:13px;color:"+(i===q.ans?"#059669":"#AE5353")+"'>"+(i===q.ans?"✅ ":"❌ ")+(q.exp||"")+"</div>";
    setTimeout(function(){qi++;renderQ();},2000);
  };

  function _passerEvalOpen(q){
    var rem=totalSec-elapsed, mnO=Math.floor(rem/60), scO=rem%60;
    var colO=rem<120?"#AE5353":rem<600?"#D97706":"#059669";
    _vc("<div class='vsec'>"
      +"<div style='background:linear-gradient(135deg,#142554,#1E3A8A);border-radius:16px;padding:16px 20px;color:#fff;margin-bottom:16px'>"
        +"<div class='fl2 fic fsb'><div style='font-size:13px;opacity:.7'>"+ev.titre+"</div>"
        +"<div style='font-family:monospace;font-size:18px;font-weight:700;color:"+colO+"'>"+String(mnO).padStart(2,'0')+":"+String(scO).padStart(2,'0')+"</div></div>"
        +"<div style='font-size:11px;opacity:.6;margin-top:6px'>Question "+(qi+1)+"/"+ev.questions.length+" · ✍️ Réponse libre</div>"
      +"</div>"
      +"<div class='vcard'>"
        +"<div style='font-family:Montserrat,sans-serif;font-size:15px;font-weight:700;color:#142554;margin-bottom:14px;line-height:1.6'>"+q.q+"</div>"
        +"<textarea id='evalOpenTxt' class='fi' rows='6' placeholder='Rédige ta réponse ici…' style='width:100%'></textarea>"
        +"<div class='fl2 fc' style='margin-top:12px'><button class='btn bi' onclick='_answerEvalOpen()'>Valider ma réponse →</button></div>"
      +"</div></div>");
  }
  window._answerEvalOpen=function(){
    var t=(document.getElementById('evalOpenTxt')?document.getElementById('evalOpenTxt').value:'').trim();
    userAnswers.push({qi:qi,text:t,open:true});
    qi++; renderQ();
  };

  timer=setInterval(function(){
    elapsed++;
    if(elapsed>=totalSec){clearInterval(timer);qi=ev.questions.length;renderQ();}
    else {
      var remaining2=totalSec-elapsed;var mn2=Math.floor(remaining2/60);var sc2=remaining2%60;
      var col2=remaining2<120?"#AE5353":remaining2<600?"#D97706":"#059669";
      var el=document.querySelector("[style*='monospace']");
      if(el){el.style.color=col2;el.textContent=String(mn2).padStart(2,'0')+":"+String(sc2).padStart(2,'0');}
      var bar=document.querySelector("[style*='transition:width']");
      if(bar)bar.style.width=Math.round((elapsed/totalSec)*100)+"%";
      // rafraîchir la présence "élèves qui composent" toutes les 5 s
      if(elapsed%5===0){ var lc=document.getElementById('evalLiveCount'); if(lc)lc.textContent=_evalLiveCount(); }
    }
  },1000);
  renderQ();
}

// ── RÉSULTATS DES ÉVALUATIONS (admin) ────────────────────────────
function mVoirResultatsEval(evalId){
  _initEvals();
  var ev=DB.evaluations.find(function(e){return e.id===evalId;});
  if(!ev){toast("Évaluation introuvable","warn");return;}
  var reps=ev.reponses||[];
  var rows=reps.map(function(r){
    var pct=Math.round((r.score/ev.questions.length)*100);
    return "<tr><td style='padding:6px 8px;font-size:13px'>"+r.nom+"</td>"
      +"<td style='padding:6px 8px;text-align:center;font-weight:700;color:"+(pct>=60?"#059669":"#AE5353")+"'>"+r.score+"/"+ev.questions.length+"</td>"
      +"<td style='padding:6px 8px;text-align:center'>"+pct+"%</td>"
      +"<td style='padding:6px 8px;font-size:11px;color:var(--ink4)'>"+r.date+"</td></tr>";
  }).join("");
  M("📊 Résultats — "+ev.titre,"",
    (rows?"<div class='tw'><table style='width:100%'><thead><tr style='background:var(--bg2)'><th style='text-align:left;padding:6px 8px'>Élève</th><th>Score</th><th>%</th><th>Date</th></tr></thead><tbody>"+rows+"</tbody></table></div>"
         :"<div class='empty'><div class='empty-ico'>📊</div>Aucune réponse reçue</div>"),
    "<button class='btn bo' onclick='cm()'>Fermer</button>",true);
}

