// MOD-3.12 : init async — await load() pour que le fetch LWS se termine avant le rendu
(async function _initApp(){
  await load();
  // Set logos
  var logoSrc=getLogo();
  ['loginLogo','sbLogo','vLogo'].forEach(function(id){var el=$(id);if(el&&logoSrc)el.src=logoSrc;});
  $('lStat1').textContent=DB.students.length;
  $('lStat2').textContent=DB.teachers.length;

  /* ── v1.19.20 : REPRISE DE SESSION ────────────────────────────────────────
     L'amorcage partait toujours sur le portail visiteur, sans jamais relire la
     session. Un admin qui rechargeait /app.html etait donc deconnecte — et
     depuis que l'accueil applicatif a ete supprime, `initVisitor` le renvoyait
     en plus sur la vitrine : le tableau de bord devenait INATTEIGNABLE.
     On relit donc la session AVANT de decider de l'ecran. */
  var _ses = _vrtRestoreSession();
  if(_ses && (_ses.type==='admin'||_ses.type==='superadmin'||_ses.type==='enseignant'||_ses.type==='eleve')){
    try{
      go2SES(_ses);        // pose SES, affiche #APP, construit la nav, va au dashboard
      return;              // ne pas repartir sur le portail visiteur
    }catch(e){
      // Reprise impossible (base incomplete) : on repart proprement en visiteur
      try{ sessionStorage.removeItem('VERITAS_SES'); }catch(e2){}
      SES=null;
    }
  }
  // Visiteur inscrit : le portail reste l'ecran, mais la session est reposee
  // pour que l'en-tete, les droits d'acces et le paywall le reconnaissent.
  if(_ses && (_ses.type==='visiteur_inscrit'||_ses.type==='visiteur')){
    SES=_ses; SESSION_TOKEN=_ses._token||null; SESSION_EXPIRY=_ses._exp||0;
  }

  // Show visitor portal by default
  goToVisitor();
  // On load visitor
  initVisitor();
  swLR('visiteur');
  if(SES&&SES.type==='visiteur_inscrit'){ try{ setTimeout(_updateVisitorHeader,60); }catch(e){} }
  // v1.9 (#7) : deep-link depuis les pages SEO (?epreuve=<id>) → ouvre les épreuves
  try{
    var _ep=new URLSearchParams(location.search).get('epreuve');
    if(_ep&&typeof showEpreuves==='function'){ setTimeout(function(){ try{ showEpreuves(); }catch(e){} },600); }
  }catch(e){}
})();

// ══ v1.7 — LECTEUR PDF SÉCURISÉ (vente numérique, consultation on-site) ══════
// Affiche un document page par page comme IMAGES servies par api/secure_pdf.php
// (le PDF brut ne quitte jamais le serveur). Aperçu gratuit = N premières pages ;
// l'achat débloque le reste. Anti-copie/-capture en couches + filigrane serveur.
window._secureApiBase=function(){
  try{ return (LWS_API.db||'').replace(/\/db\.php(\?.*)?$/,''); }catch(e){ return '/api'; }
};
window._secureToken=function(){
  try{ return window._vrtContentToken||sessionStorage.getItem('_vrtCT')||''; }catch(e){ return ''; }
};
window.openSecureBook=function(bookId){
  // v1.7 : généralisé — accepte un LIVRE (boutique) OU un CONTENU e-learning
  // (épreuve/cours) marqué « protégé ». Le type pilote le paywall.
  var book=(DB.books||[]).find(function(b){return b.id===bookId;}), kind='book';
  if(!book){
    book=((DB.elearning||{}).contenus||[]).find(function(c){return c.id===bookId;});
    kind='contenu';
  }
  if(!book){ toast('Document introuvable','warn'); return; }
  var base=_secureApiBase(), tok=_secureToken();
  var ov=document.createElement('div');
  ov.id='secureReader'; ov.className='sread';
  ov.innerHTML='<div class="sread-bar">'
    +'<div class="sread-title">🔒 '+_esc(book.titre||'Document')+'</div>'
    +'<div class="sread-zoom" role="group" aria-label="Zoom du texte">'
      +'<button class="sread-zbtn" onclick="_secureZoom(-1)" aria-label="Réduire le texte" title="Réduire">−</button>'
      +'<span class="sread-zlbl" id="sreadZoomLbl">100%</span>'
      +'<button class="sread-zbtn" onclick="_secureZoom(1)" aria-label="Agrandir le texte" title="Agrandir">+</button>'
    +'</div>'
    +'<div class="sread-pal-wrap">'
      +'<button class="sread-pal" onclick="_secureTogglePal(event)" aria-haspopup="true" aria-label="Confort de lecture" title="Confort de lecture (thème)">🎨</button>'
      +'<div class="sread-pal-pop" id="sreadPalPop" role="menu" aria-label="Thème de lecture">'
        +'<button role="menuitemradio" data-th="jour"  onclick="_secureTheme(\'jour\')">☀️ Jour</button>'
        +'<button role="menuitemradio" data-th="sepia" onclick="_secureTheme(\'sepia\')">📜 Sépia</button>'
        +'<button role="menuitemradio" data-th="nuit"  onclick="_secureTheme(\'nuit\')">🌙 Nuit</button>'
        +'<button role="menuitemradio" data-th="doux"  onclick="_secureTheme(\'doux\')">🌫️ Doux</button>'
      +'</div>'
    +'</div>'
    +'<div class="sread-page" id="sreadPageLbl" onclick="_secureJump()" title="Aller à une page" style="cursor:pointer">…</div>'
    +'<button class="sread-unlock" id="sreadUnlock" style="display:none" onclick="_secureUnlock()">🔓 Débloquer</button>'
    +'<button class="sread-fs" onclick="_secureFullscreen()" aria-label="Plein écran" title="Plein écran / présentation">⛶</button>'
    +'<button class="sread-x" onclick="closeSecureBook()" aria-label="Fermer">✕</button>'
    +'</div>'
    +'<div class="sread-stage" id="sreadStage"><div class="sread-load">📖 Chargement…</div></div>'
    +'<div class="sread-wm" id="sreadWm" aria-hidden="true"></div>'
    +'<div class="sread-shield" id="sreadShield"><div>👁️ Lecture protégée mise en pause</div><small>Revenez sur la fenêtre pour reprendre</small></div>'
    +'<div class="sread-nav"><span class="sread-foot">📖 Lecture continue — faites défiler · Protégé, sans copie ni partage</span></div>';
  document.body.appendChild(ov);
  document.body.style.overflow='hidden';
  var _savedTh=(function(){try{return localStorage.getItem('vrt_sread_theme')||'jour';}catch(_){return 'jour';}})();
  window._secureState={id:bookId,kind:kind,page:1,pages:0,freePages:10,hasAccess:false,prepared:false,base:base,tok:tok,book:book,zoom:1,theme:_savedTh};
  if(typeof _secureTheme==='function') _secureTheme(_savedTh); else ov.setAttribute('data-theme',_savedTh);
  _secureInstallGuards();
  if(typeof _secureSetWatermark==='function') _secureSetWatermark();
  // Métadonnées (nombre de pages, droits)
  fetch(base+'/secure_pdf.php?id='+encodeURIComponent(bookId)+'&meta=1'+(tok?('&token='+encodeURIComponent(tok)):''))
    .then(function(r){return r.json();})
    .then(function(m){
      if(!m||!m.ok){ _secureStageMsg('⚠️ Document indisponible pour le moment.'); return; }
      var st=window._secureState; st.pages=m.pages||0; st.freePages=m.freePages||10; st.hasAccess=!!m.hasAccess; st.prepared=!!m.prepared;
      var ub=document.getElementById('sreadUnlock'); if(ub) ub.style.display=st.hasAccess?'none':'inline-flex';
      if(!m.prepared){ _secureStageMsg('📄 Ce document n\'est pas encore disponible à la lecture en ligne.'); return; }
      _secureRenderScroll();
    })
    .catch(function(){ _secureStageMsg('⚠️ Connexion au lecteur impossible.'); });
};
window._secureStageMsg=function(html){
  var s=document.getElementById('sreadStage'); if(s) s.innerHTML='<div class="sread-load">'+html+'</div>';
};
// Paywall (affichée EN BAS du flux, après les pages gratuites).
window._securePaywallHtml=function(st){
  if(st.kind==='contenu'){
    return '<div class="sread-pay">'
      +'<div style="font-size:46px">🔒</div>'
      +'<div class="sread-pay-t">Aperçu de '+st.freePages+' pages terminé</div>'
      +'<div class="sread-pay-s">« '+_esc(st.book.titre||'')+' » fait partie des ressources premium. Abonnez-vous pour la lecture intégrale, en ligne et sans téléchargement.</div>'
      +'<button class="sread-pay-btn" onclick="_secureUnlock()">📦 Voir les abonnements</button>'
      +'<div class="sread-pay-note">Lecture sécurisée · incluse dans votre formule</div>'
      +'</div>';
  }
  var prix=(st.book.prixDigital||st.book.priceDigital||st.book.prix||0);
  return '<div class="sread-pay">'
    +'<div style="font-size:46px">🔓</div>'
    +'<div class="sread-pay-t">Vous avez lu les '+st.freePages+' pages gratuites</div>'
    +'<div class="sread-pay-s">Débloquez l\'intégralité de « '+_esc(st.book.titre||'')+' » — lecture en ligne illimitée, sans téléchargement.</div>'
    +'<div class="sread-pay-price">'+fmtN(prix)+' FCFA</div>'
    +'<button class="sread-pay-btn" onclick="_secureBuy()">💳 Débloquer la version numérique</button>'
    +'<div class="sread-pay-note">Lecture sécurisée · valable sur tous vos appareils connectés</div>'
    +'</div>';
};
// DÉFILEMENT VERTICAL CONTINU : toutes les pages accessibles empilées ; on fait
// défiler (de bas en haut), plus de Préc./Suiv. Paywall en bas après l'aperçu.
window._secureRenderScroll=function(){
  var st=window._secureState; if(!st) return;
  var stage=document.getElementById('sreadStage'); if(!stage) return;
  var total=st.pages||0;
  var readable=st.hasAccess?total:Math.min(st.freePages,(total||st.freePages));
  if(readable<1) readable=st.hasAccess?(total||1):st.freePages;
  // v1.17 : plus AUCUNE URL de page dans le DOM. On pose des toiles vides ; leur
  // contenu n'arrive qu'à l'approche de l'écran, via un bail signé, et repart
  // dès qu'on s'en éloigne. Auparavant les 300 liens d'un manuel tenaient dans
  // le document, prêts à être récoltés d'une ligne en console.
  st.readable=readable; st.sigs={}; st.busy={};
  var html='';
  for(var n=1;n<=readable;n++){
    html+='<canvas class="sread-img" data-pg="'+n+'" width="1240" height="1754" '
      +'aria-label="page '+n+'" oncontextmenu="return false"></canvas>';
  }
  if(!st.hasAccess && (total===0 || total>st.freePages)){ html+=_securePaywallHtml(st); }
  stage.innerHTML=html || '<div class="sread-load">📖 Chargement…</div>';
  _secureApplyZoom();
  _secureUpdatePageLbl();
  _secureInstallLazy();
  if(!stage._vrtScroll){ stage._vrtScroll=1; stage.addEventListener('scroll',_secureUpdatePageLbl,{passive:true}); }
};
// Bail de lecture : le serveur ne signe qu'une FENÊTRE de pages à la fois, et
// tient un quota horaire. Demander tout le document d'un coup est précisément
// ce qu'on ne veut plus pouvoir faire.
// Chaque signature est conservée AVEC son échéance : le serveur signe
// « id|page|compte|exp », donc réutiliser une signature d'une fenêtre
// antérieure sous l'échéance de la dernière la rendrait invalide (403).
window._secureEnsureSig=function(n){
  var st=window._secureState; if(!st) return Promise.reject(new Error('fermé'));
  var now=Math.floor(Date.now()/1000);
  var have=st.sigs[n];
  if(have&&have.e>now+30) return Promise.resolve(have);
  var u=st.base+'/secure_pdf.php?id='+encodeURIComponent(st.id)+'&sign=1&from='+n+'&count=8'
       +(st.tok?('&token='+encodeURIComponent(st.tok)):'');
  return fetch(u,{cache:'no-store'}).then(function(r){
    if(r.status===429) throw new Error('quota');
    return r.json();
  }).then(function(j){
    if(!j||!j.ok||!j.sigs) throw new Error('bail refusé');
    var exp=j.exp||0;
    for(var k in j.sigs){
      if(Object.prototype.hasOwnProperty.call(j.sigs,k)) st.sigs[k]={s:j.sigs[k],e:exp};
    }
    if(!st.sigs[n]) throw new Error('page non couverte');
    return st.sigs[n];
  });
};
// Peint une page DANS une toile : l'image transite en blob, n'apparaît jamais
// comme ressource du document et ne survit pas au dessin.
window._securePaintPage=function(n){
  var st=window._secureState; if(!st||st.busy[n]) return;
  var stage=document.getElementById('sreadStage'); if(!stage) return;
  var cv=stage.querySelector('.sread-img[data-pg="'+n+'"]'); if(!cv||cv._painted) return;
  st.busy[n]=1;
  _secureEnsureSig(n).then(function(bail){
    var u=st.base+'/secure_pdf.php?id='+encodeURIComponent(st.id)+'&page='+n
         +'&exp='+encodeURIComponent(bail.e)+'&sig='+encodeURIComponent(bail.s)
         +(st.tok?('&token='+encodeURIComponent(st.tok)):'');
    return fetch(u,{cache:'no-store'}).then(function(r){
      if(!r.ok) throw new Error('HTTP '+r.status);
      return r.blob();
    });
  }).then(function(blob){
    var draw=function(src,w,h){
      cv.width=w; cv.height=h;
      var cx=cv.getContext('2d'); cx.drawImage(src,0,0);
      cv._painted=1;
      // Largeur posée sur CETTE toile seule : repasser sur les trois cents
      // autres à chaque page peinte coûterait cher sans rien apporter.
      var sg=document.getElementById('sreadStage');
      if(sg){ cv.style.maxWidth='none'; cv.style.width=Math.round(Math.min(900,sg.clientWidth*0.96)*(st.zoom||1))+'px'; }
      if(src.close) src.close();
    };
    if(window.createImageBitmap){
      return createImageBitmap(blob).then(function(bmp){ draw(bmp,bmp.width,bmp.height); });
    }
    return new Promise(function(res,rej){
      var im=new Image(), ou=URL.createObjectURL(blob);
      im.onload=function(){ draw(im,im.naturalWidth,im.naturalHeight); URL.revokeObjectURL(ou); res(); };
      im.onerror=function(){ URL.revokeObjectURL(ou); rej(new Error('image illisible')); };
      im.src=ou;
    });
  }).then(function(){ delete st.busy[n]; })
    .catch(function(e){
      delete st.busy[n];
      var cx=cv.getContext('2d');
      cx.fillStyle='#F1F5F9'; cx.fillRect(0,0,cv.width,cv.height);
      cx.fillStyle='#7A88A6'; cx.font='600 34px Arial, sans-serif'; cx.textAlign='center';
      cx.fillText(e&&e.message==='quota'?'Lecture en pause — trop de pages sur cette heure'
                                        :'Page indisponible',cv.width/2,cv.height/2);
    });
};
// Charge à l'approche, libère à l'éloignement : la mémoire reste bornée et le
// document ne contient jamais plus de quelques pages à la fois.
window._secureInstallLazy=function(){
  var st=window._secureState, stage=document.getElementById('sreadStage');
  if(!st||!stage) return;
  if(st.obs){ try{st.obs.disconnect();}catch(e){} }
  if(!window.IntersectionObserver){
    for(var n=1;n<=Math.min(st.readable,4);n++) _securePaintPage(n);
    return;
  }
  st.obs=new IntersectionObserver(function(ents){
    ents.forEach(function(en){
      var pg=parseInt(en.target.getAttribute('data-pg'),10);
      if(!pg) return;
      if(en.isIntersecting){ _securePaintPage(pg); return; }
      // Hors champ ET loin : on rend la mémoire. La toile reprend sa taille
      // d'attente pour que la mise en page ne saute pas.
      if(en.target._painted&&Math.abs(pg-(st.page||1))>8){
        en.target.width=1240; en.target.height=1754; en.target._painted=0;
      }
    });
  },{root:stage,rootMargin:'600px 0px'});
  stage.querySelectorAll('.sread-img').forEach(function(c){ st.obs.observe(c); });
};
window._secureUpdatePageLbl=function(){
  var st=window._secureState, stage=document.getElementById('sreadStage'), lbl=document.getElementById('sreadPageLbl');
  if(!st||!stage||!lbl) return;
  var imgs=stage.querySelectorAll('.sread-img'), cur=imgs.length?1:0, mid=stage.scrollTop+stage.clientHeight*0.35;
  for(var i=0;i<imgs.length;i++){ if(imgs[i].offsetTop<=mid) cur=parseInt(imgs[i].getAttribute('data-pg'),10)||cur; }
  st.page=cur||1;   // sert de repère à la libération des pages éloignées
  lbl.textContent=cur?('Page '+cur+(st.pages?(' / '+st.pages):'')):'…';
};
window._secureZoom=function(d){
  var st=window._secureState; if(!st) return;
  st.zoom=Math.min(3,Math.max(0.6,Math.round(((st.zoom||1)+d*0.15)*100)/100));
  _secureApplyZoom();
};
window._secureApplyZoom=function(){
  var st=window._secureState; if(!st) return;
  var lbl=document.getElementById('sreadZoomLbl'); if(lbl) lbl.textContent=Math.round((st.zoom||1)*100)+'%';
  var stage=document.getElementById('sreadStage'); if(!stage) return;
  var w=Math.round(Math.min(900,stage.clientWidth*0.96)*(st.zoom||1))+'px';
  stage.querySelectorAll('.sread-img').forEach(function(img){ img.style.maxWidth='none'; img.style.width=w; });
};
// ── CONFORT DE LECTURE : palette de thèmes (Jour/Sépia/Nuit/Doux) ──
// Filtres CSS sur les images de pages (le filigrane reste incrusté → sécurité intacte).
window._secureTogglePal=function(e){
  if(e&&e.stopPropagation) e.stopPropagation();
  var ov=document.getElementById('secureReader'); if(!ov) return;
  var open=ov.classList.toggle('pal-open');
  if(open){ setTimeout(function(){ document.addEventListener('click',window._securePalOutside,{once:true}); },0); }
};
window._securePalOutside=function(){ var ov=document.getElementById('secureReader'); if(ov) ov.classList.remove('pal-open'); };
window._secureTheme=function(name){
  var ov=document.getElementById('secureReader'); if(!ov) return;
  if(['jour','sepia','nuit','doux'].indexOf(name)<0) name='jour';
  ov.setAttribute('data-theme',name);
  ov.classList.remove('pal-open');
  try{ localStorage.setItem('vrt_sread_theme',name); }catch(_){}
  if(window._secureState) window._secureState.theme=name;
  ov.querySelectorAll('.sread-pal-pop [data-th]').forEach(function(b){
    var on=b.getAttribute('data-th')===name;
    b.classList.toggle('on',on); b.setAttribute('aria-checked',on?'true':'false');
  });
};
// ── UX : plein écran / mode présentation ──
window._secureFullscreen=function(){
  var ov=document.getElementById('secureReader'); if(!ov) return;
  try{
    var fsEl=document.fullscreenElement||document.webkitFullscreenElement;
    if(!fsEl){ (ov.requestFullscreen||ov.webkitRequestFullscreen||function(){}).call(ov); }
    else{ (document.exitFullscreen||document.webkitExitFullscreen||function(){}).call(document); }
  }catch(e){}
};
// ── UX : aller à une page (saisie) ──
window._secureJump=function(){
  var st=window._secureState; if(!st) return;
  var max=st.hasAccess?(st.pages||0):Math.min(st.freePages,(st.pages||st.freePages));
  var v=prompt('Aller à la page (1 – '+(max||st.freePages)+') :',''); if(v===null) return;
  var n=parseInt(v,10); if(!n||n<1){ return; }
  _secureScrollToPage(n);
};
window._secureScrollToPage=function(n){
  var stage=document.getElementById('sreadStage'); if(!stage) return;
  var img=stage.querySelector('.sread-img[data-pg="'+n+'"]');
  if(img){ stage.scrollTo({top:Math.max(0,img.offsetTop-12),behavior:'smooth'}); }
  else if(typeof toast==='function'){ toast('Page '+n+' indisponible dans cet aperçu','warn'); }
};
// ── Sécurité : filigrane CLIENT vivant (en plus de celui gravé côté serveur) ──
// Couche supplémentaire liée à la session : toute capture montre AUSSI ce marqueur.
window._secureSetWatermark=function(){
  var wm=document.getElementById('sreadWm'); if(!wm) return;
  var who=(typeof SES!=='undefined'&&SES)
    ? ((SES.pre||'')+' '+(SES.nom||'')+' · '+(SES.accountId||SES.id||'')).replace(/\s+/g,' ').trim()
    : 'Aperçu VÉRITAS';
  var txt=(who+' · '+new Date().toLocaleDateString('fr-FR')).slice(0,60);
  var svg='<svg xmlns="http://www.w3.org/2000/svg" width="360" height="210">'
    +'<text x="6" y="120" transform="rotate(-28 6 120)" font-family="Arial" font-size="15" '
    +'fill="#142554" fill-opacity="0.12">'+txt.replace(/[<>&]/g,' ')+'</text></svg>';
  wm.style.backgroundImage="url('data:image/svg+xml;charset=utf-8,"+encodeURIComponent(svg)+"')";
};
window._secureUnlock=function(){
  var st=window._secureState; if(!st) return;
  if(st.kind==='contenu'){
    closeSecureBook();
    if(typeof vShowSec==='function') vShowSec('elearning',null);
    setTimeout(function(){var p=document.getElementById('elPlans'); if(p) p.scrollIntoView({behavior:'smooth'});},400);
  } else { _secureBuy(); }
};
window._secureBuy=function(){
  var st=window._secureState; if(!st) return;
  if(typeof SES==='undefined'||!SES){ toast('Connectez-vous pour acheter','warn'); if(typeof showRegisterForm==='function'){ closeSecureBook(); showRegisterForm(); } return; }
  var prix=(st.book.prixDigital||st.book.priceDigital||st.book.prix||0);
  if(typeof openPaymentModal!=='function'){ toast('Paiement indisponible','warn'); return; }
  openPaymentModal({
    montant:prix, label:'📘 Version numérique — '+(st.book.titre||''),
    refPrefix:'EBOOK', intent:'digitalbook', targetId:st.id,
    customerAccountId:SES.accountId, customerNom:(SES.pre||'')+' '+(SES.nom||''), customerTel:SES.tel||''
  });
};
// Anti-copie / anti-capture (dissuasion — voir note d'honnêteté dans secure_pdf.php)
window._secureInstallGuards=function(){
  var ov=document.getElementById('secureReader'); if(!ov) return;
  ov.addEventListener('contextmenu',function(e){e.preventDefault();});
  ov.addEventListener('dragstart',function(e){e.preventDefault();});
  ov.addEventListener('selectstart',function(e){e.preventDefault();});
  window._secureKeyGuard=function(e){
    // Bloque Ctrl+S / Ctrl+P / Ctrl+C / PrintScreen pendant la lecture
    if((e.ctrlKey||e.metaKey)&&['s','p','c','u'].indexOf((e.key||'').toLowerCase())>=0){ e.preventDefault(); toast('Action désactivée sur un document protégé','warn'); }
    if((e.key||'')==='PrintScreen'){ _secureShield(true); setTimeout(function(){_secureShield(false);},1200); try{navigator.clipboard&&navigator.clipboard.writeText('© VÉRITAS — capture interdite');}catch(_){} }
  };
  document.addEventListener('keydown',window._secureKeyGuard,true);
  // Floutage dès perte de focus / changement d'onglet (anti-capture d'arrière-plan)
  window._secureVis=function(){ _secureShield(document.hidden); };
  document.addEventListener('visibilitychange',window._secureVis);
  window._secureBlur=function(){ _secureShield(true); };
  window._secureFocus=function(){ _secureShield(false); };
  window.addEventListener('blur',window._secureBlur);
  window.addEventListener('focus',window._secureFocus);
};
window._secureShield=function(on){
  var sh=document.getElementById('sreadShield'); if(sh) sh.style.display=on?'flex':'none';
};
window.closeSecureBook=function(){
  try{ if(window._secureState&&window._secureState.obs) window._secureState.obs.disconnect(); }catch(e){}
  var ov=document.getElementById('secureReader'); if(ov) ov.remove();
  document.body.style.overflow='';
  try{
    document.removeEventListener('keydown',window._secureKeyGuard,true);
    document.removeEventListener('visibilitychange',window._secureVis);
    window.removeEventListener('blur',window._secureBlur);
    window.removeEventListener('focus',window._secureFocus);
  }catch(e){}
  window._secureState=null;
};

// ══ v1.5 — ANALYTICS MINIMALISTE : tunnel chiffré (api/stats.php) ═══════════
// 5 événements clés, fire-and-forget (sendBeacon), zéro donnée personnelle,
// jamais pour l'admin. Sans ces chiffres, le marketing pilote à l'aveugle.
// v1.13 : 2e argument `meta` optionnel (déjà stocké par stats.php, tronqué à
// 120 car.). Il sert à savoir DEPUIS QUELLE PAGE un parent écrit sur WhatsApp —
// sans lui, on compte des clics sans savoir ce qui les provoque. La déduplication
// journalière tient compte de la méta, sinon seule la première page de la journée
// serait comptée.
window._track=function(ev,meta){
  try{
    if(typeof SES!=='undefined'&&SES&&(SES.type==='admin'||SES.type==='superadmin'))return;
    // anti-doublon : 1 même événement (+ méta) / jour / appareil
    var k='_trk_'+ev+(meta?('_'+JSON.stringify(meta)):'')+'_'+new Date().toDateString();
    if(localStorage.getItem(k))return;
    localStorage.setItem(k,'1');
    var base=(typeof LWS_API!=='undefined'&&LWS_API.db)?LWS_API.db.replace(/\/db\.php.*$/,''):'/api';
    var data=JSON.stringify(meta?{ev:ev,meta:meta}:{ev:ev});
    if(navigator.sendBeacon){ navigator.sendBeacon(base+'/stats.php', new Blob([data],{type:'application/json'})); }
    else{ fetch(base+'/stats.php',{method:'POST',headers:{'Content-Type':'application/json'},body:data,keepalive:true}).catch(function(){}); }
  }catch(e){}
};
setTimeout(function(){ try{ var V=document.getElementById('VISITOR'); if(V&&V.style.display!=='none') _track('visit'); }catch(e){} },3000);

// Tableau de bord du tunnel (admin) : visites → inscriptions → essais IA →
// clics abonnement → paiements initiés, par jour sur 30 jours.
window.mStatsFunnel=function(){
  if(typeof iA!=='function'||!iA()){ toast('Réservé à l\'administration','warn'); return; }
  var base=(typeof LWS_API!=='undefined'&&LWS_API.db)?LWS_API.db.replace(/\/db\.php.*$/,''):'/api';
  var tok=(DB.cloudConfig&&DB.cloudConfig.secret)||'';
  M('📈 Tunnel d\'acquisition','30 derniers jours — données api/stats.php',
    '<div id="funnelBox" style="max-height:420px;overflow-y:auto"><div class="empty">Chargement…</div></div>',
    '<button class="btn bo" onclick="cm()">Fermer</button>',true);
  fetch(base+'/stats.php?summary=1',{headers:tok?{'Authorization':'Bearer '+tok}:{}})
    .then(function(r){return r.json();})
    .then(function(d){
      var box=document.getElementById('funnelBox'); if(!box)return;
      if(!d||!d.ok){ box.innerHTML='<div class="ib ibt"><span>⚠️</span><span>Données indisponibles ('+_esc((d&&d.error)||'serveur')+').</span></div>'; return; }
      var days=Object.keys(d.days||{});
      if(!days.length){ box.innerHTML='<div class="empty">Aucun événement encore — les chiffres arrivent dès les premières visites.</div>'; return; }
      // v1.13 : wa_click (clics WhatsApp) et tool_use (outils gratuits) suivent
      // les deux nouvelles portes d'entrée — sans eux, impossible de savoir si
      // l'Espace Parents et le calculateur de moyenne amènent des conversations.
      var tot={visit:0,signup:0,ia_try:0,sub_click:0,pay_init:0,wa_click:0,tool_use:0};
      var rows=days.map(function(t){
        var e=d.days[t]||{};
        Object.keys(tot).forEach(function(k){tot[k]+=(e[k]||0);});
        return '<tr><td class="xs2">'+t+'</td><td>'+(e.visit||0)+'</td><td>'+(e.signup||0)+'</td><td>'+(e.ia_try||0)+'</td><td>'+(e.tool_use||0)+'</td><td>'+(e.wa_click||0)+'</td><td>'+(e.sub_click||0)+'</td><td>'+(e.pay_init||0)+'</td></tr>';
      }).join('');
      var conv=function(a,b){return a?Math.round(b/a*100)+'%':'—';};
      box.innerHTML='<div class="g2 mb12">'
        +'<div class="card" style="padding:12px"><div class="xs2 mut">VISITES → INSCRIPTIONS</div><div class="bold" style="font-size:22px;color:#2563EB">'+conv(tot.visit,tot.signup)+'</div><div class="xs2 mut">'+tot.visit+' → '+tot.signup+'</div></div>'
        +'<div class="card" style="padding:12px"><div class="xs2 mut">INSCRIPTIONS → PAIEMENTS</div><div class="bold" style="font-size:22px;color:#059669">'+conv(tot.signup,tot.pay_init)+'</div><div class="xs2 mut">'+tot.signup+' → '+tot.pay_init+'</div></div>'
        +'</div>'
        +'<div class="tw"><table><thead><tr><th>Jour</th><th>👁 Visites</th><th>✨ Inscr.</th><th>🤖 IA</th><th>🧰 Outils</th><th>📲 WhatsApp</th><th>📋 Abo clic</th><th>💳 Paiement</th></tr></thead><tbody>'+rows+'</tbody></table></div>';
    })
    .catch(function(){ var box=document.getElementById('funnelBox'); if(box)box.innerHTML='<div class="ib ibt"><span>⚠️</span><span>Serveur stats injoignable.</span></div>'; });
};

// ── v1.4.4 (étude vidéo Sharesub) : BANDEAU STICKY DE CONVERSION ───────────
// Sobre : apparaît après 12 s de visite, une seule fois par session, fermable,
// jamais pour un utilisateur connecté. CTA → essai gratuit du Prof. Ambassa.
setTimeout(function(){
  try{
    if(sessionStorage.getItem('_lxCtaSeen')) return;
    if(typeof SES!=='undefined'&&SES) return; // connecté → pas de bandeau
    var V=document.getElementById('VISITOR');
    if(!V||V.style.display==='none') return;
    var d=document.createElement('div');
    d.className='lx-sticky-cta';
    // v1.13 : ce bandeau est centré en bas ; la classe sur <body> fait remonter
    // le FAB WhatsApp (bas-droite) tant qu'il est là — sinon les deux se
    // superposent sur un écran de 360 px de large.
    var _lxGone='document.body.classList.remove(\'has-sticky-cta\');';
    d.innerHTML='<span>🎓 Testez le <b>Prof. Ambassa</b> — corrigés et quiz IA <b>gratuits</b></span>'
      +'<button class="lx-go" onclick="sessionStorage.setItem(\'_lxCtaSeen\',\'1\');'+_lxGone+'this.parentNode.remove();if(typeof mAgentAmbassa===\'function\')mAgentAmbassa();">Essayer →</button>'
      +'<button class="lx-x" aria-label="Fermer" onclick="sessionStorage.setItem(\'_lxCtaSeen\',\'1\');'+_lxGone+'this.parentNode.remove();">✕</button>';
    document.body.appendChild(d);
    document.body.classList.add('has-sticky-cta');
  }catch(e){}
},12000);

// ════════════════════════════════════════════════════════════════════════════
// VERITAS — MODULE NAVIGATION HISTORIQUE (touche Retour = page précédente)
// ════════════════════════════════════════════════════════════════════════════
(function _initNavHistory(){
  // Pile interne des états de navigation
  window._navStack = [];
  // Drapeau pour éviter les boucles lors de la restauration
  window._navRestoring = false;

  // Entrée initiale dans l'historique navigateur (empêche la fermeture immédiate)
  history.replaceState({_v:0}, '');

  // ── Fonction de restauration d'un état sauvegardé ──
  window._navRestore = function(fn){
    window._navRestoring = true;
    try{ fn(); } catch(e){ console.warn('[nav]',e); }
    window._navRestoring = false;
  };

  // ── Intercepteur générique : wraps une fonction de navigation ──
  function _wrapNav(name, snapshotFn){
    var orig = window[name];
    if(typeof orig !== 'function') return;
    window[name] = function(){
      if(!window._navRestoring){
        var snap = snapshotFn ? snapshotFn.apply(this, arguments) : null;
        if(snap){
          window._navStack.push(snap);
          history.pushState({_v: window._navStack.length}, '');
        }
      }
      return orig.apply(this, arguments);
    };
  }

  // ── Wrappers par fonction ──

  // Visiteur : sections principales
  _wrapNav('vShowSec', function(sec){
    var prev = window._vCurrentSec;
    if(!prev || prev === sec) return null;
    return function(){ window._navRestoring=true; vShowSec(prev); window._navRestoring=false; };
  });

  // Admin : pages du tableau de bord
  _wrapNav('goTo', function(p){
    var prev = typeof pg !== 'undefined' ? pg : null;
    if(!prev || prev === p) return null;
    return function(){ window._navRestoring=true; goTo(prev); window._navRestoring=false; };
  });

  // Littérature : menu d'une œuvre
  _wrapNav('_showLittMenu', function(jid, key){
    var prevSec = window._vCurrentSec;
    return function(){ window._navRestoring=true; vShowSec(prevSec||'litterature'); window._navRestoring=false; };
  });

  // Littérature : sous-pages (carte, fiche, citations, techniques, contrôle, QCM)
  ['_showLittCarte','_showLittFiche','_showLittCitations',
   '_showLittTechniques','_showLittControle','_showLittQCM'].forEach(function(name){
    _wrapNav(name, function(key){
      var k = key;
      return function(){ window._navRestoring=true; _showLittMenu(k,k); window._navRestoring=false; };
    });
  });

  // Jeux éducatifs
  _wrapNav('showJeuxEdu', function(){
    var prev = window._vCurrentSec;
    if(!prev || prev === 'jeux') return null;
    return function(){ window._navRestoring=true; vShowSec(prev); window._navRestoring=false; };
  });

  // Laboratoires virtuels
  _wrapNav('showLabosVirtuels', function(){
    var prev = window._vCurrentSec;
    if(!prev || prev === 'labos') return null;
    return function(){ window._navRestoring=true; vShowSec(prev); window._navRestoring=false; };
  });

  // ── Gestionnaire de l'événement popstate (bouton Retour du navigateur) ──
  window.addEventListener('popstate', function(e){
    if(window._navStack.length > 0){
      // On a un état précédent dans notre pile → restaurer
      var fn = window._navStack.pop();
      window._navRestore(fn);
      // Maintenir l'entrée navigateur courante pour ne pas fermer l'app
      if(window._navStack.length === 0){
        history.replaceState({_v:0}, '');
      }
    } else {
      // Pile vide : on repousse un état pour ne pas quitter l'app
      history.pushState({_v:0}, '');
      toast('Utilisez le menu pour naviguer','info');
    }
  });
})();



