      cardsH+='<span style="background:'+stCol+'33;color:'+stCol+';border:1px solid '+stCol+'55;padding:3px 10px;border-radius:20px;font-size:10px;font-weight:700">'+( cv.statut||'active')+'</span>';
      cardsH+='</div>';
