function cvAdminSaveMatiere(cvId){
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});if(!cv)return;
  var mat=document.getElementById('amMat')?.value||'';
  var ensId=document.getElementById('amEns')?.value||'';
  if(!mat||!ensId){toast('Matière et enseignant requis','warn');return;}
  if(!cv.matieres)cv.matieres=[{mat:cv.matiere||mat,ensId:cv.enseignantId||ensId,col:cvMatColor(cv.matiere||mat)}];
  if(cv.matieres.find(function(m){return m.mat===mat;})){toast('Cette matière est déjà dans le groupe','warn');return;}
  cv.matieres.push({mat:mat,ensId:ensId,col:cvMatColor(mat)});
  save();re();cm();toast('✅ Matière ajoutée : '+mat);
}

// ── EMPLOI DU TEMPS DU GROUPE ────────────────────────────────────────────────
function cvAdminEDT(cvId){
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});if(!cv)return;
  if(!cv.edt)cv.edt=[];
  var matieres=cv.matieres||[{mat:cv.matiere,ensId:cv.enseignantId,col:cvMatColor(cv.matiere)}];

  // Build timetable grid
  var grid='<div style="overflow-x:auto"><div class="edt-grid" style="grid-template-columns:80px repeat('+DAYS_FR.length+',1fr)">';
  // Headers
  grid+='<div class="edt-hd" style="background:#0f172a;color:rgba(255,255,255,.6)">Horaire</div>';
  DAYS_FR.forEach(function(d){grid+='<div class="edt-hd" style="background:#0f172a;color:#FFC93C">'+d+'</div>';});
  // Rows
  TIME_SLOTS.forEach(function(slot){
    grid+='<div class="edt-slot" style="background:#1e293b;color:rgba(255,255,255,.5);font-size:10px;display:flex;align-items:center;justify-content:center;text-align:center;padding:4px">'+slot.replace('–','<br>')+'</div>';
    DAYS_FR.forEach(function(day){
      var course=cv.edt.find(function(e){return e.day===day&&e.slot===slot;});
      grid+='<div class="edt-slot" style="background:'+(course?'#0f172a':'#1a2332')+';cursor:pointer" onclick="cvEdtToggle(\''+cvId+'\',\''+day+'\',\''+slot+'\')">';
      if(course){
        grid+='<div class="edt-course" style="background:'+course.col+';color:#fff;font-size:10px;padding:4px 6px;border-radius:6px;height:100%">';
        grid+='<div style="font-weight:800">'+course.mat+'</div>';
        grid+='<div style="opacity:.7;margin-top:1px">'+course.ens+'</div>';
        grid+='</div>';
      }
      grid+='</div>';
    });
  });
  grid+='</div></div>';

  M('📅 Emploi du Temps — '+cv.nom,'Cliquez sur une case pour ajouter / supprimer un cours',
    '<div class="ib ibt mb12"><span>💡</span><span>'+matieres.length+' matière(s) disponible(s) · Sélectionnez la matière puis cliquez sur les créneaux.</span></div>'+
    '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px">'
    +matieres.map(function(m){return '<button onclick="window._edtMat=\''+m.mat+'\';window._edtEns=\''+m.ensId+'\';window._edtCol=\''+m.col+'\';[].forEach.call(document.querySelectorAll(\'.edt-mat-btn\'),function(b){b.style.opacity=\'.4\'});this.style.opacity=\'1\'" class="edt-mat-btn" style="background:'+m.col+';color:#fff;border:none;border-radius:10px;padding:6px 14px;font-size:12px;font-weight:700;cursor:pointer;opacity:.5">'+m.mat+'</button>';}).join('')
    +'</div>'+grid,
    '<button class="btn bo" onclick="cm()">Fermer</button><button class="btn bi" onclick="cvEdtSave(\''+cvId+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-save"/></svg>Sauvegarder</button>',true
  );
  // Pre-select first subject
  setTimeout(function(){var b=document.querySelector('.edt-mat-btn');if(b)b.click();},80);
}

window._edtMat=''; window._edtEns=''; window._edtCol='';
function cvEdtToggle(cvId,day,slot){
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});if(!cv)return;
  if(!cv.edt)cv.edt=[];
  var idx=cv.edt.findIndex(function(e){return e.day===day&&e.slot===slot;});
  if(idx>=0){cv.edt.splice(idx,1);}
  else if(window._edtMat){
    var t=(DB.teachers||[]).find(function(x){return x.id===window._edtEns;})||{};
    cv.edt.push({day:day,slot:slot,mat:window._edtMat,ensId:window._edtEns,ens:(t.pre||'').charAt(0)+'. '+(t.nom||'?'),col:window._edtCol||'#3C8DFF'});
  } else {toast('Sélectionnez une matière d\'abord','warn');return;}
  save();cvAdminEDT(cvId);
}
function cvEdtSave(cvId){save();cm();re();toast('✅ Emploi du temps sauvegardé');}

