function renderCVRoom(cvId){
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});if(!cv)return;
  var matieres=cv.matieres||[{mat:cv.matiere||'Général',ensId:cv.enseignantId,col:cvMatColor(cv.matiere||'Général')}];
  var matIdx=window._cvMatIdx||0;
  var curMat=matieres[matIdx]||matieres[0];
  var tab=window._cvTab||'chat';

  // Déterminer rôle de l'utilisateur dans cette salle
  var isEns=SES&&(SES.type==='enseignant'&&matieres.find(function(m){return m.ensId===SES.tid;}));
  var isAdmin=SES&&(SES.type==='admin'||SES.type==='superadmin');
  var canPost=isEns||isAdmin;

  var html='<div class="cv-room" id="cvRoom_'+cvId+'">';

  // ── SIDEBAR ──
  html+='<div class="cv-sidebar">';
  html+='<div class="cv-sidebar-hd">';
  html+='<div class="cv-sidebar-nm">'+cv.nom+'</div>';
  html+='<div class="cv-sidebar-sub">'+cv.classe+' · '+cv.eleves.length+' élève(s)</div>';
  html+='</div>';
  // Onglets sidebar
  html+='<div class="cv-tabs">';
  ['📖 Matières','👥 Membres','📅 EDT'].forEach(function(t,i){html+='<button class="cv-tab'+(i===0?' on':'')+'" onclick="cvRoomSideTab(this,'+i+',\''+cvId+'\')">'+t+'</button>';});
  html+='</div>';
  // Liste matières
  html+='<div class="cv-mat-list" id="cvSideContent_'+cvId+'">';
  matieres.forEach(function(m,mi){
    var t=(DB.teachers||[]).find(function(x){return x.id===m.ensId;})||{};
    html+='<div class="cv-mat-item'+(mi===matIdx?' on':'')+'" onclick="window._cvMatIdx='+mi+';window._cvTab=\'chat\';renderCVRoom(\''+cvId+'\')">';
    html+='<div style="display:flex;align-items:center;gap:8px">';
    html+='<div class="cv-mat-ico" style="background:'+m.col+'22"><span style="font-size:14px">'+_cvMatIco(m.mat)+'</span></div>';
    html+='<div><div class="cv-mat-nm">'+m.mat+'</div><div class="cv-mat-ens">'+(t.pre||'')+' '+(t.nom||'')+'</div></div>';
    html+='</div>';
    var msgs=(DB.cvMessages||[]).filter(function(msg){return msg.cvId===cvId&&msg.mat===m.mat;});
    if(msgs.length)html+='<div style="font-size:10px;color:rgba(255,255,255,.35);margin-top:4px">'+msgs.length+' message(s)</div>';
    html+='</div>';
  });
  html+='</div>';
  // Footer sidebar
  html+='<div style="padding:10px;border-top:1px solid rgba(255,255,255,.07)">';
  html+='<button onclick="cm()" style="width:100%;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.6);border-radius:10px;padding:7px;font-size:11px;cursor:pointer">✕ Fermer la salle</button>';
  html+='</div>';
  html+='</div>'; // end sidebar

  // ── MAIN ──
  html+='<div class="cv-main">';
  // Header
  html+='<div class="cv-main-hd">';
  html+='<div><div class="cv-main-title">'+_cvMatIco(curMat.mat)+' '+curMat.mat+'</div>';
  var tEns=(DB.teachers||[]).find(function(x){return x.id===curMat.ensId;})||{};
  html+='<div class="cv-main-sub">Prof. '+(tEns.pre||'')+' '+(tEns.nom||'—')+' · '+cv.classe+'</div></div>';
  html+='<div style="display:flex;gap:8px">';
  ['💬 Chat','📝 Sujets','📅 EDT'].forEach(function(t){
    var tKey=t.split(' ')[1].toLowerCase();
    html+='<button onclick="window._cvTab=\''+tKey+'\';renderCVRoom(\''+cvId+'\')" style="padding:5px 12px;border-radius:10px;border:none;font-size:12px;font-weight:700;cursor:pointer;background:'+(tab===tKey?curMat.col:'var(--bg2)')+';color:'+(tab===tKey?'#fff':'var(--ink3)')+'">'+t+'</button>';
  });
  html+='</div></div>';

  // Body content
  html+='<div class="cv-body" id="cvBody_'+cvId+'">';

  if(tab==='chat'){
    var msgs=(DB.cvMessages||[]).filter(function(m){return m.cvId===cvId&&m.mat===curMat.mat;});
    if(!msgs.length){
      html+='<div style="flex:1;display:flex;align-items:center;justify-content:center;flex-direction:column;color:var(--ink4);gap:8px"><div style="font-size:40px">💬</div><div style="font-size:14px;font-weight:600">Démarrez la discussion en '+curMat.mat+'</div><div style="font-size:12px">Les messages apparaissent ici en temps réel</div></div>';
    } else {
      msgs.forEach(function(msg){
        var meSes=SES&&(msg.auteurId===SES.id||msg.auteurId===SES.tid||msg.auteurId===SES.sid);
        var isEnsMsg=msg.role==='enseignant';
        var cls=msg.type==='system'?'cv-msg-sys':meSes?'cv-msg-me':isEnsMsg?'cv-msg-ens':'cv-msg-other';
        html+='<div style="display:flex;flex-direction:column">';
        if(!meSes&&msg.type!=='system')html+='<div style="font-size:10px;color:var(--ink4);margin-bottom:2px;padding:0 4px">'+msg.auteur+'</div>';
        html+='<div class="cv-msg '+cls+'">';
        if(msg.fichierData){html+='<div style="margin-bottom:6px"><a href="'+msg.fichierData+'" download="'+msg.fichierNom+'" style="background:rgba(255,255,255,.2);padding:4px 10px;border-radius:8px;font-size:11px;color:inherit;text-decoration:none">📎 '+msg.fichierNom+'</a></div>';}
        if(msg.text)html+=msg.text;
        html+='<div class="cv-msg-ts">'+msg.heure+'</div>';
        html+='</div></div>';
      });
    }
  } else if(tab==='sujets'){
    var sujetsM=(cv.sujets||[]).filter(function(s){return !s.mat||s.mat===curMat.mat;});
    if(!sujetsM.length){
      html+='<div class="empty"><div class="empty-ico">📝</div>Aucun sujet publié en '+curMat.mat+'.</div>';
    }
    sujetsM.slice().reverse().forEach(function(sj){
      var nbSoum=(DB.cvSoumissions||[]).filter(function(s){return s.sujetId===sj.id;}).length;
      html+='<div class="cv-sujet-card">';
      html+='<div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:8px">';
      html+='<div><div style="font-weight:700;font-size:14px">'+sj.titre+'</div><div style="font-size:11px;color:var(--ink4)">'+sj.type+' · Limite: '+sj.dateLimite+' · '+nbSoum+' soumission(s)</div></div>';
      html+='<div style="display:flex;gap:6px">';
      if(canPost)html+='<button class="btn bi xs" onclick="cvTeacherCorrections(\''+cvId+'\',\''+sj.id+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-pencil"/></svg>Corriger</button>';
      if(canPost||isAdmin)html+='<button class="btn bo xs" onclick="cvAdminAddSujet(\''+cvId+'\',\''+curMat.mat+'\')">＋ Sujet</button>';
      html+='</div></div>';
      if(sj.desc)html+='<div style="font-size:12px;color:var(--ink3);line-height:1.5">'+sj.desc+'</div>';
      html+='</div>';
    });
    if(canPost||isAdmin)html+='<button class="btn bi sm" onclick="cvAdminAddSujet(\''+cvId+'\',\''+curMat.mat+'\')">＋ Publier un sujet en '+curMat.mat+'</button>';
  } else if(tab==='edt'){
    html+=_buildEDTView(cv);
  }

  html+='</div>'; // end cv-body

  // Footer chat input
  if(tab==='chat'){
    html+='<div class="cv-chat-footer">';
    html+='<div style="display:flex;flex-direction:column;gap:6px;flex:1">';
    html+='<div style="display:flex;gap:6px;align-items:flex-end">';
    html+='<textarea class="cv-chat-input" id="cvChatInput_'+cvId+'" placeholder="Message en '+curMat.mat+'… (Entrée = envoyer, Maj+Entrée = saut de ligne)" rows="1" onkeydown="if(event.key===\'Enter\'&&!event.shiftKey){event.preventDefault();cvSendMsg(\''+cvId+'\',\''+curMat.mat+'\')}" oninput="this.style.height=\'auto\';this.style.height=Math.min(this.scrollHeight,100)+\'px\'"></textarea>';
    html+='<button class="cv-send" onclick="cvSendMsg(\''+cvId+'\',\''+curMat.mat+'\')">➤</button>';
    html+='</div>';
    html+='<div style="display:flex;gap:6px">';
    html+='<label style="cursor:pointer;background:var(--bg2);border:1px solid var(--bg3);border-radius:8px;padding:4px 10px;font-size:11px;color:var(--ink3)">📎 Fichier<input type="file" style="display:none" accept=".pdf,.doc,.docx,image/*" onchange="cvAttachFile(this,\''+cvId+'\',\''+curMat.mat+'\')"></label>';
    if(canPost)html+='<button onclick="cvSendSystemMsg(\''+cvId+'\',\''+curMat.mat+'\')" style="background:var(--pub);border:1px solid var(--pud);color:var(--pu);border-radius:8px;padding:4px 10px;font-size:11px;cursor:pointer;font-weight:700">📢 Annonce</button>';
    html+='</div>';
    html+='</div></div>'; // end footer
  }

  html+='</div>'; // end cv-main
  html+='</div>'; // end cv-room

  var cnt=document.getElementById('cnt');
  if(cnt){cnt.innerHTML=html;cnt.scrollTop=0;}
  // Scroll chat to bottom
  setTimeout(function(){var body=document.getElementById('cvBody_'+cvId);if(body)body.scrollTop=body.scrollHeight;},80);
  // Auto-refresh every 4 sec for "real-time"
  clearInterval(window._cvRefreshTimer);
  window._cvRefreshTimer=setInterval(function(){
    if(window._cvRoomId===cvId&&window._cvTab==='chat')renderCVRoom(cvId);
  },4000);
}

function _cvMatIco(mat){var m={'Mathématiques':'📐','Français':'📖','Anglais':'🌍','SVT':'🧬','Physique-Chimie':'⚗️','Histoire-Géographie':'🗺️','Philosophie':'💭','Informatique':'💻','Économie':'📊','EPS':'⚽'};return m[mat]||'📚';}

function _buildEDTView(cv){
  if(!cv.edt||!cv.edt.length)return '<div class="empty"><div class="empty-ico">📅</div>Aucun cours planifié.<br><span style="font-size:12px;color:var(--ink4)">L\'administrateur peut créer l\'emploi du temps.</span></div>';
  var matieres=cv.matieres||[{mat:cv.matiere,col:cvMatColor(cv.matiere)}];
  var h='<div style="overflow-x:auto"><div class="edt-grid" style="grid-template-columns:80px repeat('+DAYS_FR.length+',1fr);background:#e5e7eb">';
  h+='<div class="edt-hd">Horaire</div>';
  DAYS_FR.forEach(function(d){h+='<div class="edt-hd">'+d+'</div>';});
  TIME_SLOTS.forEach(function(slot){
    h+='<div class="edt-slot" style="font-size:9px;color:var(--ink4);text-align:center">'+slot.replace('–','<br>')+'</div>';
    DAYS_FR.forEach(function(day){
      var course=cv.edt.find(function(e){return e.day===day&&e.slot===slot;});
      h+='<div class="edt-slot">';
      if(course){
        h+='<div class="edt-course" style="background:'+course.col+';color:#fff">'+
          '<div style="font-size:10px;font-weight:800">'+course.mat+'</div>'+
          '<div style="font-size:9px;opacity:.75">'+course.ens+'</div></div>';
      }
      h+='</div>';
    });
  });
  h+='</div></div>';
  // Légende
  h+='<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">';
  matieres.forEach(function(m){h+='<span style="background:'+m.col+'22;border:1px solid '+m.col+'44;color:'+m.col+';padding:3px 10px;border-radius:8px;font-size:11px;font-weight:700">'+_cvMatIco(m.mat)+' '+m.mat+'</span>';});
  h+='</div>';
  return h;
}

function cvRoomSideTab(btn,idx,cvId){
  document.querySelectorAll('.cv-tab').forEach(function(b){b.classList.remove('on');});
  btn.classList.add('on');
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});if(!cv)return;
  var sc=document.getElementById('cvSideContent_'+cvId);if(!sc)return;
  if(idx===0){
    // Matières
    var matieres=cv.matieres||[{mat:cv.matiere,ensId:cv.enseignantId,col:cvMatColor(cv.matiere)}];
    var mi=window._cvMatIdx||0;
    sc.innerHTML=matieres.map(function(m,i){
      var t=(DB.teachers||[]).find(function(x){return x.id===m.ensId;})||{};
      return '<div class="cv-mat-item'+(i===mi?' on':'')+'" onclick="window._cvMatIdx='+i+';window._cvTab=\'chat\';renderCVRoom(\''+cvId+'\')">'+
        '<div style="display:flex;align-items:center;gap:8px">'+
        '<div class="cv-mat-ico" style="background:'+m.col+'22">'+_cvMatIco(m.mat)+'</div>'+
        '<div><div class="cv-mat-nm">'+m.mat+'</div><div class="cv-mat-ens">'+(t.pre||'')+' '+(t.nom||'')+'</div></div></div></div>';
    }).join('');
  } else if(idx===1){
    // Membres
    var eleves=(cv.eleves||[]).map(function(eid){return DB.students.find(function(s){return s.id===eid;});}).filter(Boolean);
    sc.innerHTML='<div style="padding:6px"><div style="font-size:10px;color:rgba(255,255,255,.4);text-transform:uppercase;letter-spacing:1px;margin-bottom:8px;padding:0 6px">'+eleves.length+' Élèves</div>'+
      eleves.map(function(s){return '<div style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:8px"><div class="cv-online-dot"></div><div style="font-size:12px;color:rgba(255,255,255,.8);font-weight:600">'+s.pre+' '+s.nom+'</div></div>';}).join('')+'</div>';
  } else {
    // EDT aperçu
    var edtH=_buildEDTView(cv);
    sc.innerHTML='<div style="padding:8px;max-height:400px;overflow-y:auto">'+edtH+'</div>';
  }
}

// ── ENVOI DE MESSAGES CHAT ────────────────────────────────────────────────────
function cvSendMsg(cvId,mat){
  var inp=document.getElementById('cvChatInput_'+cvId);
  var txt=(inp&&inp.value||'').trim();
  if(!txt){return;}
  if(!DB.cvMessages)DB.cvMessages=[];
  var auteur=SES?(SES.pre||'')+' '+(SES.nom||SES.name||''):'Anonyme';
  var auteurId=SES&&(SES.id||SES.tid||SES.sid)||'?';
  var role=SES&&(SES.type==='enseignant'?'enseignant':'eleve')||'visiteur';
  var now=new Date();
  DB.cvMessages.push({
    id:'msg_'+Date.now()+'_'+Math.random().toString(36).slice(2,6),
    cvId:cvId,mat:mat,
    auteur:auteur.trim(),auteurId:auteurId,role:role,
    text:txt.replace(/</g,'&lt;').replace(/>/g,'&gt;'),
    heure:now.getHours().toString().padStart(2,'0')+':'+now.getMinutes().toString().padStart(2,'0'),
    date:today(),type:'message'
  });
  save();
  if(inp)inp.value='';
  renderCVRoom(cvId);
}

function cvSendSystemMsg(cvId,mat){
  M('📢 Message Annonce','Visible par tous les élèves du groupe',
    '<textarea class="fi" id="sysAnnonce" rows="4" placeholder="Ex: Cours annulé demain — Devoir à rendre vendredi"></textarea>',
    '<button class="btn bi" onclick="(function(){var t=(document.getElementById(\'sysAnnonce\')?.value||\'\'). trim();if(!t)return;if(!DB.cvMessages)DB.cvMessages=[];var now=new Date();DB.cvMessages.push({id:\'msg_\'+Date.now(),cvId:\''+cvId+'\',mat:\''+mat+'\',auteur:(SES?SES.pre+\' \'+SES.nom:\'Admin\'),auteurId:\'system\',role:\'enseignant\',text:\'📢 \'+t,heure:now.getHours().toString().padStart(2,\'0\')+\':\'+now.getMinutes().toString().padStart(2,\'0\'),date:today(),type:\'system\'});save();cm();renderCVRoom(\''+cvId+'\');toast(\'Annonce publiée\');})()">📢 Publier</button><button class="btn bo" onclick="cm()">Annuler</button>'
  );
}

function cvAttachFile(inp,cvId,mat){
  if(!inp.files[0])return;
  var f=inp.files[0];
  if(f.size>20*1024*1024){toast('Max 20 Mo','warn');return;}
  toast('⏳ Chargement du fichier…');
  var r=new FileReader();
  r.onload=function(e){
    if(!DB.cvMessages)DB.cvMessages=[];
    var auteur=SES?(SES.pre||'')+' '+(SES.nom||''):' Anonyme';
    var auteurId=SES&&(SES.id||SES.tid||SES.sid)||'?';
    var role=SES&&SES.type==='enseignant'?'enseignant':'eleve';
    var now=new Date();
    DB.cvMessages.push({
      id:'msg_'+Date.now(),cvId:cvId,mat:mat,
      auteur:auteur.trim(),auteurId:auteurId,role:role,
      text:'',fichierData:e.target.result,fichierNom:f.name,
      heure:now.getHours().toString().padStart(2,'0')+':'+now.getMinutes().toString().padStart(2,'0'),
      date:today(),type:'file'
    });
    save();renderCVRoom(cvId);toast('✅ Fichier partagé : '+f.name);
  };
  r.readAsDataURL(f);
}

// ── AJOUTER SUJET DEPUIS LA SALLE ─────────────────────────────────────────────
function cvAdminAddSujet(cvId,mat){
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});if(!cv)return;
  var tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+7);
  var dl=tomorrow.toISOString().split('T')[0];
  M('📝 Nouveau Sujet — '+mat,cv.nom,
    '<div class="fg2">'+
    '<div class="fg full"><span class="fl">Titre *</span><input class="fi" id="assTitre" placeholder="Ex: Épreuve Séquence 3"></div>'+
    '<div class="fg"><span class="fl">Type</span><select class="fi" id="assType"><option>Épreuve</option><option>Exercice</option><option>Devoir maison</option><option>Révision</option></select></div>'+
    '<div class="fg"><span class="fl">Date limite *</span><input class="fi" id="assDate" type="date" value="'+dl+'"></div>'+
    '<div class="fg full"><span class="fl">Consignes</span><textarea class="fi" id="assDesc" rows="3"></textarea></div>'+
    '<div class="fg full"><span class="fl">Fichier PDF / Word (max 20 Mo)</span>'+
    '<input type="file" class="fi" id="assFile" accept=".pdf,.doc,.docx" style="padding:7px" onchange="_sjLoadFile(this)">'+
    '<div id="sjFilePreview" style="font-size:12px;color:var(--gr);margin-top:4px"></div></div>'+
    '<div class="fg"><span class="fl">Note sur</span><input class="fi" id="assNoteSur" type="number" value="20" min="5" max="100"></div>'+
    '</div>',
    '<button class="btn bi" onclick="cvAdminSaveSujet(\''+cvId+'\',\''+mat+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-upload"/></svg>Publier</button><button class="btn bo" onclick="cm()">Annuler</button>'
  );
}
function cvAdminSaveSujet(cvId,mat){
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});if(!cv)return;
  var titre=(document.getElementById('assTitre')?.value||'').trim();
  if(!titre){toast('Titre requis','warn');return;}
  var dl=document.getElementById('assDate')?.value;
  if(!dl){toast('Date limite requise','warn');return;}
  if(!cv.sujets)cv.sujets=[];
  cv.sujets.push({
    id:cvId+'_sj_'+gid(),titre:titre,mat:mat,
    type:document.getElementById('assType')?.value||'Épreuve',
    dateLimite:dl,desc:document.getElementById('assDesc')?.value||'',
    fichier:window._sjFileName||'',fichierData:window._sjFileData||'',fichierType:window._sjFileMime||'',
    coef:1,noteSur:parseInt(document.getElementById('assNoteSur')?.value)||20,
    datePublication:today(),enseignantId:SES&&SES.tid
  });
  window._sjFileData='';window._sjFileName='';window._sjFileMime='';
  save();cm();toast('✅ Sujet publié pour '+cv.eleves.length+' élève(s)');
  window._cvTab='sujets';renderCVRoom(cvId);
}

function cvAdminSave(){
  var nom=(document.getElementById('cvNom')?.value||'').trim();
  if(!nom){toast('Nom requis','warn');return;}
  if(!DB.classesVirtuelles) DB.classesVirtuelles=[];
  var cv={
    id:cvId(),
    nom:nom,
    classe:document.getElementById('cvCls')?.value||'',
    matiere:document.getElementById('cvMat')?.value||'',
    enseignantId:document.getElementById('cvEns')?.value||'',
    planRequis:document.getElementById('cvPlan')?.value||'gratuit',
    desc:document.getElementById('cvDesc')?.value||'',
    capacite:parseInt(document.getElementById('cvCap')?.value)||30,
    eleves:[],
    sujets:[],
    dateCreation:today(),
    statut:'active'
  };
  // Auto-ajouter élèves de la classe selon le plan
  var plan=cv.planRequis;
  (DB.students||[]).filter(function(s){return s.cls===cv.classe;}).forEach(function(s){
    if(plan==='gratuit'||studentHasPlan(s.id,plan)){
      if(!cv.eleves.includes(s.id)) cv.eleves.push(s.id);
    }
  });
  DB.classesVirtuelles.push(cv);
  save();cm();re();
  toast('✅ Classe virtuelle créée avec '+cv.eleves.length+' élèves');
}

function cvAdminEditCV(idx){
  var cv=DB.classesVirtuelles[idx];
  if(!cv)return;
  var planOpts='<option value="gratuit"'+(cv.planRequis==='gratuit'?' selected':'')+'>Gratuit</option>'+((DB.elearning&&DB.elearning.plans)||[]).map(function(p){return '<option value="'+p.id+'"'+(cv.planRequis===p.id?' selected':'')+'>'+p.nom+'</option>';}).join('');
  M('Modifier la classe virtuelle',cv.nom,
    '<div class="fg2">'+
    '<div class="fg full"><span class="fl">Nom</span><input class="fi" id="cvENom" value="'+cv.nom+'"></div>'+
    '<div class="fg"><span class="fl">Statut</span><select class="fi" id="cvEStat"><option value="active"'+(cv.statut==='active'?' selected':'')+'>Active</option><option value="suspendue"'+(cv.statut==='suspendue'?' selected':'')+'>Suspendue</option><option value="archivee"'+(cv.statut==='archivee'?' selected':'')+'>Archivée</option></select></div>'+
    '<div class="fg"><span class="fl">Plan requis</span><select class="fi" id="cvEPlan">'+planOpts+'</select></div>'+
    '<div class="fg full"><span class="fl">Description</span><textarea class="fi" id="cvEDesc" rows="3">'+cv.desc+'</textarea></div>'+
    '</div>',
    '<button class="btn bi" onclick="cvAdminUpdate('+idx+')"><svg class="vico bico" aria-hidden="true"><use href="#lc-save"/></svg>Mettre à jour</button><button class="btn bo" onclick="cm()">Annuler</button>'
  );
}
function cvAdminUpdate(idx){
  var cv=DB.classesVirtuelles[idx];if(!cv)return;
  cv.nom=document.getElementById('cvENom')?.value||cv.nom;
  cv.statut=document.getElementById('cvEStat')?.value||'active';
  cv.planRequis=document.getElementById('cvEPlan')?.value||'gratuit';
  cv.desc=document.getElementById('cvEDesc')?.value||'';
  save();cm();re();toast('✅ Classe mise à jour');
}
function cvAdminDelete(cvId){
  if(!confirm('Supprimer cette classe virtuelle ?'))return;
  DB.classesVirtuelles=(DB.classesVirtuelles||[]).filter(function(c){return c.id!==cvId;});
  save();re();toast('Classe supprimée');
}

function cvAdminManageEleves(cvId){
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});
  if(!cv)return;
  var plan=cv.planRequis;
  var eligibles=(DB.students||[]).filter(function(s){
    return s.cls===cv.classe&&(plan==='gratuit'||studentHasPlan(s.id,plan));
  });
  var autres=(DB.students||[]).filter(function(s){
    return s.cls===cv.classe&&!eligibles.includes(s);
  });

  var eligH=eligibles.map(function(s){
    var dans=cv.eleves.includes(s.id);
    return '<div class="fl2 fic fsb" style="padding:7px 0;border-bottom:1px solid var(--bg2)">'+
      '<div><div style="font-size:13px;font-weight:600">'+s.nom+' '+s.pre+'</div><div style="font-size:11px;color:var(--ink4)">'+s.mat+' · '+s.cls+'</div></div>'+
      '<button class="btn '+(dans?'br2':'bi')+' xs" onclick="cvToggleEleve(\''+cvId+'\',\''+s.id+'\')">'+( dans?'Retirer':'Ajouter')+'</button>'+
      '</div>';
  }).join('');

  var autresH=autres.length?'<div class="ib ibi mt12 mb0"><span>🔒</span><span>'+autres.length+' élève(s) sans le plan requis ('+plan+'). Mettez à jour leurs abonnements pour les ajouter.</span></div>':'';

  M('Gérer les élèves — '+cv.nom,'Classe: '+cv.classe+' · '+cv.eleves.length+'/'+cv.capacite+' élèves',
    '<div style="font-weight:700;font-size:13px;margin-bottom:10px">Élèves éligibles ('+eligibles.length+')</div>'+
    (eligH||'<div class="empty"><div class="empty-ico">👥</div>Aucun élève éligible dans cette classe</div>')+
    autresH,
    '<button class="btn bi" onclick="cvAdminAddAll(\''+cvId+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-checkcircle"/></svg>Tout ajouter</button><button class="btn bo" onclick="cm()">Fermer</button>'
  );
}
function cvToggleEleve(cvId,sid){
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});
  if(!cv)return;
  if(cv.eleves.includes(sid)) cv.eleves=cv.eleves.filter(function(x){return x!==sid;});
  else if(cv.eleves.length<cv.capacite) cv.eleves.push(sid);
  else{toast('Capacité max atteinte ('+cv.capacite+')', 'warn');return;}
  save();cvAdminManageEleves(cvId);toast('✅ Mis à jour');
}
function cvAdminAddAll(cvId){
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});
  if(!cv)return;
  var plan=cv.planRequis;
  (DB.students||[]).filter(function(s){
    return s.cls===cv.classe&&(plan==='gratuit'||studentHasPlan(s.id,plan));
  }).forEach(function(s){
    if(!cv.eleves.includes(s.id)&&cv.eleves.length<cv.capacite) cv.eleves.push(s.id);
  });
  save();cvAdminManageEleves(cvId);toast('✅ Élèves ajoutés: '+cv.eleves.length);
}

function cvAdminViewSujets(cvId){
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});
  if(!cv)return;
  var sujets=cv.sujets||[];
  var rows=sujets.map(function(s,i){
    var nbSoum=(DB.cvSoumissions||[]).filter(function(sb){return sb.sujetId===s.id;}).length;
    var nbCorr=(DB.cvSoumissions||[]).filter(function(sb){return sb.sujetId===s.id&&sb.note!==undefined&&sb.note!==null;}).length;
    return '<tr><td class="semi">'+s.titre+'</td><td>'+s.matiere+'</td>'+
      '<td><span class="bg bgd" style="font-size:11px">'+s.dateLimite+'</span></td>'+
      '<td style="text-align:center">'+nbSoum+'</td>'+
      '<td style="text-align:center;color:var(--gr);font-weight:700">'+nbCorr+'</td>'+
      '<td><button class="btn bo xs" onclick="cvViewSoumissions(\''+s.id+'\',\''+cv.id+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-clipboard"/></svg>Voir soumissions</button></td></tr>';
  }).join('');
  M('Sujets — '+cv.nom,'',
    '<div class="tw"><table><thead><tr><th>Titre</th><th>Matière</th><th>Date limite</th><th>Soumissions</th><th>Corrigés</th><th></th></tr></thead><tbody>'+
    (rows||'<tr><td colspan="6"><div class="empty"><div class="empty-ico">📝</div>Aucun sujet</div></td></tr>')+
    '</tbody></table></div>',
    '<button class="btn bo" onclick="cm()">Fermer</button>','',true
  );
}

// ── GROUPES WHATSAPP ─────────────────────────────────────────────────────────
function pgWAGroupes(){
  if(!DB.waGroupes) DB.waGroupes=[];
  autoCreateWAGroups();
  var h='<div style="margin-top:12px">';
  h+='<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px">';
  DB.waGroupes.forEach(function(grp){
    var membres=(grp.membres||[]).map(function(mid){
      return DB.students.find(function(s){return s.id===mid;});
    }).filter(Boolean);
    var tel=membres.slice(0,3).map(function(s){
      return s.ptel||s.tel||'';
    }).filter(Boolean);
    // Génération lien WhatsApp group
    var waText=encodeURIComponent('🎓 Bienvenue dans le groupe VÉRITAS — '+grp.classe+' !\n\nCe groupe est réservé aux élèves et parents de la classe de '+grp.classe+'.\n\n📚 Informations scolaires, devoirs, examens.\n\nAdministration VÉRITAS');
    var waLink='https://wa.me/'+((DB.school&&DB.school.tel||'237656720476').replace(/[^0-9]/g,''))+'?text='+waText;
    h+='<div style="background:linear-gradient(135deg,#25d366,#128C7E);border-radius:14px;padding:14px;color:#fff;position:relative">';
    h+='<div style="font-family:Montserrat,sans-serif;font-size:13px;font-weight:700;margin-bottom:4px">'+grp.nom+'</div>';
    h+='<div style="font-size:11px;opacity:.8;margin-bottom:10px">'+membres.length+' membre(s)</div>';
    if(grp.lien){
      h+='<a href="'+grp.lien+'" target="_blank" style="display:inline-flex;align-items:center;gap:5px;background:rgba(255,255,255,.2);color:#fff;padding:5px 12px;border-radius:20px;font-size:11px;font-weight:700;text-decoration:none;margin-bottom:6px">🔗 Rejoindre le groupe</a><br>';
    }
    h+='<div style="display:flex;gap:6px;flex-wrap:wrap">';
    h+='<button onclick="waSetLink(\''+grp.id+'\')" style="background:rgba(255,255,255,.2);border:none;color:#fff;padding:4px 10px;border-radius:12px;font-size:10px;font-weight:700;cursor:pointer">🔗 Lien groupe</button>';
    h+='<a href="'+waLink+'" target="_blank" style="background:rgba(255,255,255,.2);border:none;color:#fff;padding:4px 10px;border-radius:12px;font-size:10px;font-weight:700;cursor:pointer;text-decoration:none;display:inline-block">📤 Inviter tous</a>';
    h+='<button onclick="waViewMembres(\''+grp.id+'\')" style="background:rgba(255,255,255,.2);border:none;color:#fff;padding:4px 10px;border-radius:12px;font-size:10px;font-weight:700;cursor:pointer">👥 Membres</button>';
    h+='</div>';
    h+='</div>';
  });
  h+='</div></div>';
  return h;
}

function waSetLink(grpId){
  var grp=DB.waGroupes.find(function(g){return g.id===grpId;});if(!grp)return;
  M('Lien du groupe WhatsApp',grp.nom,
    '<div class="ib ibt mb12"><span>💡</span><span>Créez d\'abord votre groupe WhatsApp manuellement, puis collez ici le lien d\'invitation généré (Paramètres → Lien d\'invitation du groupe).</span></div>'+
    '<div class="fg"><span class="fl">Lien d\'invitation WhatsApp</span><input class="fi" id="waLienInput" value="'+(grp.lien||'')+'" placeholder="https://chat.whatsapp.com/..."></div>',
    '<button class="btn bi" onclick="waSaveLink(\''+grpId+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-save"/></svg>Enregistrer</button><button class="btn bo" onclick="cm()">Annuler</button>'
  );
}
function waSaveLink(grpId){
  var grp=DB.waGroupes.find(function(g){return g.id===grpId;});if(!grp)return;
  grp.lien=(document.getElementById('waLienInput')?.value||'').trim();
  save();cm();re();toast('✅ Lien enregistré');
}
function waViewMembres(grpId){
  var grp=DB.waGroupes.find(function(g){return g.id===grpId;});if(!grp)return;
  var membres=(grp.membres||[]).map(function(mid){return DB.students.find(function(s){return s.id===mid;});}).filter(Boolean);
  var rows=membres.map(function(s){
    var tel=s.ptel||s.tel||'—';
    var waLink='https://wa.me/'+(tel.replace(/[^0-9]/g,''));
    return '<tr><td class="semi">'+s.nom+' '+s.pre+'</td><td>'+s.mat+'</td><td>'+tel+'</td>'+
      '<td><a href="'+waLink+'" target="_blank" class="btn bvi xs"><svg class="vico bico" aria-hidden="true"><use href="#lc-message"/></svg>Message</a></td></tr>';
  }).join('');
  M('Membres — '+grp.nom,grp.classe+' · '+membres.length+' élèves',
    '<div class="tw"><table><thead><tr><th>Élève</th><th>Matricule</th><th>Téléphone</th><th>Action</th></tr></thead><tbody>'+
    (rows||'<tr><td colspan="4"><div class="empty">Aucun membre</div></td></tr>')+
    '</tbody></table></div>',
    '<button class="btn bi" onclick="waInviteAll(\''+grpId+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-upload"/></svg>Inviter tous</button><button class="btn bo" onclick="cm()">Fermer</button>','',true
  );
}
function waInviteAll(grpId){
  var grp=DB.waGroupes.find(function(g){return g.id===grpId;});if(!grp)return;
  if(!grp.lien){toast('Ajoutez d\'abord le lien du groupe','warn');return;}
  var msg=encodeURIComponent('🎓 Bonjour ! Rejoignez le groupe WhatsApp VÉRITAS — '+grp.classe+' :\n\n'+grp.lien+'\n\n📚 Cours · Devoirs · Examens · Annonces\n\nAdministration VÉRITAS');
  var membres=(grp.membres||[]).map(function(mid){return DB.students.find(function(s){return s.id===mid;});}).filter(Boolean);
  if(!membres.length){toast('Aucun membre à inviter','warn');return;}
  // Ouvrir WhatsApp pour le premier membre (les autres via clic manuel)
  var tel=(membres[0].ptel||membres[0].tel||'').replace(/[^0-9]/g,'');
  if(tel) window.open('https://wa.me/'+tel+'?text='+msg,'_blank');
  toast('Invitation envoyée ('+membres.length+' membres à contacter)');
}

// ── PAGE: CLASSES VIRTUELLES TEACHER ────────────────────────────────────────
function pgClassesVirtuellesTeacher(){
  var tid=SES&&SES.tid;
  // L'enseignant voit TOUTES les classes où il enseigne au moins une matière
  var cvs=(DB.classesVirtuelles||[]).filter(function(c){
    if(c.enseignantId===tid)return true;
    return (c.matieres||[]).some(function(m){return m.ensId===tid;});
  });

  var h='<div class="fl2 fic fsb mb16 fw g8"><div class="bold" style="font-size:18px">📚 Mes Classes Virtuelles</div></div>';
  if(!cvs.length){
    h+='<div class="empty"><div class="empty-ico">📚</div>Aucune classe virtuelle assignée.<br><span style="font-size:12px;color:var(--ink4)">Contactez l\'administration pour en créer une.</span></div>';
    return h;
  }

  h+='<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:16px">';
  cvs.forEach(function(cv){
    var matieres=cv.matieres||[{mat:cv.matiere||'—',ensId:cv.enseignantId,col:cvMatColor(cv.matiere||'—')}];
    // Filtrer uniquement les matières de cet enseignant
    var mesMatieres=matieres.filter(function(m){return m.ensId===tid;});
    var totalSoums=(DB.cvSoumissions||[]).filter(function(s){
      return (cv.sujets||[]).some(function(sj){return sj.id===s.sujetId;});
    }).length;
    var nonCorr=(DB.cvSoumissions||[]).filter(function(s){
      return (cv.sujets||[]).some(function(sj){return sj.id===s.sujetId;})&&(s.note===null||s.note===undefined);
    }).length;

    h+='<div style="background:var(--sur);border-radius:16px;border:1px solid var(--bg3);overflow:hidden;box-shadow:var(--sh)">';
    // Header avec gradient
    h+='<div style="background:linear-gradient(135deg,#0f172a,#1e3a8a);padding:14px 16px">';
    h+='<div style="font-family:Montserrat,sans-serif;font-size:14px;font-weight:800;color:#fff;margin-bottom:3px">'+cv.nom+'</div>';
    h+='<div style="font-size:11px;color:rgba(255,255,255,.5)">'+cv.classe+' · '+cv.eleves.length+' élève(s)</div>';
    h+='</div>';
    // Mes matières dans ce groupe
    h+='<div style="padding:12px 14px;border-bottom:1px solid var(--bg3)">';
    h+='<div style="font-size:10px;font-weight:700;color:var(--ink4);text-transform:uppercase;letter-spacing:.8px;margin-bottom:8px">Mes matières dans ce groupe</div>';
    h+='<div style="display:flex;flex-wrap:wrap;gap:6px">';
    mesMatieres.forEach(function(m){
      h+='<div style="background:'+m.col+'18;border:1px solid '+m.col+'44;border-radius:10px;padding:5px 12px;display:flex;align-items:center;gap:5px">';
      h+='<span style="font-size:14px">'+_cvMatIco(m.mat)+'</span>';
      h+='<span style="font-size:12px;font-weight:700;color:'+m.col+'">'+m.mat+'</span>';
      h+='</div>';
    });
    h+='</div></div>';
    // Stats rapides
    h+='<div style="display:grid;grid-template-columns:1fr 1fr 1fr;border-bottom:1px solid var(--bg3)">';
    [['📝',(cv.sujets||[]).filter(function(s){return !s.mat||mesMatieres.some(function(m){return m.mat===s.mat;});}).length,'Sujets'],['📤',totalSoums,'Soumis'],['⚠️',nonCorr,'À corriger']].forEach(function(x){
      h+='<div style="padding:10px;text-align:center"><div style="font-size:16px">'+x[0]+'</div><div style="font-family:monospace;font-size:16px;font-weight:700;color:var(--ink)">'+x[1]+'</div><div style="font-size:10px;color:var(--ink4)">'+x[2]+'</div></div>';
    });
    h+='</div>';
    // Actions
    h+='<div style="padding:12px 14px;display:flex;gap:8px;flex-wrap:wrap">';
    h+='<button class="btn bi sm" onclick="window._cvRoomId=\''+cv.id+'\';window._cvMatIdx=0;window._cvTab=\'chat\';renderCVRoom(\''+cv.id+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-presentation"/></svg>Ouvrir la salle</button>';
    h+='<button class="btn bvi sm" onclick="cvAdminAddSujet(\''+cv.id+'\',\''+mesMatieres[0].mat+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-pencil"/></svg>Publier sujet</button>';
    if(nonCorr>0)h+='<button class="btn" style="background:var(--reb);color:var(--re);border:1px solid var(--red);border-radius:var(--r);padding:7px 14px;font-size:12px;font-weight:700;cursor:pointer" onclick="cvShowAllCorrections(\''+cv.id+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-alert"/></svg>'+nonCorr+' à corriger</button>';
    h+='</div>';
    h+='</div>';
  });
  h+='</div>';
  return h;
}

function cvShowAllCorrections(cvId){
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});if(!cv)return;
  var tid=SES&&SES.tid;
  var mesSujets=(cv.sujets||[]).filter(function(s){
    if(!tid)return true;
    var m=(cv.matieres||[]).find(function(x){return x.mat===s.mat;});
    return !s.mat||(m&&m.ensId===tid);
  });
  var nonCorr=(DB.cvSoumissions||[]).filter(function(s){
    return mesSujets.some(function(sj){return sj.id===s.sujetId;})&&(s.note===null||s.note===undefined);
  });
  M('⚠️ Soumissions à corriger',cv.nom+' — '+nonCorr.length+' en attente',
    nonCorr.map(function(s){
      var el=DB.students.find(function(x){return x.id===s.eleveId;})||{};
      var sj=mesSujets.find(function(x){return x.id===s.sujetId;})||{};
      return '<div style="background:var(--bg);border-radius:10px;padding:10px;margin-bottom:8px;border:1px solid var(--bg3)">'+
        '<div class="fl2 fic fsb"><div><div class="semi s">'+el.pre+' '+el.nom+'</div><div style="font-size:11px;color:var(--ink4)">'+sj.titre+' · '+(s.mat||sj.mat||'—')+'</div></div>'+
        '<button class="btn bi xs" onclick="cvCorrectSoumission(\''+s.id+'\',\''+s.sujetId+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-pencil"/></svg>Corriger</button></div>'+
        '</div>';
    }).join(''),
    '<button class="btn bo" onclick="cm()">Fermer</button>',true
  );
}

function cvTeacherAddSujet(cvId){
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});
  if(!cv)return;
  var tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+7);
  var dl=tomorrow.toISOString().split('T')[0];
  M('Nouveau Sujet — '+cv.nom,'Publier un sujet, épreuve ou exercice',
    '<div class="fg2">'+
    '<div class="fg full"><span class="fl">Titre du sujet *</span><input class="fi" id="sjTitre" placeholder="Ex: Épreuve Séquence 3 — Algèbre"></div>'+
    '<div class="fg"><span class="fl">Type</span><select class="fi" id="sjType"><option>Épreuve</option><option>Exercice</option><option>Devoir maison</option><option>Révision</option><option>Contrôle</option></select></div>'+
    '<div class="fg"><span class="fl">Date limite de soumission *</span><input class="fi" id="sjDate" type="date" value="'+dl+'"></div>'+
    '<div class="fg full"><span class="fl">Consignes / Énoncé</span><textarea class="fi" id="sjDesc" rows="4" placeholder="Décrivez le travail demandé..."></textarea></div>'+
    '<div class="fg full"><span class="fl">Fichier joint — Épreuve (PDF ou Word, max 20 Mo)</span>'+
    '<input type="file" class="fi" id="sjFileUpload" accept=".pdf,.doc,.docx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document" style="padding:7px" onchange="_sjLoadFile(this)">'+
    '<div id="sjFilePreview" style="font-size:12px;color:var(--ink3);margin-top:4px"></div></div>'+
    '<div class="fg"><span class="fl">Coefficient</span><input class="fi" id="sjCoef" type="number" value="1" min="1" max="10"></div>'+
    '<div class="fg"><span class="fl">Note sur</span><input class="fi" id="sjNoteSur" type="number" value="20" min="5" max="100"></div>'+
    '</div>',
    '<button class="btn bi" onclick="cvTeacherSaveSujet(\''+cvId+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-upload"/></svg>Publier</button><button class="btn bo" onclick="cm()">Annuler</button>'
  );
}

function cvTeacherSaveSujet(cvId){
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});if(!cv)return;
  var titre=(document.getElementById('sjTitre')?.value||'').trim();
  if(!titre){toast('Titre requis','warn');return;}
  var dl=document.getElementById('sjDate')?.value;
  if(!dl){toast('Date limite requise','warn');return;}
  if(!cv.sujets) cv.sujets=[];
  var sj={
    id:cvId+'_sj_'+gid(),
    titre:titre,
    type:document.getElementById('sjType')?.value||'Épreuve',
    dateLimite:dl,
    desc:document.getElementById('sjDesc')?.value||'',
    fichier:window._sjFileName||'',
    fichierData:window._sjFileData||'',
    fichierType:window._sjFileMime||'',
    coef:parseInt(document.getElementById('sjCoef')?.value)||1,
    noteSur:parseInt(document.getElementById('sjNoteSur')?.value)||20,
    datePublication:today(),
    enseignantId:SES&&SES.tid
  };
  window._sjFileData=''; window._sjFileName=''; window._sjFileMime='';
  cv.sujets.push(sj);
  // Notifier les élèves via toast (en production: push/email)
  save();cm();re();
  toast('✅ Sujet publié pour '+cv.eleves.length+' élève(s)');
}

function cvTeacherDeleteSujet(cvId,sjId){
  if(!confirm('Supprimer ce sujet ?'))return;
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});if(!cv)return;
  cv.sujets=(cv.sujets||[]).filter(function(s){return s.id!==sjId;});
  save();re();toast('Sujet supprimé');
}

function cvViewSoumissions(sjId,cvId){
  cvTeacherCorrections(cvId,sjId);
}
function cvTeacherCorrections(cvId,sjId){
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});if(!cv)return;
  var sj=(cv.sujets||[]).find(function(s){return s.id===sjId;});if(!sj)return;
  var soumissions=(DB.cvSoumissions||[]).filter(function(s){return s.sujetId===sjId;});

  // Tous les élèves attendus
  var eleves=cv.eleves.map(function(eid){return DB.students.find(function(s){return s.id===eid;});}).filter(Boolean);

  var rows=eleves.map(function(el){
    var soum=soumissions.find(function(s){return s.eleveId===el.id;});
    if(!soum) return '<tr style="background:var(--reb)"><td class="semi">'+el.nom+' '+el.pre+'</td><td><span class="bg bgr" style="font-size:11px">Non soumis</span></td><td>—</td><td>—</td><td>—</td></tr>';
    var corrige=soum.note!==undefined&&soum.note!==null;
    return '<tr>'+
      '<td class="semi">'+_esc(el.nom)+' '+_esc(el.pre)+'</td>'+
      '<td><span class="bg bgg" style="font-size:11px">'+_esc(soum.dateSoumission||'')+'</span></td>'+
      '<td style="font-size:12px;max-width:200px">'+(soum.contenu?_esc(soum.contenu.substring(0,60))+'...':'')+(soum.fichier?'<br><a href="'+_esc(soum.fichier)+'" target="_blank" style="font-size:11px;color:var(--bl)">📎 Fichier</a>':'')+'</td>'+
      '<td>'+(corrige?'<span class="mono bold" style="color:var(--gr)">'+soum.note+'/'+sj.noteSur+'</span>':'<span class="bg bgd" style="font-size:11px">À corriger</span>')+'</td>'+
      '<td><button class="btn bi xs" onclick="cvCorrectSoumission(\''+soum.id+'\',\''+sjId+'\')">'+( corrige?'✏️ Réviser':'✅ Corriger')+'</button></td>'+
      '</tr>';
  }).join('');

  M('Corrections — '+sj.titre,cv.nom+' · '+soumissions.length+'/'+eleves.length+' soumissions',
    '<div class="tw"><table><thead><tr><th>Élève</th><th>Date</th><th>Rendu</th><th>Note</th><th>Action</th></tr></thead><tbody>'+
    (rows||'<tr><td colspan="5"><div class="empty">Aucune soumission</div></td></tr>')+
    '</tbody></table></div>',
    '<button class="btn bo" onclick="cm()">Fermer</button>','',true
  );
}

function cvCorrectSoumission(soumId,sjId){
  var soum=(DB.cvSoumissions||[]).find(function(s){return s.id===soumId;});if(!soum)return;
  var el=DB.students.find(function(s){return s.id===soum.eleveId;})||{};
  // Find noteSur
  var noteSur=20;
  (DB.classesVirtuelles||[]).forEach(function(cv){
    var sj=(cv.sujets||[]).find(function(s){return s.id===sjId;});
    if(sj) noteSur=sj.noteSur||20;
  });
  M('Corriger — '+_esc(el.nom||'')+' '+_esc(el.pre||''),'',
    '<div class="ib ibt mb12"><span>📄</span><span style="white-space:pre-wrap">'+_esc(soum.contenu||'Aucun texte fourni')+'</span></div>'+
    (soum.fichierUrl?
      '<div style="margin-bottom:12px"><a class="btn bvi sm" href="'+_esc(soum.fichierUrl)+'" target="_blank" rel="noopener"><svg class="vico bico" aria-hidden="true"><use href="#lc-doc"/></svg>☁️ Voir le fichier soumis</a> <a class="btn bo sm" href="'+_esc(soum.fichierUrl)+'" download target="_blank"><svg class="vico bico" aria-hidden="true"><use href="#lc-download"/></svg>Télécharger</a></div>':
     soum.fichierData?
      '<div style="margin-bottom:12px"><button class="btn bvi sm" onclick="_applyWatermarkAndDownload(window._getSoumData(\''+soum.id+'\'),\''+(soum.fichier||'soumission.pdf')+'\',\''+(soum.fichierType||'')+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-doc"/></svg>💾 Voir le fichier soumis</button></div>':
      (soum.fichier?'<a href="'+soum.fichier+'" target="_blank" class="btn bvi sm mb12"><svg class="vico bico" aria-hidden="true"><use href="#lc-doc"/></svg>Voir le fichier soumis</a><br>':''))+
    '<div class="fg2">'+
    '<div class="fg"><span class="fl">Note /'+noteSur+'</span><input class="fi" id="corrNote" type="number" min="0" max="'+noteSur+'" value="'+(soum.note||0)+'" placeholder="0-'+noteSur+'"></div>'+
    '<div class="fg"><span class="fl">Appréciation</span><select class="fi" id="corrAppr"><option>Excellent travail</option><option>Très bien</option><option>Bien</option><option>Assez bien</option><option>Passable</option><option>Insuffisant</option><option>Travail non fait sérieusement</option></select></div>'+
    '<div class="fg full"><span class="fl">Commentaire personnalisé</span><textarea class="fi" id="corrComment" rows="3" placeholder="Feedback pour l\'élève...">'+( soum.commentaire||'')+'</textarea></div>'+
    '</div>',
    '<button class="btn bi" onclick="cvSaveCorrection(\''+soumId+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-save"/></svg>Enregistrer la note</button><button class="btn bo" onclick="cm()">Annuler</button>'
  );
}

function cvSaveCorrection(soumId){
  var soum=(DB.cvSoumissions||[]).find(function(s){return s.id===soumId;});if(!soum)return;
  var note=parseFloat(document.getElementById('corrNote')?.value);
  if(isNaN(note)||note<0){toast('Note invalide','warn');return;}
  soum.note=note;
  soum.appreciation=document.getElementById('corrAppr')?.value||'';
  soum.commentaire=document.getElementById('corrComment')?.value||'';
  soum.dateCorrection=today();
  soum.correcteurId=SES&&(SES.tid||SES.id);
  save();cm();toast('✅ Note enregistrée: '+note);
}

