// ── CHAT INTERACTIF CLASSE VIRTUELLE ─────────────────────────────────────────
function _cvChatOpen(cvId,cv,userId,userType){
  var msgs=(DB.cvMessages||[]).filter(function(m){return m.cvId===cvId;}).slice(-50);
  var col=cvColor(cv&&cv.matiere||'');

  var msgsH=msgs.map(function(m){
    var isMe=(m.auteurId===userId);
    var auteur=m.auteurNom||'Inconnu';
    var role=m.auteurType==='enseignant'?'👨‍🏫':'🎓';
    var bg=isMe?col+'22':'var(--bg2)';
    var align=isMe?'flex-end':'flex-start';
    var br=isMe?'14px 14px 4px 14px':'14px 14px 14px 4px';
    return '<div style="display:flex;flex-direction:column;align-items:'+align+';margin-bottom:10px">'+
      '<div style="font-size:10px;color:var(--ink4);margin-bottom:3px">'+(isMe?'':role+' '+auteur)+(isMe?'Moi ':'')+'· '+m.date+'</div>'+
      '<div style="background:'+bg+';border-radius:'+br+';padding:9px 12px;max-width:75%;font-size:13px;color:var(--ink);border:1px solid var(--bg3)">'+
      m.texte+
      (m.fichier?'<br><a href="'+m.fichier+'" target="_blank" style="font-size:11px;color:'+col+'">📎 Fichier joint</a>':'')+
      '</div></div>';
  }).join('');

  M('💬 Discussion — '+(cv&&cv.nom||'Classe'),
    (cv&&cv.classe||'')+' · '+(cv&&cv.matiere||''),
    '<div style="height:320px;overflow-y:auto;padding:12px;background:var(--bg);border-radius:10px;border:1px solid var(--bg3);margin-bottom:12px" id="cvChatMsgs">'+
    (msgsH||'<div class="empty" style="padding:30px 0"><div class="empty-ico">💬</div>Soyez le premier à écrire !</div>')+
    '</div>'+
    '<div class="fg2">'+
    '<div class="fg" style="grid-column:1/-1"><textarea class="fi" id="cvChatTxt" rows="2" placeholder="Votre message..."></textarea></div>'+
    '<div class="fg"><span class="fl">Fichier (optionnel)</span><input class="fi" id="cvChatFile" type="url" placeholder="Lien Drive..."></div>'+
    '</div>',
    '<button class="btn bi" onclick="cvChatSend(\''+cvId+'\',\''+userId+'\',\''+userType+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-upload"/></svg>Envoyer</button>'+
    '<button class="btn bo" onclick="cm()">Fermer</button>','',true
  );
  // Scroll to bottom
  setTimeout(function(){
    var el=document.getElementById('cvChatMsgs');
    if(el) el.scrollTop=el.scrollHeight;
  },100);
}

function cvChatSend(cvId,userId,userType){
  var txt=(document.getElementById('cvChatTxt')?.value||'').trim();
  if(!txt){toast('Écrivez un message','warn');return;}
  if(!DB.cvMessages) DB.cvMessages=[];
  var nom='';
  if(userType==='enseignant'){
    var t=(DB.teachers||[]).find(function(x){return x.id===userId;});
    nom=t?(t.pre+' '+t.nom):'Enseignant';
  } else if(userType==='eleve'){
    var s=(DB.students||[]).find(function(x){return x.id===userId;});
    nom=s?(s.pre+' '+s.nom):'Élève';
  } else {
    nom='Admin';
  }
  DB.cvMessages.push({
    id:cvMsgId(),
    cvId:cvId,
    auteurId:userId,
    auteurNom:nom,
    auteurType:userType,
    texte:txt,
    fichier:document.getElementById('cvChatFile')?.value||'',
    date:today()
  });
  save();
  // Reload the chat
  var cv=(DB.classesVirtuelles||[]).find(function(c){return c.id===cvId;});
  _cvChatOpen(cvId,cv,userId,userType);
}

// ── PAGE: CLASSES VIRTUELLES ÉLÈVE ──────────────────────────────────────────
function pgMesClassesVirtuelles(){
  var eid=SES&&SES.sid;
  var etud=SES&&(DB.students.find(function(s){return s.id===eid;})||{});
  var maCls=etud&&etud.cls||'';

  var cvs=(DB.classesVirtuelles||[]).filter(function(cv){
    return cv.eleves&&cv.eleves.includes(eid)&&cv.statut==='active';
  });
  var autresCvs=(DB.classesVirtuelles||[]).filter(function(cv){
    return cv.classe===maCls&&(!cv.eleves||!cv.eleves.includes(eid))&&cv.statut==='active';
  });

  var h='<div class="fl2 fic fsb mb16"><div class="bold" style="font-size:18px">📚 Mes Salles de Classe</div>';
  h+='<span style="font-size:12px;color:var(--ink4)">'+maCls+'</span></div>';

  if(!cvs.length&&!autresCvs.length){
    h+='<div class="empty"><div class="empty-ico">📚</div>Aucune classe virtuelle disponible.<br><span style="font-size:12px;color:var(--ink4)">Votre enseignant en créera bientôt.</span></div>';
    return h;
  }

  h+='<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:16px;margin-bottom:20px">';
  cvs.forEach(function(cv){
    var matieres=cv.matieres||[{mat:cv.matiere||'—',ensId:cv.enseignantId,col:cvMatColor(cv.matiere||'—')}];
    var mesSoums=(DB.cvSoumissions||[]).filter(function(s){return s.eleveId===eid;});
    var nouveauxSujets=(cv.sujets||[]).filter(function(sj){return !mesSoums.find(function(s){return s.sujetId===sj.id;})&&new Date(sj.dateLimite)>=new Date();}).length;
    var nouveauxMsgs=(DB.cvMessages||[]).filter(function(m){return m.cvId===cv.id&&m.date===today()&&m.auteurId!==eid;}).length;

    h+='<div style="background:var(--sur);border-radius:16px;border:1px solid var(--bg3);overflow:hidden;box-shadow:var(--sh);cursor:pointer;transition:.2s" onmouseover="this.style.transform=\'translateY(-4px)\';this.style.boxShadow=\'var(--sh2)\'" onmouseout="this.style.transform=\'\';this.style.boxShadow=\'var(--sh)\'">';
    // Gradient header
    h+='<div style="background:linear-gradient(135deg,#0f172a,#1e3a8a);padding:16px;position:relative">';
    if(nouveauxSujets>0)h+='<div style="position:absolute;top:10px;right:10px;background:#AE5353;color:#fff;border-radius:20px;padding:2px 8px;font-size:10px;font-weight:700">'+nouveauxSujets+' nouveau(x)</div>';
    if(nouveauxMsgs>0&&nouveauxSujets===0)h+='<div style="position:absolute;top:10px;right:10px;background:#3C8DFF;color:#fff;border-radius:20px;padding:2px 8px;font-size:10px;font-weight:700">'+nouveauxMsgs+' msg</div>';
    h+='<div style="font-family:Montserrat,sans-serif;font-size:15px;font-weight:800;color:#fff;margin-bottom:4px">'+cv.nom+'</div>';
    h+='<div style="font-size:11px;color:rgba(255,255,255,.5)">'+cv.classe+' · '+matieres.length+' matière(s)</div>';
    h+='</div>';
    // Matières
    h+='<div style="padding:12px 14px;display:flex;flex-wrap:wrap;gap:5px;border-bottom:1px solid var(--bg3)">';
    matieres.forEach(function(m){
      var t=(DB.teachers||[]).find(function(x){return x.id===m.ensId;})||{};
      h+='<div style="background:'+m.col+'15;border:1px solid '+m.col+'35;border-radius:8px;padding:3px 10px;font-size:11px;font-weight:700;color:'+m.col+'">'+_cvMatIco(m.mat)+' '+m.mat+'</div>';
    });
    h+='</div>';
    // Stats
    h+='<div style="display:grid;grid-template-columns:1fr 1fr;border-bottom:1px solid var(--bg3)">';
    [['📝',(cv.sujets||[]).length,'Sujets'],['✅',mesSoums.filter(function(s){return (cv.sujets||[]).some(function(sj){return sj.id===s.sujetId;});}).length,'Soumis']].forEach(function(x){
      h+='<div style="padding:10px;text-align:center"><div style="font-size:13px">'+x[0]+'</div><div style="font-size:16px;font-weight:700;color:var(--ink)">'+x[1]+'</div><div style="font-size:10px;color:var(--ink4)">'+x[2]+'</div></div>';
    });
    h+='</div>';
    // Bouton entrer
    h+='<div style="padding:12px 14px">';
    h+='<button class="btn bi" style="width:100%;justify-content:center" onclick="window._cvRoomId=\''+cv.id+'\';window._cvMatIdx=0;window._cvTab=\'chat\';renderCVRoom(\''+cv.id+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-rocket"/></svg>Entrer dans la salle</button>';
    h+='</div>';
    h+='</div>';
  });
  h+='</div>';

  if(autresCvs.length){
    h+='<div class="card" style="border:1px dashed var(--bg3)">';
    h+='<div class="ct"><span class="ct-ico"><svg class="vico" aria-hidden="true"><use href="#lc-lock"/></svg></span>Autres classes (abonnement requis)</div>';
    autresCvs.forEach(function(cv){
      var plan=(DB.elearning&&DB.elearning.plans||[]).find(function(p){return p.id===cv.planRequis;})||{nom:'Abonnement'};
      h+='<div class="fl2 fic fsb" style="padding:8px 0;border-bottom:1px solid var(--bg2)">'+
        '<div><div style="font-size:13px;font-weight:600">'+cv.nom+'</div>'+
        '<div style="font-size:11px;color:var(--ink4)">'+(cv.matieres||[{mat:cv.matiere}]).map(function(m){return m.mat;}).join(', ')+'</div></div>'+
        '<span class="bg bgpu" style="font-size:11px">🔒 '+plan.nom+'</span></div>';
    });
    h+='</div>';
  }
  return h;
}

