function cvEleveSave(cvId,sjId,eid){
  var txt=(document.getElementById('soumTxt')?.value||'').trim();
  var fichier=(window._soumFileName||'').trim();
  var fichierData=(window._soumFileData||'').trim();
  if(!txt&&!fichierData){toast('Écrivez votre réponse ou ajoutez un fichier','warn');return;}
  if(!DB.cvSoumissions) DB.cvSoumissions=[];
  // Vérifier pas déjà soumis
  var existing=(DB.cvSoumissions||[]).find(function(s){return s.sujetId===sjId&&s.eleveId===eid;});
  if(existing){toast('Vous avez déjà soumis ce travail','warn');return;}
  DB.cvSoumissions.push({
    id:cvSubId(),
    cvId:cvId,
    sujetId:sjId,
    eleveId:eid,
    contenu:txt,
    fichier:fichier,
    fichierData:fichierData,
    fichierType:window._soumFileMime||'',
    dateSoumission:today(),
    note:null,
    commentaire:'',
    appreciation:''
  });
  window._soumFileData=''; window._soumFileName=''; window._soumFileMime='';
  save();cm();re();
  toast('✅ Travail soumis avec succès !');
}

