    +'<div class="fg">'
      +'<span class="fl">Niveau / Classe</span>'
      +'<input class="fi" id="wgNiveau" placeholder="ex : Terminale D, 3ème, tous">'
    +'</div>'
    +'<div class="fg">'
      +'<span class="fl">Nom du groupe WA</span>'
      +'<input class="fi" id="wgNom" placeholder="ex : Terminale D 2025-2026">'
    +'</div>'
    +'<div class="fg">'
