// Cherche-et-remplace les sous-titres (.vsec-sub / .acc-sub) selon la langue active.
// Sûr : on ne touche qu'aux nœuds texte EXACTEMENT connus, pas aux contenus pédagogiques.
window._translateSubs = function(){
  try{
    var lang = (DB && DB._lang) || localStorage.getItem('_vrtLang') || 'fr';
    if(lang!=='en') return;
    // v1.4.2 : sélecteurs ÉLARGIS — labels de formulaires (.fl), CTA des plans,
    // pieds de cartes, bouton retour → l'anglophone est servi sur tout le parcours.
    var sel = '.vsec-sub, .acc-sub, .vlit-banner__sub, .vgz-section-sub, .acc-pill, .vgz-section-title, .scl, .vsec-title, .fl, .vplan-cta, .vplan-footer, .back-btn, .rc-tag';
    document.querySelectorAll(sel).forEach(function(el){
      // 1) Élément de pur texte : remplacer son textContent.
      // 2) Élément avec icône en enfant : traduire UNIQUEMENT le dernier nœud texte
      //    (préserve l'icône/SVG, évite les faux positifs).
      var last = el.lastChild;
      if(last && last.nodeType===3){
        var raw = last.textContent;
        var trimmed = raw.replace(/\s+$/,'').replace(/^\s+/,'');
        if(trimmed && I18N_SUBS_EN[trimmed]){
          last.textContent = ' ' + I18N_SUBS_EN[trimmed];
          return;
        }
      }
      if(el.children.length===0){
        var full = (el.textContent||'').trim();
        if(I18N_SUBS_EN[full]) el.textContent = I18N_SUBS_EN[full];
      }
    });
  }catch(e){}
};
window.t = function(key, fallback){
  try {
    var lang = (DB && DB._lang) || localStorage.getItem('_vrtLang') || 'fr';
    var dict = I18N_DICT[lang] || I18N_DICT.fr;
    return dict[key] || I18N_DICT.fr[key] || fallback || key;
  } catch(e){ return fallback || key; }
};

window.setLang = function(lang, silent){
  if(lang!=='fr' && lang!=='en') return;
  try {
    DB._lang = lang;
    localStorage.setItem('_vrtLang', lang);
    if(typeof save==='function') save();
    document.documentElement.lang = lang==='en' ? 'en' : 'fr-CM';

    // Traduire éléments avec data-i18n
    document.querySelectorAll('[data-i18n]').forEach(function(el){
      var k = el.getAttribute('data-i18n');
      el.textContent = t(k);
    });

    // ── v2.2 : traduction visible immédiate de la nav visiteur ──
    var navMap = lang==='en' ? {
      'Accueil':'Home','E-Learning':'E-Learning','Boutique':'Shop','Jeux':'Games',
      'Labos':'Labs','Classes':'Classes','Orientation':'Guidance','Calendrier':'Calendar',
      'Épreuves':'Exams','Évals':'Tests','Devoir IA':'AI Tutor','Parrainage':'Referral',
      'Parcours IA':'AI Path','Forum':'Forum','Actualités':'News','Contact':'Contact',
      'IA':'AI','Pratiquer':'Practice','Communauté':'Community','Infos':'Info','Partenaires':'Partners',
      'Panier':'Cart',"S'inscrire":'Sign up','Se connecter':'Log in','Enseignant':'Teacher'
    } : {
      'Home':'Accueil','Shop':'Boutique','Games':'Jeux','Labs':'Labos','Classes':'Classes',
      'Guidance':'Orientation','Calendar':'Calendrier','Exams':'Épreuves','Tests':'Évals',
      'AI Tutor':'Devoir IA','Referral':'Parrainage','AI Path':'Parcours IA','News':'Actualités',
      'AI':'IA','Practice':'Pratiquer','Community':'Communauté','Info':'Infos','Partners':'Partenaires',
      'Cart':'Panier','Sign up':"S'inscrire",'Log in':'Se connecter','Teacher':'Enseignant'
    };
    document.querySelectorAll('.vnav-btn, .vlogin-btns .btn').forEach(function(btn){
      // Récupérer le dernier nœud texte (après SVG icône), en préservant l'espace et la flèche ▾
      btn.childNodes.forEach(function(n){
        if(n.nodeType===3 && n.textContent.trim()){
          var raw = n.textContent;
          var lead = (raw.match(/^\s*/)||[''])[0];
          var hadArrow = /▾\s*$/.test(raw.trim());
          var t0 = raw.trim().replace(/\s*▾\s*$/,'');
          if(navMap[t0]) n.textContent = lead + navMap[t0] + (hadArrow?' ▾':'');
        }
      });
    });

    // v1.2.4 : traduire aussi les sous-titres des panneaux (interface seulement)
    try{ if(typeof _translateSubs==='function') _translateSubs(); }catch(e){}
    if(!silent) toast(lang==='en'?'🌐 Language: English ✓':'🌐 Langue : Français ✓','ok');
  } catch(e){ console.warn('setLang:',e); if(!silent) toast('Erreur changement langue','warn'); }
};

window.mLanguageMenu = function(){
  var curr = (DB && DB._lang) || localStorage.getItem('_vrtLang') || 'fr';
  var EN = (curr==='en');

  // v1.15.3 — Enrichi. On n'affiche QUE les deux langues réellement traduites :
  // annoncer une troisième langue qui ne traduit rien serait une promesse creuse.
  // Ce qu'on ajoute à la place : le nom natif, l'état courant lisible, le
  // périmètre exact de la traduction, et la passerelle vers le sous-système
  // anglophone (GCE) — la vraie attente derrière « passer en anglais » au Cameroun.
  var LANGS = [
    { code:'fr', drapeau:'🇫🇷', nom:'Français', natif:'Langue d\'enseignement', sous:EN?'Francophone subsystem':'Sous-système francophone' },
    { code:'en', drapeau:'🇬🇧', nom:'English',  natif:'Interface language',     sous:EN?'Anglophone subsystem (GCE)':'Sous-système anglophone (GCE)' }
  ];

  var body = '<div style="display:grid;gap:10px;padding:2px">';
  LANGS.forEach(function(L){
    var actif = (curr===L.code);
    body += '<button class="btn" onclick="setLang(\''+L.code+'\');cm()" aria-pressed="'+actif+'" '
      +'style="display:flex;align-items:center;gap:13px;text-align:left;padding:14px 15px;border-radius:14px;'
      +'background:'+(actif?'linear-gradient(150deg,#16295C,#101F45)':'#F4F6FA')+';'
      +'color:'+(actif?'#fff':'#142554')+';'
      +'border:1px solid '+(actif?'rgba(255,201,60,.45)':'rgba(20,37,84,.12)')+';font-weight:600">'
      +'<span style="font-size:26px;line-height:1;flex-shrink:0">'+L.drapeau+'</span>'
      +'<span style="flex:1;min-width:0">'
        +'<span style="display:block;font-size:15.5px;font-weight:800">'+L.nom+'</span>'
        +'<span style="display:block;font-size:11px;opacity:.72;margin-top:2px">'+L.sous+'</span>'
      +'</span>'
      +(actif
        ? '<span style="flex-shrink:0;font-size:10px;font-weight:800;letter-spacing:.6px;color:#FFC93C;text-transform:uppercase">'+(EN?'Active':'Actuelle')+'</span>'
        : '<span style="flex-shrink:0;font-size:17px;opacity:.35">→</span>')
      +'</button>';
  });
  body += '</div>';

  // Périmètre : dire précisément ce qui bascule et ce qui ne bascule pas.
  body += '<div style="margin-top:14px;padding:12px 13px;background:#F4F6FA;border-radius:12px;font-size:12.5px;color:#374151;line-height:1.5">'
    +'<b style="color:#142554">'+(EN?'What changes':'Ce qui change')+'</b><br>'
    +(EN
      ? 'Menus, buttons and labels switch to English. Teaching content (courses, set works, past papers) stays in the language it was written in — French for the francophone subsystem, English for GCE material.'
      : 'Les menus, boutons et libellés passent en anglais. Les contenus pédagogiques (cours, œuvres, épreuves) restent dans leur langue d\'origine — français pour le sous-système francophone, anglais pour les ressources GCE.')
    +'</div>';

  // Passerelle vers les ressources anglophones : l'intention réelle, souvent.
  body += '<button class="btn" onclick="cm();vShowSec(\'epreuves\',null)" '
    +'style="margin-top:10px;width:100%;padding:12px;border-radius:12px;background:rgba(255,201,60,.16);'
    +'border:1px solid rgba(199,146,10,.38);color:#7A5A05;font-weight:700;font-size:13px">'
    +(EN?'📘 Browse GCE papers & resources':'📘 Voir les épreuves et ressources GCE')
    +'</button>';

  M(t('menu.lang','Langue'), EN?'Interface language':'Langue de l\'interface', body,
    '<button class="btn bi" onclick="cm()">'+t('btn.close','Fermer')+'</button>');
};

// Auto-load langue au démarrage — v1.2.4 : applique RÉELLEMENT la traduction de l'UI
// au chargement. Auparavant, seul documentElement.lang était posé : la nav repassait
// en français à chaque rechargement → bilinguisme perçu comme « partiel ». On ré-applique
// aussi après chaque navigation visiteur via window._vrtReapplyLang().
window._vrtReapplyLang = function(){
  try {
    var lg = (typeof DB!=='undefined' && DB && DB._lang) || localStorage.getItem('_vrtLang') || 'fr';
    if(lg==='en' && typeof setLang==='function') setLang('en', true);
  } catch(e){}
};
try {
  var savedLang = localStorage.getItem('_vrtLang');
  if(savedLang==='en'){
    document.documentElement.lang = 'en';
    if(document.readyState==='complete'){ setTimeout(window._vrtReapplyLang, 400); }
    else { window.addEventListener('load', function(){ setTimeout(window._vrtReapplyLang, 500); }); }
  }
} catch(e){}

