// ── v1.2 P2 — PAGES ADMIN : Stats Business + Parrainage ────────────
// ════════════════════════════════════════════════════════════════════
window.pgStatsBusiness = function(){
  if(!iA()) return na();
  try {
    var pays = (DB.payAttempts||[]).filter(function(p){return p.status==='paid';});
    var allPays = DB.payAttempts||[];
    var totalCA = pays.reduce(function(s,p){return s+(+p.montant||0);},0);
    var now = new Date();
    var caMois = pays.filter(function(p){
      try{var d=new Date(p.created||p.date); return d.getFullYear()===now.getFullYear() && d.getMonth()===now.getMonth();}catch(e){return false;}
    }).reduce(function(s,p){return s+(+p.montant||0);},0);
    var caSem = pays.filter(function(p){
      try{var d=new Date(p.created||p.date); return (now-d)/(1000*60*60*24) <= 7;}catch(e){return false;}
    }).reduce(function(s,p){return s+(+p.montant||0);},0);
    var nbStud = (DB.students||[]).length;
    var nbVisit = (DB.visitorAccounts||[]).length;
    var nbAbo = ((DB.elearning||{}).abonnements||[]).filter(function(a){return a.statut==='actif';}).length;
    var nbBook = (DB.bookPurchases||[]).length;
    var nbPar = (DB.parrainages||[]).length;
    var pendingPays = allPays.filter(function(p){return p.status==='pending';}).length;
    var convRate = nbVisit>0 ? ((nbAbo/nbVisit)*100).toFixed(1) : '0';

    // Top 5 produits
    var prodCount = {};
    pays.forEach(function(p){
      var k = p.label||'(inconnu)';
      prodCount[k] = (prodCount[k]||0)+(+p.montant||0);
    });
    var topProd = Object.entries(prodCount).sort(function(a,b){return b[1]-a[1];}).slice(0,5);

    // Évolution 6 mois
    var monthlyData = [];
    for(var i=5;i>=0;i--){
      var d = new Date(now.getFullYear(), now.getMonth()-i, 1);
      var label = ['Jan','Fév','Mar','Avr','Mai','Juin','Juil','Aoû','Sep','Oct','Nov','Déc'][d.getMonth()];
      var ca = pays.filter(function(p){
        try{var pd=new Date(p.created||p.date); return pd.getFullYear()===d.getFullYear() && pd.getMonth()===d.getMonth();}catch(e){return false;}
      }).reduce(function(s,p){return s+(+p.montant||0);},0);
      monthlyData.push({label:label, val:ca});
    }
    var maxMonth = Math.max(1, ...monthlyData.map(function(m){return m.val;}));

    var bars = monthlyData.map(function(m){
      var h = Math.max(8,(m.val/maxMonth)*140);
      return '<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:4px">'
        +'<div style="font-size:10px;color:#6B7280;font-weight:700">'+(m.val>0?fmt(m.val):'')+'</div>'
        +'<div style="width:80%;height:'+h+'px;background:linear-gradient(180deg,#3C8DFF,#142554);border-radius:6px 6px 0 0;transition:.3s"></div>'
        +'<div style="font-size:11px;color:#374151;font-weight:600">'+m.label+'</div></div>';
    }).join('');

    var topHTML = topProd.map(function(t,i){
      var medal = ['🥇','🥈','🥉','4️⃣','5️⃣'][i];
      return '<div style="display:flex;justify-content:space-between;padding:10px 14px;background:#fff;border-radius:10px;margin-bottom:6px;border:1px solid #E5E7EB">'
        +'<span>'+medal+' '+_esc(t[0])+'</span>'
        +'<b style="color:#3A8F73">'+fmt(t[1])+'</b></div>';
    }).join('') || '<div style="text-align:center;padding:20px;color:#9CA3AF">Aucune vente confirmée</div>';

    return '<div class="pgt"><span class="pgt-ico"><svg class="vico vico-19" aria-hidden="true"><use href="#lc-chart"/></svg></span>Statistiques Business</div>'
      +'<div class="card mt12"><div class="ct"><span class="ct-ico"><svg class="vico" aria-hidden="true"><use href="#lc-coins"/></svg></span>Chiffre d\'affaires</div>'
      +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px">'
      +_statCard('💰', fmt(totalCA), 'CA total', '#3A8F73')
      +_statCard('📅', fmt(caMois), 'CA ce mois', '#3C8DFF')
      +_statCard('📆', fmt(caSem), 'CA cette semaine', '#6C56A6')
      +_statCard('⏳', pendingPays, 'En attente', '#C46F6F')
      +'</div></div>'
      +'<div class="card mt12"><div class="ct"><span class="ct-ico"><svg class="vico" aria-hidden="true"><use href="#lc-trending"/></svg></span>Évolution 6 derniers mois</div>'
      +'<div style="display:flex;align-items:flex-end;justify-content:space-around;height:200px;gap:10px;padding:14px">'+bars+'</div></div>'
      +'<div class="card mt12"><div class="ct"><span class="ct-ico"><svg class="vico" aria-hidden="true"><use href="#lc-users"/></svg></span>Utilisateurs</div>'
      +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:14px">'
      +_statCard('🎓', nbStud, 'Élèves inscrits', '#FFC93C')
      +_statCard('🌐', nbVisit, 'Visiteurs', '#3A91A0')
      +_statCard('📊', convRate+'%', 'Taux conversion', '#C37199')
      +_statCard('🎁', nbPar, 'Parrainages', '#F59E0B')
      +'</div></div>'
      +'<div class="card mt12"><div class="ct"><span class="ct-ico"><svg class="vico" aria-hidden="true"><use href="#lc-cart"/></svg></span>Activité</div>'
      +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:14px">'
      +_statCard('🎓', nbAbo, 'Abonnements actifs', '#3A8F73')
      +_statCard('📚', nbBook, 'Achats livres', '#F59E0B')
      +'</div></div>'
      +'<div class="card mt12"><div class="ct"><span class="ct-ico"><svg class="vico" aria-hidden="true"><use href="#lc-award"/></svg></span>Top 5 produits (CA)</div>'+topHTML+'</div>';
  } catch(e){
    console.error('pgStatsBusiness:',e);
    return '<div class="pgt"><span class="pgt-ico"><svg class="vico vico-19" aria-hidden="true"><use href="#lc-chart"/></svg></span>Statistiques Business</div><div class="card">Erreur : '+_esc(e.message)+'</div>';
  }
};

