// ════════════════════════════════════════════════════════════════════
window.mStudyRoom = function(){
  var ses = (typeof SES!=='undefined' && SES) ? SES : null;
  if(!ses){
    M('👥 Étude en groupe','Étudiez à plusieurs en temps réel',
      '<div style="text-align:center;padding:20px"><p>Créez une room avec un code à 6 chiffres et invitez vos amis à étudier ensemble : QCM, chat, leaderboard live.</p></div>',
      '<button class="btn bo" onclick="cm()">Fermer</button><button class="btn bi" onclick="cm();showRegisterForm()"><svg class="vico bico" aria-hidden="true"><use href="#lc-sparkles"/></svg>S\'inscrire</button>');
    return;
  }
  M('👥 Mode Étude en Groupe','Créez ou rejoignez une room',
    '<div style="padding:8px">'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">'
      +'<div style="background:linear-gradient(135deg,#EFF6FF,#DBEAFE);border:2px solid #93C5FD;border-radius:14px;padding:18px;text-align:center;cursor:pointer;transition:transform .2s" onmouseover="this.style.transform=\'translateY(-3px)\'" onmouseout="this.style.transform=\'\'" onclick="_createStudyRoom()">'
        +'<div style="font-size:36px;margin-bottom:8px">🚀</div>'
        +'<div style="font-weight:800;color:#1E3A8A;font-size:14px">Créer une room</div>'
        +'<div style="font-size:11px;color:#6A8DC7;margin-top:4px">Code unique 6 chiffres</div>'
      +'</div>'
      +'<div style="background:linear-gradient(135deg,#F0FDF4,#D1FAE5);border:2px solid #6EE7B7;border-radius:14px;padding:18px;text-align:center;cursor:pointer;transition:transform .2s" onmouseover="this.style.transform=\'translateY(-3px)\'" onmouseout="this.style.transform=\'\'" onclick="_joinStudyRoom()">'
        +'<div style="font-size:36px;margin-bottom:8px">🔑</div>'
        +'<div style="font-weight:800;color:#065F46;font-size:14px">Rejoindre une room</div>'
        +'<div style="font-size:11px;color:#3A8F73;margin-top:4px">Saisir le code reçu</div>'
      +'</div>'
    +'</div>'
    +'<div style="background:#FEF3C7;border:1px solid #FCD34D;padding:12px;border-radius:10px;font-size:11px;color:#92400E;margin-top:14px;line-height:1.5">'
      +'<b>💡 Comment ça marche :</b><br>1. Créez une room → recevez code 6 chiffres<br>2. Partagez le code à vos amis<br>3. Tous ensemble : QCM commun, chat live, classement temps réel'
    +'</div>'
    +'</div>',
    '<button class="btn bi" onclick="cm()">Fermer</button>', true);
};

window._createStudyRoom = function(){
  var ses = (typeof SES!=='undefined' && SES) ? SES : null;
  if(!ses) return;
  var code = String(Math.floor(100000 + Math.random()*900000));
  DB.studyRooms = DB.studyRooms || {};
  DB.studyRooms[code] = {
    code: code,
    hostId: ses.id,
    hostName: (ses.pre||'')+' '+(ses.nom||''),
    members: [{id:ses.id, name:(ses.pre||'')+' '+(ses.nom||''), score:0, joinedAt:Date.now()}],
    created: Date.now(),
    status: 'lobby',
    questions: []
  };
  try { save(); } catch(e){}
  _renderStudyRoom(code);
};

window._joinStudyRoom = function(){
  cm();
  M('🔑 Rejoindre une room','Saisissez le code à 6 chiffres',
    '<div class="fg"><span class="fl">Code de la room</span><input class="fi" id="joinRoomCode" placeholder="123456" maxlength="6" style="font-size:24px;letter-spacing:6px;text-align:center;font-family:JetBrains Mono,monospace"></div>',
    '<button class="btn bo" onclick="cm()">Annuler</button>'
    +'<button class="btn bi" onclick="_confirmJoinRoom()">Rejoindre</button>');
};

window._confirmJoinRoom = function(){
  var code = (_ge('joinRoomCode')||{}).value || '';
  code = code.replace(/\s/g,'');
  if(!/^\d{6}$/.test(code)){ toast('Code invalide (6 chiffres)','warn'); return; }
  var ses = (typeof SES!=='undefined' && SES) ? SES : null;
  if(!ses) return;
  DB.studyRooms = DB.studyRooms || {};
  var room = DB.studyRooms[code];
  if(!room){ toast('Room introuvable','warn'); return; }
  if(!room.members.find(function(m){return m.id===ses.id;})){
    room.members.push({id:ses.id, name:(ses.pre||'')+' '+(ses.nom||''), score:0, joinedAt:Date.now()});
    try { save(); } catch(e){}
  }
  cm();
  _renderStudyRoom(code);
};

window._renderStudyRoom = function(code){
  var room = (DB.studyRooms||{})[code];
  if(!room){ toast('Room expirée','warn'); return; }
  var ses = (typeof SES!=='undefined' && SES) ? SES : null;
  var isHost = ses && ses.id === room.hostId;
  var body = '<div style="padding:8px">'
    +'<div style="background:linear-gradient(135deg,#142554,#1E3A8A);color:#fff;padding:18px;border-radius:14px;margin-bottom:14px;text-align:center">'
      +'<div style="font-size:10px;text-transform:uppercase;letter-spacing:2px;color:#FFC93C;font-weight:800">Code de la room</div>'
      +'<div style="font-size:42px;font-weight:900;letter-spacing:6px;font-family:JetBrains Mono,monospace;color:#FFC93C;margin:6px 0">'+code+'</div>'
      +'<button class="btn" style="background:rgba(255,201,60,.2);color:#FFC93C;border:1px solid rgba(255,201,60,.4);padding:6px 12px;font-size:11px;border-radius:8px" onclick="navigator.clipboard.writeText(\''+code+'\').then(function(){toast(\'Code copié\');})"><svg class="vico bico" aria-hidden="true"><use href="#lc-clipboard"/></svg>Copier code</button>'
    +'</div>'
    +'<div style="font-weight:700;color:#142554;margin-bottom:8px">👥 Membres ('+room.members.length+')</div>'
    +'<div style="background:#F9FAFB;border-radius:10px;padding:10px;max-height:200px;overflow-y:auto">'
    +room.members.map(function(m,i){
      return '<div style="display:flex;align-items:center;gap:10px;padding:6px;border-bottom:1px solid #F3F4F6">'
        +'<div style="width:32px;height:32px;border-radius:50%;background:linear-gradient(135deg,#3C8DFF,#6C56A6);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:13px">'+((m.name||'?')[0]||'?').toUpperCase()+'</div>'
        +'<div style="flex:1"><div style="font-weight:600;color:#142554;font-size:13px">'+_esc(m.name)+(m.id===room.hostId?' <span style="background:#FFC93C;color:#142554;font-size:9px;padding:1px 5px;border-radius:4px;font-weight:800">HÔTE</span>':'')+'</div></div>'
        +(m.score>0?'<div style="font-weight:800;color:#3A8F73">+'+m.score+' XP</div>':'')
      +'</div>';
    }).join('')
    +'</div>'
    +(isHost
      ? '<div style="margin-top:14px;padding:12px;background:#FEF3C7;border-radius:10px"><div style="font-weight:700;color:#92400E;margin-bottom:8px">⚙️ Actions hôte</div><button class="btn bi" style="width:100%" onclick="_startGroupQuiz(\''+code+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-zap"/></svg>Lancer le quiz commun (10 QCM)</button></div>'
      : '<div style="margin-top:14px;padding:12px;background:#EFF6FF;border-radius:10px;text-align:center;font-size:13px;color:#1E3A8A">⏳ En attente que l\'hôte lance le quiz…</div>'
    )
    +'</div>';
  M('👥 Room '+code,room.members.length+' membre(s) connecté(s)',body,
    '<button class="btn bo" onclick="cm()">Quitter</button>'
    +'<button class="btn bi" onclick="_renderStudyRoom(\''+code+'\')"><svg class="vico bico" aria-hidden="true"><use href="#lc-refresh"/></svg>Rafraîchir</button>', true);
};

window._startGroupQuiz = function(code){
  var room = (DB.studyRooms||{})[code];
  if(!room) return;
  if(!room.questions || !room.questions.length){
    room.questions = _generateBattleQuestions();
    try { save(); } catch(e){}
  }
  // Lancer le mode quiz (réutilise la logique battle adaptée)
  toast('Quiz de groupe lancé !','ok');
  _lancerBattle(); // Réutilise la mécanique existante
};

