// v1.2.1 — Rendu Markdown -> HTML stylé et pédagogique pour les réponses IA
window._aiMarkdown = function(src){
  if(!src) return '';
  var esc=function(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');};
  var inl=function(t){
    t=esc(t);
    t=t.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
    t=t.replace(/`([^`]+)`/g,'<code>$1</code>');
    t=t.replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g,'$1<em>$2</em>');
    return t;
  };
  var lines=String(src).replace(/\r\n/g,'\n').split('\n');
  var out='',i=0;
  var isSep=function(s){return /^\s*\|?[\s:|-]+\|?\s*$/.test(s)&&s.indexOf('-')>=0;};
  while(i<lines.length){
    var ln=lines[i];
    if(/^\s*\|.*\|\s*$/.test(ln)&&i+1<lines.length&&isSep(lines[i+1])){
      var hd=ln.trim().replace(/^\||\|$/g,'').split('|').map(function(c){return c.trim();});
      i+=2; var rs=[];
      while(i<lines.length&&/^\s*\|.*\|\s*$/.test(lines[i])){ rs.push(lines[i].trim().replace(/^\||\|$/g,'').split('|').map(function(c){return c.trim();})); i++; }
      out+='<table class="ai-tbl"><thead><tr>'+hd.map(function(h){return '<th>'+inl(h)+'</th>';}).join('')+'</tr></thead><tbody>'+rs.map(function(r){return '<tr>'+r.map(function(c){return '<td>'+inl(c)+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table>';
      continue;
    }
    var hm=ln.match(/^\s*(#{1,4})\s+(.*)$/);
    if(hm){ var lv=Math.min(4,hm[1].length)+2; out+='<h'+lv+' class="ai-h">'+inl(hm[2])+'</h'+lv+'>'; i++; continue; }
    if(/^\s*([-*_])\1{2,}\s*$/.test(ln)){ out+='<hr class="ai-hr">'; i++; continue; }
    if(/^\s*[-*]\s+/.test(ln)){ var it=[]; while(i<lines.length&&/^\s*[-*]\s+/.test(lines[i])){ it.push(inl(lines[i].replace(/^\s*[-*]\s+/,''))); i++; } out+='<ul class="ai-ul">'+it.map(function(x){return '<li>'+x+'</li>';}).join('')+'</ul>'; continue; }
    if(/^\s*\d+\.\s+/.test(ln)){ var oi=[]; while(i<lines.length&&/^\s*\d+\.\s+/.test(lines[i])){ oi.push(inl(lines[i].replace(/^\s*\d+\.\s+/,''))); i++; } out+='<ol class="ai-ol">'+oi.map(function(x){return '<li>'+x+'</li>';}).join('')+'</ol>'; continue; }
    if(/^\s*$/.test(ln)){ i++; continue; }
    var p=[ln]; i++;
    while(i<lines.length&&!/^\s*$/.test(lines[i])&&!/^\s*[-*]\s+/.test(lines[i])&&!/^\s*\d+\.\s+/.test(lines[i])&&!/^\s*#{1,4}\s+/.test(lines[i])&&!/^\s*\|.*\|\s*$/.test(lines[i])&&!/^\s*([-*_])\1{2,}\s*$/.test(lines[i])){ p.push(lines[i]); i++; }
    out+='<p class="ai-p">'+p.map(inl).join('<br>')+'</p>';
  }
  return out;
};

window.mAgentAmbassa = function(taskId){
  // v2.7 : ouvert à tous (anonymes inclus, avec quota 2 essais lifetime)
  var ses = (typeof SES!=='undefined' && SES) ? SES : null;
  if(!_checkRateLimit('ambassa', 20)) return;

  if(taskId){
    return _ambassaTaskForm(taskId);
  }

  // Menu principal : 7 cards taches
  var cards = AMBASSA_TACHES.map(function(t){
    return '<div onclick="cm();mAgentAmbassa(\''+t.id+'\')" style="background:#fff;border:1.5px solid '+t.col+'40;border-radius:14px;padding:14px;cursor:pointer;transition:all .2s;display:flex;gap:12px;align-items:flex-start" onmouseover="this.style.transform=\'translateY(-3px)\';this.style.boxShadow=\'0 8px 20px rgba(0,0,0,.08)\';this.style.borderColor=\''+t.col+'\'" onmouseout="this.style.transform=\'\';this.style.boxShadow=\'\';this.style.borderColor=\''+t.col+'40\'">'
      +'<div style="width:42px;height:42px;border-radius:50%;background:'+t.col+'18;display:flex;align-items:center;justify-content:center;flex-shrink:0">'
      +'<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="'+t.col+'" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><use href="#lc-'+t.ic+'"/></svg>'
      +'</div>'
      +'<div style="flex:1"><div style="font-weight:800;font-size:14px;color:'+t.col+'">'+t.t+'</div><div style="font-size:11px;color:#6B7280;margin-top:3px;line-height:1.4">'+t.d+'</div></div>'
      +'<div style="color:'+t.col+';font-size:18px;align-self:center">→</div>'
      +'</div>';
  }).join('');

  var hist = (ses && ses.id) ? ((DB._ambassaHist||{})[ses.id] || []) : [];
  var histPreview = hist.length ? '<div style="margin-top:18px;padding:12px;background:#F3F4F6;border-radius:10px"><div style="font-weight:700;font-size:12px;color:#374151;margin-bottom:6px">📚 Vos '+Math.min(3,hist.length)+' dernières générations</div>'
    +hist.slice(-3).reverse().map(function(h){
      return '<div style="font-size:11px;color:#6B7280;padding:4px 0;border-bottom:1px solid #E5E7EB">• '+_esc(h.task)+' — '+_esc((h.prompt||'').substring(0,50))+'…</div>';
    }).join('')+'</div>' : '';

  // v2.7 : badge quota visible
  var quotaBadge = (typeof _aiQuotaBadgeHtml === 'function') ? _aiQuotaBadgeHtml('ambassa') : '';
  var tier = (typeof _aiTier === 'function') ? _aiTier() : 'anon';

  var body = '<div style="padding:8px">'
    +'<div style="background:linear-gradient(135deg,#142554,#6C56A6);color:#fff;padding:18px;border-radius:14px;margin-bottom:14px;display:flex;gap:14px;align-items:center;flex-wrap:wrap">'
      +'<div style="width:64px;height:64px;border-radius:50%;background:linear-gradient(135deg,#FFE082,#FFC93C);display:flex;align-items:center;justify-content:center;overflow:hidden;border:3px solid #FFC93C;box-shadow:0 4px 14px rgba(255,201,60,.4);flex-shrink:0;position:relative">'
        +'<span style="position:absolute;color:#142554;font-size:28px;font-weight:900;font-family:Plus Jakarta Sans,sans-serif;line-height:1">A</span>'
        +'<img src="ambassa-avatar.png" alt="Professeur Ambassa" style="position:relative;z-index:2;width:100%;height:100%;object-fit:cover;display:block">'
      +'</div>'
      +'<div style="flex:1;min-width:200px"><div style="font-size:11px;text-transform:uppercase;letter-spacing:1.5px;color:#FFC93C;font-weight:800">Agent IA pédagogique</div>'
      +'<div style="font-size:20px;font-weight:900;font-family:Plus Jakarta Sans">Professeur Ambassa</div>'
      +'<div style="font-size:11px;opacity:.85;font-style:italic;font-family:Crimson Pro,serif">Expert MINESEC · BEPC · Probatoire · BAC · Programme camerounais</div></div>'
      +(quotaBadge ? '<div>'+quotaBadge+'</div>' : '')
    +'</div>'
    + (tier === 'anon'
      ? '<div style="background:#FEF3C7;border:1px solid #FCD34D;padding:10px 14px;border-radius:10px;margin-bottom:12px;font-size:12px;color:#92400E"><b>🎁 Essai gratuit :</b> vous avez 2 essais Ambassa pour découvrir. <a href="javascript:cm();showRegisterForm()" style="color:#92400E;font-weight:700;text-decoration:underline">Inscrivez-vous gratuitement</a> pour 3 essais/semaine + sauvegarde.</div>'
      : (tier === 'free'
        ? '<div style="background:#EEF2FF;border:1px solid #C7D2FE;padding:10px 14px;border-radius:10px;margin-bottom:12px;font-size:12px;color:#3730A3"><b>💎 Compte gratuit :</b> 3 essais Ambassa / semaine. <a href="javascript:cm();vShowSec(\'elearning\',null);setTimeout(function(){var p=document.getElementById(\'elPlans\');if(p)p.scrollIntoView({behavior:\'smooth\'});},400)" style="color:#3730A3;font-weight:700;text-decoration:underline">Passer à un plan</a> pour utiliser sans limite.</div>'
        : ''))
    +'<div style="font-size:13px;color:#142554;font-weight:700;margin-bottom:10px">Que souhaitez-vous créer ?</div>'
    +'<div style="display:grid;gap:8px">'+cards+'</div>'
    +histPreview
    +'</div>';

  M('🎓 Professeur Ambassa','Votre IA pédagogique camerounaise',body,
    '<button class="btn bo" onclick="cm()">Fermer</button>'
    +'<button class="btn bi" onclick="cm();mAmbassaHistorique()"><svg class="vico bico" aria-hidden="true"><use href="#lc-book"/></svg>Historique complet</button>', true);
};

