// ── v1.1 — MODULE 1 : PAGE PRODUIT FULLSCREEN ────────────────────
// ══════════════════════════════════════════════════════════════════

function openProductPage(itemId, type){
  var item = null;
  var el = DB.elearning || {};
  if(type === 'contenu'){
    item = (el.contenus||[]).find(function(c){return c.id===itemId;});
  } else if(type === 'abonnement'){
    item = (el.plans||[]).find(function(p){return p.id===itemId;});
  } else if(type === 'article'){
    item = (DB.books||[]).find(function(b){return b.id===itemId;});
  }
  if(!item) { toast('Produit introuvable','warn'); return; }

  var titre = item.titre || item.nom || 'Produit';
  var prix = item.prix || 0;
  var desc = item.desc || item.description || '';
  var apercu = item.apercu || item.resume || '';
  var classe = item.classe || item.cls || '';
  var matiere = item.matiere || '';
  var seq = item.seq || '';
  var ico = item.ico || (type==='contenu'?'📄':type==='abonnement'?'🎓':'📚');
  var chaps = item.chaps || item.chapitres || [];
  var prixAncien = item.prixAncien || item.oldPrix || 0;

  // v1.2.4 — Le paiement DOIT porter l'intent et la cible. Jusqu'ici ces deux
  // boutons appelaient openPaymentModal sans métadonnées : le client payait,
  // et rien ne s'activait ni ne rétribuait l'auteur (intent 'generic').
  var _pIntent = _intentDeType(type);
  var _pArgs = 'montant:'+prix
    +',label:\''+_esc(titre).replace(/'/g,"\\'")+'\''
    +',refPrefix:\''+(type==='article'?'SHOP':'ELRN')+'\''
    +',intent:\''+_pIntent+'\''
    +',targetId:\''+_esc(String(itemId))+'\'';
  var prixFmt = new Intl.NumberFormat('fr-FR').format(prix) + ' FCFA';

  var badges = '';
  if(classe) badges += '<span style="display:inline-block;background:var(--blb);color:var(--bl);padding:4px 10px;border-radius:20px;font-size:11px;font-weight:700;margin-right:6px">'+_esc(classe)+'</span>';
  if(matiere) badges += '<span style="display:inline-block;background:var(--pub);color:var(--pu);padding:4px 10px;border-radius:20px;font-size:11px;font-weight:700;margin-right:6px">'+_esc(matiere)+'</span>';
  if(seq) badges += '<span style="display:inline-block;background:var(--orb);color:var(--or);padding:4px 10px;border-radius:20px;font-size:11px;font-weight:700">'+_esc(seq)+'</span>';

  var chapHtml = '';
  if(chaps.length){
    chapHtml = '<div style="margin-top:16px"><div style="font-family:Montserrat,sans-serif;font-size:14px;font-weight:700;color:var(--ink);margin-bottom:10px">📋 Contenu inclus</div>';
    chapHtml += chaps.map(function(ch){ return '<div style="padding:6px 0;border-bottom:1px solid var(--bg2);font-size:13px;color:var(--ink2)"><span style="color:var(--gr);margin-right:8px">✅</span>'+_esc(ch)+'</div>'; }).join('');
    chapHtml += '</div>';
  }

  var waNum = (window.VERITAS_PAYMENTS?.whatsapp||'').replace(/[^0-9+]/g,'').replace(/^\+/,'');
  var waMsg = encodeURIComponent('Bonjour, je souhaite commander :\n\n📦 '+titre+'\n💰 '+prixFmt+'\n\nMerci de me confirmer la disponibilité.');
  var waUrl = 'https://wa.me/'+waNum+'?text='+waMsg;

  var html = ''
    +'<div id="productPageOverlay" style="position:fixed;inset:0;z-index:9500;background:#fff;overflow-y:auto;animation:su .25s">'
    +'<div style="max-width:680px;margin:0 auto;padding:24px 20px 40px">'

    // Close button
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px">'
    +'<button onclick="document.getElementById(\'productPageOverlay\').remove()" style="background:var(--bg2);border:none;border-radius:50%;width:40px;height:40px;font-size:20px;cursor:pointer;display:flex;align-items:center;justify-content:center">←</button>'
    +'<span style="font-size:11px;color:var(--ink4);font-weight:600;letter-spacing:1px;text-transform:uppercase">VÉRITAS Boutique</span>'
    +'</div>'

    // SECTION A — Hero produit
    +'<div style="text-align:center;margin-bottom:28px">'
    +'<div style="font-size:64px;margin-bottom:12px">'+ico+'</div>'
    +'<div style="font-family:Montserrat,sans-serif;font-size:22px;font-weight:800;color:var(--ink);margin-bottom:8px">'+_esc(titre)+'</div>'
    +(badges?'<div style="margin-bottom:12px">'+badges+'</div>':'')
    +(prixAncien?'<div style="font-size:14px;color:var(--ink4);text-decoration:line-through">'+new Intl.NumberFormat('fr-FR').format(prixAncien)+' FCFA</div>':'')
    +'<div style="font-family:Montserrat,sans-serif;font-size:32px;font-weight:900;color:var(--gold)">'+prixFmt+'</div>'
    +'<div style="margin-top:10px;display:inline-block;background:var(--grb);color:var(--gr);padding:6px 14px;border-radius:20px;font-size:12px;font-weight:700">✅ Accès immédiat après paiement</div>'
    +'</div>'

    // CTA principal
    +'<div style="display:flex;gap:10px;margin-bottom:28px;flex-wrap:wrap">'
    +'<button onclick="document.getElementById(\'productPageOverlay\').remove();openPaymentModal({'+_pArgs+'})" style="flex:1;min-width:200px;background:var(--gold);color:var(--ink);border:none;border-radius:14px;padding:16px 24px;font-family:Montserrat,sans-serif;font-size:15px;font-weight:800;cursor:pointer;box-shadow:0 4px 16px rgba(255,201,60,.3)">💳 Payer maintenant — '+prixFmt+'</button>'
    // « Ajouter au panier » RETIRÉ avec le panier (v1.18). Il était le SEUL
    // bouton à remplir DB.cart, et l'icône de la barre était le SEUL moyen de
    // rouvrir le panier : le garder aurait laissé l'acheteur remplir un panier
    // qu'il ne pouvait plus ouvrir. « Payer maintenant » prend toute la largeur.
    +'</div>'

    // SECTION B — Aperçu
    +(apercu?'<div style="margin-bottom:24px"><div style="font-family:Montserrat,sans-serif;font-size:14px;font-weight:700;color:var(--ink);margin-bottom:10px">📖 Aperçu du contenu</div><div style="background:var(--bg2);padding:16px;border-radius:0 12px 12px 0;font-size:13px;color:var(--ink2);line-height:1.7">'+_esc(apercu)+'</div></div>':'')

    // SECTION C — Description + chapitres
    +(desc?'<div style="margin-bottom:24px"><div style="font-family:Montserrat,sans-serif;font-size:14px;font-weight:700;color:var(--ink);margin-bottom:10px">📝 Description</div><div style="font-size:13px;color:var(--ink2);line-height:1.7">'+_esc(desc)+'</div></div>':'')
    +chapHtml

    // SECTION D — Informations livraison
    +'<div style="margin:28px 0;background:var(--sur2);border:1px solid var(--bg2);border-radius:14px;padding:20px">'
    +'<div style="font-family:Montserrat,sans-serif;font-size:14px;font-weight:700;color:var(--ink);margin-bottom:12px">📦 Informations de livraison</div>'
    +'<div style="font-size:13px;color:var(--ink2);line-height:2">'
    +'📩 Livraison par WhatsApp sous 24h<br>'
    +'📱 Compatible smartphone, tablette, ordinateur<br>'
    +'🔒 Paiement sécurisé — MoMo · Orange Money · PayPal · Carte'
    +'</div></div>'

    // SECTION E — CTA final
    +'<div style="display:flex;flex-direction:column;gap:10px;margin-top:24px">'
    +'<button onclick="document.getElementById(\'productPageOverlay\').remove();openPaymentModal({'+_pArgs+'})" style="background:var(--gold);color:var(--ink);border:none;border-radius:14px;padding:16px;font-family:Montserrat,sans-serif;font-size:15px;font-weight:800;cursor:pointer;box-shadow:0 4px 16px rgba(255,201,60,.3)">💳 Payer — '+prixFmt+'</button>'
    +'<a href="'+waUrl+'" target="_blank" rel="noopener" style="text-align:center;background:#25d366;color:#fff;border:none;border-radius:14px;padding:14px;font-family:Montserrat,sans-serif;font-size:14px;font-weight:700;cursor:pointer;text-decoration:none">📲 Commander par WhatsApp</a>'
    +'<button onclick="document.getElementById(\'productPageOverlay\').remove()" style="background:var(--bg2);color:var(--ink3);border:none;border-radius:14px;padding:12px;font-size:13px;font-weight:600;cursor:pointer">← Retour à la boutique</button>'
    +'</div>'

    +'</div></div>';

  var wrap = document.createElement('div');
  wrap.innerHTML = html;
  document.body.appendChild(wrap.firstChild);
}
window.openProductPage = openProductPage;

// ═══════════════════��══════════════════════════════════════════════
// ── v1.1 — MODULE 2 : PANIER DE COMMANDE ────────────────────────
// ═══════════════════════════════════════════════��══════════════════

function _getCart(){ DB.cart = DB.cart || []; return DB.cart; }

function addToCart(itemId, type){
  var cart = _getCart();
  var existing = cart.find(function(c){return c.id===itemId;});
  if(existing){ existing.qty = (existing.qty||1)+1; save(); renderCartBadge(); toast('✓ Quantité mise à jour'); return; }

  var item = null, titre = '', prix = 0;
  var el = DB.elearning || {};
  if(type === 'contenu'){
    item = (el.contenus||[]).find(function(c){return c.id===itemId;});
    if(item){ titre = item.titre; prix = item.prix||0; }
  } else if(type === 'abonnement'){
    item = (el.plans||[]).find(function(p){return p.id===itemId;});
    if(item){ titre = item.nom; prix = item.prix||0; }
  } else if(type === 'article'){
    item = (DB.books||[]).find(function(b){return b.id===itemId;});
    if(item){ titre = item.titre; prix = item.prix||0; }
  }
  if(!item){ toast('Produit introuvable','warn'); return; }

  cart.push({id:itemId, titre:titre, prix:prix, type:type, qty:1});
  save();
  renderCartBadge();
  toast('✓ '+titre+' ajouté au panier');
}

function removeFromCart(itemId){
  DB.cart = (DB.cart||[]).filter(function(c){return c.id!==itemId;});
  save();
  renderCartBadge();
  openCart();
}

function renderCartBadge(){
  var cart = _getCart();
  var badge = document.getElementById('cartBadge');
  if(!badge) return;
  var total = cart.reduce(function(s,c){return s+(c.qty||1);},0);
  if(total > 0){
    badge.style.display = 'flex';
    badge.textContent = total > 99 ? '99+' : total;
  } else {
    badge.style.display = 'none';
  }
}

function openCart(){
  var cart = _getCart();
  if(!cart.length){
    M('🛒 Votre panier','Aucun article',
      '<div style="text-align:center;padding:30px"><div style="font-size:48px;margin-bottom:12px">🛒</div><div style="font-size:14px;color:var(--ink4)">Votre panier est vide.<br>Parcourez notre boutique pour ajouter des articles.</div></div>',
      '<button class="btn bo" onclick="cm()">Fermer</button>');
    return;
  }
  var total = cart.reduce(function(s,c){return s + (c.prix||0)*(c.qty||1);},0);
  var totalFmt = new Intl.NumberFormat('fr-FR').format(total) + ' FCFA';
  var rows = cart.map(function(c){
    var sub = new Intl.NumberFormat('fr-FR').format((c.prix||0)*(c.qty||1));
    return '<div style="display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid var(--bg2)">'
      +'<div style="flex:1;min-width:0"><div style="font-size:13px;font-weight:600;color:var(--ink)">'+_esc(c.titre)+'</div>'
      +'<div style="font-size:11px;color:var(--ink4);margin-top:2px">'+_esc(c.type)+' · Qté: '+(c.qty||1)+'</div></div>'
      +'<div style="font-family:Montserrat,sans-serif;font-size:13px;font-weight:700;color:var(--gold);white-space:nowrap">'+sub+' F</div>'
      +'<button onclick="removeFromCart(\''+c.id+'\')" style="background:var(--reb);color:var(--re);border:none;border-radius:8px;width:28px;height:28px;font-size:14px;cursor:pointer">×</button>'
      +'</div>';
  }).join('');

  var labels = cart.map(function(c){return c.titre;}).join(' + ');
  if(labels.length > 60) labels = labels.substring(0,57)+'...';

  // v1.2.4 — Le panier règle N articles en UN paiement : on transmet le détail
  // ligne par ligne, sinon rien ne s'active et aucun auteur n'est rétribué.
  var _lignes = cart.map(function(c){
    return { intent:_intentDeType(c.type), targetId:c.id,
             montant:(c.prix||0)*(c.qty||1), label:c.titre };
  });
  var _lignesJson = _esc(JSON.stringify(_lignes)).replace(/"/g,'&quot;');

  M('🛒 Votre panier', cart.length+' article'+(cart.length>1?'s':''),
    rows
    +'<div style="display:flex;justify-content:space-between;align-items:center;padding:16px 0;margin-top:8px">'
    +'<span style="font-family:Montserrat,sans-serif;font-size:14px;font-weight:700;color:var(--ink)">Total</span>'
    +'<span style="font-family:Montserrat,sans-serif;font-size:20px;font-weight:900;color:var(--gold)">'+totalFmt+'</span>'
    +'</div>',
    '<button class="btn bo" onclick="cm()">Continuer les achats</button>'
    +'<button class="btn bi" onclick="cm();openPaymentModal({montant:'+total+',label:\'🛒 '+_esc(labels).replace(/'/g,"\\'")+'\',refPrefix:\'CART\',intent:\'cart\',lignes:'+_lignesJson+'})"><svg class="vico bico" aria-hidden="true"><use href="#lc-card"/></svg>Payer tout — '+totalFmt+'</button>',
    true);
}

window.addToCart = addToCart;
window.removeFromCart = removeFromCart;
window.openCart = openCart;
window.renderCartBadge = renderCartBadge;
setTimeout(renderCartBadge, 500);

// ══════════════════════════════════���═══════════════════════════════
// ── v1.1 — MODULE 4 : CODES PROMO ───────────────────────��───────
// ══════════════════════════════════════════��═══════════════════════

window.VERITAS_PROMOS = window.VERITAS_PROMOS || {
  'ELEVE10':  {pct:10, label:'10% élève', usage:0, max:100},
  'FIDELE5':  {pct:5,  label:'5% fidèle', usage:0, max:999},
  'VERITAS20':{pct:20, label:'20% spécial', usage:0, max:50},
  'RENTR2026':{pct:15, label:'Rentrée 2026', usage:0, max:200}
};

var _promoApplied = null;
var _promoDiscount = 0;

/* Le code promo affichait « Nouveau total : 20 000 FCFA »… et le bouton de
   paiement encaissait 25 000. Le montant part figé dans l'onclick au moment du
   rendu (`_payInitCampay('ref',MONTANT,…)`), et cette fonction ne touchait que
   du texte : le client lisait une remise qu'il ne recevait jamais. Le montant
   remis est désormais déposé dans _VRT_PAYX[ref], que _payInitCampay relit
   juste avant d'appeler le serveur.

   La table lue est DB.promoCodes et non plus VERITAS_PROMOS, pour deux raisons
   qui vont ensemble : VERITAS_PROMOS n'est jamais persistée (un code créé par
   l'admin disparaît au rechargement), et surtout le SERVEUR ne connaît qu'elle
   — il borne désormais tout sous-paiement à la meilleure remise active en base.
   Appliquer ici une remise que le serveur ignore ferait payer le client pour
   rien : paiement accepté, accès refusé. */
function appliquerPromo(originalMontant, ref){
  var code = (document.getElementById('promoInput')?.value||'').trim().toUpperCase();
  var fb = document.getElementById('promoFeedback');
  var _pose = function(m){
    if(!ref) return;
    window._VRT_PAYX = window._VRT_PAYX || {};
    window._VRT_PAYX[ref] = window._VRT_PAYX[ref] || {};
    window._VRT_PAYX[ref].montantFinal = m;
  };
  if(!code){ if(fb) fb.innerHTML=''; _promoApplied=null; _promoDiscount=0; _pose(0); return; }

  var promo = ((typeof DB!=='undefined' && DB.promoCodes) || []).find(function(p){
    return p && p.actif && String(p.code||'').toUpperCase() === code;
  });
  if(!promo){
    if(fb) fb.innerHTML='<span style="color:var(--re);font-size:12px;font-weight:600">❌ Code invalide ou expiré</span>';
    _promoApplied=null; _promoDiscount=0; _pose(0);
    toast('❌ Code invalide ou expiré','warn');
    return;
  }

  var val = parseFloat(promo.reduction)||0;
  var reduction = (promo.type === 'fixed') ? Math.round(val)
                                           : Math.round(originalMontant * val / 100);
  if(reduction >= originalMontant) reduction = originalMontant - 1;   // jamais 0 FCFA à encaisser
  if(reduction < 0) reduction = 0;
  var newTotal = originalMontant - reduction;

  _promoApplied = code;
  _promoDiscount = Math.round(reduction * 100 / (originalMontant||1));
  _pose(newTotal);

  if(fb) fb.innerHTML='<span style="color:var(--gr);font-size:12px;font-weight:600">✅ '+_esc(promo.desc||code)+' — -'+new Intl.NumberFormat('fr-FR').format(reduction)+' FCFA → Nouveau total : <strong>'+new Intl.NumberFormat('fr-FR').format(newTotal)+' FCFA</strong></span>';
  toast('✅ Code appliqué — '+new Intl.NumberFormat('fr-FR').format(reduction)+' FCFA de réduction !');

  var totalEl = document.getElementById('payStepTotal');
  if(totalEl) totalEl.textContent = new Intl.NumberFormat('fr-FR').format(newTotal) + ' FCFA';
}
window.appliquerPromo = appliquerPromo;

// ═════════════════════════════════════════════════���════════════════
// ── v1.1 — MODULE 3 : TUNNEL DE PAIEMENT AMÉLIORÉ ───────────────
// ═══════════════════════════════��══════════════════════���═══════════

var _origOpenPaymentModal = openPaymentModal;

openPaymentModal = function(payInfo){
  payInfo = payInfo || {};
  var montant = payInfo.montant || 0;
  var label = payInfo.label || 'Paiement VÉRITAS';
  var ref = payInfo.ref || _payRef(payInfo.refPrefix || 'VT');
  var P = window.VERITAS_PAYMENTS;
  if(!P) return;

  // Le bouton « ⚡ Payer maintenant » est un onclick construit en chaîne : il ne
  // peut transporter que des scalaires. Le détail d'un PANIER (N articles en un
  // seul paiement) n'y entrait donc pas, et le serveur recevait un paiement
  // « cart » sans savoir quoi débloquer. On le met de côté par référence ;
  // _payInitCampay le rattache au corps de la requête.
  try{
    window._VRT_PAYX = window._VRT_PAYX || {};
    window._VRT_PAYX[ref] = { lignes: (payInfo.lignes && payInfo.lignes.length) ? payInfo.lignes : null };
  }catch(e){}

  _promoApplied = null;
  _promoDiscount = 0;

  var montantFmt = new Intl.NumberFormat('fr-FR').format(montant) + ' FCFA';
  var montantEUR = (montant / 655).toFixed(2);

  var waNum = (P.whatsapp||'').replace(/[^0-9+]/g,'').replace(/^\+/,'');

  // Stepper HTML
  var stepper = '<div style="display:flex;align-items:center;justify-content:center;gap:8px;margin-bottom:20px">'
    +'<div id="payStep1Ind" style="width:28px;height:28px;border-radius:50%;background:var(--gold);color:var(--ink);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800">①</div>'
    +'<div style="width:30px;height:2px;background:var(--bg3)"></div>'
    +'<div id="payStep2Ind" style="width:28px;height:28px;border-radius:50%;background:var(--bg3);color:var(--ink4);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800">②</div>'
    +'<div style="width:30px;height:2px;background:var(--bg3)"></div>'
    +'<div id="payStep3Ind" style="width:28px;height:28px;border-radius:50%;background:var(--bg3);color:var(--ink4);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800">③</div>'
    +'</div>'
    +'<div style="display:flex;justify-content:center;gap:24px;font-size:10px;color:var(--ink4);margin-bottom:16px;text-align:center">'
    +'<span style="width:70px">Coordonnées</span><span style="width:70px">Paiement</span><span style="width:70px">Confirmer</span></div>';

  // Step 1 : Client form
  /* Acheter un manuel demandait TROIS écrans : la fiche du livre, puis « Vos
     coordonnées », puis le paiement. Or l'appelant transmet déjà `customerNom`
     et `customerTel` (confirmerAchat les tire de la session), et l'étape ① les
     redemandait quand même — à vide. Le client connecté retapait son propre nom
     avant de pouvoir payer, et beaucoup abandonnaient là.
     Les champs sont donc préremplis, et quand nom + téléphone sont déjà connus
     l'étape ① est SAUTÉE : on ouvre directement sur les moyens de paiement. Elle
     reste accessible d'un clic (« ← Précédent ») pour corriger une faute de
     frappe, et le visiteur non connecté la voit toujours — lui, on ne sait rien
     de lui. */
  var _cNom  = (payInfo.customerNom  || ((typeof SES!=='undefined'&&SES) ? ((SES.pre||'')+' '+(SES.nom||'')) : '')).trim();
  var _cTel  = (payInfo.customerTel  || ((typeof SES!=='undefined'&&SES) ? (SES.tel||'')   : '')).trim();
  var _cMail = (payInfo.customerEmail || ((typeof SES!=='undefined'&&SES) ? (SES.email||'') : '')).trim();
  var _coordConnues = !!(_cNom && _cTel);

  var step1 = '<div id="payStep1">'
    +'<div style="background:linear-gradient(135deg,#142554,#1E3A8A);color:#fff;padding:16px;border-radius:14px;margin-bottom:16px">'
    +'<div style="font-size:11px;letter-spacing:2px;opacity:.7;text-transform:uppercase">Paiement pour</div>'
    +'<div style="font-family:Montserrat,sans-serif;font-size:18px;font-weight:800;margin-top:4px">'+_esc(label)+'</div>'
    +'<div style="font-size:28px;font-weight:900;color:#FFC93C;margin-top:8px" id="payStepTotal">'+montantFmt+'</div>'
    +'<div style="font-size:11px;opacity:.7;margin-top:2px">≈ '+montantEUR+' € / USD</div>'
    // v1.14 — TRANSPARENCE DES FRAIS. Un parent qui découvre un écart entre le
    // prix annoncé et la somme débitée ne revient pas payer une seconde fois.
    // On annonce donc les frais opérateur AVANT le paiement, et on dit qu'ils
    // sont absorbés : le client paie le montant affiché, pas un franc de plus.
    +'<div style="margin-top:10px;padding:7px 11px;background:rgba(255,255,255,.08);border-radius:8px;font-size:11.5px;line-height:1.5">'
      +'Frais opérateur estimés (2 %) : <strong>'+new Intl.NumberFormat('fr-FR').format(Math.round(montant*0.02))+' FCFA</strong>'
      +' — <span style="opacity:.85">pris en charge par le centre. Vous êtes débité de <strong style="color:#FFC93C">'+montantFmt+'</strong>.</span>'
    +'</div>'
    +'</div>'
    +'<div style="font-family:Montserrat,sans-serif;font-size:13px;font-weight:700;margin-bottom:10px;color:var(--ink)">👤 Vos coordonnées</div>'
    +'<div class="fg2">'
    +'<div class="fg"><span class="fl">Nom complet *</span><input class="fi" id="payNom" value="'+_esc(_cNom)+'" placeholder="Ex: MBALLA Jean-Pierre"></div>'
    +'<div class="fg"><span class="fl">Numéro WhatsApp *</span><input class="fi" id="payTel" type="tel" value="'+_esc(_cTel)+'" placeholder="+237 6XX XX XX XX"></div>'
    +'<div class="fg"><span class="fl">Email (pour PDF)</span><input class="fi" id="payEmail" type="email" value="'+_esc(_cMail)+'" placeholder="votre@email.com"></div>'
    +'</div>'
    +'<div style="margin-top:12px"><span class="fl">Code promo</span><div style="display:flex;gap:8px"><input class="fi" id="promoInput" placeholder="Ex: ELEVE10" style="flex:1;text-transform:uppercase"><button class="btn bi sm" onclick="appliquerPromo('+montant+',\''+ref+'\')" style="white-space:nowrap">Appliquer</button></div><div id="promoFeedback" style="margin-top:6px"></div></div>'
    +'<div style="margin-top:16px;text-align:right"><button class="btn bi" onclick="_payGoStep(2)">Suivant →</button></div>'
    +'</div>';

  // Step 2 : Payment methods
  // ⚠️ v1.12 — C'EST CETTE MODALE QUI S'AFFICHE. Une seconde définition,
  // plus ancienne et porteuse de la tuile CamPay, existe plus haut dans le
  // fichier ; elle est ÉCRASÉE par ce `openPaymentModal = function` et n'est
  // jamais exécutée. Sans le bloc ci-dessous, l'encaissement automatique
  // n'apparaîtrait donc JAMAIS aux clients, même une fois les clés CamPay
  // posées sur le serveur.
  var _campayTile = (typeof _payCampayReady === 'function' && _payCampayReady())
    ? ('<div style="background:#fff;border:2px solid #059669;border-radius:12px;padding:14px;grid-column:1/-1">'
      +'<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">'
        +'<div style="font-size:26px">⚡</div>'
        +'<div style="font-family:Montserrat,sans-serif;font-weight:800;font-size:13.5px;color:#142554">'+_payTileTitre()+'</div>'
        +'<span style="margin-left:auto;background:linear-gradient(135deg,#059669,#3A8F73);color:#fff;font-size:9.5px;font-weight:800;padding:2px 8px;border-radius:8px">⚡ AUTO</span>'
      +'</div>'
      +'<div style="font-size:11px;color:var(--ink4);line-height:1.5;margin-bottom:8px">'+_payTileTexte()+'</div>'
      +'<input class="fi" id="campayPhoneInput_'+ref+'" placeholder="'+_payTilePlaceholder()+'" value="'+String(payInfo.customerTel||'').replace(/[^0-9+]/g,'')+'" style="font-size:12px;padding:8px 10px;width:100%;margin-bottom:8px">'
      +'<button class="btn" style="width:100%;background:linear-gradient(135deg,#059669,#3A8F73);color:#fff;border:none;border-radius:8px;padding:12px;font-weight:800;font-size:13px;cursor:pointer" onclick="_payInitCampay(\''+ref+'\','+montant+',\''+String(label).replace(/[\\\\\x27"]/g,'')+'\',\''+(payInfo.intent||'generic')+'\',\''+(payInfo.targetId||'')+'\',\''+(payInfo.customerAccountId||'')+'\',\''+String(payInfo.customerNom||'').replace(/[\\\\\x27"]/g,'')+'\')">⚡ Payer maintenant — '+montantFmt+'</button>'
    +'</div>')
    : '';

  var step2 = '<div id="payStep2" style="display:none">'
    +'<div class="bold s mb10" style="color:var(--ink2)">💰 Choisissez votre moyen de paiement :</div>'
    // Bandeau d'attente : n'a de sens QUE pour les moyens manuels. Quand
    // l'encaissement automatique est disponible, promettre « 24 h » au moment
    // de payer découragerait inutilement le client.
    + (_campayTile
        ? '<div class="ib ibt mb12" style="background:rgba(5,150,105,.08);"><span>⚡</span><span>'+_payTileBandeau()+'</span></div>'
        : '<div class="ib ibt mb12" style="background:rgba(220,38,38,.08);"><span>⚠️</span><span><strong>Important :</strong> après votre paiement, passez à l\'étape 3 pour nous envoyer votre confirmation avec la référence <strong>'+ref+'</strong>. Votre accès sera activé sous 24 h.</span></div>')
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px;margin-bottom:16px">'
    + _campayTile
    // MoMo
    +'<div style="background:#fff;border:2px solid '+P.momo.couleur+';border-radius:12px;padding:12px;cursor:pointer" onclick="_payCopy(\''+P.momo.numero.replace(/[^0-9+]/g,'')+'\',\'Numéro MoMo\')">'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px"><div style="font-size:24px">'+P.momo.ico+'</div><div style="font-family:Montserrat,sans-serif;font-weight:800;font-size:13px;color:#142554">'+P.momo.label+'</div></div>'
    +'<div style="font-family:monospace;font-size:14px;font-weight:800;color:'+P.momo.couleur+'">'+P.momo.numero+'</div>'
    +'<div style="font-size:10px;color:var(--ink4);margin-top:4px">Nom: '+P.momo.nomCompte+' · USSD: '+P.momo.code+'</div>'
    +'<div style="font-size:9px;color:var(--ink4);margin-top:4px;font-style:italic">👆 Cliquez pour copier</div></div>'
    // Orange
    +'<div style="background:#fff;border:2px solid '+P.orange.couleur+';border-radius:12px;padding:12px;cursor:pointer" onclick="_payCopy(\''+P.orange.numero.replace(/[^0-9+]/g,'')+'\',\'Numéro Orange Money\')">'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px"><div style="font-size:24px">'+P.orange.ico+'</div><div style="font-family:Montserrat,sans-serif;font-weight:800;font-size:13px;color:#142554">'+P.orange.label+'</div></div>'
    +'<div style="font-family:monospace;font-size:14px;font-weight:800;color:'+P.orange.couleur+'">'+P.orange.numero+'</div>'
    +'<div style="font-size:10px;color:var(--ink4);margin-top:4px">Nom: '+P.orange.nomCompte+' · USSD: '+P.orange.code+'</div>'
    +'<div style="font-size:9px;color:var(--ink4);margin-top:4px;font-style:italic">👆 Cliquez pour copier</div></div>'
    // PayPal
    +'<a href="'+P.paypal.url+'" target="_blank" rel="noopener" style="text-decoration:none;background:#fff;border:2px solid '+P.paypal.couleur+';border-radius:12px;padding:12px;display:block">'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px"><div style="font-size:24px">'+P.paypal.ico+'</div><div style="font-family:Montserrat,sans-serif;font-weight:800;font-size:13px;color:#142554">'+P.paypal.label+'</div></div>'
    +'<div style="font-size:11px;color:var(--ink4)">Paiement international sécurisé</div>'
    +'<div style="font-size:10px;color:'+P.paypal.couleur+';margin-top:4px;font-weight:700">→ Ouvrir PayPal</div></a>'
    // Stripe (affiché seulement si configuré)
    + (_payOK(P.stripe.url) ? ('<a href="'+P.stripe.url+'" target="_blank" rel="noopener" style="text-decoration:none;background:#fff;border:2px solid '+P.stripe.couleur+';border-radius:12px;padding:12px;display:block">'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px"><div style="font-size:24px">'+P.stripe.ico+'</div><div style="font-family:Montserrat,sans-serif;font-weight:800;font-size:13px;color:#142554">'+P.stripe.label+'</div></div>'
    +'<div style="font-size:11px;color:var(--ink4)">Visa · Mastercard · Amex</div>'
    +'<div style="font-size:10px;color:'+P.stripe.couleur+';margin-top:4px;font-weight:700">→ Payer par carte</div></a>') : '')
    // Bank (affiché seulement si configuré)
    + (_payOK(P.bank.iban) ? ('<div style="background:#fff;border:2px solid '+P.bank.couleur+';border-radius:12px;padding:12px;grid-column:1/-1">'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px"><div style="font-size:24px">'+P.bank.ico+'</div><div style="font-family:Montserrat,sans-serif;font-weight:800;font-size:13px;color:#142554">'+P.bank.label+'</div></div>'
    +'<div style="font-size:11px;color:var(--ink3);line-height:1.6"><strong>Titulaire:</strong> '+P.bank.titulaire+' · <strong>Banque:</strong> '+P.bank.banque+'<br><strong>IBAN:</strong> <span style="font-family:monospace;background:var(--bg2);padding:2px 4px;border-radius:4px;font-size:10px">'+P.bank.iban+'</span> · <strong>SWIFT:</strong> '+P.bank.swift+'</div></div>') : '')
    +'</div>'
    +'<div style="display:flex;justify-content:space-between;margin-top:12px"><button class="btn bo" onclick="_payGoStep(1)">← Précédent</button><button class="btn bi" onclick="_payGoStep(3)">J\'ai payé → Confirmer</button></div>'
    +'</div>';

  // Step 3 : Confirmation
  var step3 = '<div id="payStep3" style="display:none">'
    +'<div style="text-align:center;padding:16px">'
    +'<div style="font-size:48px;margin-bottom:12px">✅</div>'
    +'<div style="font-family:Montserrat,sans-serif;font-size:18px;font-weight:800;color:var(--ink);margin-bottom:8px">Confirmation de paiement</div>'
    +'<div style="background:var(--bg2);border-radius:12px;padding:16px;margin:16px 0;text-align:left">'
    +'<div style="font-size:12px;color:var(--ink4);margin-bottom:4px">Référence de transaction</div>'
    +'<div style="font-family:monospace;font-size:18px;font-weight:800;color:var(--gold)">'+ref+'</div>'
    +'<div style="font-size:12px;color:var(--ink4);margin-top:8px">Montant : <strong>'+montantFmt+'</strong></div>'
    +'</div>'
    +'<div style="font-size:13px;color:var(--ink2);line-height:1.7;margin-bottom:16px">Notre équipe activera votre accès sous <strong>24h</strong> après vérification.<br>Conservez cette référence.</div>'
    +'<button class="btn bo sm" onclick="_payCopy(\''+ref+'\',\'Référence\')" style="margin-bottom:12px"><svg class="vico bico" aria-hidden="true"><use href="#lc-clipboard"/></svg>Copier la référence</button>'
    +'</div>'
    +'<div id="payStep3WA"></div>'
    +'<div style="display:flex;justify-content:space-between;margin-top:12px"><button class="btn bo" onclick="_payGoStep(2)">← Précédent</button><button class="btn bi" onclick="cm()">Fermer</button></div>'
    +'</div>';

  var body = stepper + step1 + step2 + step3;

  // Save attempt
  try{
    DB.payAttempts = DB.payAttempts || [];
    DB.payAttempts.push({
      ref: ref, label: label, montant: montant,
      date: new Date().toISOString(),
      status: 'pending'
    });
    if(typeof save === 'function') save();
  }catch(e){}

  M('💰 Paiement Sécurisé', label+' — '+montantFmt, body,
    '<button class="btn bo" onclick="cm()">Fermer</button>', true);

  // Un écran de moins : on n'ouvre pas sur un formulaire déjà rempli. Le
  // setTimeout laisse M() poser le DOM — _payGoStep lit les champs, qui
  // n'existent pas encore à cet instant.
  if(_coordConnues) setTimeout(function(){ try{ _payGoStep(2); }catch(e){} }, 0);
};
window.openPaymentModal = openPaymentModal;

function _payGoStep(step){
  var s1=document.getElementById('payStep1'), s2=document.getElementById('payStep2'), s3=document.getElementById('payStep3');
  var i1=document.getElementById('payStep1Ind'), i2=document.getElementById('payStep2Ind'), i3=document.getElementById('payStep3Ind');
  if(!s1||!s2||!s3) return;

  if(step===2){
    var nom=(document.getElementById('payNom')?.value||'').trim();
    var tel=(document.getElementById('payTel')?.value||'').trim();
    if(!nom||!tel){toast('Nom et WhatsApp requis','warn');return;}
    // Save client info to latest payAttempt
    var latest = (DB.payAttempts||[])[(DB.payAttempts||[]).length-1];
    if(latest){latest.clientNom=nom;latest.clientTel=tel;latest.clientEmail=(document.getElementById('payEmail')?.value||'').trim();if(_promoApplied){latest.promo=_promoApplied;latest.discount=_promoDiscount;latest.montantFinal=Math.round(latest.montant*(100-_promoDiscount)/100);}save();}
  }

  if(step===3){
    // Build WhatsApp confirmation
    var latest2=(DB.payAttempts||[])[(DB.payAttempts||[]).length-1]||{};
    var cNom=latest2.clientNom||'';
    var cTel=latest2.clientTel||'';
    var mFinal=latest2.montantFinal||latest2.montant||0;
    var mFinalFmt=new Intl.NumberFormat('fr-FR').format(mFinal)+' FCFA';
    var P2=window.VERITAS_PAYMENTS;
    var waNum2=(P2.whatsapp||'').replace(/[^0-9+]/g,'').replace(/^\+/,'');
    var waMsg2=encodeURIComponent('Bonjour,\n\nJe viens d\'effectuer un paiement.\n\n👤 Nom: '+cNom+'\n📱 Tél: '+cTel+'\n📦 Article: '+(latest2.label||'')+'\n💰 Montant: '+mFinalFmt+'\n🔖 Réf: '+(latest2.ref||'')+'\n💳 Moyen: [MoMo / Orange / PayPal / Carte / Virement]\n\nMerci de confirmer.');
    var waUrl2='https://wa.me/'+waNum2+'?text='+waMsg2;
    var s3wa=document.getElementById('payStep3WA');
    if(s3wa) s3wa.innerHTML='<a href="'+waUrl2+'" target="_blank" rel="noopener" style="display:flex;align-items:center;justify-content:center;gap:10px;background:#25d366;color:#fff;border-radius:12px;padding:14px;font-family:Montserrat,sans-serif;font-weight:800;font-size:14px;text-decoration:none;box-shadow:0 4px 16px rgba(37,211,102,.4)">📲 Envoyer ma confirmation WhatsApp</a>';
  }

  s1.style.display=step===1?'block':'none';
  s2.style.display=step===2?'block':'none';
  s3.style.display=step===3?'block':'none';
  if(i1){i1.style.background=step>=1?'var(--gold)':'var(--bg3)';i1.style.color=step>=1?'var(--ink)':'var(--ink4)';}
  if(i2){i2.style.background=step>=2?'var(--gold)':'var(--bg3)';i2.style.color=step>=2?'var(--ink)':'var(--ink4)';}
  if(i3){i3.style.background=step>=3?'var(--gold)':'var(--bg3)';i3.style.color=step>=3?'var(--ink)':'var(--ink4)';}
}
window._payGoStep = _payGoStep;

// ══════════════════════════════════════════════════���═══════════════
// ── v1.1 — MODULE 5 : TABLEAU DE BORD PAIEMENTS (admin) ─────────
// ══════════════════════════════════════════════════════════════════

function pgPaiementsAdmin(){
  if(!iA()) return na();
  var atts = (DB.payAttempts||[]).slice().reverse();
  var paid = atts.filter(function(a){return a.status==='paid';});
  var pending = atts.filter(function(a){return a.status==='pending';});
  var totalCollected = paid.reduce(function(s,a){return s+(a.montantFinal||a.montant||0);},0);
  var avgRevenue = paid.length ? Math.round(totalCollected/paid.length) : 0;

  // KPIs
  var h = '<div class="fl2 fic fsb mb16 fw g8"><div class="bold" style="font-size:18px">💳 Tableau de bord Paiements</div></div>';
  h += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:24px">';
  h += '<div style="background:linear-gradient(135deg,var(--grb),var(--grd));border-radius:14px;padding:16px;text-align:center"><div style="font-size:11px;color:var(--gr);font-weight:700;text-transform:uppercase;letter-spacing:1px">Total collecté</div><div style="font-family:Montserrat,sans-serif;font-size:20px;font-weight:900;color:var(--gr);margin-top:6px">'+new Intl.NumberFormat('fr-FR').format(totalCollected)+'</div><div style="font-size:10px;color:var(--ink4)">FCFA</div></div>';
  h += '<div style="background:linear-gradient(135deg,var(--orb),var(--ord));border-radius:14px;padding:16px;text-align:center"><div style="font-size:11px;color:var(--or);font-weight:700;text-transform:uppercase;letter-spacing:1px">En attente</div><div style="font-family:Montserrat,sans-serif;font-size:20px;font-weight:900;color:var(--or);margin-top:6px">'+pending.length+'</div><div style="font-size:10px;color:var(--ink4)">transactions</div></div>';
  h += '<div style="background:linear-gradient(135deg,var(--blb),var(--bld));border-radius:14px;padding:16px;text-align:center"><div style="font-size:11px;color:var(--bl);font-weight:700;text-transform:uppercase;letter-spacing:1px">Validées</div><div style="font-family:Montserrat,sans-serif;font-size:20px;font-weight:900;color:var(--bl);margin-top:6px">'+paid.length+'</div><div style="font-size:10px;color:var(--ink4)">transactions</div></div>';
  h += '<div style="background:linear-gradient(135deg,var(--pub),var(--pud));border-radius:14px;padding:16px;text-align:center"><div style="font-size:11px;color:var(--pu);font-weight:700;text-transform:uppercase;letter-spacing:1px">Revenu moyen</div><div style="font-family:Montserrat,sans-serif;font-size:20px;font-weight:900;color:var(--pu);margin-top:6px">'+new Intl.NumberFormat('fr-FR').format(avgRevenue)+'</div><div style="font-size:10px;color:var(--ink4)">FCFA / transaction</div></div>';
  h += '</div>';

  // Filter
  h += '<div style="display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap">';
  h += '<button class="btn bo sm" onclick="window._payFilter=\'\';re();" style="'+((!window._payFilter)?'background:var(--ink);color:#fff':'')+'">Tous ('+atts.length+')</button>';
  h += '<button class="btn bo sm" onclick="window._payFilter=\'pending\';re();" style="'+((window._payFilter==='pending')?'background:var(--or);color:#fff':'')+'">En attente ('+pending.length+')</button>';
  h += '<button class="btn bo sm" onclick="window._payFilter=\'paid\';re();" style="'+((window._payFilter==='paid')?'background:var(--gr);color:#fff':'')+'">Payés ('+paid.length+')</button>';
  h += '</div>';

  // Filtered list
  var filtered = atts;
  if(window._payFilter==='pending') filtered = pending;
  else if(window._payFilter==='paid') filtered = paid;

  // Table
  if(filtered.length){
    h += '<div class="tw" style="max-height:400px;overflow:auto"><table><thead><tr><th>Réf</th><th>Nom</th><th>Tél</th><th>Article</th><th>Montant</th><th>Date</th><th>Statut</th><th>Actions</th></tr></thead><tbody>';
    filtered.forEach(function(a){
      var dt = a.date ? new Date(a.date).toLocaleString('fr-FR') : '';
      var statColor = a.status==='paid' ? 'var(--gr)' : 'var(--or)';
      var mnt = a.montantFinal || a.montant || 0;
      var clientWA = (a.clientTel||'').replace(/[^0-9]/g,'');
      if(clientWA && !clientWA.startsWith('237')) clientWA = '237'+clientWA;
      h += '<tr>'
        +'<td style="font-family:monospace;font-size:10px">'+_esc(a.ref||'')+'</td>'
        +'<td style="font-size:11px">'+_esc(a.clientNom||'-')+'</td>'
        +'<td style="font-size:11px">'+_esc(a.clientTel||'-')+'</td>'
        +'<td style="font-size:11px;max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+_esc(a.label||'')+'</td>'
        +'<td style="font-size:11px;white-space:nowrap;font-weight:700">'+new Intl.NumberFormat('fr-FR').format(mnt)+' F</td>'
        +'<td style="font-size:10px;color:var(--ink4);white-space:nowrap">'+dt+'</td>'
        +'<td><span style="padding:2px 8px;border-radius:10px;font-size:9px;font-weight:800;background:'+statColor+';color:#fff">'+_esc(a.status||'pending').toUpperCase()+'</span></td>'
        +'<td style="white-space:nowrap">'
        +'<button class="btn xs bi" onclick="(function(){var a=DB.payAttempts.find(function(x){return x.ref===\''+a.ref+'\'});if(a){a.status=\'paid\';save();re();toast(\'✓ Marqué payé\');}})()">✓</button> '
        +(clientWA?'<a href="https://wa.me/'+clientWA+'" target="_blank" class="btn xs bo" style="text-decoration:none">📲</a> ':'')
        +'<button class="btn xs bo" style="color:var(--re)" onclick="(function(){if(!confirm(\'Supprimer ?\'))return;DB.payAttempts=DB.payAttempts.filter(function(x){return x.ref!==\''+a.ref+'\'});save();re();})()">🗑</button>'
        +'</td></tr>';
    });
    h += '</tbody></table></div>';
  } else {
    h += '<div style="text-align:center;padding:30px;color:var(--ink4)">Aucune transaction trouvée.</div>';
  }

  // Monthly chart (CSS bars)
  h += '<div style="margin-top:28px"><div style="font-family:Montserrat,sans-serif;font-size:14px;font-weight:700;margin-bottom:16px;color:var(--ink)">📊 Revenus mensuels (6 derniers mois)</div>';
  var months = [];
  var now = new Date();
  for(var mi=5;mi>=0;mi--){
    var d = new Date(now.getFullYear(), now.getMonth()-mi, 1);
    var mKey = d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2);
    var mLabel = ['Jan','Fév','Mar','Avr','Mai','Jun','Jul','Aoû','Sep','Oct','Nov','Déc'][d.getMonth()];
    var mTotal = paid.filter(function(a){return(a.date||'').startsWith(mKey);}).reduce(function(s,a){return s+(a.montantFinal||a.montant||0);},0);
    months.push({label:mLabel, total:mTotal});
  }
  var maxM = Math.max.apply(null, months.map(function(m){return m.total;}))||1;
  h += '<div style="display:flex;align-items:flex-end;gap:8px;height:120px;padding:8px 0;border-bottom:2px solid var(--bg2)">';
  months.forEach(function(m){
    var pct = Math.round(m.total/maxM*100);
    h += '<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%">'
      +'<div style="font-size:9px;color:var(--ink4);margin-bottom:4px">'+(m.total?new Intl.NumberFormat('fr-FR').format(m.total):'0')+'</div>'
      +'<div style="width:100%;max-width:40px;height:'+Math.max(pct,4)+'%;background:var(--gold);border-radius:6px 6px 0 0;transition:height .3s"></div>'
      +'</div>';
  });
  h += '</div><div style="display:flex;gap:8px;margin-top:6px">';
  months.forEach(function(m){ h+='<div style="flex:1;text-align:center;font-size:10px;color:var(--ink4);font-weight:600">'+m.label+'</div>'; });
  h += '</div></div>';

  // Promo codes section
  h += '<div style="margin-top:28px"><div style="font-family:Montserrat,sans-serif;font-size:14px;font-weight:700;margin-bottom:12px;color:var(--ink)">🏷️ Codes Promo actifs</div>';
  // Source unique : DB.promoCodes. C'est la seule table PERSISTÉE, la seule que
  // le tunnel de paiement applique, et la seule que le serveur consulte pour
  // borner un sous-paiement. L'ancienne window.VERITAS_PROMOS vivait en mémoire :
  // les codes créés ici disparaissaient au rechargement, et l'écran affichait
  // pourtant « ACTIF ».
  var promos = (typeof DB!=='undefined' && DB.promoCodes) ? DB.promoCodes : [];
  if(promos.length){
    h += '<div class="tw"><table><thead><tr><th>Code</th><th>Réduction</th><th>Propriétaire</th><th>Commission</th><th>Description</th><th>Utilisations</th><th>Statut</th></tr></thead><tbody>';
    var _LV = (typeof _prtL==='function') ? _prtL() : {};
    promos.forEach(function(p){
      var actif = !!p.actif;
      var red = (p.type==='fixed') ? fmt(p.reduction) : (p.reduction+' %');
      // Qui touche quoi : la colonne qui manquait. Sans elle, impossible de
      // savoir au premier coup d'œil quels codes rémunèrent quelqu'un.
      var op = p.partnerId ? (DB.partners||[]).find(function(x){return x && x.id===p.partnerId;}) : null;
      var olv = op ? (_LV[op.level||'bronze'] || _LV.bronze || {}) : null;
      var oNom = op ? (op.nom||op.name||op.code||'—') : (p.partnerNom||'');
      h += '<tr><td style="font-family:monospace;font-weight:700">'+_esc(p.code||'')+'</td><td>'+_esc(red)+'</td>'
        +'<td>'+(oNom ? _esc(oNom) : '<span style="opacity:.5">— personne —</span>')+'</td>'
        +'<td>'+(olv ? '<b>'+Math.round((olv.commission||0)*100)+' %</b> <span style="opacity:.6;font-size:11px">'+_esc(olv.label||'')+'</span>' : '<span style="opacity:.5">—</span>')+'</td>'
        +'<td>'+_esc(p.desc||'')+'</td><td>'+(p.usage||0)+'</td>'
        +'<td><span style="padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;background:'+(actif?'var(--gr)':'var(--re)')+';color:#fff">'+(actif?'ACTIF':'INACTIF')+'</span></td></tr>';
    });
    h += '</tbody></table></div>';
  }
  h += '<button class="btn bo sm mt14" onclick="_mAddPromo()">+ Ajouter un code promo</button>';
  h += '</div>';

  return h;
}

function _mAddPromo(){
  /* Un code promo sans propriétaire ne rémunère PERSONNE. C'était la source de
     confusion : on créait « MIT » en croyant faire un code de parrainage, alors
     que DB.promoCodes ne fait que réduire le prix — les commissions, elles, se
     lisent sur DB.partners[].code. Deux tables, deux effets, un seul écran de
     création : le champ ci-dessous les relie enfin, et affiche le taux réel du
     partenaire (il découle de son PALIER, il ne se saisit pas). */
  var parts = (typeof DB!=='undefined' && DB.partners) ? DB.partners.filter(function(p){return p && p.status==='active';}) : [];
  var L = (typeof _prtL==='function') ? _prtL() : {};
  var optsP = '<option value="">— Aucun (simple réduction, personne n\'est rémunéré) —</option>'
    + parts.map(function(p){
        var lv = L[p.level||'bronze'] || L.bronze || {commission:0.05,label:'Bronze'};
        return '<option value="'+_esc(p.id)+'">'+_esc(p.nom||p.name||p.code||p.id)
             + ' — '+(lv.label||p.level||'Bronze')+' · '+Math.round((lv.commission||0)*100)+' % de commission</option>';
      }).join('');

  M('🏷️ Nouveau code promo','',
    '<div class="fg2">'
    +'<div class="fg"><span class="fl">Code *</span><input class="fi" id="npCode" placeholder="MONCODE" style="text-transform:uppercase"></div>'
    +'<div class="fg"><span class="fl">Réduction (%) *</span><input class="fi" id="npPct" type="number" min="1" max="100" placeholder="10"></div>'
    +'<div class="fg"><span class="fl">Label</span><input class="fi" id="npLabel" placeholder="Description courte"></div>'
    +'<div class="fg"><span class="fl">Utilisations max *</span><input class="fi" id="npMax" type="number" min="1" placeholder="100"></div>'
    +'</div>'
    +'<div class="fg" style="margin-top:12px"><span class="fl">Propriétaire du code (parrain rémunéré)</span>'
      +'<select class="fi" id="npOwner">'+optsP+'</select></div>'
    +'<div class="ib ibt" style="margin-top:10px"><span>💡</span><span>'
      +(parts.length
        ? 'La <strong>réduction</strong> est ce que le client économise. La <strong>commission</strong> est ce que touche le parrain : elle découle de son palier (Bronze 5 % · Argent 8 % · Or 10 % · Diamant 12 %) et ne se saisit pas ici. Elle est recalculée par le serveur à chaque vente.'
        : 'Aucun partenaire actif pour l\'instant : ce code réduira le prix sans rémunérer personne. Créez d\'abord un partenaire dans <strong>Partenaires</strong> pour en faire un code de parrainage.')
    +'</span></div>',
    '<button class="btn bo" onclick="cm()">Annuler</button><button class="btn bi" onclick="_saveNewPromo()"><svg class="vico bico" aria-hidden="true"><use href="#lc-check"/></svg>Créer</button>');
}

function _saveNewPromo(){
  var code=(document.getElementById('npCode')?.value||'').trim().toUpperCase();
  var pct=parseInt(document.getElementById('npPct')?.value)||0;
  var label=(document.getElementById('npLabel')?.value||'').trim();
  var max=parseInt(document.getElementById('npMax')?.value)||100;
  if(!code||!pct){toast('Code et % requis','warn');return;}
  // Écrit dans la base (et sauvegardé) : sans save(), le code n'existait que
  // le temps de l'onglet, et le tunnel de paiement — qui lit DB.promoCodes —
  // ne l'aurait de toute façon jamais vu.
  if(typeof DB==='undefined'){toast('Base indisponible','err');return;}
  if(!DB.promoCodes) DB.promoCodes=[];
  if(DB.promoCodes.some(function(p){return String(p.code||'').toUpperCase()===code;})){
    toast('Ce code existe déjà','warn'); return;
  }
  var owner = (document.getElementById('npOwner')?.value||'').trim();
  var oPart = owner ? (DB.partners||[]).find(function(p){return p && p.id===owner;}) : null;
  DB.promoCodes.push({id:(typeof gid==='function'?gid():'pc'+Date.now()),code:code,
    reduction:pct,type:'percent',desc:label||('Promo '+code),actif:true,usage:0,max:max,
    // Propriétaire : c'est LUI qui rend le code rémunérateur. Le taux n'est pas
    // recopié ici — il découle du palier du partenaire, qui évolue avec ses
    // ventes, et le serveur le recalcule de toute façon à chaque encaissement.
    partnerId: owner || null,
    partnerNom: oPart ? (oPart.nom||oPart.name||oPart.code||'') : ''});
  if(typeof save==='function') save();
  cm();re();
  toast('✓ Code '+code+' créé ('+pct+'%)');
}

window.pgPaiementsAdmin = pgPaiementsAdmin;
window._mAddPromo = _mAddPromo;
window._saveNewPromo = _saveNewPromo;

