  s.minPayout = parseInt(((_ge?_ge('_ps_min'):document.getElementById('_ps_min'))||{value:5000}).value)||5000;
  s.payoutsBlockedReason = ((_ge?_ge('_ps_reason'):document.getElementById('_ps_reason'))||{value:''}).value;
