// ── APPLICATION du code parrainage à une vente ─────────────────────────────
// À appeler depuis confirmerAchat() / validerAbonnement() / autres ventes
// data = { refType:'book'|'elearning'|'product', refId, refLabel, saleAmount, qty }
function applyPartnerCode(code, data){
  if(!code || !data) return null;
  var codeUp = String(code).trim().toUpperCase();
  var partner = (DB.partners||[]).find(function(p){return p.code===codeUp && p.status==='active';});
  if(!partner) return null;
  var L = _prtL();
  var lv = L[partner.level||'bronze'] || L.bronze;
  var pct = lv.commission;
  var amount = Math.round((data.saleAmount||0) * pct);
  if(amount<=0) return null;
  var c = {
    id: (typeof gid==='function')?gid():'com_'+Date.now(),
    partnerId: partner.id,
    type: 'sale',
    refType: data.refType || 'other',
    refId: data.refId || '',
    refLabel: data.refLabel || '',
    saleAmount: data.saleAmount||0,
    commissionPct: pct,
    commissionAmount: amount,
    qty: data.qty || 1,
    status: 'pending',
    date: (typeof today==='function')?today():new Date().toISOString().substring(0,10)
  };
  if(!DB.commissions) DB.commissions=[];
  DB.commissions.push(c);
  if(!partner.stats) partner.stats={salesCount:0,totalCommission:0,paidOut:0,pending:0};
  partner.stats.salesCount = (partner.stats.salesCount||0) + (c.qty||1);
  partner.stats.totalCommission = (partner.stats.totalCommission||0) + amount;
  partner.stats.pending = (partner.stats.pending||0) + amount;
  calculatePartnerLevel(partner.id);
  _prtSave();
  return c;
}

// v1.2.5 — RÉPARTITION DIRECTE. Une commission de code promo (ou un bonus de
// palier) VALIDÉE est créditée dans le solde de versement UNIFIÉ
// (DB.partenairesSplit) → payée par la passerelle active AVEC les parrains, les
// auteurs et les enseignants, en un seul flux et un seul tableau de bord.
// Idempotent : double garde (c._distributed + paymentRef unique par commission)
// → jamais de double crédit, même si les chemins webhook + polling confirment le
// même paiement.
// v1.2.6 : le canal est celui du fournisseur en service (CamerPay au lancement).
window._payDistributeCommission = function(c){
  if(!c || c._distributed) return 0;
  var amt = c.commissionAmount || 0;
  if(amt <= 0 || !c.partnerId) return 0;
  DB.partenairesSplit = DB.partenairesSplit || {};
  DB.splits = DB.splits || [];
  var payRef = (c.type==='level_bonus' ? 'BONUS:' : 'COM:') + c.id;
  if(DB.splits.some(function(x){ return x.paymentRef === payRef; })){ c._distributed = true; return 0; }
  var s = {
    id: (typeof gid==='function') ? gid() : 's'+Date.now(),
    paymentRef: payRef,
    type: (c.type==='level_bonus') ? 'bonus_palier' : 'commission_code',
    partenaireId: c.partnerId,
    description: (c.type==='level_bonus')
      ? ('Bonus ' + (c.refLabel || 'palier'))
      : ('Commission code — ' + (c.refLabel || c.refType || 'vente')),
    montantBase: c.saleAmount || 0,
    pct: c.commissionPct || 0,
    montant: amt,
    etat: 'pending',
    createdAt: Date.now()
  };
  var ps = DB.partenairesSplit[c.partnerId] || (DB.partenairesSplit[c.partnerId] = { solde:0, totalVerse:0, splits:[] });
  DB.splits.push(s);
  ps.solde += amt;
  ps.splits.push(s.id);
  c._distributed = true;
  // Marque le canal réel : évite tout double-paiement par l'ancien tableau de
  // bord partenaire, et dit lequel des deux fournisseurs a la charge du solde.
  c.payoutChannel = (typeof _payProviderFile==='function' && _payProviderFile()==='payment_campay.php')
                    ? 'campay' : 'camerpay';
  return amt;
};

// v1.2.2 (bug de chaîne #3) : confirme les commissions d'une vente quand le
// paiement est VALIDÉ par l'admin → elles comptent alors pour le palier/bonus.
// Appelé à l'activation d'abonnement et à la validation d'un achat.
// v1.2.5 : chaque commission validée est AUSSITÔT répartie dans le solde CamPay.
function confirmCommissionsForSale(refType, refId){
  if(!DB.commissions) return 0;
  var n=0, touched={};
  DB.commissions.forEach(function(c){
    if(c.status==='pending' && c.refType===refType && String(c.refId)===String(refId)){
      c.status='validated'; c.validatedAt=(typeof today==='function')?today():''; n++;
      try { _payDistributeCommission(c); } catch(e){}   // ⚡ répartition directe → solde CamPay
      var p=(DB.partners||[]).find(function(x){return x.id===c.partnerId;});
      if(p){ calculatePartnerLevel(p.id); touched[c.partnerId]=1; }   // peut créditer un bonus de palier
    }
  });
  if(n>0){
    try{_prtSave&&_prtSave();}catch(e){} try{save&&save();}catch(e){}
    // Versement automatique une seule fois par partenaire, après TOUS les crédits
    // (commission de vente + éventuel bonus de palier cumulés dans le même solde).
    Object.keys(touched).forEach(function(pid){ try { _payMaybeAutoPayout(pid); } catch(e){} });
  }
  return n;
}
window.confirmCommissionsForSale = confirmCommissionsForSale;

// ── RECALCUL du palier — MIX ouvrages + abos + autres ──────────────────────
function calculatePartnerLevel(partnerId){
  var partner = (DB.partners||[]).find(function(p){return p.id===partnerId;});
  if(!partner) return;
  var L = _prtL();
  // v1.2.2 FIX (bug de chaîne #3) : le PALIER ne compte que les ventes CONFIRMÉES
  // (paiement validé). Les commissions 'pending' (paiement non encore vérifié) ne
  // doivent pas faire monter le palier ni débloquer des bonus → anti-fraude.
  var totalSales = (DB.commissions||[])
    .filter(function(c){return c.partnerId===partnerId && c.type==='sale' && (c.status==='validated'||c.status==='paid');})
    .reduce(function(s,c){return s + (c.qty||1);}, 0);
  var newLevel = 'bronze';
  ['diamant','or','argent','bronze'].forEach(function(lv){
    if(newLevel==='bronze' && lv!=='bronze' && totalSales >= (L[lv].min||0)) newLevel = lv;
  });
  if(newLevel !== partner.level){
    var bonus = (L[newLevel].bonusFixe||0);
    if(bonus>0){
      if(!DB.commissions) DB.commissions=[];
      var _bonusCom = {
        id: (typeof gid==='function')?gid():'com_'+Date.now(),
        partnerId: partner.id,
        type: 'level_bonus',
        refType: 'palier',
        refLabel: 'Palier '+L[newLevel].label,
        commissionAmount: bonus,
        commissionPct: 0,
        status: 'validated',   // le bonus est ACQUIS dès l'atteinte du palier
        validatedAt: (typeof today==='function')?today():'',
        date: (typeof today==='function')?today():new Date().toISOString().substring(0,10)
      };
      DB.commissions.push(_bonusCom);
      // ⚡ réparti directement dans le solde de versement (comme une commission)
      try { if(typeof _payDistributeCommission==='function') _payDistributeCommission(_bonusCom); } catch(e){}
      if(!partner.stats) partner.stats={};
      partner.stats.totalCommission = (partner.stats.totalCommission||0) + bonus;
    }
    partner.level = newLevel;
    if(!partner.stats) partner.stats={};
    partner.stats.levelUnlockedAt = (typeof today==='function')?today():new Date().toISOString().substring(0,10);
    if(typeof autoNotify==='function'){
      autoNotify('🎉 Nouveau palier atteint',
        partner.name+' · '+L[newLevel].badge+' '+L[newLevel].label+(bonus?' (+ bonus '+_prtFmt(bonus)+')':''),
        'admin');
    }
  }
}

